// Hyperrealistic Candy-Apple Burgundy Lowrider Bowling Ball on Polished Maple Lane
// Rendered with p5.js v2 + p5.brush in WEBGL

const CX = 600;
const CY = 615;
const R = 345;
const VX = 600;
const VY = 175;
const Y_HORIZON = 235;
const Y_CONTACT = CY + R; // 960

// Ball 3D orientation (tilted slightly toward viewer and turned slightly for dynamic symmetry)
const BALL_YAW = -0.11;   // radians
const BALL_PITCH = 0.16;  // radians

// Primary light direction (upper-left window crown)
const LIGHT = normalize3([-0.42, -0.54, 0.73]);

function normalize3(v) {
  let m = Math.hypot(v[0], v[1], v[2]) || 1;
  return [v[0] / m, v[1] / m, v[2] / m];
}

// Project spherical coordinates (u = longitude from spine, v = latitude) onto the 2D canvas
function projectBall(u, v, radScale = 1.0) {
  let lx = Math.sin(u) * Math.cos(v);
  let ly = Math.sin(v);
  let lz = Math.cos(u) * Math.cos(v);

  // Rotate around Y (yaw)
  let cy = Math.cos(BALL_YAW), sy = Math.sin(BALL_YAW);
  let x1 = lx * cy + lz * sy;
  let y1 = ly;
  let z1 = -lx * sy + lz * cy;

  // Rotate around X (pitch)
  let cp = Math.cos(BALL_PITCH), sp = Math.sin(BALL_PITCH);
  let nx = x1;
  let ny = y1 * cp - z1 * sp;
  let nz = y1 * sp + z1 * cp;

  let rad = R * radScale;
  return {
    x: CX + nx * rad,
    y: CY + ny * rad,
    z: nz * rad,
    nx: nx,
    ny: ny,
    nz: nz,
    visible: nz > 0.015,
    foreshorten: Math.max(0.12, nz)
  };
}

// Compute x coordinate of maple board seam b at canvas height y
function boardSeamX(b, y) {
  let widthAtContact = 76; // 1.06" board width relative to 8.5" ball (690px)
  let t = (y - VY) / (Y_CONTACT - VY);
  return VX + b * widthAtContact * t;
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7719);
  noiseSeed(7719);

  // Custom brushes for hyperrealistic automotive lacquer, airbrush, metal-flake & Mack sword striping
  brush.add("soft_glaze", {
    type: "default",
    weight: 16,
    scatter: 1.1,
    sharpness: 0.07,
    grain: 3,
    opacity: 19,
    spacing: 0.22,
    pressure: [0.25, 1.0, 0.25],
    noise: 0.15
  });

  brush.add("fine_glaze", {
    type: "default",
    weight: 7,
    scatter: 0.45,
    sharpness: 0.15,
    grain: 2,
    opacity: 28,
    spacing: 0.18,
    pressure: [0.2, 1.0, 0.2],
    noise: 0.1
  });

  brush.add("mack_striper", {
    type: "default",
    weight: 2.35,
    scatter: 0.015,
    sharpness: 0.91,
    grain: 1,
    opacity: 235,
    spacing: 0.07,
    pressure: [0.06, 1.0, 0.04],
    noise: 0.04
  });

  brush.add("mack_core", {
    type: "default",
    weight: 1.05,
    scatter: 0.008,
    sharpness: 0.96,
    grain: 0,
    opacity: 245,
    spacing: 0.07,
    pressure: [0.04, 1.0, 0.03],
    noise: 0.02
  });

  brush.add("flake_spray", {
    type: "spray",
    weight: 8.5,
    scatter: 3.6,
    opacity: 80,
    spacing: 0.32,
    pressure: [0.4, 1.15, 0.4]
  });

  brush.add("wood_grain", {
    type: "default",
    weight: 0.75,
    scatter: 0.12,
    sharpness: 0.62,
    grain: 11,
    opacity: 42,
    spacing: 0.2,
    pressure: [0.2, 1.0, 0.2],
    noise: 0.55
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#0b1018");

  // 1. Moody Cool-Toned Alley Background (above horizon)
  drawAlleyBackground();

  // 2. Polished Maple Lane Boards in Linear Perspective
  let boardColors = drawMapleLane();

  // 3. Lane Surface Reflections (Window Sheen, Ball Burgundy Reflection & Reflected Pinstripes)
  drawLaneReflections(boardColors);

  // 4. The Candy-Apple Burgundy Sphere Base & Internal Depth
  drawCandySphereBase(boardColors);

  // 5. Metallic Micro-Flake Layer Suspended in the Candy Base
  drawMetalFlakeLayer();

  // 6. Translucent Candy-Apple Lacquer Over-Glaze
  drawCandyOverGlaze();

  // 7. Custom-Shop Lowrider Pinstripes (Lime Green, Cream & Cool Cyan Accents)
  drawAllPinstripes();

  // 8. Crisp, Dark, Bevelled Finger Holes
  drawAllFingerHoles();

  // 9. Sharp Mirrored Window Reflection Across the Crown & Final Specular Gloss
  drawCrownWindowReflection();

  noLoop();
}

// ============================================================================
// 1. ALLEY BACKGROUND
// ============================================================================
function drawAlleyBackground() {
  brush.noField();
  brush.noStroke();

  // Deep cool navy-charcoal backdrop
  brush.wash("#090e17", 255);
  brush.rect(0, 0, 1200, Y_HORIZON + 15, "corner");

  // Distant atmospheric cool window/ceiling glow
  let glowBands = [
    { x: 460, y: 110, w: 680, h: 170, c: "#162436", a: 120 },
    { x: 420, y: 95,  w: 520, h: 130, c: "#1f354d", a: 95 },
    { x: 380, y: 80,  w: 360, h: 95,  c: "#2d4c6b", a: 75 }
  ];
  for (let g of glowBands) {
    brush.wash(g.c, g.a);
    brush.rect(g.x, g.y, g.w, g.h, "center");
  }

  // Subtle horizontal structural beams & pin-deck shadow line at the horizon
  brush.set("soft_glaze", "#1c2d42", 1.4);
  for (let y = 30; y < Y_HORIZON - 20; y += 26) {
    brush.line(40, y, 1160, y);
  }

  // Crisp dark gutter/pit horizon divider
  brush.noStroke();
  brush.wash("#05070c", 235);
  brush.rect(0, Y_HORIZON - 16, 1200, 22, "corner");

  brush.set("rotring", "#2b3e54", 0.9);
  brush.line(0, Y_HORIZON, 1200, Y_HORIZON);
}

// ============================================================================
// 2. POLISHED MAPLE LANE BOARDS (COOL PALETTE)
// ============================================================================
function drawMapleLane() {
  brush.noField();

  // Base lane foundation
  brush.noStroke();
  brush.wash("#333942", 255);
  brush.rect(0, Y_HORIZON, 1200, 1200 - Y_HORIZON, "corner");

  // Cool-shifted rock maple palette (silvered honey, ash-taupe, slate-amber, cool pewter)
  const mapleTones = [
    "#54565c", "#6c6864", "#7d776f", "#4a4e57",
    "#8a8177", "#5e5f63", "#746e68", "#636266",
    "#948b80", "#4f5259", "#827b73", "#595b61"
  ];

  let boardMeta = {};

  // Draw individual perspective boards from b = -22 to +22
  for (let b = -22; b <= 21; b++) {
    let idx = Math.abs(b * 7 + 13) % mapleTones.length;
    let col = mapleTones[idx];
    // Slight vertical reflection jitter per board (realistic floorboard tilt)
    let jitter = (noise(b * 0.7, 1.3) - 0.5) * 9.0;
    boardMeta[b] = { col, jitter };

    let xTopL = boardSeamX(b, Y_HORIZON);
    let xTopR = boardSeamX(b + 1, Y_HORIZON);
    let xBotL = boardSeamX(b, 1200);
    let xBotR = boardSeamX(b + 1, 1200);

    // Skip if completely off-screen
    if (Math.max(xTopL, xTopR, xBotL, xBotR) < -20 || Math.min(xTopL, xTopR, xBotL, xBotR) > 1220) {
      continue;
    }

    // Board base wash
    brush.noStroke();
    brush.wash(col, 230);
    brush.beginShape(0);
    brush.vertex(constrain(xTopL, -40, 1240), Y_HORIZON);
    brush.vertex(constrain(xTopR, -40, 1240), Y_HORIZON);
    brush.vertex(constrain(xBotR, -80, 1280), 1200);
    brush.vertex(constrain(xBotL, -80, 1280), 1200);
    brush.endShape(true);

    // Subtle tonal variation along the board length (plank joints)
    let jointY = map(noise(b * 1.9 + 5), 0, 1, 340, 880);
    let xJL = boardSeamX(b, jointY);
    let xJR = boardSeamX(b + 1, jointY);
    brush.wash(b % 2 === 0 ? "#242a34" : "#aba196", 32);
    brush.beginShape(0);
    brush.vertex(constrain(xJL, -40, 1240), jointY);
    brush.vertex(constrain(xJR, -40, 1240), jointY);
    brush.vertex(constrain(xBotR, -80, 1280), 1200);
    brush.vertex(constrain(xBotL, -80, 1280), 1200);
    brush.endShape(true);

    // Fine wood-grain fibers along perspective lines
    let grainCount = b >= -8 && b <= 8 ? 5 : 3;
    for (let g = 1; g <= grainCount; g++) {
      let frac = g / (grainCount + 1);
      let gx1 = lerp(xTopL, xTopR, frac);
      let gx2 = lerp(xBotL, xBotR, frac);
      if (gx2 > -50 && gx2 < 1250) {
        let grainCol = (g + b) % 2 === 0 ? "#36383f" : "#9c9388";
        brush.set("wood_grain", grainCol, 0.85);
        brush.line(gx1, Y_HORIZON, gx2, 1200);
      }
    }

    // Range-finder arrows inlaid on every 5th board in the upper mid-ground
    if (b % 5 === 0 && b >= -10 && b <= 10) {
      let arrowY = 390 - Math.abs(b) * 8;
      let arrowLen = 48;
      let axMidTop = boardSeamX(b + 0.5, arrowY - arrowLen);
      let axL = boardSeamX(b + 0.08, arrowY);
      let axR = boardSeamX(b + 0.92, arrowY);
      let axMidIn = boardSeamX(b + 0.5, arrowY - 12);
      brush.noStroke();
      brush.wash("#22252e", 185);
      brush.beginShape(0);
      brush.vertex(axMidTop, arrowY - arrowLen);
      brush.vertex(axR, arrowY);
      brush.vertex(axMidIn, arrowY - 12);
      brush.vertex(axL, arrowY);
      brush.endShape(true);
    }
  }

  // Crisp board seam lines converging to (VX, VY)
  for (let b = -22; b <= 22; b++) {
    let xTop = boardSeamX(b, Y_HORIZON);
    let xBot = boardSeamX(b, 1200);
    if (Math.max(xTop, xBot) < -20 || Math.min(xTop, xBot) > 1220) continue;

    // Dark seam groove
    brush.set("rotring", "#232730", 0.55);
    brush.line(xTop, Y_HORIZON, xBot, 1200);

    // Subtle specular catch along adjacent board edge
    brush.set("2H", "#a39d95", 0.4);
    brush.line(xTop + 0.6, Y_HORIZON, xBot + 1.2, 1200);
  }

  return boardMeta;
}

// ============================================================================
// 3. LANE SURFACE REFLECTIONS & SHADOWS
// ============================================================================
function drawLaneReflections(boardMeta) {
  brush.noField();

  // A. Cool Window Specular Column stretching down the left-center of the lane
  for (let i = 0; i < 12; i++) {
    let t = i / 11;
    let bStart = lerp(-9, -6.5, t);
    let bEnd = lerp(-0.5, -2.5, t);
    let xTL = boardSeamX(bStart, Y_HORIZON);
    let xTR = boardSeamX(bEnd, Y_HORIZON);
    let xBL = boardSeamX(bStart, 1200);
    let xBR = boardSeamX(bEnd, 1200);

    brush.noStroke();
    brush.wash("#b5d8f0", 14);
    brush.beginShape(0);
    brush.vertex(xTL, Y_HORIZON);
    brush.vertex(xTR, Y_HORIZON);
    brush.vertex(xBR, 1200);
    brush.vertex(xBL, 1200);
    brush.endShape(true);
  }

  // B. Cool Slate Vignette on outer lane edges and horizon depth
  brush.noStroke();
  brush.wash("#121a26", 110);
  brush.beginShape(0);
  brush.vertex(0, Y_HORIZON);
  brush.vertex(boardSeamX(-7, Y_HORIZON), Y_HORIZON);
  brush.vertex(boardSeamX(-7, 1200), 1200);
  brush.vertex(0, 1200);
  brush.endShape(true);

  brush.wash("#101722", 125);
  brush.beginShape(0);
  brush.vertex(boardSeamX(6, Y_HORIZON), Y_HORIZON);
  brush.vertex(1200, Y_HORIZON);
  brush.vertex(1200, 1200);
  brush.vertex(boardSeamX(6, 1200), 1200);
  brush.endShape(true);

  // C. Board-broken Mirror Reflection of the Candy-Apple Burgundy Ball on the Lane
  // The reflection sits directly below Y_CONTACT (960 down to 1200) across boards -5 to +5
  for (let b = -5; b <= 4; b++) {
    let meta = boardMeta[b] || { jitter: 0 };
    let jit = meta.jitter;

    // Sample vertical slices within board b
    let yTop = Y_CONTACT - 18 + jit;
    let yBot = 1200;
    let xTL = boardSeamX(b, yTop);
    let xTR = boardSeamX(b + 1, yTop);
    let xBL = boardSeamX(b, yBot);
    let xBR = boardSeamX(b + 1, yBot);

    // Distance from center board determines how deep the burgundy reflection reaches
    let distFromCenter = Math.abs(b + 0.5);
    if (distFromCenter < 4.6) {
      let reach = Math.sqrt(Math.max(0, 1 - Math.pow(distFromCenter / 4.6, 2)));
      let reflEnd = Math.min(1200, Y_CONTACT + reach * 255 + jit * 2);

      let xEL = boardSeamX(b, reflEnd);
      let xER = boardSeamX(b + 1, reflEnd);

      // Deep wine reflection wash on this board strip
      brush.noStroke();
      brush.wash("#2b0410", 145);
      brush.beginShape(0);
      brush.vertex(xTL, yTop);
      brush.vertex(xTR, yTop);
      brush.vertex(xER, reflEnd);
      brush.vertex(xEL, reflEnd);
      brush.endShape(true);

      // Brighter candy-crimson core reflection near the middle boards
      if (distFromCenter < 3.2) {
        let midEnd = Math.min(1200, Y_CONTACT + reach * 190 + jit);
        let xML = boardSeamX(b, midEnd);
        let xMR = boardSeamX(b + 1, midEnd);
        brush.wash("#59071f", 110);
        brush.beginShape(0);
        brush.vertex(xTL, yTop + 10);
        brush.vertex(xTR, yTop + 10);
        brush.vertex(xMR, midEnd);
        brush.vertex(xML, midEnd);
        brush.endShape(true);
      }
    }
  }

  // Soft airbrushed burgundy & lime-green glow in the lane reflection
  for (let r = 260; r >= 50; r -= 25) {
    let col = r > 160 ? "#24030d" : (r > 95 ? "#4a0619" : "#6e0a25");
    brush.set("soft_glaze", col, 2.2);
    brush.arc(CX, Y_CONTACT + 75, r, 10, 170);
  }

  // Reflected Pinstripe Ghosts in the Polished Maple (lime green & cream curves)
  const reflStripes = [
    { pts: [[-185, 1005], [-110, 1065], [-35, 1135], [0, 1165]], c: "#78bd14", w: 1.1 },
    { pts: [[185, 1005], [110, 1065], [35, 1135], [0, 1165]], c: "#78bd14", w: 1.1 },
    { pts: [[-120, 995], [-68, 1045], [-18, 1095], [0, 1130]], c: "#d9d2b8", w: 0.9 },
    { pts: [[120, 995], [68, 1045], [18, 1095], [0, 1130]], c: "#d9d2b8", w: 0.9 },
    { pts: [[-235, 1020], [-155, 1085], [-75, 1150]], c: "#639e10", w: 0.85 },
    { pts: [[235, 1020], [155, 1085], [75, 1150]], c: "#639e10", w: 0.85 }
  ];
  for (let rs of reflStripes) {
    let spts = rs.pts.map(p => [CX + p[0], p[1], 0.8]);
    brush.set("fine_glaze", rs.c, rs.w);
    brush.spline(spts, 0.5);
    brush.set("mack_striper", rs.c, rs.w * 0.55);
    brush.spline(spts, 0.5);
  }

  // Re-scribe crisp board seams across the reflection so the reflection sits *inside* the wood finish
  for (let b = -6; b <= 6; b++) {
    let x1 = boardSeamX(b, Y_CONTACT - 30);
    let x2 = boardSeamX(b, 1200);
    brush.set("rotring", "#161820", 0.6);
    brush.line(x1, Y_CONTACT - 30, x2, 1200);
  }

  // Horizontal glossy polyurethane reflection streaks across the lane
  for (let i = 0; i < 45; i++) {
    let ry = random(Y_HORIZON + 15, 1190);
    let span = map(ry, Y_HORIZON, 1200, 90, 420);
    let rx = CX + random(-420, 320);
    let col = ry > Y_CONTACT - 10 && Math.abs(rx - CX) < 240 ? "#7a1632" : "#b8d4eb";
    brush.set("2H", col, random(0.3, 0.7));
    brush.line(rx - span * 0.5, ry, rx + span * 0.5, ry);
  }

  // D. Cast Shadow & Tight Contact Ambient Occlusion under the Ball
  let shadowLayers = [
    { rx: 280, ry: 46, yOff: 8,  c: "#0d1018", a: 110 },
    { rx: 220, ry: 34, yOff: 5,  c: "#08070d", a: 150 },
    { rx: 155, ry: 22, yOff: 2,  c: "#050308", a: 195 },
    { rx: 95,  ry: 12, yOff: 0,  c: "#020104", a: 245 }
  ];
  brush.noStroke();
  for (let sl of shadowLayers) {
    brush.wash(sl.c, sl.a);
    drawEllipsePoly(CX + 12, Y_CONTACT + sl.yOff, sl.rx, sl.ry, 40);
  }
}

function drawEllipsePoly(cx, cy, rx, ry, steps = 48) {
  brush.beginShape(0);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    brush.vertex(cx + cos(a) * rx, cy + sin(a) * ry);
  }
  brush.endShape(true);
}

// ============================================================================
// 4. CANDY-APPLE BURGUNDY SPHERE BASE & CURVED LANE BOUNCE REFLECTION
// ============================================================================
function drawCandySphereBase(boardMeta) {
  brush.noField();
  brush.noStroke();

  // 1. Deepest black-cherry / midnight-plum foundation sphere
  brush.wash("#120208", 255);
  drawEllipsePoly(CX, CY, R, R, 72);

  // 2. Concentric eccentric shading layers building toward the upper-left light core
  const candyRamp = [
    { ox: -15,  oy: -18,  rad: 0.96, c: "#1c030c", a: 210 },
    { ox: -28,  oy: -34,  rad: 0.90, c: "#290411", a: 190 },
    { ox: -42,  oy: -50,  rad: 0.83, c: "#3b0518", a: 175 },
    { ox: -56,  oy: -66,  rad: 0.75, c: "#4f0620", a: 165 },
    { ox: -70,  oy: -82,  rad: 0.67, c: "#660828", a: 155 },
    { ox: -84,  oy: -98,  rad: 0.58, c: "#800a31", a: 150 },
    { ox: -98,  oy: -112, rad: 0.49, c: "#9c0d3b", a: 145 },
    { ox: -110, oy: -125, rad: 0.40, c: "#b81145", a: 140 },
    { ox: -122, oy: -136, rad: 0.31, c: "#d41952", a: 130 },
    { ox: -132, oy: -146, rad: 0.22, c: "#eb2864", a: 115 }
  ];

  for (let layer of candyRamp) {
    brush.wash(layer.c, layer.a);
    drawEllipsePoly(CX + layer.ox, CY + layer.oy, R * layer.rad, R * layer.rad, 60);
  }

  // 3. Soft spray/glaze transitions along the spherical terminator
  for (let i = 0; i < 36; i++) {
    let t = i / 35;
    let rad = lerp(R * 0.18, R * 0.96, t);
    let ox = lerp(-130, 0, t);
    let oy = lerp(-145, 0, t);
    let col = t < 0.35 ? "#d91c54" : (t < 0.68 ? "#7a092c" : "#2b0311");
    brush.set("soft_glaze", col, 1.8);
    // Clip arc inside sphere by keepingox+rad <= R
    let safeRad = Math.min(rad, R - Math.hypot(ox, oy) - 4);
    if (safeRad > 15) {
      brush.arc(CX + ox, CY + oy, safeRad, 0, 360);
    }
  }

  // 4. Fisheye Reflection of the Maple Lane Boards on the Lower Hemisphere of the Ball
  // Because the sphere acts as a convex mirror, the converging lane boards wrap around the bottom curve!
  for (let b = -6; b <= 5; b++) {
    let uL = b * 0.17;
    let uR = (b + 1) * 0.17;
    let vTop = 0.36;
    let vBot = 1.18;

    let polyPts = [];
    for (let s = 0; s <= 6; s++) {
      let u = lerp(uL, uR, s / 6);
      let p = projectBall(u, vTop, 0.992);
      if (p.visible) polyPts.push([p.x, p.y]);
    }
    for (let s = 6; s >= 0; s--) {
      let u = lerp(uL, uR, s / 6);
      let p = projectBall(u, vBot, 0.992);
      if (p.visible) polyPts.push([p.x, p.y]);
    }

    if (polyPts.length >= 4) {
      brush.noStroke();
      let tone = Math.abs(b) % 2 === 0 ? "#4f2632" : "#381522";
      brush.wash(tone, 58);
      brush.beginShape(0);
      for (let pt of polyPts) brush.vertex(pt[0], pt[1]);
      brush.endShape(true);

      // Curved board seam line reflected on the lower sphere
      let seamPts = [];
      for (let sv = vTop; sv <= vBot; sv += 0.12) {
        let sp = projectBall(uL, sv, 0.992);
        if (sp.visible) seamPts.push([sp.x, sp.y, sp.foreshorten * 0.7]);
      }
      if (seamPts.length >= 3) {
        brush.set("rotring", "#1a040c", 0.45);
        brush.spline(seamPts, 0.4);
      }
    }
  }

  // 5. Cool Palette Fresnel Rim Reflections (Left & Upper-Right Edges of Sphere)
  for (let pass = 0; pass < 3; pass++) {
    let rad = R - 3 - pass * 4;
    brush.set("fine_glaze", pass === 0 ? "#6ea8cc" : "#3a5a78", 1.2 - pass * 0.25);
    brush.arc(CX, CY, rad, 135, 225); // Left cool rim
    brush.arc(CX, CY, rad, 305, 45);  // Right cool rim
  }
}

// ============================================================================
// 5. METAL-FLAKE LAYER (FINE SPECKLE SUSPENDED IN CANDY BASE)
// ============================================================================
function drawMetalFlakeLayer() {
  brush.noField();

  // A. Spray bands of metallic shimmer across the illuminated hemisphere
  for (let i = 0; i < 48; i++) {
    let u1 = random(-1.1, 0.4);
    let v1 = random(-1.05, 0.35);
    let u2 = u1 + random(0.18, 0.45);
    let v2 = v1 + random(-0.15, 0.15);

    let p1 = projectBall(u1, v1, 0.97);
    let p2 = projectBall(u2, v2, 0.97);
    if (!p1.visible || !p2.visible) continue;

    let dotL = p1.nx * LIGHT[0] + p1.ny * LIGHT[1] + p1.nz * LIGHT[2];
    if (dotL > -0.15) {
      let col = dotL > 0.65 ? "#ff6b93" : (dotL > 0.3 ? "#d9164b" : "#780b32");
      brush.set("flake_spray", col, map(dotL, -0.15, 1, 0.55, 1.35));
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }
  }

  // B. Individual crisp micro-flakes (2,400 metallic prism specks)
  for (let i = 0; i < 2400; i++) {
    // Concentrate flakes toward the lit side and mid-tone ring
    let u = random(-1.35, 1.25);
    let v = random(-1.25, 1.15);
    let p = projectBall(u, v, random(0.96, 0.992));
    if (!p.visible) continue;

    let dotL = p.nx * LIGHT[0] + p.ny * LIGHT[1] + p.nz * LIGHT[2];
    // Stochastic acceptance weighted by illumination
    if (random() > map(dotL, -0.5, 1.0, 0.08, 0.95)) continue;

    let flakeCol;
    let w;
    if (dotL > 0.72) {
      // Hot crown zone: sparkling rose-gold, cool silver-pink, cyan prism & vivid ruby
      let r = random();
      flakeCol = r < 0.35 ? "#ffb3c9" : (r < 0.65 ? "#ff3870" : (r < 0.85 ? "#fff0f5" : "#a8ecff"));
      w = random(0.55, 1.15);
    } else if (dotL > 0.35) {
      // Rich candy zone: electric crimson, magenta-berry & warm copper-rose
      let r = random();
      flakeCol = r < 0.45 ? "#e0164c" : (r < 0.8 ? "#b00e44" : "#ff668c");
      w = random(0.45, 0.95);
    } else if (dotL > 0.0) {
      // Deep oxblood transition: plum-magenta & dark ruby
      flakeCol = random() < 0.6 ? "#7a0930" : "#59123a";
      w = random(0.35, 0.75);
    } else {
      // Shadow core: faint cool violet-wine glints
      flakeCol = "#3b0a29";
      w = random(0.3, 0.6);
    }

    let len = random(1.2, 2.8) * p.foreshorten;
    let ang = random(0, 180) * (Math.PI / 180);
    let dx = Math.cos(ang) * len * 0.5;
    let dy = Math.sin(ang) * len * 0.5;

    brush.set("rotring", flakeCol, w * p.foreshorten);
    brush.line(p.x - dx, p.y - dy, p.x + dx, p.y + dy);
  }
}

