function drawCandyOverGlaze() {
  brush.noField();
  brush.noStroke();

  // Embeds the metal-flake beneath rich, glassy candy-apple dye
  brush.wash("#5e0521", 48);
  drawEllipsePoly(CX, CY, R * 0.99, R * 0.99, 64);

  brush.wash("#9e0b37", 42);
  drawEllipsePoly(CX - 75, CY - 85, R * 0.62, R * 0.62, 54);

  // Deep shadow crescent along the bottom-right core to amplify 3D roundness
  for (let i = 0; i < 8; i++) {
    let rad = R * lerp(0.76, 0.97, i / 7);
    brush.set("soft_glaze", "#14020a", 2.1);
    brush.arc(CX + 18, CY + 18, rad, 345, 115);
  }

  // Crisp outer sphere silhouette refinement
  brush.set("rotring", "#240512", 0.95);
  brush.arc(CX, CY, R, 0, 360);
}

// ============================================================================
// 7. LOWRIDER PINSTRIPES (SYMMETRICAL SCROLLS IN LIME GREEN & CREAM)
// ============================================================================
// Helper: project a 3D spherical (u, v, pressure) curve and draw it with brush.spline
function drawSphericalCurve(uvPts, brushName, col, weightMult = 1.0, offsetPx = [0, 0]) {
  // Interpolate densely along segments so the curve hugs the 3D sphere accurately
  let dense = [];
  for (let i = 0; i < uvPts.length - 1; i++) {
    let a = uvPts[i];
    let b = uvPts[i + 1];
    let dist = Math.hypot(b[0] - a[0], b[1] - a[1]);
    let steps = Math.max(3, Math.ceil(dist / 0.045));
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      dense.push([
        lerp(a[0], b[0], t),
        lerp(a[1], b[1], t),
        lerp(a[2] ?? 1.0, b[2] ?? 1.0, t)
      ]);
    }
  }
  dense.push(uvPts[uvPts.length - 1]);

  // Project and filter visible points with minimum screen spacing
  let screenPts = [];
  for (let pt of dense) {
    let p = projectBall(pt[0], pt[1], 0.996);
    if (p.visible) {
      let sx = p.x + offsetPx[0];
      let sy = p.y + offsetPx[1];
      let sp = Math.max(0.08, (pt[2] ?? 1.0) * Math.pow(p.foreshorten, 0.65));
      if (screenPts.length === 0 || Math.hypot(sx - screenPts[screenPts.length - 1][0], sy - screenPts[screenPts.length - 1][1]) > 2.2) {
        screenPts.push([sx, sy, sp]);
      }
    }
  }

  if (screenPts.length >= 3) {
    brush.set(brushName, col, weightMult);
    brush.spline(screenPts, 0.45);
  } else if (screenPts.length === 2) {
    brush.set(brushName, col, weightMult * screenPts[0][2]);
    brush.line(screenPts[0][0], screenPts[0][1], screenPts[1][0], screenPts[1][1]);
  }
}

// Helper: draw both +u and -u symmetrical lowrider pinstripe curves
function drawSymPinstripe(uvPts, baseCol, coreCol, weightMult = 1.0, hasCenterMirror = true) {
  let sides = hasCenterMirror ? [1, -1] : [1];
  for (let dir of sides) {
    let mirrored = uvPts.map(p => [p[0] * dir, p[1], p[2] ?? 1.0]);

    // 1. Sub-surface clearcoat shadow onto the candy base
    drawSphericalCurve(mirrored, "mack_striper", "#160208", weightMult * 0.95, [2.2, 3.2]);

    // 2. Main lacquer stroke with Mack sword striper
    drawSphericalCurve(mirrored, "mack_striper", baseCol, weightMult, [0, 0]);

    // 3. Wet specular ridge down the center of the stroke
    if (coreCol) {
      drawSphericalCurve(mirrored, "mack_core", coreCol, weightMult * 0.72, [-0.3, -0.3]);
    }
  }
}

// Helper: draw symmetrical teardrop / dot accent on the sphere
function drawSymDot(u, v, radiusPx, baseCol, coreCol) {
  let sides = Math.abs(u) < 0.001 ? [1] : [1, -1];
  for (let dir of sides) {
    let p = projectBall(u * dir, v, 0.996);
    if (!p.visible) continue;
    let r = radiusPx * p.foreshorten;
    brush.set("mack_striper", "#160208", r * 0.9);
    brush.line(p.x + 2, p.y + 2.5, p.x + 2 + 0.8, p.y + 2.5 + 0.8);

    brush.set("mack_striper", baseCol, r);
    brush.line(p.x - 0.5, p.y - 0.5, p.x + 0.5, p.y + 0.5);

    if (coreCol) {
      brush.set("mack_core", coreCol, r * 0.75);
      brush.line(p.x - 0.3, p.y - 0.3, p.x + 0.3, p.y + 0.3);
    }
  }
}

