// ============================================================================
// 8. CRISP, DARK, BEVELLED FINGER HOLES
// ============================================================================
function drawSingleFingerHole(uCenter, vCenter, angRadius) {
  let steps = 48;
  let outerRing = [];
  let innerRing = [];
  let deepRing = [];

  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * Math.PI * 2;
    let du = (Math.cos(a) * angRadius) / Math.max(0.3, Math.cos(vCenter));
    let dv = Math.sin(a) * angRadius;

    let pOut = projectBall(uCenter + du * 1.15, vCenter + dv * 1.15, 0.998);
    let pIn  = projectBall(uCenter + du * 1.00, vCenter + dv * 1.00, 0.995);
    let pDep = projectBall(uCenter + du * 0.88, vCenter + dv * 0.88, 0.975);

    outerRing.push(pOut);
    innerRing.push(pIn);
    deepRing.push([pDep.x + 4.5, pDep.y + 5.5]);
  }

  // 1. Outer Chamfer / Bevel Base (dark burgundy shell thickness)
  brush.noStroke();
  brush.wash("#24030d", 240);
  brush.beginShape(0);
  for (let p of outerRing) brush.vertex(p.x, p.y);
  brush.endShape(true);

  // 2. Directional Bevel Lighting (Top-Left bevel is in shadow; Bottom-Right bevel catches razor-sharp window highlight!)
  for (let i = 0; i < steps; i++) {
    let next = (i + 1) % steps;
    let a = (i / steps) * Math.PI * 2;
    // Outward bevel normal relative to light from top-left (-0.6, -0.8)
    // Bottom-right side of hole (cos(a) > 0, sin(a) > 0) faces the upper-left light!
    let catchLight = Math.cos(a) * 0.62 + Math.sin(a) * 0.78;

    let segCol;
    let segW;
    if (catchLight > 0.72) {
      segCol = "#eef9ff"; // Crisp mirror bevel highlight
      segW = 1.65;
    } else if (catchLight > 0.35) {
      segCol = "#ff5c8a"; // Candy ruby bevel refraction
      segW = 1.35;
    } else if (catchLight > -0.15) {
      segCol = "#8a0c33"; // Mid-tone burgundy bevel
      segW = 1.1;
    } else {
      segCol = "#120107"; // Shadowed bevel rim
      segW = 1.25;
    }

    let xm1 = (outerRing[i].x + innerRing[i].x) * 0.5;
    let ym1 = (outerRing[i].y + innerRing[i].y) * 0.5;
    let xm2 = (outerRing[next].x + innerRing[next].x) * 0.5;
    let ym2 = (outerRing[next].y + innerRing[next].y) * 0.5;

    brush.set("mack_striper", segCol, segW);
    brush.line(xm1, ym1, xm2, ym2);
  }

  // 3. Deep Drilled Core Bore (Matte Charcoal / Black Polyurethane Core)
  brush.noStroke();
  brush.wash("#08090f", 255);
  brush.beginShape(0);
  for (let p of innerRing) brush.vertex(p.x, p.y);
  brush.endShape(true);

  // Subtle internal cylindrical wall grazing light on the lower-right wall of the bore
  brush.wash("#191b26", 180);
  brush.beginShape(0);
  for (let i = 0; i <= 20; i++) {
    let idx = (i + 38) % steps;
    brush.vertex(innerRing[idx].x, innerRing[idx].y);
  }
  for (let i = 20; i >= 0; i--) {
    let idx = (i + 38) % steps;
    brush.vertex(deepRing[idx][0], deepRing[idx][1]);
  }
  brush.endShape(true);

  // Pitch-black abyss at the bottom of the bore
  brush.wash("#030306", 250);
  brush.beginShape(0);
  for (let pt of deepRing) brush.vertex(pt[0], pt[1]);
  brush.endShape(true);

  // 4. Razor-sharp inner & outer bevel edges
  let innerSpline = innerRing.map(p => [p.x, p.y, 0.9]);
  innerSpline.push(innerSpline[0]);
  brush.set("rotring", "#040206", 0.85);
  brush.spline(innerSpline, 0.4);
}

function drawAllFingerHoles() {
  brush.noField();
  // Two upper finger holes (middle & ring finger) symmetrically flanking the spine
  drawSingleFingerHole(-0.17, -0.56, 0.082);
  drawSingleFingerHole(0.17, -0.56, 0.082);

  // Larger lower thumb hole centered on the spine
  drawSingleFingerHole(0.0, -0.20, 0.098);
}

// ============================================================================
// 9. SHARP MIRRORED WINDOW REFLECTION ACROSS THE CROWN & CLEARCOAT GLOSS
// ============================================================================
function drawCrownWindowReflection() {
  brush.noField();

  // A. Soft Cool-Cyan Atmospheric Bloom around the Crown Window Reflection
  let crownCenter = projectBall(-0.54, -0.50, 0.95);
  brush.noStroke();
  brush.wash("#6cb8e6", 34);
  drawEllipsePoly(crownCenter.x, crownCenter.y, 135, 105, 40);
  brush.wash("#a8dcff", 28);
  drawEllipsePoly(crownCenter.x - 12, crownCenter.y - 10, 95, 72, 36);

  // B. Sharp, Multi-Paned Industrial Window Reflection Warped to the Sphere's Curvature
  // 2 rows x 3 columns of window panes in spherical (u, v) space across the upper-left crown
  const uCols = [
    [-0.92, -0.71],
    [-0.67, -0.45],
    [-0.41, -0.21]
  ];
  const vRows = [
    [-0.78, -0.51],
    [-0.47, -0.20]
  ];

  for (let r = 0; r < vRows.length; r++) {
    for (let c = 0; c < uCols.length; c++) {
      let u0 = uCols[c][0], u1 = uCols[c][1];
      let v0 = vRows[r][0], v1 = vRows[r][1];

      // Build curved spherical polygon for this window pane
      let panePts = [];
      let steps = 8;
      for (let s = 0; s <= steps; s++) {
        let p = projectBall(lerp(u0, u1, s / steps), v0, 0.998);
        if (p.visible) panePts.push([p.x, p.y]);
      }
      for (let s = 1; s <= steps; s++) {
        let p = projectBall(u1, lerp(v0, v1, s / steps), 0.998);
        if (p.visible) panePts.push([p.x, p.y]);
      }
      for (let s = steps - 1; s >= 0; s--) {
        let p = projectBall(lerp(u0, u1, s /StepsOrDefault(steps)), v1, 0.998);
        if (p.visible) panePts.push([p.x, p.y]);
      }
      for (let s = steps - 1; s >= 1; s--) {
        let p = projectBall(u0, lerp(v0, v1, s / steps), 0.998);
        if (p.visible) panePts.push([p.x, p.y]);
      }

      if (panePts.length < 4) continue;

      // Intensity falls off slightly from top-left pane (r=0,c=0) to bottom-right pane (r=1,c=2)
      let intensity = 1.0 - (r * 0.22 + c * 0.16);

      // 1. Chromatic / Clearcoat Double-Reflection Ghost (subtle cyan offset)
      brush.noStroke();
      brush.wash("#5ce1ff", Math.round(48 * intensity));
      brush.beginShape(0);
      for (let pt of panePts) brush.vertex(pt[0] + 3.5, pt[1] + 3.5);
      brush.endShape(true);

      // 2. Crisp Cool Ice-Blue Glass Fill
      brush.wash("#c4e8ff", Math.round(165 * intensity));
      brush.beginShape(0);
      for (let pt of panePts) brush.vertex(pt[0], pt[1]);
      brush.endShape(true);

      // 3. Pure Specular White Core inside Upper Portion of Each Pane
      let vMid = lerp(v0, v1, 0.68);
      let corePts = [
        projectBall(u0 + 0.015, v0 + 0.015, 0.998),
        projectBall(u1 - 0.015, v0 + 0.015, 0.998),
        projectBall(u1 - 0.015, vMid, 0.998),
        projectBall(u0 + 0.015, vMid, 0.998)
      ];
      brush.wash("#ffffff", Math.round(215 * intensity));
      brush.beginShape(0);
      for (let cp of corePts) brush.vertex(cp.x, cp.y);
      brush.endShape(true);

      // 4. Razor-sharp Window Frame Edges (Mullion Glints)
      let edgeLoop = panePts.map(pt => [pt[0], pt[1], 0.95]);
      edgeLoop.push(edgeLoop[0]);
      brush.set("mack_core", "#ffffff", 0.95 * intensity);
      brush.spline(edgeLoop, 0.15);

      // Diagonal glass reflection streak across the pane
      let d1 = projectBall(lerp(u0, u1, 0.18), lerp(v0, v1, 0.82), 0.998);
      let d2 = projectBall(lerp(u0, u1, 0.82), lerp(v0, v1, 0.18), 0.998);
      brush.set("mack_striper", "#ffffff", 1.15 * intensity);
      brush.line(d1.x, d1.y, d2.x, d2.y);
    }
  }

  // C. Secondary High-Gloss Strip Reflection along Upper-Right Crown (Overhead Alley Light)
  let tubeReflect = [
    [0.45, -0.78, 0.15],
    [0.64, -0.64, 0.95],
    [0.82, -0.44, 1.10],
    [0.96, -0.20, 0.75],
    [1.06, 0.04, 0.15]
  ];
  drawSphericalCurve(tubeReflect, "fine_glaze", "#8ac8f0", 1.35, [0, 0]);
  drawSphericalCurve(tubeReflect, "mack_striper", "#e6f5ff", 1.10, [0, 0]);
  drawSphericalCurve(tubeReflect, "mack_core", "#ffffff", 0.85, [0, 0]);

  // D. Pinpoint Starburst Glints on the Crown & Bevel Rim
  const glints = [
    projectBall(-0.66, -0.52, 0.998),
    projectBall(-0.42, -0.50, 0.998),
    projectBall(-0.11, -0.50, 0.998), // Left finger-hole bevel catch
    projectBall(0.23, -0.50, 0.998),  // Right finger-hole bevel catch
    projectBall(0.07, -0.13, 0.998)   // Thumb-hole bevel catch
  ];
  for (let g of glints) {
    if (!g.visible) continue;
    brush.set("mack_core", "#ffffff", 1.1);
    brush.line(g.x - 9, g.y, g.x + 9, g.y);
    brush.line(g.x, g.y - 9, g.x, g.y + 9);
    brush.set("mack_core", "#b8ecff", 0.75);
    brush.line(g.x - 5, g.y - 5, g.x + 5, g.y + 5);
    brush.line(g.x - 5, g.y + 5, g.x + 5, g.y - 5);
  }
}

function StepsOrDefault(s) {
  return s || 8;
}

// Hyperrealistic Dish-Soap Foam in a Brushed Steel Kitchen Sink
// Wet-in-wet opal watercolour washes & crisp graphite pencil arcs (p5.brush)

const SEED = 4281;

const PALETTE = {
  paper: "#edf2f6",
  steelDarkest: "#182026",
  steelDeep: "#28333c",
  steelShadow: "#3d4b56",
  steelMid: "#5c6b77",
  steelLight: "#8a99a6",
  steelBright: "#bac6d0",
  steelGleam: "#e2eaf0",

  milkBase: "#e4edf4",
  milkBright: "#f5f9fc",
  milkShadow: "#adc0cf",
  pureWhite: "#ffffff",

  // Opal play-of-colour (Peacock Blue primary accent + electric flashes)
  peacockDeep: "#005f7a",
  peacockMid: "#0091b5",
  peacockBright: "#00bfe0",
  peacockPale: "#6ce5f7",

  electricGreen: "#00d46a",
  chartreuse: "#7bf1a8",

  violetDeep: "#621b99",
  violetBright: "#9d4edd",
  magentaFlash: "#d06bf7",

  tangerine: "#ff6d00",
  amberGlow: "#ffaa1d",

  graphiteDark: "#222b33",
  graphiteMid: "#465461",
  graphiteLight: "#768694",
  graphiteFaint: "#9eadba"
};

let bubbles = [];
let microBubbles = [];
let septums = [];
let plateauNodes = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);

  randomSeed(SEED);
  noiseSeed(SEED);

  // Register custom brushes for specular glints, thin-film streaks, and fine froth
  brush.add("film_glaze", {
    type: "marker",
    weight: 4,
    scatter: 0.15,
    opacity: 28,
    spacing: 0.35,
    pressure: [0.3, 1.2, 0.3],
    markerTip: false,
    noise: 0.3
  });

  brush.add("razor_pencil", {
    type: "default",
    weight: 0.42,
    scatter: 0.04,
    sharpness: 0.88,
    grain: 0.45,
    opacity: 210,
    spacing: 0.12,
    pressure: [0.4, 1.15, 0.35],
    noise: 0.25
  });

  brush.add("specular_nib", {
    type: "default",
    weight: 0.85,
    scatter: 0.02,
    sharpness: 0.95,
    grain: 0.15,
    opacity: 250,
    spacing: 0.1,
    pressure: [0.6, 1.3, 0.5],
    noise: 0.1
  });

  brush.add("froth_stipple", {
    type: "spray",
    weight: 3.2,
    scatter: 2.4,
    opacity: 95,
    spacing: 0.45,
    pressure: [0.6, 1.1, 0.6],
    noise: 0.5
  });

  // Add a custom gentle sink-brush vector field
  brush.addField("steel_grain", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col / field.length;
        let ny = row / field[0].length;
        // Subtle sweeping curve of a pressed stainless steel sink basin
        let baseAngle = -16 + 14 * sin(nx * 140 - ny * 90) + 6 * cos(ny * 180);
        field[col][row] = baseAngle;
      }
    }
    return field;
  });

  buildFoamGeometry();
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.paper);

  // 1. Brushed Stainless Steel Sink Basin
  drawBrushedSteelSink();

  // 2. Recessed Steel Sink Drain / Strainer (Upper Right)
  drawSinkDrain(915, 255, 195, 0.66, -14);

  // 3. Cast Shadow & Iridescent Caustics of the Foam Pile on Wet Steel
  drawFoamShadowsAndCaustics();

  // 4. Dense Milky Under-Foam & Whipped Suds Banks
  drawMilkyUnderFoam();

  // 5. Wet-in-Wet Watercolour Opal Iridescence (Batched by Colour for Smooth Bleeds)
  drawBatchedOpalWashes();

  // 6. Internal Pressed Bubble Walls (Septums) & Plateau Border Menisci
  drawInternalFoamWalls();

  // 7. Outer Bubble Domes, Colored Pencil Iridescent Rims & Micro-Froth
  drawBubbleDomesAndRims();

  // 8. Hyperrealistic Warped Window Reflections & Specular Highlights
  drawSpecularReflections();

  // 9. Stray Water Droplets & Final Crisp Graphite Accents
  drawSurfaceDetails();

  noLoop();
}

// =============================================================================
// GEOMETRY GENERATION: 3D-Layered Soap Foam & Plateau Intersections
// =============================================================================
function buildFoamGeometry() {
  bubbles = [];
  microBubbles = [];
  septums = [];
  plateauNodes = [];

  // Define the main diagonal/curved ridge of piled soap foam in the sink
  // Sweeping from bottom-left (120, 1080) through center (560, 620) to lower-right (1050, 880)
  // and billowing up toward (380, 290)
  const heroCenters = [
    { x: 460, y: 580, r: 138, tier: 3, accent: "peacock" },
    { x: 645, y: 650, r: 124, tier: 3, accent: "green" },
    { x: 325, y: 725, r: 118, tier: 3, accent: "violet" },
    { x: 525, y: 795, r: 112, tier: 3, accent: "tangerine" },
    { x: 355, y: 455, r: 106, tier: 3, accent: "peacock" },
    { x: 750, y: 805, r: 108, tier: 3, accent: "peacock" },
    { x: 215, y: 575, r: 96, tier: 3, accent: "green" },
    { x: 605, y: 475, r: 94, tier: 3, accent: "tangerine" },
    { x: 425, y: 945, r: 104, tier: 3, accent: "violet" },
    { x: 220, y: 880, r: 98, tier: 3, accent: "peacock" },
    { x: 665, y: 950, r: 95, tier: 3, accent: "green" },
    { x: 875, y: 695, r: 88, tier: 3, accent: "violet" },
    { x: 255, y: 365, r: 84, tier: 3, accent: "peacock" },
    { x: 895, y: 885, r: 92, tier: 3, accent: "tangerine" },
    { x: 515, y: 355, r: 78, tier: 3, accent: "green" },
    { x: 125, y: 740, r: 86, tier: 3, accent: "violet" },
    { x: 745, y: 545, r: 76, tier: 3, accent: "peacock" },
    { x: 315, y: 1045, r: 82, tier: 3, accent: "tangerine" }
  ];

  for (let h of heroCenters) {
    bubbles.push({
      x: h.x + random(-8, 8),
      y: h.y + random(-8, 8),
      r: h.r * random(0.95, 1.05),
      tier: h.tier,
      accent: h.accent,
      rot: random(360),
      swirlDir: random() > 0.5 ? 1 : -1,
      id: bubbles.length
    });
  }

  // Pack medium bubbles (radii 34..68) into the foam mound
  const accents = ["peacock", "peacock", "green", "violet", "tangerine", "peacock"];
  let attempts = 0;
  while (bubbles.length < 66 && attempts < 2500) {
    attempts++;
    // Sample near existing bubbles or within the foam basin zone
    let anchor = random(bubbles);
    let ang = random(360);
    let rCand = map(pow(random(), 1.35), 0, 1, 32, 70);
    let distFactor = random(0.68, 0.96);
    let cx = anchor.x + cos(ang) * (anchor.r + rCand) * distFactor;
    let cy = anchor.y + sin(ang) * (anchor.r + rCand) * distFactor;

    // Keep out of the upper-right exposed steel drain zone
    let distToDrain = dist(cx, cy, 930, 240);
    if (distToDrain < 285 && random() < 0.92) continue;
    if (cx < 55 || cx > 1145 || cy < 130 || cy > 1150) continue;

    // Check packing constraints: allow realistic foam compression (0.64 to 0.95 of sum of radii)
    let valid = true;
    for (let b of bubbles) {
      let d = dist(cx, cy, b.x, b.y);
      let minD = (b.r + rCand) * 0.58;
      if (d < minD) {
        valid = false;
        break;
      }
    }
    if (valid) {
      bubbles.push({
        x: cx,
        y: cy,
        r: rCand,
        tier: 2,
        accent: random(accents),
        rot: random(360),
        swirlDir: random() > 0.5 ? 1 : -1,
        id: bubbles.length
      });
    }
  }

  // Pack smaller perimeter & crevice bubbles (radii 16..32)
  attempts = 0;
  while (bubbles.length < 105 && attempts < 2500) {
    attempts++;
    let anchor = random(bubbles);
    let ang = random(360);
    let rCand = random(16, 31);
    let distFactor = random(0.74, 1.02);
    let cx = anchor.x + cos(ang) * (anchor.r + rCand) * distFactor;
    let cy = anchor.y + sin(ang) * (anchor.r + rCand) * distFactor;

    if (dist(cx, cy, 930, 240) < 230 && random() < 0.85) continue;
    if (cx < 40 || cx > 1160 || cy < 95 || cy > 1165) continue;

    let valid = true;
    for (let b of bubbles) {
      let d = dist(cx, cy, b.x, b.y);
      if (d < (b.r + rCand) * 0.62) {
        valid = false;
        break;
      }
    }
    if (valid) {
      bubbles.push({
        x: cx,
        y: cy,
        r: rCand,
        tier: 1,
        accent: random(accents),
        rot: random(360),
        swirlDir: random() > 0.5 ? 1 : -1,
        id: bubbles.length
      });
    }
  }

  // Sort bubbles so smaller/deeper ones draw first and large hero domes crown the top,
  // with slight y-sorting for natural 3D overlap
  bubbles.sort((a, b) => (a.tier * 100 + a.r) - (b.tier * 100 + b.r));

  // Re-assign sorted indices
  for (let i = 0; i < bubbles.length; i++) bubbles[i].id = i;

  // Compute pairwise pressed bubble walls (Plateau septums)
  for (let i = 0; i < bubbles.length; i++) {
    for (let j = i + 1; j < bubbles.length; j++) {
      let b1 = bubbles[i];
      let b2 = bubbles[j];
      let d = dist(b1.x, b1.y, b2.x, b2.y);
      let rSum = b1.r + b2.r;

      if (d < rSum * 0.99 && d > abs(b1.r - b2.r) * 0.55) {
        let a = (b1.r * b1.r - b2.r * b2.r + d * d) / (2 * d);
        a = constrain(a, -b1.r * 0.92, b1.r * 0.92);
        let h = sqrt(max(4, b1.r * b1.r - a * a));

        let ux = (b2.x - b1.x) / d;
        let uy = (b2.y - b1.y) / d;
        let nx = -uy;
        let ny = ux;

        let mx = b1.x + a * ux;
        let my = b1.y + a * uy;

        let p1 = { x: mx + h * nx, y: my + h * ny };
        let p2 = { x: mx - h * nx, y: my - h * ny };

        // Young-Laplace pressure law: higher pressure inside smaller bubble bends wall toward larger bubble
        let bendDir = b1.r > b2.r ? -1 : 1;
        let ratioDiff = abs(b1.r - b2.r) / max(b1.r, b2.r);
        let bendAmt = h * (0.12 + 0.18 * ratioDiff) * bendDir;
        let mid = {
          x: mx + ux * bendAmt,
          y: my + uy * bendAmt
        };

        septums.push({
          p1,
          mid,
          p2,
          b1,
          b2,
          len: h * 2,
          nx: ux,
          ny: uy
        });

        plateauNodes.push({ x: p1.x, y: p1.y, r: constrain(h * 0.16, 3, 11) });
        plateauNodes.push({ x: p2.x, y: p2.y, r: constrain(h * 0.16, 3, 11) });
      }
    }
  }

  // Generate clusters of tiny micro-bubbles along Plateau borders and foam edges
  for (let node of plateauNodes) {
    let count = floor(random(2, 6));
    for (let k = 0; k < count; k++) {
      let ang = random(360);
      let rad = random(1.5, node.r * 1.4);
      microBubbles.push({
        x: node.x + cos(ang) * rad,
        y: node.y + sin(ang) * rad,
        r: random(2.2, 7.5)
      });
    }
  }

  // Add perimeter foam micro-bubbles where suds meet the wet steel
  for (let b of bubbles) {
    if (b.tier === 1 || random() < 0.35) {
      let n = floor(random(4, 10));
      let baseAng = random(360);
      for (let k = 0; k < n; k++) {
        let a = baseAng + random(-55, 55);
        let d = b.r + random(-4, 16);
        microBubbles.push({
          x: b.x + cos(a) * d,
          y: b.y + sin(a) * d,
          r: random(2.5, 9.5)
        });
      }
    }
  }
}

