    let ly = random(40, 1100);
    brush.set("2H", "#0b1320", random(0.3, 0.7));
    brush.line(lx, ly, lx + random(-8, 8), ly + random(60, 180));
  }

  // =========================================================================
  // 2. ANATOMICAL UNDERPAINTING OF THE NECK, HEAD & FAR WATTLE
  // =========================================================================
  const neckUnderSilhouette = [
    [590, 355], [465, 352], [355, 405], [240, 520],
    [130, 690], [52, 910], [28, 1195], [945, 1195],
    [905, 1005], [840, 845], [765, 685], [720, 505], [650, 410]
  ];
  brush.noStroke();
  brush.wash("#051214", 255);
  drawClosedShape(neckUnderSilhouette, 0.3);
  brush.noWash();

  // Deep sap-green & Prussian teal-black tonal bed for the hackles
  brush.noStroke();
  brush.fill("#0b261e", 150);
  brush.fillBleed(0.25, "in");
  brush.fillTexture(0.4, 0.15);
  drawClosedShape([
    [540, 365], [380, 420], [210, 610], [80, 920],
    [70, 1190], [890, 1190], [810, 860], [670, 530]
  ], 0.35);

  // Warm burnt-umber & deep vermilion glow along the upper dorsal arch of the neck
  brush.fill("#361207", 140);
  drawClosedShape([
    [560, 355], [440, 365], [310, 470], [180, 680],
    [100, 950], [360, 960], [500, 670], [610, 450]
  ], 0.35);
  brush.noFill();

  // =========================================================================
  // 3. PETRYKIVKA NECK HACKLES — LAYERED VERMILION, SAFFRON & SAP GREEN
  // =========================================================================
  // Helper to evaluate dorsal (left) and ventral (right) neck boundaries at any y
  function getNeckBounds(y) {
    let t = constrain((y - 345) / (1190 - 345), 0, 1);
    // Dorsal arch curves proudly left from x=465 at nape down to x=35 at bottom
    let xLeft = 468 - 435 * Math.pow(t, 0.82) + 18 * Math.sin(t * Math.PI);
    // Ventral edge sweeps from x=635 at throat out to x=935 at lower breast
    let xRight = 625 + 315 * Math.pow(t, 1.15);
    return { xLeft, xRight, t };
  }

  // Pass 3A: Deep Iridescent Plume Fans ("Hrebinchyk" / Onion-Frond Clusters) in Lower & Mid Neck
  // Built from bottom to top so upper cascades drape naturally over lower fans
  const fanRows = [1155, 1075, 995, 915, 835, 755, 675, 595];
  for (let r = 0; r < fanRows.length; r++) {
    let ry = fanRows[r];
    let { xLeft, xRight, t } = getNeckBounds(ry);
    let span = xRight - xLeft;
    let fanCount = Math.floor(map(r, 0, fanRows.length - 1, 6, 4));

    for (let f = 0; f < fanCount; f++) {
      let u = (f + 0.5 + (r % 2) * 0.35) / (fanCount + 0.4);
      if (u > 0.96) continue;
      let cx = xLeft + span * u + random(-14, 14);
      let cy = ry + random(-12, 12);

      // Center axis of this plume cluster tilts along the neck flow
      let baseAxis = map(u, 0, 1, 2.08, 1.38) + random(-0.08, 0.08);
      let plumeLen = map(t, 0.3, 1.0, 105, 165) * random(0.92, 1.08);

      // Determine local lighting (bright dorsal left -> iridescent mid -> cool shadow right/under wattle)
      let inWattleShadow = (cx > 540 && cy < 940);
      let lightFactor = constrain(1.0 - u * 0.95 - (inWattleShadow ? 0.35 : 0), 0.05, 1.0);

      // Fan of 5 paired Petrykivka comma strokes converging toward the plume shaft
      for (let k = -2; k <= 2; k++) {
        let side = k === 0 ? 1 : Math.sign(k);
        let offsetAngle = k * 0.21;
        let sx = cx + Math.cos(baseAxis - Math.PI * 0.5) * (k * 13);
        let sy = cy + Math.sin(baseAxis - Math.PI * 0.5) * (k * 13);
        let strokeLen = plumeLen * (1.0 - Math.abs(k) * 0.11);
        let bend = -side * (0.42 + Math.abs(k) * 0.08);

        let pts = buildCommaPath(sx, sy, baseAxis + offsetAngle, strokeLen, bend);

        // Choose sap green, viridian, vermilion, or saffron based on position in the fan & light
        let cBase, cBelly, cTail, cBead = null;
        if (Math.abs(k) === 2 || lightFactor < 0.38) {
          // Cool iridescent sap green & viridian outer/shadow strokes
          cBase = random(["#0b2b22", "#123d29", "#0d3338"]);
          cBelly = random(["#1e5c32", "#286e39", "#195752"]);
          cTail = random(["#439448", "#38876c", "#6eb85a"]);
          if (random() < 0.4) cBead = "#2f7d40";
        } else if (Math.abs(k) === 1) {
          // Sap green transitioning to vermilion or saffron
          if (lightFactor > 0.58) {
            cBase = random(["#c72214", "#d93018", "#215e2e"]);
            cBelly = random(["#eb491c", "#f07c14", "#39853e"]);
            cTail = random(["#ffb324", "#ffd147", "#5eb04e"]);
            cBead = "#ff6e24";
          } else {
            cBase = random(["#164728", "#8f1912", "#14423d"]);
            cBelly = random(["#297036", "#c93118", "#246b5c"]);
            cTail = random(["#52a149", "#f28d18", "#54ab8e"]);
          }
        } else {
          // Central lance of the plume: blazing saffron & vermilion or bright emerald
          if (lightFactor > 0.45) {
            cBase = random(["#d92b16", "#e85c12"]);
            cBelly = random(["#f59314", "#ffad1f"]);
            cTail = random(["#ffdc5e", "#e8f299"]);
            cBead = "#ffe36e";
          } else {
            cBase = "#19522c";
            cBelly = "#36823c";
            cTail = "#f29718";
            cBead = "#56ab4e";
          }
        }

        drawPetrykivkaComma(pts, cBase, cBelly, cTail, random(0.88, 1.15), cBead);
      }
    }
  }

  // Pass 3B: Primary Accumulation of Hundreds of Imbricated Lanceolate Comma Strokes
  // Sweeping from lower neck (y=1140) all the way up to the crown & nape (y=348)
  const totalTiers = 24;
  for (let tier = 0; tier < totalTiers; tier++) {
    let normTier = tier / (totalTiers - 1); // 0 = bottom (1140), 1 = top nape (348)
    let baseY = lerp(1140, 348, Math.pow(normTier, 0.92));
    let { xLeft, xRight, t } = getNeckBounds(baseY);

    // At the top near the face/eye (y < 520), feathers wrap behind the ear-lobe and facial skin
    if (baseY < 520) {
      xRight = map(baseY, 348, 520, 610, 565);
    } else if (baseY < 860) {
      // Tuck under the hanging wattles on the right
      xRight = Math.min(xRight, map(baseY, 520, 860, 660, 830));
    }

    let span = Math.max(80, xRight - xLeft);
    // Denser, smaller commas near the head; longer, sweeping commas down the cape
    let strokeCount = Math.floor(map(normTier, 0, 1, 21, 13));
    let stagger = (tier % 2) * 0.48;

    for (let i = -1; i <= strokeCount; i++) {
      let u = (i + stagger + random(-0.14, 0.14)) / strokeCount;
      if (u < -0.06 || u > 1.04) continue;

      let sx = xLeft + span * u;
      let sy = baseY + Math.sin(u * Math.PI) * 18 + random(-7, 7);

      // Compute anatomical flow direction & S/C-curve bend
      // On left dorsal contour (u ~ 0): arches out to the left and down (angle ~ 2.15 .. 2.45 rad)
      // In center of neck (u ~ 0.5): sweeps down-left (angle ~ 1.75 .. 2.05 rad)
      // On right breast/throat (u ~ 0.9): sweeps down-right (angle ~ 1.25 .. 1.55 rad)
      let flowAngle;
      if (baseY < 470) {
        // Crown & nape arch backward and downward from behind the comb
        flowAngle = map(u, 0, 1, 2.52, 2.05) + random(-0.08, 0.08);
      } else {
        flowAngle = map(u, 0, 1, 2.28, 1.32) + random(-0.09, 0.09);
      }

      let baseLen = map(normTier, 0, 1, 148, 54) * map(Math.abs(u - 0.35), 0, 0.7, 1.12, 0.84);
      let strokeLen = baseLen * random(0.88, 1.14);

      // Graceful Petrykivka comma bend: dorsal plumes flare outward at the tip, mid plumes curve rhythmically
      let bendDir = u < 0.22 ? 1 : (u > 0.78 ? -1 : (i % 2 === 0 ? 1 : -0.7));
      let bendAmount = bendDir * random(0.36, 0.68);

      let pts = buildCommaPath(sx, sy, flowAngle, strokeLen, bendAmount);

      // Photographic 3D lighting + Iridescent Color Layering (Vermilion, Saffron, Sap Green, Cool Teal)
      let inWattleShadow = (sx > 530 && sy > 480 && sy < 930);
      // Cylindrical highlight runs along u = 0.12 .. 0.45 and high up on the nape/crown
      let cylinderLight = Math.exp(-Math.pow((u - 0.26) / 0.36, 2));
      let heightLight = map(normTier, 0, 1, 0.65, 1.05);
      let lum = cylinderLight * heightLight * (inWattleShadow ? 0.42 : 1.0);

      let wScale = map(normTier, 0, 1, 1.12, 0.64) * random(0.88, 1.12);

      // Layering logic: interweave Sap Green, Vermilion, and Saffron so all three build the iridescence
      let roll = (i * 7 + tier * 3) % 10;
      let cBase, cBelly, cTail, cBead = null;

      if (lum > 0.68) {
        // Sunlit Nape & Dorsal Ridge: Blazing Saffron & Vermilion with Sap Green iridescent roots
        if (roll < 4) {
          // Saffron-gold comma with vermilion drop bead
          cBase = random(["#e06b0e", "#eb8410", "#d44d12"]);
          cBelly = random(["#ffad19", "#ffc429", "#ffa014"]);
          cTail = random(["#ffe875", "#fff2a6", "#d9f285"]);
          cBead = random(["#d92514", "#fff099"]);
        } else if (roll < 8) {
          // Fiery Vermilion comma tapering to glowing Saffron tail
          cBase = random(["#b81812", "#d42616", "#e03419"]);
          cBelly = random(["#f2481d", "#ff5e24", "#eb3b18"]);
          cTail = random(["#ffb824", "#ffd447", "#ff9519"]);
          cBead = "#ffad24";
        } else {
          // Sunlit Sap Green iridescent comma woven right through the gold & vermilion
          cBase = random(["#194f28", "#205e2e"]);
          cBelly = random(["#36853b", "#459944"]);
          cTail = random(["#8cd158", "#ffcf40"]);
          cBead = "#6ec252";
        }
      } else if (lum > 0.36) {
        // Mid-Neck Iridescent Zone: Equal interplay of Sap Green, Vermilion, and Saffron
        if (roll < 4) {
          // Rich Sap Green comma with emerald or saffron tip
          cBase = random(["#0f3820", "#174a28", "#124238"]);
          cBelly = random(["#266e35", "#32803b", "#206954"]);
          cTail = random(["#5cb04e", "#80c958", "#f5a61b"]);
          cBead = random(["#439645", "#eb8a14"]);
        } else if (roll < 7) {
          // Vermilion -> Sap Green / Saffron transitional comma
          cBase = random(["#9e1712", "#bd2216", "#cf2d18"]);
          cBelly = random(["#e34219", "#eb5a1c", "#b85c16"]);
          cTail = random(["#ff9e19", "#469442", "#ffc436"]);
          cBead = "#ff6a21";
        } else {
          // Deep Saffron -> Vermilion -> Emerald comma
          cBase = random(["#245e2e", "#b54810"]);
          cBelly = random(["#e88b14", "#f5a318"]);
          cTail = random(["#ffd859", "#52a64b"]);
          cBead = "#ffc938";
        }
      } else {
        // Cool Shadow Zone (Under Wattles, Lower Breast, Deep Plume Recesses)
        if (roll < 6) {
          // Deep Sap Green & Cool Viridian-Teal comma strokes
          cBase = random(["#061c1c", "#0a2922", "#0d3028"]);
          cBelly = random(["#154a34", "#1d5c33", "#165254"]);
          cTail = random(["#328243", "#388c76", "#54a662"]);
          if (random() < 0.35) cBead = "#29754d";
        } else if (roll < 8) {
          // Smoldering Vermilion ember in the dark green shadow
          cBase = random(["#590b10", "#781214"]);
          cBelly = random(["#ab2016", "#c72d18"]);
          cTail = random(["#e86f17", "#2e7338"]);
        } else {
          // Dark Olive-Gold / Saffron glint in shadow
          cBase = "#143822";
          cBelly = "#8c520f";
          cTail = "#d98c16";
        }
      }

      drawPetrykivkaComma(pts, cBase, cBelly, cTail, wScale, cBead);

      // Companion secondary comma stroke tucked beside major dorsal & mid-neck plumes for extra richness
      if (u < 0.55 && random() < 0.58) {
        let subAngle = flowAngle + (bendDir * 0.14);
        let subPts = buildCommaPath(
          sx + random(6, 13),
          sy + random(4, 10),
          subAngle,
          strokeLen * 0.76,
          bendAmount * 1.12
        );
        let scBase = roll % 2 === 0 ? "#1b592e" : "#cf2917";
