    [[758, 535], [802, 645], [812, 755], [778, 848]],
    [[695, 545], [722, 665], [725, 785], [705, 875]],
    [[632, 555], [645, 665], [648, 775], [638, 825]]
  ];
  for (let crest of wattleCrests) {
    brush.set("waxy_glaze", "#e09eb5", 0.65);
    brush.spline(crest, 0.45);
