      let gx = pt[0] + random(-8, 8);
      let gy = pt[1] + random(-8, 8);
      brush.set("comma_body", random(["#eb9eb8", "#cfdcf2", "#f2f7ff"]), random(0.18, 0.34));
      brush.line(gx, gy, gx + random(-2, 2), gy + random(-3, 3));
