    if (t < 0.45) {
      let u = t / 0.45;
      ax = lerp(585, 468, u) + random(-10, 10);
      ay = lerp(355, 425, u) + random(-8, 8);
      aAngle = lerp(2.55, 2.25, u) + random(-0.1, 0.1);
      aLen = random(42, 68);
    } else {
      let u = (t - 0.45) / 0.55;
      ax = lerp(485, 595, u) + random(-12, 12);
      ay = lerp(455, 645, u) + random(-10, 10);
      // Avoid covering the white ear-lobe center (538, 528)
      if (dist(ax, ay, 538, 528) < 48) {
        ax -= 42;
      }
      aAngle = lerp(2.22, 1.85, u) + random(-0.1, 0.1);
      aLen = random(48, 82);
    }

    let pts = buildCommaPath(ax, ay, aAngle, aLen, random(0.35, 0.62));
    if (i % 3 === 0) {
      drawPetrykivkaComma(pts, "#d92816", "#ff6e1f", "#ffe36e", 0.58, "#ffba26");
    } else if (i % 3 === 1) {
      drawPetrykivkaComma(pts, "#eb8412", "#ffc229", "#fff29c", 0.55, "#d42214");
    } else {
      drawPetrykivkaComma(pts, "#164f28", "#34853b", "#82cf56", 0.56, "#f5a318");
    }
