  // Tiny sparse black & scarlet bristle filoplumes on the bare facial lore & below the eye
  for (let i = 0; i < 65; i++) {
    let fx = random(595, 765);
    let fy = random(375, 495);
    if (dist(fx, fy, 650, 435) < 40) continue; // Keep clear of the eye bead
