  // =========================================================================
  // 11. THE EYE — GLOSSY AMBER BEAD WITH PINPOINT WINDOW REFLECTION
  // =========================================================================
  const EX = 650;
  const EY = 435;

  // 1. Leathery dark charcoal-plum & scarlet eyelid ring
  brush.noStroke();
  brush.wash("#1a0910", 255);
  brush.circle(EX, EY, 39, 0.08);
  brush.noWash();

  // 28 fleshy eyelid rim tubercles catching cool specular light
  for (let i = 0; i < 28; i++) {
