  // Dark glass-bead limbal shadow ring around the outer iris circumference
  for (let i = 0; i < 24; i++) {
    let a1 = (i / 24) * Math.PI * 2;
    let a2 = ((i + 1.2) / 24) * Math.PI * 2;
    brush.set("vein_brush", "#080304", 0.85);
    brush.spline([
      [EX + Math.cos(a1) * 30.5, EY + Math.sin(a1) * 30.5],
      [EX + Math.cos((a1 + a2) * 0.5) * 31.2, EY + Math.sin((a1 + a2) * 0.5) * 31.2],
      [EX + Math.cos(a2) * 30.5, EY + Math.sin(a2) * 30.5]
