    brush.line(px1, py1, px2, py2);
  }

  // 6. PINPOINT REFLECTION OF A WINDOW ON THE GLOSSY CORNEAL DOME
  // Positioned on the upper-right corneal curvature (EX + 8, EY - 11)
  // A crisp, slightly curved 4-pane casement window reflection + secondary wet tear-film arc
  const wx = EX + 6;
  const wy = EY - 13;

  // Soft cool sky-blue corneal bloom around the window reflection
  brush.noStroke();
  brush.fill("#8cb8eb", 95);
  brush.fillBleed(0.18, "out");
  brush.circle(wx + 4, wy + 4, 11, 0.05);
  brush.noFill();

  // Four curved miniature window panes in cool daylight sky-white (#d8ecff -> #ffffff)
  const panes = [
    // Top-left pane
    [[wx - 4.5, wy - 4.0], [wx + 0.8, wy - 5.2], [wx + 1.2, wy - 0.5], [wx - 4.2, wy + 0.4]],
    // Top-right pane
    [[wx + 2.6, wy - 5.5], [wx + 7.8, wy - 4.2], [wx + 8.2, wy + 0.4], [wx + 2.8, wy - 0.5]],
    // Bottom-left pane
    [[wx - 4.0, wy + 2.0], [wx + 1.2, wy + 1.2], [wx + 1.5, wy + 5.8], [wx - 3.4, wy + 6.4]],
    // Bottom-right pane
    [[wx + 2.8, wy + 1.2], [wx + 8.2, wy + 2.0], [wx + 7.6, wy + 6.5], [wx + 3.0, wy + 5.8]]
  ];

  brush.noStroke();
  for (let p = 0; p < panes.length; p++) {
    brush.wash(p < 2 ? "#f2f8ff" : "#cbe2fa", 255);
    drawClosedShape(panes[p], 0.15);
  }
  brush.noWash();

  // Crisp pure-white pinpoint flare on the upper window panes
  brush.set("comma_filament", "#ffffff", 0.72);
  brush.line(wx - 3.8, wy - 3.6, wx + 0.4, wy - 4.6);
  brush.line(wx + 3.0, wy - 4.8, wx + 7.2, wy - 3.6);
  brush.set("comma_body", "#ffffff", 0.28);
  brush.line(wx - 2.0, wy - 2.8, wx - 0.5, wy - 3.2);

  // Secondary wet tear-meniscus reflection along the bottom-left rim of the cornea
  brush.set("comma_filament", "#b8d4f2", 0.45);
  brush.spline([
    [EX - 21, EY + 21],
    [EX - 12, EY + 27],
    [EX - 1, EY + 29],
    [EX + 9, EY + 27]
  ], 0.5);
  // Pinpoint tear-duct sparkle
  brush.set("comma_body", "#ffffff", 0.24);
  brush.line(EX + 27, EY + 14, EX + 28.5, EY + 14.5);

  noLoop();
}

