// ============================================================================
// SAFE P5.BRUSH PRIMITIVE HELPERS
// ============================================================================

function resetBrushState() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
}

function washPoly(pts, col, opacity = 255, curvature = 0) {
  if (!pts || pts.length < 3) return;
  resetBrushState();
  brush.wash(col, opacity);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrushState();
}

function watercolorPoly(pts, col, opacity = 110, bleed = 0.14, tex = 0.38, border = 0.25, curvature = 0) {
  if (!pts || pts.length < 3) return;
  resetBrushState();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrushState();
}

function hatchPoly(pts, brushName, col, weight, dist, angle, opts = {}, curvature = 0) {
  if (!pts || pts.length < 3) return;
  resetBrushState();
  brush.hatchStyle(brushName, col, weight);
  brush.hatch(dist, angle, opts);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrushState();
}

function strokePoly(pts, brushName, col, weight = 1, closed = true, curvature = 0) {
  if (!pts || pts.length < 2) return;
  resetBrushState();
  brush.set(brushName, col, weight);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
  resetBrushState();
}

function drawLine(x1, y1, x2, y2, brushName, col, weight = 1) {
  resetBrushState();
  brush.set(brushName, col, weight);
  brush.line(x1, y1, x2, y2);
  resetBrushState();
}

function drawSpline(pts, brushName, col, weight = 1, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  resetBrushState();
  brush.set(brushName, col, weight);
  brush.spline(pts, curvature);
  resetBrushState();
}

function drawCircleWash(x, y, r, col, opacity = 255) {
  resetBrushState();
  brush.wash(col, opacity);
  brush.circle(x, y, r, 0.03);
  resetBrushState();
}

// ============================================================================
// 2-POINT PERSPECTIVE PANEL ENGINE
// ============================================================================

function makePanel(x0, yTop0, yBot0, x1, vx, vy, depthRatio = 1.0) {
  return { x0, yTop0, yBot0, x1, vx, vy, depthRatio };
}

function panelPt(p, s, t) {
  let sp = p.depthRatio === 1.0 ? s : (s * p.depthRatio) / (1 + s * (p.depthRatio - 1));
  let x = p.x0 + (p.x1 - p.x0) * sp;
  let yAtX0 = p.yTop0 + (p.yBot0 - p.yTop0) * t;
  let y = p.vy + (yAtX0 - p.vy) * ((x - p.vx) / (p.x0 - p.vx));
  return [x, y];
}

function panelQuad(p, s0, t0, s1, t1) {
  return [
    panelPt(p, s0, t0),
    panelPt(p, s1, t0),
    panelPt(p, s1, t1),
    panelPt(p, s0, t1)
  ];
}

