// ============================================================================
// 2. TOWERING CUMULUS CLOUD (OPAQUE WATERCOLOR / GOUACHE)
// ============================================================================

function buildBillowPoly(lobes, baseY, stepsPerLobe = 10, seedOffset = 0) {
  let pts = [];
  let first = lobes[0];
  let last = lobes[lobes.length - 1];

  // Start at bottom-left of cloud mass
  pts.push([first.x - first.r * 0.85, baseY]);

  for (let i = 0; i < lobes.length; i++) {
    let L = lobes[i];
    let aStart = L.a0 !== undefined ? L.a0 : 195;
    let aEnd = L.a1 !== undefined ? L.a1 : 345;
    for (let s = 0; s <= stepsPerLobe; s++) {
      let t = s / stepsPerLobe;
      let ang = aStart + (aEnd - aStart) * t;
      // Add subtle cauliflower sub-billows along the arc
      let subBump = 1 + 0.08 * sin(t * 360 * 2.5 + i * 47 + seedOffset)
                      + 0.05 * (noise(i * 3.1 + t * 2.4, seedOffset * 0.1) - 0.5);
      let rx = L.r * subBump;
      let ry = (L.ry || L.r * 0.92) * subBump;
      let px = L.x + cos(ang) * rx;
      let py = L.y + sin(ang) * ry;
      pts.push([px, py]);
    }
  }

  // Close along a sculpted flat/scalloped cumulus underside
  pts.push([last.x + last.r * 0.85, baseY]);
  let spanX = (last.x + last.r * 0.85) - (first.x - first.r * 0.85);
  for (let b = 1; b <= 6; b++) {
    let bt = 1 - b / 7;
    let bx = (first.x - first.r * 0.85) + spanX * bt;
    let by = baseY + sin(b * 65 + seedOffset) * 8;
    pts.push([bx, by]);
  }

  return pts;
}

function drawCloudTurret(lobes, baseY, opts = {}) {
  let dx = opts.shadowDx !== undefined ? opts.shadowDx : 16;
  let dy = opts.shadowDy !== undefined ? opts.shadowDy : 20;
  let seed = opts.seed || 10;

  let mainPts = buildBillowPoly(lobes, baseY, 10, seed);
  let shadowPts = mainPts.map(p => [p[0] + dx, min(baseY + dy * 0.8, p[1] + dy)]);
  let midPts = mainPts.map(p => [p[0] + dx * 0.45, min(baseY + dy * 0.35, p[1] + dy * 0.42)]);

  // 1. Crisp Lilac Underside & Deep Shadow Mass
  washPoly(shadowPts, opts.lilacDark || "#766598", 235, 0.12);
  watercolorPoly(shadowPts, opts.lilacMid || "#8b78ab", 95, 0.08, 0.35, 0.35, 0.12);

  // 2. Warm Mauve / Apricot Bounce Transition
  washPoly(midPts, opts.warmMid || "#cbb7d9", 225, 0.12);
  let warmRimPts = mainPts.map(p => [p[0] + 4, p[1] + 5]);
  washPoly(warmRimPts, opts.apricot || "#f7e2c6", 230, 0.12);

  // 3. Saturated Titanium White / Warm Cream Sunlit Gouache Mass
  washPoly(mainPts, opts.whiteCol || "#fffaf0", 250, 0.12);
  watercolorPoly(mainPts, "#ffffff", 110, 0.04, 0.25, 0.2, 0.12);

  // 4. Internal Sculpted Florets (brightest sunlit upper-left crowns)
  for (let i = 0; i < lobes.length; i++) {
    let L = lobes[i];
    if (L.r < 28) continue;
    let crownLobes = [
      { x: L.x - L.r * 0.22, y: L.y - L.r * 0.12, r: L.r * 0.58, a0: 185, a1: 335 },
      { x: L.x + L.r * 0.15, y: L.y - L.r * 0.05, r: L.r * 0.48, a0: 205, a1: 350 }
    ];
    let crownPts = buildBillowPoly(crownLobes, L.y + L.r * 0.38, 7, seed + i * 19);
    // Subtle lilac shadow tuck under internal floret
    let tuckPts = crownPts.map(p => [p[0] + 7, p[1] + 9]);
    washPoly(tuckPts, opts.lilacLight || "#a996c7", 170, 0.1);
    washPoly(crownPts, "#fffdf9", 250, 0.1);

    // Dry-brush gouache texture along sunlit rim
    let rimArc = [];
    for (let a = 195; a <= 315; a += 20) {
      rimArc.push([
        L.x + cos(a) * L.r * 0.98,
        L.y + sin(a) * (L.ry || L.r * 0.92) * 0.98
      ]);
    }
    drawSpline(rimArc, "cloud_puff", "#ffffff", 0.55, 0.5);
    drawSpline(rimArc, "fine_liner", "#fffef9", 0.35, 0.5);
  }
}

