function drawWeedCluster(cx, cy, scale = 1.0, count = 12) {
  // Base shadow tuft
  drawCircleWash(cx, cy + 2 * scale, 18 * scale, "#394f29", 210);
  drawCircleWash(cx - 4 * scale, cy - 3 * scale, 15 * scale, "#5c8032", 220);

  // Grass blades & sunlit foxtails
  for (let i = 0; i < count; i++) {
    let ang = -65 + (i / max(1, count - 1)) * 130 + random(-10, 10);
    let len = (18 + random(24)) * scale;
    let tx = cx + sin(ang) * len * 0.8;
    let ty = cy - cos(ang) * len;
    let mx = (cx + tx) * 0.5 + sin(ang) * 4 * scale;
    let my = (cy + ty) * 0.5 - 4 * scale;

    let col = i % 3 === 0 ? "#436327" : (i % 3 === 1 ? "#7da636" : "#c7d952");
    drawSpline([[cx + random(-8, 8) * scale, cy], [mx, my], [tx, ty]], "fine_liner", col, 0.42 * scale, 0.4);

    // Golden-green foxtail plume on select tall stems
    if (i % 4 === 1 && scale > 0.55) {
      let fx = tx + sin(ang) * 7 * scale;
      let fy = ty - cos(ang) * 5 * scale;
      drawLine(tx, ty, fx, fy, "gouache_flat", "#d9e368", 0.55 * scale);
      drawLine(tx + 1, ty + 1, fx + 1, fy + 1, "fine_liner", "#8fa834", 0.35 * scale);
    }
  }
}

