function drawSinglePole(cx, yTop, yBot, baseW, isHero) {
  let topW = baseW * 0.62;
  let xLTop = cx - topW * 0.5;
  let xRTop = cx + topW * 0.5;
  let xLBot = cx - baseW * 0.5;
  let xRBot = cx + baseW * 0.5;

  // Sunlit left concrete face
  washPoly([
    [xLTop, yTop], [cx, yTop], [cx, yBot], [xLBot, yBot]
  ], "#efe2ce", 250);

  // Shaded right lilac-grey concrete face
  washPoly([
    [cx, yTop], [xRTop, yTop], [xRBot, yBot], [cx, yBot]
  ], "#7f758c", 250);

  // Crisp technical pen outlines
  drawLine(xLTop, yTop, xLBot, yBot, "fine_liner", "#fffaf0", 0.35);
  drawLine(xRTop, yTop, xRBot, yBot, "fine_liner", "#4a4257", 0.4);

  // Crossarms near the top
  let armY1 = yTop + (yBot - yTop) * 0.075;
  let armY2 = yTop + (yBot - yTop) * 0.135;
  let armSpan = baseW * 3.4;

  for (let ay of [armY1, armY2]) {
    drawLine(cx - armSpan * 0.55, ay - baseW * 0.18, cx + armSpan * 0.45, ay + baseW * 0.14, "fine_liner", "#454857", 0.12 * baseW);
    drawLine(cx - armSpan * 0.55, ay - baseW * 0.18 - 1, cx + armSpan * 0.45, ay + baseW * 0.14 - 1, "fine_liner", "#dfe6ed", 0.05 * baseW);

    // White ceramic insulators
    for (let u of [-0.48, -0.22, 0.18, 0.4]) {
      let ix = cx + armSpan * u;
      let iy = ay + u * baseW * 0.32;
      drawCircleWash(ix, iy - baseW * 0.12, max(1.5, baseW * 0.14), "#ffffff", 250);
    }
  }

  if (!isHero) return;

  // HERO POLE DETAILS:
  // Galvanized steel mounting bands
  for (let by of [115, 168, 225, 315, 420, 560, 710]) {
    let hw = lerp(topW, baseW, (by - yTop) / (yBot - yTop)) * 0.52;
    drawLine(cx - hw, by, cx + hw, by, "fine_liner", "#4b4e5e", 0.55);
    drawLine(cx - hw, by - 1, cx, by - 1, "fine_liner", "#e8eef5", 0.35);
  }

  // Alternating foot-step climbing bolts sticking out left & right
  for (let sy = 190; sy < 760; sy += 34) {
    let side = ((sy / 34) % 2 === 0) ? -1 : 1;
    let hw = lerp(topW, baseW, (sy - yTop) / (yBot - yTop)) * 0.5;
    let bx1 = cx + side * hw;
    let bx2 = bx1 + side * 7;
    drawLine(bx1, sy, bx2, sy, "fine_liner", "#434554", 0.42);
    drawLine(bx2, sy, bx2, sy - 4, "fine_liner", "#434554", 0.42);
  }

  // Cylindrical Grey Pole-Mounted Transformer (y = 225..310)
  const tx = cx - 26;
  const ty = 228;
  const tw = 34;
  const th = 76;
  // Transformer shadow on pole
  washPoly([[cx - 4, ty + 8], [cx + 8, ty + 8], [cx + 8, ty + th + 6], [cx - 4, ty + th + 6]], "#524961", 220);
  // Transformer cylinder body (sunlit left, shaded right)
  washPoly([[tx, ty], [tx + tw * 0.55, ty], [tx + tw * 0.55, ty + th], [tx, ty + th]], "#d5dce3", 250);
  washPoly([[tx + tw * 0.55, ty], [tx + tw, ty], [tx + tw, ty + th], [tx + tw * 0.55, ty + th]], "#7b8394", 250);
  // Top & bottom elliptical caps
  washPoly([[tx - 2, ty - 3], [tx + tw + 2, ty - 3], [tx + tw, ty + 4], [tx, ty + 4]], "#eef4f7", 250);
  washPoly([[tx, ty + th - 2], [tx + tw, ty + th - 2], [tx + tw - 2, ty + th + 4], [tx + 2, ty + th + 4]], "#555c6b", 250);
  // Cooling fins & high-voltage bushings on top of transformer
  for (let fx = tx + 5; fx < tx + tw - 4; fx += 5) {
    drawLine(fx, ty + 10, fx, ty + th - 8, "fine_liner", "#5a6273", 0.35);
  }
  drawLine(tx + 9, ty - 3, tx + 7, ty - 16, "fine_liner", "#6b4c3e", 0.65);
  drawLine(tx + 24, ty - 3, tx + 26, ty - 16, "fine_liner", "#6b4c3e", 0.65);
  strokePoly([[tx, ty], [tx + tw, ty], [tx + tw, ty + th], [tx, ty + th]], "fine_liner", "#3f4452", 0.4, true);

  // Yellow & Black Diagonal Warning Sheath on Lower Pole (y = 755..875)
  const wy0 = 755, wy1 = 875;
  washPoly([[cx - 8.5, wy0], [cx + 8.5, wy0], [cx + 9, wy1], [cx - 9, wy1]], "#f2b824", 245);
  for (let sy = wy0 + 8; sy < wy1 - 4; sy += 14) {
    washPoly([
      [cx - 8.8, sy], [cx + 8.8, sy - 7],
      [cx + 8.8, sy - 1], [cx - 8.8, sy + 6]
    ], "#26232b", 240);
  }
}

