// ============================================================================
// PRODUCT SHELF, CAN/BOTTLE RENDERER & PERSPECTIVE MICRO-TYPOGRAPHY
// ============================================================================

function drawProductShelf(frontP, tTop, tBot, specs) {
  let numSlots = specs.length;
  let sStart = 0.072;
  let sEnd = 0.862;
  let slotW = (sEnd - sStart) / numSlots;

  let tCanBottom = tTop + (tBot - tTop) * 0.72;
  let tRailBottom = tTop + (tBot - tTop) * 0.85;
  let tBtnBottom = tBot;

  // Metallic horizontal shelf plate behind cans
  washPoly(panelQuad(frontP, 0.065, tCanBottom - 0.008, 0.920, tCanBottom + 0.008), "#b8c2cc", 250);

  for (let i = 0; i < numSlots; i++) {
    let spec = specs[i];
    let s0 = sStart + i * slotW + slotW * 0.09;
    let s1 = sStart + (i + 1) * slotW - slotW * 0.09;
    let sMid = (s0 + s1) * 0.5;

    // Determine vertical top of can/bottle based on type
    let itemTop = tTop + (tCanBottom - tTop) * (spec.type === "short" ? 0.22 : (spec.type === "can" ? 0.10 : 0.0));

    if (spec.type === "bottle") {
      // PET Bottle: Lower body + tapered shoulder + narrow neck + colored cap
      let tShoulder = itemTop + (tCanBottom - itemTop) * 0.30;
      let tNeck = itemTop + (tCanBottom - itemTop) * 0.12;
      let sNeck0 = sMid - (s1 - s0) * 0.22;
      let sNeck1 = sMid + (s1 - s0) * 0.22;

      // Bottle body & shoulder
      let bottlePoly = [
        panelPt(frontP, sNeck0, tNeck),
        panelPt(frontP, sNeck1, tNeck),
        panelPt(frontP, s1, tShoulder),
        panelPt(frontP, s1, tCanBottom),
        panelPt(frontP, s0, tCanBottom),
        panelPt(frontP, s0, tShoulder)
      ];
      washPoly(bottlePoly, spec.col, 248);

      // Sunlit left cylindrical highlight & right shadow
      washPoly(panelQuad(frontP, s0 + (s1 - s0) * 0.08, tShoulder, s0 + (s1 - s0) * 0.28, tCanBottom), "#ffffff", 95);
      washPoly(panelQuad(frontP, s1 - (s1 - s0) * 0.24, tShoulder, s1, tCanBottom), "#1d222e", 75);

      // Colored plastic bottle cap
      washPoly(panelQuad(frontP, sNeck0 - 0.002, itemTop, sNeck1 + 0.002, tNeck), spec.cap, 250);
      strokePoly(bottlePoly, "fine_liner", "#2b303d", 0.3, true);
    } else {
      // Aluminum Beverage Can (Tall or Short)
      let canQuad = panelQuad(frontP, s0, itemTop, s1, tCanBottom);
      washPoly(canQuad, spec.col, 250);

      // Cylindrical specular highlight on left & roll-off shadow on right
      washPoly(panelQuad(frontP, s0 + (s1 - s0) * 0.08, itemTop, s0 + (s1 - s0) * 0.26, tCanBottom), "#ffffff", 105);
      washPoly(panelQuad(frontP, s1 - (s1 - s0) * 0.25, itemTop, s1, tCanBottom), "#171821", 85);

      // Silver metallic top rim & pull-tab glint
      washPoly(panelQuad(frontP, s0 + 0.002, itemTop - 0.005, s1 - 0.002, itemTop + 0.006), spec.cap, 250);
      let rimL = panelPt(frontP, s0 + 0.002, itemTop);
      let rimR = panelPt(frontP, s1 - 0.002, itemTop);
      drawLine(rimL[0], rimL[1], rimR[0], rimR[1], "fine_liner", "#ffffff", 0.42);
      strokePoly(canQuad, "fine_liner", "#282a36", 0.3, true);
    }

    // Distinct Label Band & Graphic Motif on Every Can/Bottle!
    let tBand0 = itemTop + (tCanBottom - itemTop) * 0.34;
    let tBand1 = itemTop + (tCanBottom - itemTop) * 0.76;

    if (spec.motif === "wave") {
      // Classic Cola white dynamic wave ribbon
      let wPts = [
        panelPt(frontP, s0, tBand0 + 0.015),
        panelPt(frontP, sMid, tBand0 + 0.004),
        panelPt(frontP, s1, tBand0 + 0.018),
        panelPt(frontP, s1, tBand0 + 0.026),
        panelPt(frontP, sMid, tBand0 + 0.012),
        panelPt(frontP, s0, tBand0 + 0.023)
      ];
      washPoly(wPts, "#ffffff", 245);
      drawPanelText(frontP, spec.text, s0 + 0.004, itemTop + 0.012, s1 - 0.004, tBand0 + 0.002, "#ffffff", 0.25);
    } else if (spec.motif === "kanji") {
      // Vertical scroll label (Green Tea / Oolong / Red Bean)
      let vQuad = panelQuad(frontP, sMid - (s1 - s0) * 0.26, itemTop + (tCanBottom - itemTop) * 0.24, sMid + (s1 - s0) * 0.26, tCanBottom - 0.008);
      washPoly(vQuad, spec.band, 245);
      // Crisp vertical kanji strokes + red hanko seal dot
      let kTop = panelPt(frontP, sMid, itemTop + (tCanBottom - itemTop) * 0.32);
      let kBot = panelPt(frontP, sMid, tCanBottom - 0.018);
      drawLine(kTop[0], kTop[1], kBot[0], kBot[1], "fine_liner", spec.bandCol, 0.38);
      drawLine(kTop[0] - 2.5, (kTop[1] + kBot[1]) * 0.48, kTop[0] + 2.5, (kTop[1] + kBot[1]) * 0.48, "fine_liner", spec.bandCol, 0.32);
      drawCircleWash(kBot[0] + 1.5, kBot[1] + 2, 1.8, "#d93226", 245);
    } else {
      // Horizontal / Badge Brand Label
      washPoly(panelQuad(frontP, s0 + 0.001, tBand0, s1 - 0.001, tBand1), spec.band, 245);

      if (spec.motif === "circle" || spec.motif === "oval") {
        let cPt = panelPt(frontP, sMid, (tBand0 + tBand1) * 0.5);
        drawCircleWash(cPt[0], cPt[1], (s1 - s0) * 115, spec.bandCol, 220);
      } else if (spec.motif === "diamond" || spec.motif === "mtn") {
        let mPts = [
          panelPt(frontP, sMid, tBand0 + 0.003),
          panelPt(frontP, s1 - 0.005, tBand1 - 0.003),
          panelPt(frontP, s0 + 0.005, tBand1 - 0.003)
        ];
        washPoly(mPts, spec.bandCol, 225);
      }

      // Micro brand lettering on the label band
      let txtCol = (spec.motif === "circle" || spec.motif === "oval" || spec.motif === "diamond" || spec.motif === "mtn")
        ? "#ffffff" : spec.bandCol;
      drawPanelText(frontP, spec.text, s0 + 0.004, tBand0 + 0.005, s1 - 0.004, tBand1 - 0.005, txtCol, 0.24);
    }

    // Clear plastic lower holder clip at base of each beverage
    washPoly(panelQuad(frontP, s0 - 0.002, tCanBottom - 0.010, s1 + 0.002, tCanBottom), "#dce6ed", 175);

    // Price & Temperature Strip directly below the shelf (Blue = COLD, Red-Orange = HOT)
    let railCol = spec.hot ? "#d94126" : "#1e6eb8";
    washPoly(panelQuad(frontP, s0 - 0.004, tCanBottom, s1 + 0.004, tRailBottom), railCol, 250);
    // White price tag box on right half of slot
    washPoly(panelQuad(frontP, sMid - 0.002, tCanBottom + 0.003, s1 + 0.002, tRailBottom - 0.003), "#ffffff", 250);
    drawPanelText(frontP, spec.price, sMid, tCanBottom + 0.004, s1, tRailBottom - 0.004, "#1e1d26", 0.20);

    // Black Oblong Selection Push-Button with Green LED (or Red SOLD OUT LED)
    let btnQuad = panelQuad(frontP, s0 + 0.002, tRailBottom + 0.003, s1 - 0.002, tBtnBottom - 0.002);
    washPoly(btnQuad, "#22212b", 250);
    // Glossy top highlight on push button
    let bTopL = panelPt(frontP, s0 + 0.004, tRailBottom + 0.005);
    let bTopR = panelPt(frontP, s1 - 0.004, tRailBottom + 0.005);
    drawLine(bTopL[0], bTopL[1], bTopR[0], bTopR[1], "fine_liner", "#8a92a3", 0.3);

    // Tiny glowing LED indicator dot inside the button
    let ledPt = panelPt(frontP, sMid, (tRailBottom + tBtnBottom) * 0.5);
    drawCircleWash(ledPt[0], ledPt[1], 1.8, spec.soldOut ? "#ff3b2e" : "#5cff79", 250);
  }

  // Shelf divider rail lines
  let rL = panelPt(frontP, 0.065, tCanBottom);
  let rR = panelPt(frontP, 0.875, tCanBottom);
  drawLine(rL[0], rL[1], rR[0], rR[1], "fine_liner", "#353845", 0.42);
}

