function drawSpecularOverlapsAndFilmFinish(bagCX, bagCY, bagAngle) {
  // 1. Explicit additive density highlight zones where major objects cross one another:
  //    - Umbrella ribs crossing beneath the Left Side / Camera / PCB of the Smartphone
  //    - Key 2 blade crossing over the Top-Left of the Umbrella ribs & Inner Pocket Zipper
  const overlapPolys = [
    // Umbrella shaft & ribs crossing the left edge of the smartphone
    roundRectPts(-152, -32, 68, 95, 6, 735, 675, -11),
    // Key 2 blade overlapping the inner pocket zipper & umbrella ribs
    roundRectPts(65, 22, 54, 18, 3, 435, 415, 40)
  ];

  for (let poly of overlapPolys) {
    xrayWash(poly, PAL.milkBright, 55);
  }

  // 2. Soft Film Halation / Bloom Spray Passes over brightest metallic clusters
  const bloomCenters = [
    [435, 415, 95],   // Key ring cluster
    [735, 675, 110],  // Smartphone logic board & coils
    [590, 560, 85],   // Umbrella runner hub & smartphone camera overlap
    [350, 790, 65],   // Lipstick swivel mechanism
    [660, 965, 75],   // Overlapping coins
    [235, 565, 45],   // Perfume atomizer pump
    [720, 290, 60]    // Main zipper slider
  ];

  for (let b of bloomCenters) {
    brush.set("xray_bloom", PAL.cyanGlow, 1.3);
    brush.circle(b[0], b[1], b[2], 0.25);
    brush.set("xray_bloom", PAL.whitePure, 0.85);
    brush.circle(b[0], b[1], b[2] * 0.55, 0.2);
  }

  // 3. Delicate Soft White Pencil Contour Shading Across Ghostly Leather Folds
  for (let i = 0; i < 28; i++) {
    let lx = map(i, 0, 27, -480, 480);
    let ly0 = -310 + sin(i * 22) * 35;
    let ly1 = 420 + cos(i * 18) * 35;
    let p0 = xform(lx, ly0, bagCX, bagCY, bagAngle);
    let pMid = xform(lx + sin(i * 35) * 28, (ly0 + ly1) * 0.5, bagCX, bagCY, bagAngle);
    let p1 = xform(lx, ly1, bagCX, bagCY, bagAngle);
    brush.set("xray_pencil", PAL.veilLight, 0.45);
    brush.spline([p0, pMid, p1], 0.35);
  }

  // 4. Subtle Clinical Radiograph Calibration Ticks & Film Border Grain at Hard-Cropped Edges
  // Top-right and bottom-left radiographic calibration scales (ultra-fine technical pen)
  for (let t = 0; t <= 40; t++) {
    let pos = 45 + t * 8;
    let len = t % 10 === 0 ? 14 : t % 5 === 0 ? 9 : 5;
    // Top-right edge calibration ticks
    brush.set("xray_pen", PAL.cyanMid, t % 10 === 0 ? 0.65 : 0.42);
    brush.line(1182 - len, pos, 1182, pos);
    // Bottom-left edge calibration ticks
    brush.line(pos, 1182 - len, pos, 1182);
  }

  // Tiny radiographic crosshairs near corners
  const crosshairs = [
    [38, 38],
    [1162, 38],
    [38, 1162],
    [1162, 1162]
  ];
  for (let ch of crosshairs) {
    brush.set("xray_pen", PAL.cyanMid, 0.55);
    brush.line(ch[0] - 10, ch[1], ch[0] + 10, ch[1]);
    brush.line(ch[0], ch[1] - 10, ch[0], ch[1] + 10);
    let cPts = ellipsePts(0, 0, 5, 5, ch[0], ch[1], 0, 14);
    strokePoly(cPts, true, 0.1);
  }
}

