// ============================================================================
// GEOMETRY & COORDINATE UTILITIES
// ============================================================================

function safeLine(x1, y1, x2, y2) {
  if (dist(x1, y1, x2, y2) > 0.4) {
    brush.line(x1, y1, x2, y2);
  }
}

function safeSpline(pts, curv = 0.5) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    if (dist(pts[i][0], pts[i][1], clean[clean.length - 1][0], clean[clean.length - 1][1]) > 0.6) {
      clean.push(pts[i]);
    }
  }
  if (clean.length === 2) {
    safeLine(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  } else if (clean.length >= 3) {
    brush.spline(clean, curv);
  }
}

function drawPolyShape(poly, closeShape = true, curv = 0.15) {
  if (!poly || poly.length < 3) return;
  brush.beginShape(curv);
  for (let i = 0; i < poly.length; i++) {
    brush.vertex(poly[i][0], poly[i][1]);
  }
  brush.endShape(closeShape);
}

function pointInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect = ((yi > y) !== (yj > y)) &&
      (x < ((xj - xi) * (y - yi)) / (yj - yi + 1e-9) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function pointInAnyShadow(x, y) {
  return (
    pointInPoly(x, y, G.shadowFrontOuter) ||
    pointInPoly(x, y, G.shadowLeftTemple) ||
    pointInPoly(x, y, G.shadowRightTemple)
  );
}

function pointInFrontFrame(x, y) {
  if (!pointInPoly(x, y, G.frontOuter)) return false;
  if (pointInPoly(x, y, G.leftLens)) return false;
  if (pointInPoly(x, y, G.rightLens)) return false;
  return true;
}

function clipSegmentToCondition(x1, y1, x2, y2, condFn, steps = 28) {
  let segments = [];
  let curr = null;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = lerp(x1, x2, t);
    let y = lerp(y1, y2, t);
    if (condFn(x, y)) {
      if (!curr) curr = [[x, y]];
      else curr.push([x, y]);
    } else {
      if (curr && curr.length >= 2) {
        segments.push([curr[0], curr[curr.length - 1]]);
      }
      curr = null;
    }
  }
  if (curr && curr.length >= 2) {
    segments.push([curr[0], curr[curr.length - 1]]);
  }
  return segments;
}

function clipPolylineToCondition(pts, condFn) {
  let pieces = [];
  let curr = [];
  for (let i = 0; i < pts.length - 1; i++) {
    let p0 = pts[i], p1 = pts[i + 1];
    let d = dist(p0[0], p0[1], p1[0], p1[1]);
    let steps = max(2, floor(d / 3));
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let x = lerp(p0[0], p1[0], t);
      let y = lerp(p0[1], p1[1], t);
      if (condFn(x, y)) {
        curr.push([x, y]);
      } else {
        if (curr.length >= 2) pieces.push(curr);
        curr = [];
      }
    }
  }
  let last = pts[pts.length - 1];
  if (condFn(last[0], last[1])) curr.push(last);
  if (curr.length >= 2) pieces.push(curr);
  return pieces;
}

// ============================================================================
// 1. SUNGLASSES 3D-TO-2D PARAMETRIC MODEL
// ============================================================================

function buildSunglassesGeometry() {
  G.cx = 602;
  G.cy = 656;
  G.ang = -18.5; // Jaunty angle of sunglasses resting on the tabletop
  G.cosA = cos(G.ang);
  G.sinA = sin(G.ang);

  // Hard daylight direction vector (top-left to bottom-right)
  G.sunDx = 0.64;
  G.sunDy = 0.88;

  // Convert local sunglasses coords (u, v, z) to world canvas (x, y)
  // z >= 0 is height above the laminate tabletop (in px)
  G.toWorld = function(u, v, z = 0) {
    let vCam = v - z * 0.16;
    let wx = G.cx + u * G.cosA - vCam * G.sinA;
    let wy = G.cy + u * G.sinA + vCam * G.cosA;
    return [wx, wy];
  };

  // Project a 3D point (u, v, z) onto the tabletop (z = 0) along hard daylight ray
  G.toShadow = function(u, v, z = 0) {
    let wx0 = G.cx + u * G.cosA - v * G.sinA;
    let wy0 = G.cy + u * G.sinA + v * G.cosA;
    return [wx0 + z * G.sunDx, wy0 + z * G.sunDy];
  };

  // Inverse world-to-local (assuming z = 0 reference plane)
  G.toLocal = function(wx, wy) {
    let dx = wx - G.cx;
    let dy = wy - G.cy;
    let u = dx * G.cosA + dy * G.sinA;
    let v = -dx * G.sinA + dy * G.cosA;
    return [u, v];
  };

  // Height function of front frame: bottom rims touch tabletop (z=4), top brow is elevated (z=102)
  G.frontZ = function(u, v) {
    let normV = constrain(map(v, 108, -104, 0, 1), 0, 1);
    let arch = (1 - sq(u / 400)) * 12;
    return 4 + normV * 96 + max(0, arch);
  };

  // Build front outer frame contour in local (u, v)
  // Tracing clockwise from top-center bridge -> right brow -> right endpiece -> right bottom rim -> keyhole bridge -> left bottom rim -> left endpiece -> left brow
  let rightHalfLocal = [
    [0, -78],
    [35, -82],
    [78, -94],
    [135, -104],
    [198, -106],
    [262, -100],
    [314, -90],
    [368, -84], // Top-outer endpiece wing
    [374, -62],
    [370, -34], // Bottom of endpiece wing
    [340, -24],
    [328, 6],
    [312, 48],
    [284, 84],
    [238, 104],
    [182, 108], // Bottom center of right rim (touches tabletop)
    [126, 100],
    [84, 76],
    [58, 38],
    [46, 2],    // Nose pad flare
    [36, -22],  // Keyhole narrow waist
    [26, -46],  // Keyhole upper arch
    [12, -56],
    [0, -58]    // Top of keyhole arch
  ];

  G.frontOuterLocal = [];
  for (let i = 0; i < rightHalfLocal.length; i++) {
    G.frontOuterLocal.push(rightHalfLocal[i]);
  }
  for (let i = rightHalfLocal.length - 2; i >= 1; i--) {
    G.frontOuterLocal.push([-rightHalfLocal[i][0], rightHalfLocal[i][1]]);
  }

  // Inset contour for front 3D chamfered bevel
  G.frontBevelLocal = G.frontOuterLocal.map((pt) => {
    let u = pt[0], v = pt[1];
    let su = u * 0.965;
    let sv = v * 0.93;
    if (abs(u) < 55 && v > -65) {
      su = u * 1.08;
      sv = v - 5;
    }
    return [su, sv];
  });

  // Left & Right Lens Polygons in local (u, v)
  function makeLensLocal(sign) {
    let pts = [];
    let steps = 48;
    for (let i = 0; i < steps; i++) {
      let a = map(i, 0, steps, 0, 360);
      let ca = cos(a), sa = sin(a);
      // Superellipse with pantoscopic taper
      let exp = 2.55;
      let rx = 123;
      let ry = 78;
      let x = Math.sign(ca) * pow(abs(ca), 2 / exp) * rx;
      let y = Math.sign(sa) * pow(abs(sa), 2 / exp) * ry;
      // Shape modifications for authentic vintage lens contour
      if (y < 0) x *= 1.04 - 0.04 * (y / ry);
      if (y > 0) {
        // Taper cheek side and nasal side
        x *= 0.94 - 0.08 * (y / ry);
      }
      // Slight downward nasal droop, upward temple sweep
      y += -5 * (x / rx) + 4;
      let u = sign * (184 + x);
      let v = 3 + y;
      pts.push([u, v]);
    }
    return pts;
  }

  G.leftLensLocal = makeLensLocal(-1);
  G.rightLensLocal = makeLensLocal(1);

  // Outer lens bezel groove (slightly larger than lens)
  G.leftBezelLocal = G.leftLensLocal.map(p => [
    -184 + (p[0] + 184) * 1.065,
    3 + (p[1] - 3) * 1.075
  ]);
  G.rightBezelLocal = G.rightLensLocal.map(p => [
    184 + (p[0] - 184) * 1.065,
    3 + (p[1] - 3) * 1.075
  ]);

  // World & Shadow projections of Front Frame and Lenses
  G.frontOuter = G.frontOuterLocal.map(p => G.toWorld(p[0], p[1], G.frontZ(p[0], p[1])));
  G.frontBevel = G.frontBevelLocal.map(p => G.toWorld(p[0], p[1], G.frontZ(p[0], p[1]) + 1.5));
  // Lower 3D thickness rim wall of front frame
  G.frontUnderWall = G.frontOuterLocal.map(p => G.toWorld(p[0], p[1] + 9, max(0, G.frontZ(p[0], p[1]) - 9)));

  G.leftLens = G.leftLensLocal.map(p => G.toWorld(p[0], p[1], G.frontZ(p[0], p[1])));
  G.rightLens = G.rightLensLocal.map(p => G.toWorld(p[0], p[1], G.frontZ(p[0], p[1])));
  G.leftBezel = G.leftBezelLocal.map(p => G.toWorld(p[0], p[1], G.frontZ(p[0], p[1])));
  G.rightBezel = G.rightBezelLocal.map(p => G.toWorld(p[0], p[1], G.frontZ(p[0], p[1])));

  G.shadowFrontOuter = G.frontOuterLocal.map(p => G.toShadow(p[0], p[1], G.frontZ(p[0], p[1])));
  G.shadowLeftLens = G.leftLensLocal.map(p => G.toShadow(p[0], p[1], G.frontZ(p[0], p[1])));
  G.shadowRightLens = G.rightLensLocal.map(p => G.toShadow(p[0], p[1], G.frontZ(p[0], p[1])));

  // Build Folded Temple Arms (Left Arm & Right Arm)
  // Spine points: [u, v, z, halfWidth]
  G.leftTempleSpine = [
    [-354, -74, 92, 13],
    [-295, -112, 82, 12],
    [-195, -148, 68, 10.5],
    [-75, -172, 52, 9.5],
    [45, -182, 36, 9.5],
    [155, -178, 20, 11.5],
    [238, -156, 7, 13.5],  // Ergonomic paddle swell
    [288, -118, 1, 12.0],  // Ear-hook contacts tabletop (z ~ 1)
    [306, -78, 4, 9.0]     // Rounded tip behind right brow/lens
  ];

  G.rightTempleSpine = [
    [354, -74, 94, 13],
    [290, -124, 86, 12],
    [185, -172, 74, 10.5],
    [55, -206, 60, 9.5],   // Passes over/behind left temple arm
    [-75, -220, 42, 9.5],
    [-185, -212, 22, 11.5],
    [-262, -182, 7, 13.5], // Ergonomic paddle swell
    [-304, -138, 1, 12.0], // Ear-hook contacts tabletop (z ~ 1)
    [-316, -94, 4, 9.0]    // Rounded tip
  ];

  function buildTubePolys(spine) {
    let topEdge = [], botEdge = [];
    let sTopEdge = [], sBotEdge = [];
    let wirePts = [];
    for (let i = 0; i < spine.length; i++) {
      let p = spine[i];
      let pPrev = spine[max(0, i - 1)];
      let pNext = spine[min(spine.length - 1, i + 1)];
      let du = pNext[0] - pPrev[0];
      let dv = pNext[1] - pPrev[1];
      let len = sqrt(du * du + dv * dv) + 1e-6;
      let nu = -dv / len;
      let nv = du / len;
      let hw = p[3];

      let u1 = p[0] + nu * hw, v1 = p[1] + nv * hw;
      let u2 = p[0] - nu * hw, v2 = p[1] - nv * hw;

      topEdge.push(G.toWorld(u1, v1, p[2]));
      botEdge.push(G.toWorld(u2, v2, p[2]));
      sTopEdge.push(G.toShadow(u1, v1, p[2]));
      sBotEdge.push(G.toShadow(u2, v2, p[2]));
      wirePts.push(G.toWorld(p[0], p[1], p[2]));
    }
    let worldPoly = topEdge.concat(botEdge.reverse());
    let shadowPoly = sTopEdge.concat(sBotEdge.reverse());
    return { worldPoly, shadowPoly, wirePts };
  }

  let leftT = buildTubePolys(G.leftTempleSpine);
  G.leftTemple = leftT.worldPoly;
  G.shadowLeftTemple = leftT.shadowPoly;
  G.leftTempleWire = leftT.wirePts;

  let rightT = buildTubePolys(G.rightTempleSpine);
  G.rightTemple = rightT.worldPoly;
  G.shadowRightTemple = rightT.shadowPoly;
  G.rightTempleWire = rightT.wirePts;

  // Lens centers in world coords for spherical reflection mapping
  G.leftLensCenter = G.toWorld(-184, 3, G.frontZ(-184, 3));
  G.rightLensCenter = G.toWorld(184, 3, G.frontZ(184, 3));
}

// ============================================================================
// 2. DETERMINISTIC MEMPHIS LAMINATE PATTERN GENERATOR
// ============================================================================

function buildMemphisPattern() {
  memphis.ang = 26; // Jaunty tilt of the Memphis tabletop pattern
  memphis.cosM = cos(memphis.ang);
  memphis.sinM = sin(memphis.ang);

  // Convert Memphis-grid coordinates (mx, my) centered at (600, 600) to canvas (x, y)
  memphis.toWorld = function(mx, my) {
    return [
      600 + mx * memphis.cosM - my * memphis.sinM,
      600 + mx * memphis.sinM + my * memphis.cosM
    ];
  };

  // Large geometric color-block slabs on the laminate
  memphis.slabs = [
    {
      pts: [[-950, -780], [-220, -780], [-340, 880], [-950, 880]],
      col: "#d2f4e8", streakCol: "#bcece0", accentCol: "#a6e3d3" // Pastel mint zone
    },
    {
      pts: [[-220, -780], [420, -780], [290, 880], [-340, 880]],
      col: "#fdf5d4", streakCol: "#f9eab8", accentCol: "#f4df9b" // Pastel lemon-cream zone
    },
    {
      pts: [[420, -780], [980, -780], [980, 880], [290, 880]],
      col: "#ffd4e4", streakCol: "#ffbfd7", accentCol: "#ffa8c9" // Pastel bubblegum zone
    }
  ];

  // Secondary bold Memphis geometric shapes (stepped triangles, circles, arches)
  memphis.geoShapes = [
    // Sunny lemon stepped triangle top-left
    {
      type: "poly",
      pts: [[-620, -540], [-140, -540], [-140, -420], [-260, -420], [-260, -300], [-380, -300], [-380, -180], [-620, -180]],
      col: "#ffe268", shadowCol: "#19181d", offset: [10, 10]
    },
    // Bubblegum pink circle & half-pill bottom-left
    {
      type: "poly",
      pts: [[-560, 210], [-210, 210], [-170, 340], [-240, 460], [-520, 460], [-600, 340]],
      col: "#ff82b2", shadowCol: "#19181d", offset: [11, 11]
    },
    // Saturated mint diamond-slab upper-right
    {
      type: "poly",
      pts: [[180, -580], [640, -640], [560, -240], [110, -210]],
      col: "#64dfc1", shadowCol: "#19181d", offset: [10, 10]
    },
    // Lemon yellow Memphis arch lower-right
    {
      type: "poly",
      pts: [[220, 250], [680, 220], [720, 580], [490, 590], [470, 390], [380, 390], [360, 600], [190, 610]],
      col: "#ffda47", shadowCol: "#19181d", offset: [11, 11]
    },
    // Soft pastel lavender-blue accent bar near center
    {
      type: "poly",
      pts: [[-190, -110], [270, -160], [290, -45], [-170, 5]],
      col: "#b8c4ff", shadowCol: "#19181d", offset: [9, 9]
    }
  ].map(s => {
    let wPts = s.pts.map(p => memphis.toWorld(p[0], p[1]));
    let sPts = s.pts.map(p => memphis.toWorld(p[0] + s.offset[0], p[1] + s.offset[1]));
    return { ...s, wPts, sPts };
  });

  // Terrazzo flecks (angular 5-to-7-sided polygons in pink, mint, lemon, black, white)
  memphis.terrazzo = [];
  let tzColors = [
    "#ff6ea7", "#ff94be", "#52d9b8", "#8ceadf",
    "#ffd23f", "#ffe98a", "#18171c", "#18171c", "#fffdf7"
  ];
  for (let i = 0; i < 115; i++) {
    let mx = random(-780, 780);
    let my = random(-780, 780);
    let rBase = random(10, 34);
    let nVerts = floor(random(5, 8));
    let rot = random(360);
    let col = tzColors[i % tzColors.length];
    let hasShadow = random() < 0.45 && col !== "#18171c";
    let pts = [];
    let sPts = [];
    for (let v = 0; v < nVerts; v++) {
      let a = rot + v * (360 / nVerts) + random(-18, 18);
      let r = rBase * random(0.65, 1.25);
      let px = mx + cos(a) * r;
      let py = my + sin(a) * r * random(0.65, 1.15);
      pts.push(memphis.toWorld(px, py));
      sPts.push(memphis.toWorld(px + 4.5, py + 4.5));
    }
    memphis.terrazzo.push({ pts, sPts, col, hasShadow });
  }

  // Squiggles (sinusoidal worms & sawtooth zig-zags running off every edge)
  memphis.squiggles = [];
  let sqConfigs = [
    { mx: -680, my: -620, len: 360, ang: 12, amp: 24, freq: 3.5, col: "#ff5c99", type: "sine", w: 1.9 },
    { mx: -120, my: -650, len: 420, ang: -35, amp: 26, freq: 4.0, col: "#18171c", type: "zigzag", w: 1.5 },
    { mx: 450, my: -620, len: 390, ang: 48, amp: 22, freq: 3.5, col: "#ffda47", type: "sine", w: 2.0 },
    { mx: -740, my: -140, len: 440, ang: -18, amp: 28, freq: 4.5, col: "#45d4b2", type: "sine", w: 2.0 },
    { mx: -90, my: -260, len: 380, ang: 22, amp: 22, freq: 3.5, col: "#ff6ea7", type: "zigzag", w: 1.7 },
    { mx: 340, my: -180, len: 450, ang: -28, amp: 26, freq: 4.0, col: "#18171c", type: "sine", w: 1.6 },
    { mx: -720, my: 280, len: 420, ang: 32, amp: 25, freq: 4.0, col: "#ffd23f", type: "zigzag", w: 1.8 },
    { mx: -260, my: 140, len: 460, ang: -14, amp: 27, freq: 4.5, col: "#45d4b2", type: "sine", w: 2.1 },
    { mx: 240, my: 80, len: 430, ang: 18, amp: 24, freq: 4.0, col: "#ff5c99", type: "sine", w: 1.9 },
    { mx: -580, my: 620, len: 410, ang: -25, amp: 24, freq: 3.5, col: "#18171c", type: "sine", w: 1.6 },
    { mx: -40, my: 520, len: 460, ang: 8, amp: 28, freq: 4.5, col: "#ffda47", type: "sine", w: 2.0 },
    { mx: 420, my: 460, len: 390, ang: -42, amp: 24, freq: 3.5, col: "#45d4b2", type: "zigzag", w: 1.8 },
    // Extra squiggles near the sunglasses so they reflect richly in the lenses
    { mx: -340, my: -60, len: 310, ang: 55, amp: 20, freq: 3.5, col: "#ff6ea7", type: "sine", w: 1.8 },
    { mx: 110, my: -30, len: 330, ang: -48, amp: 21, freq: 3.5, col: "#ffd23f", type: "zigzag", w: 1.7 },
    { mx: -180, my: 310, len: 340, ang: 16, amp: 22, freq: 4.0, col: "#18171c", type: "sine", w: 1.5 },
    { mx: 280, my: -360, len: 350, ang: 8, amp: 23, freq: 3.5, col: "#ff5c99", type: "sine", w: 1.9 },
    { mx: -490, my: -390, len: 330, ang: -32, amp: 21, freq: 3.5, col: "#45d4b2", type: "zigzag", w: 1.7 },
    { mx: 520, my: 140, len: 360, ang: -15, amp: 23, freq: 4.0, col: "#18171c", type: "sine", w: 1.6 }
  ];

  for (let cfg of sqConfigs) {
    let pts = [];
    let sPts = [];
    let steps = cfg.type === "zigzag" ? cfg.freq * 2 + 1 : 34;
    let ca = cos(cfg.ang), sa = sin(cfg.ang);
    let na = -sa, nb = ca;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let along = t * cfg.len;
      let across = 0;
      if (cfg.type === "zigzag") {
        across = (i % 2 === 0 ? 1 : -1) * cfg.amp;
      } else {
        across = sin(t * cfg.freq * 360) * cfg.amp;
      }
      let px = cfg.mx + along * ca + across * na;
      let py = cfg.my + along * sa + across * nb;
      pts.push(memphis.toWorld(px, py));
      sPts.push(memphis.toWorld(px + 7, py + 7));
    }
    memphis.squiggles.push({ ...cfg, pts, sPts });
  }

  // Confetti dashes (short rotated marker pills in pink, mint, lemon, black)
  memphis.confetti = [];
  let cfColors = ["#18171c", "#ff5c99", "#3dd6b5", "#ffd23f", "#18171c", "#ff85b3"];
  for (let i = 0; i < 140; i++) {
    let mx = random(-760, 760);
    let my = random(-760, 760);
    let len = random(18, 42);
    let a = random(360);
    let col = cfColors[i % cfColors.length];
    let p1 = memphis.toWorld(mx - cos(a) * len * 0.5, my - sin(a) * len * 0.5);
    let p2 = memphis.toWorld(mx + cos(a) * len * 0.5, my + sin(a) * len * 0.5);
    let sp1 = memphis.toWorld(mx - cos(a) * len * 0.5 + 4, my - sin(a) * len * 0.5 + 4);
    let sp2 = memphis.toWorld(mx + cos(a) * len * 0.5 + 4, my + sin(a) * len * 0.5 + 4);
    memphis.confetti.push({ p1, p2, sp1, sp2, col });
  }

  // Memphis dot-grid clusters & hollow geometric rings
  memphis.dotGrids = [
    { mx: -480, my: -60, rows: 5, cols: 5, sp: 24 },
    { mx: 340, my: -440, rows: 6, cols: 4, sp: 24 },
    { mx: -80, my: 360, rows: 5, cols: 6, sp: 24 },
    { mx: 490, my: 320, rows: 4, cols: 5, sp: 24 },
    { mx: -320, my: -480, rows: 4, cols: 5, sp: 24 }
  ];
}

// ============================================================================
// 3. ALCOHOL-MARKER LAMINATE BASE WITH VISIBLE STREAK OVERLAPS
// ============================================================================

function drawLaminateBase() {
  brush.noStroke();
  brush.noHatch();

  // Wash foundation for each diagonal laminate slab
  for (let slab of memphis.slabs) {
    let wPoly = slab.pts.map(p => memphis.toWorld(p[0], p[1]));
    brush.wash(slab.col, 235);
    drawPolyShape(wPoly, true, 0);
  }
  brush.noWash();

  // Alcohol-marker chisel streaks running at +26 degrees with visible overlap bands
  let step = 22;
  for (let my = -860; my <= 860; my += step) {
    let pStart = memphis.toWorld(-920, my);
    let pEnd = memphis.toWorld(920, my);

    // Determine tint variation for natural hand-laid Copic marker streaks
    let bandIdx = floor((my + 900) / step);
    let streakCol = (bandIdx % 3 === 0) ? "#f5e7be" : (bandIdx % 3 === 1 ? "#d4f2e6" : "#ffdbe8");
    let overlapCol = (bandIdx % 2 === 0) ? "#e8d6a7" : "#b8e4d4";

    brush.set("chisel_marker", streakCol, random(0.92, 1.08));
    safeLine(pStart[0], pStart[1], pEnd[0], pEnd[1]);

    // Thin darker alcohol-marker overlap seam where adjacent chisel passes meet
    let pSeam1 = memphis.toWorld(-920, my + step * 0.44);
    let pSeam2 = memphis.toWorld(920, my + step * 0.44);
    brush.set("copic_flat", overlapCol, 0.28);
    safeLine(pSeam1[0], pSeam1[1], pSeam2[0], pSeam2[1]);
  }

  // Zone-specific saturated marker streak passes inside the Pink and Mint slabs
  for (let slabIdx = 0; slabIdx < memphis.slabs.length; slabIdx++) {
    let slab = memphis.slabs[slabIdx];
    let wPoly = slab.pts.map(p => memphis.toWorld(p[0], p[1]));
    brush.hatchStyle("chisel_marker", slab.streakCol, 0.78);
    brush.hatch(24, memphis.ang + (slabIdx === 1 ? 0 : 90), { rand: 0.02 });
    brush.noStroke();
    drawPolyShape(wPoly, true, 0);
    brush.noHatch();

    // Secondary overlap streak lines
    brush.hatchStyle("copic_flat", slab.accentCol, 0.32);
    brush.hatch(24, memphis.ang + (slabIdx === 1 ? 0 : 90), { rand: 0.01 });
    drawPolyShape(wPoly, true, 0);
    brush.noHatch();
  }
}

// ============================================================================
// 4. MEMPHIS TABLETOP GRAPHICS (SQUIGGLES, TERRAZZO, CONFETTI)
// ============================================================================

function drawMemphisTabletop() {
  // 4A. Bold Memphis geometric slabs with hard black offset shadows & marker streak fills
  for (let g of memphis.geoShapes) {
    // Hard black Memphis drop shadow
    brush.noStroke();
    brush.wash(g.shadowCol, 235);
    drawPolyShape(g.sPts, true, 0.04);
    brush.noWash();

    // Saturated marker fill + visible marker streak hatching
    brush.wash(g.col, 240);
    drawPolyShape(g.wPts, true, 0.04);
    brush.noWash();

    brush.hatchStyle("copic_flat", lerpColor(color(g.col), color("#d94b82"), 0.18), 0.48);
    brush.hatch(14, memphis.ang - 35, { rand: 0.02 });
    drawPolyShape(g.wPts, true, 0.04);
    brush.noHatch();

    // Crisp technical pen outline
    brush.set("rotring", "#18171c", 0.95);
    drawPolyShape(g.wPts, true, 0.04);
  }

  // 4B. Dot-matrix halftone clusters
  for (let dg of memphis.dotGrids) {
    for (let r = 0; r < dg.rows; r++) {
      for (let c = 0; c < dg.cols; c++) {
        let wp = memphis.toWorld(dg.mx + c * dg.sp, dg.my + r * dg.sp);
        if (wp[0] > -30 && wp[0] < 1230 && wp[1] > -30 && wp[1] < 1230) {
          brush.noStroke();
          brush.wash("#18171c", 230);
          brush.circle(wp[0], wp[1], 3.2, 0.08);
          brush.noWash();
        }
      }
    }
  }

  // 4C. Terrazzo flecks
  for (let tz of memphis.terrazzo) {
    let c0 = tz.pts[0];
    if (c0[0] < -60 || c0[0] > 1260 || c0[1] < -60 || c0[1] > 1260) continue;

    if (tz.hasShadow) {
      brush.noStroke();
      brush.wash("#18171c", 215);
      drawPolyShape(tz.sPts, true, 0.05);
      brush.noWash();
    }

    brush.noStroke();
    brush.wash(tz.col, 245);
    drawPolyShape(tz.pts, true, 0.05);
    brush.noWash();

    brush.set("rotring", "#18171c", 0.55);
    drawPolyShape(tz.pts, true, 0.05);
  }

  // 4D. Confetti dashes
  for (let cf of memphis.confetti) {
    if (cf.p1[0] < -50 || cf.p1[0] > 1250 || cf.p1[1] < -50 || cf.p1[1] > 1250) continue;

    if (cf.col !== "#18171c") {
      brush.set("copic_flat", "#18171c", 0.9);
      safeLine(cf.sp1[0], cf.sp1[1], cf.sp2[0], cf.sp2[1]);
    }
    brush.set("copic_flat", cf.col, 1.15);
    safeLine(cf.p1[0], cf.p1[1], cf.p2[0], cf.p2[1]);

    brush.set("micro_pen", "#18171c", 0.65);
    safeLine(cf.p1[0], cf.p1[1], cf.p2[0], cf.p2[1]);
  }

  // 4E. Sinusoidal & Zig-Zag Squiggles with offset drop shadows
  for (let sq of memphis.squiggles) {
    // Hard black offset shadow
    if (sq.col !== "#18171c") {
      brush.set("copic_flat", "#18171c", sq.w * 0.95);
      safeSpline(sq.sPts, sq.type === "zigzag" ? 0.05 : 0.55);
    }

    // Coloured marker body of squiggle
    brush.set("copic_flat", sq.col, sq.w);
    safeSpline(sq.pts, sq.type === "zigzag" ? 0.05 : 0.55);

    // Crisp ink edge
    brush.set("rotring", "#18171c", 0.72);
    safeSpline(sq.pts, sq.type === "zigzag" ? 0.05 : 0.55);
  }
}

// ============================================================================
// 5. HARD DAYLIGHT CAST SHADOW, LENS REFRACTION & AMBER CAUSTICS
// ============================================================================

function drawCastShadowsAndCaustics() {
  // 5A. Base cool violet-charcoal marker shadow wash for frame & folded temple arms
  brush.noStroke();
  brush.fillBleed(0.02, "in");
  brush.fillTexture(0.18, 0.35);

  // Folded temple arm shadows
  brush.fill("#48415c", 125);
  drawPolyShape(G.shadowLeftTemple, true, 0.12);
  drawPolyShape(G.shadowRightTemple, true, 0.12);

  // Front frame outer shadow
  brush.fill("#3d3650", 135);
  drawPolyShape(G.shadowFrontOuter, true, 0.12);
  brush.noFill();

  // 5B. Warm golden-amber caustic glow inside the shadow where sunlight filters through translucent tortoiseshell
  let causticPolys = [
    G.shadowLeftTemple,
    G.shadowRightTemple
  ];
  for (let cp of causticPolys) {
    brush.hatchStyle("amber_glaze", "#f29422", 0.62);
    brush.hatch(8, G.ang + 15, { rand: 0.04 });
    brush.noStroke();
    drawPolyShape(cp, true, 0.1);
    brush.noHatch();
  }

  // Glowing honey-orange caustic rim inside the front frame shadow (around the lenses & keyhole bridge)
  let steps = 65;
  for (let i = 0; i < steps; i++) {
    let t = i / steps;
    let idx = floor(t * G.frontOuterLocal.length);
    let lp = G.frontOuterLocal[idx];
    let sp = G.toShadow(lp[0] * 0.9, lp[1] * 0.88, G.frontZ(lp[0], lp[1]));
    if (!pointInPoly(sp[0], sp[1], G.shadowLeftLens) && !pointInPoly(sp[0], sp[1], G.shadowRightLens)) {
      if (noise(i * 0.35) > 0.36) {
        brush.set("amber_glaze", "#f7a428", random(0.6, 1.15));
        let ang = G.ang + random(-25, 25);
        safeLine(sp[0] - cos(ang) * 12, sp[1] - sin(ang) * 12, sp[0] + cos(ang) * 12, sp[1] + sin(ang) * 12);
      }
    }
  }

  // 5C. Tinted G-15 green-charcoal glass refraction inside the Left & Right Lens shadows
  brush.noStroke();
  brush.fill("#22332b", 130);
  drawPolyShape(G.shadowLeftLens, true, 0.15);
  drawPolyShape(G.shadowRightLens, true, 0.15);
  brush.noFill();

  // Marker streak hatching across the cast shadows so the alcohol-marker texture is continuous
  let shadowPolys = [G.shadowLeftTemple, G.shadowRightTemple, G.shadowFrontOuter];
  for (let sp of shadowPolys) {
    brush.hatchStyle("copic_flat", "#2b253a", 0.42);
    brush.hatch(13, memphis.ang, { rand: 0.02 });
    brush.noStroke();
    drawPolyShape(sp, true, 0.1);
    brush.noHatch();
  }

  // 5D. Re-ink & glaze Memphis elements that fall inside the cast shadow so the pattern is visible through the shadow!
  for (let tz of memphis.terrazzo) {
    let c = tz.pts[0];
    if (pointInAnyShadow(c[0], c[1])) {
      let darkCol = lerpColor(color(tz.col), color("#161324"), 0.62);
      brush.noStroke();
      brush.wash(darkCol, 195);
      drawPolyShape(tz.pts, true, 0.05);
      brush.noWash();
      brush.set("micro_pen", "#100e18", 0.55);
      drawPolyShape(tz.pts, true, 0.05);
    }
  }

  for (let cf of memphis.confetti) {
    let segs = clipSegmentToCondition(cf.p1[0], cf.p1[1], cf.p2[0], cf.p2[1], pointInAnyShadow, 14);
    for (let s of segs) {
      let darkCol = lerpColor(color(cf.col), color("#161324"), 0.65);
      brush.set("copic_flat", darkCol, 0.95);
      safeLine(s[0][0], s[0][1], s[1][0], s[1][1]);
    }
  }

  for (let sq of memphis.squiggles) {
    let pieces = clipPolylineToCondition(sq.pts, pointInAnyShadow);
    for (let pc of pieces) {
      let darkCol = lerpColor(color(sq.col), color("#151221"), 0.62);
      brush.set("copic_flat", darkCol, sq.w * 0.9);
      safeSpline(pc, sq.type === "zigzag" ? 0.05 : 0.5);
      brush.set("rotring", "#0e0c16", 0.65);
      safeSpline(pc, sq.type === "zigzag" ? 0.05 : 0.5);
    }
  }

  // 5E. Bright thin refractive caustic ring around the perimeter of the lens shadows
  brush.set("amber_glaze", "#ffd97d", 0.45);
  drawPolyShape(G.shadowLeftLens, true, 0.12);
  drawPolyShape(G.shadowRightLens, true, 0.12);

  // 5F. Crisp hard-daylight shadow contour in dark violet-charcoal marker + fine pen
  brush.set("copic_flat", "#231e30", 0.48);
  drawPolyShape(G.shadowLeftTemple, true, 0.1);
  drawPolyShape(G.shadowRightTemple, true, 0.1);
  drawPolyShape(G.shadowFrontOuter, true, 0.1);
}

// ============================================================================
// 6. FOLDED TORTOISESHELL TEMPLE ARMS, WIRE CORES & HINGES
// ============================================================================

function renderTortoiseshellOnPoly(poly, spinePts, wirePts, seedOffset) {
  // 1. Base translucent golden-honey & warm amber resin wash
  brush.noStroke();
  brush.wash("#f5b841", 235);
  drawPolyShape(poly, true, 0.12);
  brush.noWash();

  // Contour-following amber marker glaze streaks
  brush.hatchStyle("amber_glaze", "#e37b1c", 0.62);
  brush.hatch(7, G.ang + 8, { rand: 0.03 });
  drawPolyShape(poly, true, 0.12);
  brush.noHatch();

  // 2. Internal metallic wire core (silver/champagne-gold tang running through the translucent acetate)
  if (wirePts && wirePts.length >= 3) {
    brush.set("copic_flat", "#fff3c4", 0.52);
    safeSpline(wirePts, 0.4);
    brush.set("micro_pen", "#8c6d32", 0.65);
    safeSpline(wirePts, 0.4);

    // Tiny filigree hatch engravings along the metallic wire core
    for (let i = 1; i < wirePts.length - 1; i++) {
      let p0 = wirePts[i - 1], p1 = wirePts[i + 1];
      let ang = atan2(p1[1] - p0[1], p1[0] - p0[0]) + 90;
      for (let f = 0; f < 5; f++) {
        let t = f / 5;
        let wx = lerp(wirePts[i][0], wirePts[i + 1][0], t);
        let wy = lerp(wirePts[i][1], wirePts[i + 1][1], t);
        brush.set("micro_pen", "#73531c", 0.45);
        safeLine(wx - cos(ang) * 3, wy - sin(ang) * 3, wx + cos(ang) * 3, wy + sin(ang) * 3);
      }
    }
  }

  // 3. Layered Tortoiseshell Mottling (Burnt Sienna -> Mahogany -> Deep Espresso-Umber)
  for (let i = 0; i < spinePts.length - 1; i++) {
    let sp0 = spinePts[i], sp1 = spinePts[i + 1];
    for (let sub = 0; sub < 4; sub++) {
      let t = (sub + 0.5) / 4;
      let u = lerp(sp0[0], sp1[0], t);
      let v = lerp(sp0[1], sp1[1], t);
      let z = lerp(sp0[2], sp1[2], t);
      let hw = lerp(sp0[3], sp1[3], t);

      let nVal = noise((i * 4 + sub) * 0.42 + seedOffset);
      if (nVal > 0.34) {
        let wp = G.toWorld(u + random(-4, 4), v + random(-hw * 0.4, hw * 0.4), z);
        if (!pointInPoly(wp[0], wp[1], poly)) continue;

        // Build organic stretched tortoise patch clipped to temple polygon
        let patchR = hw * random(0.55, 1.05);
        let siennaPts = [];
        let umberPts = [];
        let espressoPts = [];
        let pAng = G.ang + random(-35, 35);
        for (let k = 0; k < 10; k++) {
          let a = pAng + k * 36;
          let rad = patchR * (0.7 + 0.45 * noise(k * 0.5, i + seedOffset));
          let sx = wp[0] + cos(a) * rad * 1.35;
          let sy = wp[1] + sin(a) * rad * 0.75;
          if (pointInPoly(sx, sy, poly)) siennaPts.push([sx, sy]);

          let ux = wp[0] + cos(a) * rad * 0.95;
          let uy = wp[1] + sin(a) * rad * 0.55;
          if (pointInPoly(ux, uy, poly)) umberPts.push([ux, uy]);

          let ex = wp[0] + cos(a) * rad * 0.58;
          let ey = wp[1] + sin(a) * rad * 0.35;
          if (pointInPoly(ex, ey, poly)) espressoPts.push([ex, ey]);
        }

        brush.noStroke();
        if (siennaPts.length >= 3) {
          brush.wash("#c84b12", 185);
          drawPolyShape(siennaPts, true, 0.25);
        }
        if (umberPts.length >= 3 && nVal > 0.42) {
          brush.wash("#541e09", 215);
          drawPolyShape(umberPts, true, 0.25);
        }
        if (espressoPts.length >= 3 && nVal > 0.5) {
          brush.wash("#1e0802", 240);
          drawPolyShape(espressoPts, true, 0.25);
        }
        brush.noWash();
      }
    }
  }

  // 4. Lower bevel shadow & upper specular highlight along the temple arm
  let half = floor(poly.length / 2);
  let topRim = poly.slice(0, half);
  let botRim = poly.slice(half);

  // Warm subsurface golden edge along bottom rim
  brush.set("amber_glaze", "#ffbe3b", 0.55);
  safeSpline(botRim, 0.35);

  // Dark espresso outer contour
  brush.set("rotring", "#240c03", 0.75);
  drawPolyShape(poly, true, 0.12);

  // Crisp white polished acetate specular highlight along upper ridge
  let specLine = [];
  for (let i = 1; i < topRim.length - 1; i++) {
    let pT = topRim[i];
    let pB = botRim[botRim.length - 1 - i];
    specLine.push([lerp(pT[0], pB[0], 0.24), lerp(pT[1], pB[1], 0.24)]);
  }
  brush.set("gloss_pen", "#ffffff", 0.85);
  safeSpline(specLine, 0.35);
}

function drawMetallicHinge(u, v, z, sign) {
  let barrels = 5;
  for (let b = 0; b < barrels; b++) {
    let bv = v - 6 + b * 3.2;
    let p1 = G.toWorld(u - sign * 8, bv, z);
    let p2 = G.toWorld(u + sign * 8, bv, z);
    let col = (b % 2 === 0) ? "#e8dec8" : "#8c7a5b";
    brush.set("copic_flat", col, 0.36);
    safeLine(p1[0], p1[1], p2[0], p2[1]);
    brush.set("micro_pen", "#261d11", 0.55);
    safeLine(p1[0], p1[1], p2[0], p2[1]);
  }
  // Hinge screw head
  let sc = G.toWorld(u, v, z + 1);
  brush.noStroke();
  brush.wash("#f7f1e1", 245);
  brush.circle(sc[0], sc[1], 4.5, 0.05);
  brush.noWash();
  brush.set("micro_pen", "#1f170d", 0.65);
  brush.circle(sc[0], sc[1], 4.5, 0.05);
  safeLine(sc[0] - 2.8, sc[1] - 1.5, sc[0] + 2.8, sc[1] + 1.5);
}

function drawFoldedTempleArms() {
  // 6A. Left Temple Arm (underneath where the two arms cross)
  renderTortoiseshellOnPoly(G.leftTemple, G.leftTempleSpine, G.leftTempleWire, 10.5);

  // Cast shadow of Right Temple Arm onto Left Temple Arm at the crossing zone
  let crossShadow = [];
  for (let pt of G.leftTemple) {
    let checkPt = [pt[0] - 8, pt[1] - 11];
    if (pointInPoly(checkPt[0], checkPt[1], G.rightTemple)) {
      crossShadow.push(pt);
    }
  }
  if (crossShadow.length >= 3) {
    brush.noStroke();
    brush.wash("#170702", 180);
    drawPolyShape(crossShadow, true, 0.1);
    brush.noWash();
  }

  // 6B. Right Temple Arm (crosses over the Left Temple Arm)
  renderTortoiseshellOnPoly(G.rightTemple, G.rightTempleSpine, G.rightTempleWire, 77.3);

  // 6C. Precision 5-barrel metallic hinges at left and right corners
  drawMetallicHinge(-346, -72, 92, -1);
  drawMetallicHinge(346, -72, 94, 1);
}

// ============================================================================
// 7. LENSES & WARPED MINIATURE MEMPHIS PATTERN IN FINE PEN
// ============================================================================

// Convex spherical mirror warp mapping any world point (wx, wy) into a lens reflection point
function warpPointToLens(wx, wy, lensSign) {
  let lCenter = lensSign < 0 ? G.leftLensCenter : G.rightLensCenter;
  let dx = wx - lCenter[0];
  let dy = wy - lCenter[1];

  // Rotate into sunglasses local axis
  let lu = dx * G.cosA + dy * G.sinA;
  let lv = -dx * G.sinA + dy * G.cosA;

  // Convex dome tilt shift (left lens tilts slightly left-up, right lens tilts slightly right-up)
  lu += lensSign * 45;
  lv += 35;

  // Normalize to wide tabletop capture radius (680 px)
  let nx = lu / 640;
  let ny = lv / 640;
  let r2 = nx * nx + ny * ny;
  let r = sqrt(r2);

  // Spherical convex barrel compression (miniaturizes and curves straight lines near lens rim)
  let scale = 1.0 / (1.0 + 0.95 * r + 0.85 * r2);
  let rx = nx * scale * 132;
  let ry = ny * scale * 86;

  // Convert back from lens-local to world coordinates
  let uLens = (lensSign * 184) + rx;
  let vLens = 3 + ry;
  return G.toWorld(uLens, vLens, G.frontZ(uLens, vLens));
}

function drawWarpedPatternInLens(lensPoly, lensSign) {
  let inThisLens = (x, y) => pointInPoly(x, y, lensPoly);

  // 1. Deep vintage G-15 green-charcoal glass base built with alcohol-marker sweeps
  brush.noStroke();
  brush.wash("#101b16", 242);
  drawPolyShape(lensPoly, true, 0.12);
  brush.noWash();

  // Diagonal marker tonal variation across the glass
  brush.hatchStyle("chisel_marker", "#182821", 0.72);
  brush.hatch(14, G.ang - 38, { rand: 0.02 });
  drawPolyShape(lensPoly, true, 0.12);
  brush.noHatch();

  // Subtle silhouette of the folded temple tip visible through the upper-outer semi-transparent glass
  let templePoly = lensSign < 0 ? G.rightTemple : G.leftTemple;
  let ghostPts = templePoly.filter(p => inThisLens(p[0], p[1]));
  if (ghostPts.length >= 3) {
    brush.noStroke();
    brush.wash("#261a10", 115);
    drawPolyShape(ghostPts, true, 0.1);
    brush.noWash();
  }

  // 2. Warped miniature laminate marker-streak grid lines in fine pen
  for (let my = -680; my <= 680; my += 55) {
    let rawLine = [];
    for (let mx = -700; mx <= 700; mx += 45) {
      let wp = memphis.toWorld(mx, my);
      rawLine.push(warpPointToLens(wp[0], wp[1], lensSign));
    }
    let clipped = clipPolylineToCondition(rawLine, inThisLens);
    for (let pc of clipped) {
      brush.set("micro_pen", "#294238", 0.52);
      safeSpline(pc, 0.45);
    }
  }

  // 3. Warped miniature Memphis geometric color slabs (hatched in fine colored pen)
  for (let g of memphis.geoShapes) {
    let wPoly = [];
    for (let i = 0; i < g.wPts.length; i++) {
      let p0 = g.wPts[i];
      let p1 = g.wPts[(i + 1) % g.wPts.length];
      for (let s = 0; s < 6; s++) {
        let x = lerp(p0[0], p1[0], s / 6);
        let y = lerp(p0[1], p1[1], s / 6);
        wPoly.push(warpPointToLens(x, y, lensSign));
      }
    }
    let insideVerts = wPoly.filter(p => inThisLens(p[0], p[1]));
    if (insideVerts.length >= 3) {
      let refCol = lerpColor(color(g.col), color("#162922"), 0.32);
      brush.hatchStyle("micro_pen", refCol, 0.68);
      brush.hatch(3.2, G.ang + 25, { rand: 0.02 });
      brush.noStroke();
      drawPolyShape(insideVerts, true, 0.15);
      brush.noHatch();

      brush.set("micro_pen", refCol, 0.8);
      drawPolyShape(insideVerts, true, 0.15);
    }
  }

  // 4. Warped miniature Terrazzo flecks in fine technical pen
  for (let tz of memphis.terrazzo) {
    let warpedPts = tz.pts.map(p => warpPointToLens(p[0], p[1], lensSign));
    if (warpedPts.every(p => inThisLens(p[0], p[1]))) {
      let refCol = tz.col === "#18171c"
        ? "#070d0a"
        : lerpColor(color(tz.col), color("#20382f"), 0.22);
      brush.set("micro_pen", refCol, 0.72);
      drawPolyShape(warpedPts, true, 0.08);

      // Tiny pen hatch inside each reflected terrazzo fleck
      let c0 = warpedPts[0], c2 = warpedPts[floor(warpedPts.length / 2)];
      safeLine(c0[0], c0[1], c2[0], c2[1]);
    }
  }

  // 5. Warped miniature Confetti dashes in fine pen
  for (let cf of memphis.confetti) {
    let wp1 = warpPointToLens(cf.p1[0], cf.p1[1], lensSign);
    let wp2 = warpPointToLens(cf.p2[0], cf.p2[1], lensSign);
    if (inThisLens(wp1[0], wp1[1]) && inThisLens(wp2[0], wp2[1])) {
      let refCol = cf.col === "#18171c"
        ? "#070d0a"
        : lerpColor(color(cf.col), color("#28453a"), 0.18);
      brush.set("micro_pen", refCol, 0.95);
      safeLine(wp1[0], wp1[1], wp2[0], wp2[1]);
    }
  }

  // 6. Warped miniature Squiggles with double-line fine pen contours & cross-hatching
  for (let sq of memphis.squiggles) {
    let wPts = sq.pts.map(p => warpPointToLens(p[0], p[1], lensSign));
    let wShadowPts = sq.sPts.map(p => warpPointToLens(p[0], p[1], lensSign));

    let sPieces = clipPolylineToCondition(wShadowPts, inThisLens);
    for (let sp of sPieces) {
      brush.set("micro_pen", "#060b09", 0.9);
      safeSpline(sp, sq.type === "zigzag" ? 0.05 : 0.45);
    }

    let pieces = clipPolylineToCondition(wPts, inThisLens);
    let refCol = sq.col === "#18171c"
      ? "#486b5d"
      : lerpColor(color(sq.col), color("#ffffff"), 0.12);

    for (let pc of pieces) {
      // Main fine-pen reflection of squiggle
      brush.set("micro_pen", refCol, 1.05);
      safeSpline(pc, sq.type === "zigzag" ? 0.05 : 0.45);

      // Parallel fine-pen ribbon edge + tiny cross-hatch ticks for obsessive graphic detail
      let offsetPc = pc.map(p => [p[0] + 1.8, p[1] - 1.8]);
      brush.set("micro_pen", refCol, 0.65);
      safeSpline(offsetPc, sq.type === "zigzag" ? 0.05 : 0.45);

      for (let k = 0; k < pc.length; k += 2) {
        safeLine(pc[k][0], pc[k][1], offsetPc[k][0], offsetPc[k][1]);
      }
    }
  }

  // 7. Warped miniature dot-grids in fine pen
  for (let dg of memphis.dotGrids) {
    for (let r = 0; r < dg.rows; r++) {
      for (let c = 0; c < dg.cols; c++) {
        let wp = memphis.toWorld(dg.mx + c * dg.sp, dg.my + r * dg.sp);
        let rp = warpPointToLens(wp[0], wp[1], lensSign);
        if (inThisLens(rp[0], rp[1])) {
          brush.set("micro_pen", "#82b8a3", 0.7);
          brush.circle(rp[0], rp[1], 1.4, 0.05);
        }
      }
    }
  }

  // 8. Curved hard-daylight overhead window specular reflection across upper-left of lens
  let specArc1 = [];
  let specArc2 = [];
  for (let a = 195; a <= 262; a += 5) {
    let rx = cos(a) * 96;
    let ry = sin(a) * 58;
    let u1 = lensSign * 184 + rx;
    let v1 = 3 + ry;
    let u2 = lensSign * 184 + rx * 0.84;
    let v2 = 3 + ry * 0.84;
    specArc1.push(G.toWorld(u1, v1, G.frontZ(u1, v1)));
    specArc2.push(G.toWorld(u2, v2, G.frontZ(u2, v2)));
  }
  let windowPoly = specArc1.concat(specArc2.slice().reverse());
  brush.noStroke();
  brush.wash("#e3f7f3", 95);
  drawPolyShape(windowPoly, true, 0.15);
  brush.noWash();

  // Crisp fine-pen hatching inside window reflection
  for (let i = 0; i < specArc1.length; i++) {
    brush.set("micro_pen", "#ffffff", 0.75);
    safeLine(specArc1[i][0], specArc1[i][1], specArc2[i][0], specArc2[i][1]);
  }
  brush.set("gloss_pen", "#ffffff", 0.7);
  safeSpline(specArc1, 0.4);

  // 9. Warm amber inner rim reflection & crisp glass bevel edge
  brush.set("amber_glaze", "#d9751e", 0.35);
  drawPolyShape(lensPoly, true, 0.12);

  brush.set("micro_pen", "#9be3cc", 0.7);
  drawPolyShape(lensPoly, true, 0.12);
}

function drawLensesAndReflections() {
  drawWarpedPatternInLens(G.leftLens, -1);
  drawWarpedPatternInLens(G.rightLens, 1);
}

// ============================================================================
// 8. FRONT TORTOISESHELL FRAME IN LAYERED MARKER GLAZES
// ============================================================================

function drawFrontTortoiseshellFrame() {
  // 8A. Lower 3D thickness wall of the front frame (gives sculptural slab depth)
  for (let i = 0; i < G.frontOuter.length; i++) {
    let pTop = G.frontOuter[i];
    let pBot = G.frontUnderWall[i];
    let lp = G.frontOuterLocal[i];
    // Draw vertical/bevel thickness along bottom rims, bridge keyhole & endpieces
    if (lp[1] > -45 || abs(lp[0]) > 315) {
      let nVal = noise(i * 0.25 + 42);
      let wallCol = nVal > 0.48 ? "#240b03" : "#d96b18";
      brush.set("copic_flat", wallCol, 0.55);
      safeLine(pTop[0], pTop[1], pBot[0], pBot[1]);
    }
  }

  // 8B. Layer 1: Luminous Honey-Gold & Pale Amber Base along the entire front frame
  // Sample dense radial/contour rings around both rims, bridge, and endpieces
  let frameSamplePoints = [];

  // Ring samples around Left & Right Rims
  for (let sign of [-1, 1]) {
    for (let a = 0; a < 360; a += 4) {
      let rad = a;
      let pIn = sign < 0 ? G.leftLensLocal[floor((a / 360) * G.leftLensLocal.length)] : G.rightLensLocal[floor((a / 360) * G.rightLensLocal.length)];
      // Step outward from lens edge to outer frame boundary
      for (let rStep = 0.15; rStep <= 1.25; rStep += 0.18) {
        let u = pIn[0] + cos(rad) * 26 * rStep * (abs(pIn[0]) > 290 ? 1.85 : 1.0);
        let v = pIn[1] + sin(rad) * 24 * rStep;
        let wp = G.toWorld(u, v, G.frontZ(u, v));
        if (pointInFrontFrame(wp[0], wp[1])) {
          frameSamplePoints.push({ u, v, wp, ang: G.ang + a + 90 });
        }
      }
    }
  }

  // Bridge & Keyhole samples
  for (let u = -72; u <= 72; u += 6) {
    for (let v = -96; v <= 35; v += 6) {
      let wp = G.toWorld(u, v, G.frontZ(u, v));
      if (pointInFrontFrame(wp[0], wp[1])) {
        frameSamplePoints.push({ u, v, wp, ang: G.ang + (v < -50 ? 0 : 85) });
      }
    }
  }

  // Endpiece wing samples
  for (let sign of [-1, 1]) {
    for (let u = 298; u <= 372; u += 6) {
      for (let v = -92; v <= -20; v += 6) {
        let uu = sign * u;
        let wp = G.toWorld(uu, v, G.frontZ(uu, v));
        if (pointInFrontFrame(wp[0], wp[1])) {
          frameSamplePoints.push({ u: uu, v, wp, ang: G.ang + 12 });
        }
      }
    }
  }

  // Lay down luminous honey-gold & warm amber base marker strokes
  for (let sp of frameSamplePoints) {
    let n = noise(sp.u * 0.018 + 10, sp.v * 0.018 + 10);
    let col = n > 0.55 ? "#fadc75" : (n > 0.28 ? "#f5ab33" : "#e67e19");
    let len = 9;
    let dx = cos(sp.ang) * len;
    let dy = sin(sp.ang) * len;
    let x1 = sp.wp[0] - dx, y1 = sp.wp[1] - dy;
    let x2 = sp.wp[0] + dx, y2 = sp.wp[1] + dy;
    if (pointInFrontFrame(x1, y1) && pointInFrontFrame(x2, y2)) {
      brush.set("copic_flat", col, 0.55);
      safeLine(x1, y1, x2, y2);
    }
  }

  // 8C. Layer 2 & 3: Obsessive Tortoiseshell Mottling in Layered Marker Glazes
  // (Fiery Burnt Sienna -> Deep Mahogany -> Obsidian Espresso-Umber)
  let mottleLayers = [
    { thresh: 0.36, radScale: 1.35, col: "#d14e12", alpha: 175, brushW: 0.48 }, // Fiery burnt sienna glaze
    { thresh: 0.43, radScale: 1.02, col: "#8f2808", alpha: 205, brushW: 0.42 }, // Rich mahogany glaze
    { thresh: 0.49, radScale: 0.76, col: "#421404", alpha: 230, brushW: 0.36 }, // Deep raw umber
    { thresh: 0.55, radScale: 0.52, col: "#1a0601", alpha: 248, brushW: 0.30 }  // Obsidian espresso core
  ];

  for (let layer of mottleLayers) {
    for (let i = 0; i < frameSamplePoints.length; i += 2) {
      let sp = frameSamplePoints[i];
      // Anisotropic noise stretched diagonally for authentic tortoise shell flow
      let nx = (sp.u * 0.8 + sp.v * 0.6) * 0.024;
      let ny = (-sp.u * 0.6 + sp.v * 0.8) * 0.036;
      let nVal = noise(nx + 50, ny + 50);

      if (nVal > layer.thresh) {
        let rBase = 14 * layer.radScale * map(nVal, layer.thresh, 1, 0.6, 1.35);
        let patchPts = [];
        let stretchAng = sp.ang + 28;
        for (let k = 0; k < 10; k++) {
          let a = k * 36;
          let r = rBase * (0.72 + 0.4 * noise(k * 0.6, i * 0.1));
          let lx = cos(a) * r * 1.4;
          let ly = sin(a) * r * 0.72;
          let px = sp.wp[0] + lx * cos(stretchAng) - ly * sin(stretchAng);
          let py = sp.wp[1] + lx * sin(stretchAng) + ly * cos(stretchAng);
          if (pointInFrontFrame(px, py)) {
            patchPts.push([px, py]);
          }
        }
        if (patchPts.length >= 4) {
          brush.noStroke();
          brush.wash(layer.col, layer.alpha);
          drawPolyShape(patchPts, true, 0.25);
          brush.noWash();

          // Visible marker edge ring
          brush.set("amber_glaze", layer.col, layer.brushW);
          drawPolyShape(patchPts, true, 0.25);
        }
      }
    }
  }

  // 8D. Layer 4: Subsurface Fiery Golden-Amber Glow along Bevels & Keyhole Bridge
  for (let i = 0; i < G.frontBevel.length - 1; i++) {
    let p0 = G.frontBevel[i];
    let p1 = G.frontBevel[i + 1];
    let n = noise(i * 0.3 + 99);
    if (n > 0.35) {
      let glowCol = n > 0.62 ? "#ffea75" : "#ff9b21";
      brush.set("amber_glaze", glowCol, 0.42);
      safeLine(p0[0], p0[1], p1[0], p1[1]);
    }
  }

  // Inner lens bezel groove shading & amber bounce
  for (let bezel of [G.leftBezel, G.rightBezel]) {
    brush.set("amber_glaze", "#f59c24", 0.38);
    drawPolyShape(bezel, true, 0.15);
    brush.set("rotring", "#1f0902", 0.85);
    drawPolyShape(bezel, true, 0.15);
  }
  brush.set("rotring", "#140501", 0.95);
  drawPolyShape(G.leftLens, true, 0.12);
  drawPolyShape(G.rightLens, true, 0.12);

  // Outer frame crisp boundary
  brush.set("rotring", "#1c0702", 0.9);
  drawPolyShape(G.frontOuter, true, 0.12);
  brush.set("micro_pen", "#0f0300", 0.75);
  drawPolyShape(G.frontUnderWall, true, 0.12);

  // 8E. Sculpted Keyhole Bridge & Integrated Nose Pad Highlights
  let khArch = [];
  for (let u = -38; u <= 38; u += 4) {
    let v = -58 + sq(u / 38) * 38;
    khArch.push(G.toWorld(u, v, G.frontZ(u, v)));
  }
  brush.set("amber_glaze", "#ffbe3d", 0.48);
  safeSpline(khArch, 0.4);
  brush.set("rotring", "#1c0702", 0.85);
  safeSpline(khArch, 0.4);

  // Translucent crystal-amber nose pads flanking the keyhole
  for (let sign of [-1, 1]) {
    let npPoly = [
      G.toWorld(sign * 42, -16, 48),
      G.toWorld(sign * 54, -8, 44),
      G.toWorld(sign * 58, 28, 28),
      G.toWorld(sign * 45, 22, 32)
    ];
    brush.noStroke();
    brush.wash("#ffcf66", 165);
    drawPolyShape(npPoly, true, 0.2);
    brush.noWash();
    brush.set("gloss_pen", "#ffffff", 0.65);
    safeLine(npPoly[0][0], npPoly[0][1], npPoly[3][0], npPoly[3][1]);
  }

  // 8F. Twin Metallic Diamond-Shield Hinge Pins (Rivets) on Left & Right Endpieces
  for (let sign of [-1, 1]) {
    let pinPositions = [
      [sign * 348, -62],
      [sign * 324, -60]
    ];
    for (let pos of pinPositions) {
      let u = pos[0], v = pos[1];
      let z = G.frontZ(u, v) + 2;
      let dPoly = [
        G.toWorld(u - sign * 8, v, z),
        G.toWorld(u, v - 4.2, z),
        G.toWorld(u + sign * 8, v, z),
        G.toWorld(u, v + 4.2, z)
      ];
      // Dark recess bezel
      brush.set("rotring", "#1a0802", 0.85);
      drawPolyShape(dPoly, true, 0.1);

      // Warm champagne-silver metallic fill
      brush.noStroke();
      brush.wash("#f5eedc", 245);
      drawPolyShape(dPoly, true, 0.1);
      brush.noWash();

      // Metallic reflection split & central rivet pin
      let c = G.toWorld(u, v, z);
      brush.set("micro_pen", "#594a33", 0.55);
      brush.circle(c[0], c[1], 2.2, 0.04);
      brush.set("gloss_pen", "#ffffff", 0.7);
      safeLine(dPoly[0][0], dPoly[0][1], dPoly[1][0], dPoly[1][1]);
    }
  }
}

// ============================================================================
// 9. HIGH-GLOSS SPECULAR RIBBONS & OPTICAL MICRO-DETAILS
// ============================================================================

function drawFinalMicroDetails() {
  // 9A. Razor-sharp white & pale-sky specular reflection ribbons on polished acetate brow bar
  for (let sign of [-1, 1]) {
    let browSpec1 = [];
    let browSpec2 = [];
    for (let u = 68; u <= 305; u += 12) {
      let uu = sign * u;
      let t = (u - 68) / (305 - 68);
      let v1 = -90 - sin(t * 180) * 11;
      let v2 = v1 + 4.2;
      browSpec1.push(G.toWorld(uu, v1, G.frontZ(uu, v1) + 2));
      browSpec2.push(G.toWorld(uu, v2, G.frontZ(uu, v2) + 2));
    }
    let specRibbon = browSpec1.concat(browSpec2.slice().reverse());
    brush.noStroke();
    brush.wash("#ffffff", 195);
    drawPolyShape(specRibbon, true, 0.2);
    brush.noWash();

    brush.set("gloss_pen", "#ffffff", 0.95);
    safeSpline(browSpec1, 0.45);
    brush.set("micro_pen", "#d9f0ff", 0.65);
    safeSpline(browSpec2, 0.45);
  }

  // 9B. Bridge top ridge specular highlight
  let bridgeSpec = [];
  for (let u = -48; u <= 48; u += 8) {
    let v = -75 - (1 - sq(u / 48)) * 5;
    bridgeSpec.push(G.toWorld(u, v, G.frontZ(u, v) + 2));
  }
  brush.set("gloss_pen", "#ffffff", 1.05);
  safeSpline(bridgeSpec, 0.45);

  // 9C. Lower cheek rim chamfered bevel speculars
  for (let sign of [-1, 1]) {
    let cheekSpec = [];
    for (let a = 32; a <= 138; a += 8) {
      let u = sign * (184 + cos(a) * 134);
      let v = 3 + sin(a) * 91;
      let wp = G.toWorld(u, v, G.frontZ(u, v) + 1.5);
      if (pointInFrontFrame(wp[0], wp[1])) cheekSpec.push(wp);
    }
    brush.set("gloss_pen", "#fff9e6", 0.72);
    safeSpline(cheekSpec, 0.4);
  }

  // 9D. Inner lens rim thickness catch-lights (top-left daylight rim on glass bevel)
  for (let sign of [-1, 1]) {
    let rimGlint = [];
    for (let a = 15; a <= 115; a += 7) {
      let u = sign * 184 + cos(a) * 123;
      let v = 3 + sin(a) * 78;
      rimGlint.push(G.toWorld(u, v, G.frontZ(u, v)));
    }
    brush.set("gloss_pen", "#ffffff", 0.62);
    safeSpline(rimGlint, 0.4);
  }
}

// Hyperrealist Coloured Pencil on Mid-Grey Toned Paper
// "Dawn from the Driver's Seat — Coastal Overcast & Dew Droplets"

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);

  // Define custom coloured-pencil and pastel-blending brushes before scaling
  brush.add("soft_blend", {
    type: "default",
    weight: 10,
    scatter: 1.8,
    sharpness: 0.15,
    grain: 14,
    opacity: 28,
    spacing: 0.25,
    pressure: [0.3, 1.0, 0.3],
    noise: 0.6
  });

  brush.add("color_pencil", {
    type: "default",
    weight: 1.3,
    scatter: 0.35,
    sharpness: 0.68,
    grain: 22,
    opacity: 135,
    spacing: 0.14,
    pressure: [0.5, 1.15, 0.45],
    noise: 0.45
  });

  brush.add("white_pencil", {
    type: "default",
    weight: 1.1,
    scatter: 0.18,
    sharpness: 0.82,
    grain: 18,
    opacity: 210,
    spacing: 0.1,
    pressure: [0.6, 1.25, 0.5],
    noise: 0.25
  });

  brush.scaleBrushes(3);

  // Custom subtle vector field for coastal swell & overcast drift
  brush.addField("marine_drift", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col / field.length;
        let ny = row / field[0].length;
        field[col][row] = (noise(nx * 2.5, ny * 4.0) - 0.5) * 8;
      }
    }
    return field;
  });
}

// Helper: evaluate the left A-pillar inner boundary X for a given Y
function getAPillarX(y) {
  // Slopes from x = 235 at y = 0 down to x = 68 at y = 860
  return map(y, 0, 860, 235, 68, true);
}

// Helper: evaluate top roof header lower boundary Y for a given X
function getRoofY(x) {
  // Slight downward curve toward the edges, plus rearview mirror mount at top-right
  let base = 44 + 18 * pow((x - 650) / 550, 2);
  if (x > 960) {
    base = max(base, map(x, 960, 1200, 50, 108));
  }
  return base;
}

// Helper: evaluate dashboard cowl & binnacle top Y for a given X
function getDashY(x) {
  let baseCowl = 825 + 16 * sin(map(x, 0, 1200, 0, 180));
  // Instrument binnacle hood rises smoothly between x = 165 and x = 775
  if (x > 165 && x < 775) {
    let u = map(x, 165, 775, -1, 1);
    let arch = 44 * pow(1 - u * u, 1.6);
    baseCowl -= arch;
  }
  return baseCowl;
}

// Helper: check if a point (x, y) with margin is safely on the open windshield glass
function isOnWindshield(x, y, margin = 0) {
  if (x < getAPillarX(y) + 18 + margin) return false;
  if (x > 1192 - margin) return false;
  if (y < getRoofY(x) + 10 + margin) return false;
  if (y > getDashY(x) - 24 - margin) return false;
  return true;
}

function draw() {
  translate(-width / 2, -height / 2);
  randomSeed(7481);
  noiseSeed(7481);

  // =========================================================================
  // 1. MID-GREY TONED PAPER GROUND & PAPER TOOTH
  // =========================================================================
  background("#7b8087");

  brush.noStroke();
  brush.noFill();

  // Subtle warm/cool tonal variations in the grey paper
  const paperPatches = [
    { x: 600, y: 300, w: 1180, h: 550, c: "#828890", a: 35 },
    { x: 600, y: 650, w: 1180, h: 450, c: "#737880", a: 35 },
    { x: 600, y: 1020, w: 1180, h: 360, c: "#6c7077", a: 45 }
  ];
  for (let p of paperPatches) {
    brush.wash(p.c, p.a);
    brush.rect(p.x, p.y, p.w, p.h, "center");
  }
  brush.noWash();

  // Paper grain: fine horizontal and diagonal tooth across the toned sheet
  brush.set("2H", "#868b93", 0.35);
  for (let i = 0; i < 220; i++) {
    let y = random(0, 1200);
    let x1 = random(0, 350);
    let x2 = x1 + random(350, 850);
    brush.line(x1, y, min(1200, x2), y + random(-3, 3));
  }
  brush.set("2H", "#6e737a", 0.32);
  for (let i = 0; i < 220; i++) {
    let y = random(0, 1200);
    let x1 = random(0, 400);
    let x2 = x1 + random(300, 800);
    brush.line(x1, y, min(1200, x2), y + random(-4, 4));
  }

  // =========================================================================
  // 2. BEYOND THE GLASS: OVERCAST MARINE LAYER, DAWN BAND, OCEAN & FAINT PIER
  // =========================================================================
  const horizonY = 468;

  // 2A. Soft watercolor/pastel under-washes for the marine-layer sky & sea
  brush.noStroke();
  const skyBands = [
    { y: 85, h: 90, c: "#667280", a: 85 },
    { y: 155, h: 95, c: "#717e8d", a: 85 },
    { y: 230, h: 95, c: "#7f8d9c", a: 85 },
    { y: 300, h: 85, c: "#91a0af", a: 85 },
    { y: 365, h: 70, c: "#a8b6c4", a: 90 },
    { y: 415, h: 55, c: "#c2ced9", a: 95 },
    { y: 448, h: 38, c: "#d8e0e6", a: 105 },
    // Hint of cool pale pastel shell/cream right at the marine-layer break
    { y: 458, h: 22, c: "#e5e2de", a: 75 }
  ];
  for (let b of skyBands) {
    brush.wash(b.c, b.a);
    brush.rect(640, b.y, 1120, b.h, "center");
  }

  const seaBands = [
    { y: 482, h: 28, c: "#a5b2be", a: 90 },
    { y: 512, h: 42, c: "#8d9ba8", a: 90 },
    { y: 555, h: 58, c: "#798794", a: 90 },
    { y: 615, h: 72, c: "#677482", a: 95 },
    { y: 685, h: 82, c: "#576370", a: 100 },
    { y: 765, h: 95, c: "#46515d", a: 110 }
  ];
  for (let b of seaBands) {
    brush.wash(b.c, b.a);
    brush.rect(640, b.y, 1120, b.h, "center");
  }
  brush.noWash();

  // 2B. Soft blended coloured-pencil sky & cloud ceiling
  brush.field("marine_drift");
  for (let y = 52; y < horizonY; y += 3.2) {
    let t = map(y, 52, horizonY, 0, 1);
    let col;
    if (t < 0.38) {
      col = lerpColor(color("#636f7d"), color("#7d8b9a"), t / 0.38);
    } else if (t < 0.72) {
      col = lerpColor(color("#7d8b9a"), color("#aab8c6"), (t - 0.38) / 0.34);
    } else if (t < 0.91) {
      col = lerpColor(color("#aab8c6"), color("#d5dfe7"), (t - 0.72) / 0.19);
    } else {
      col = lerpColor(color("#d5dfe7"), color("#e7e5e0"), (t - 0.91) / 0.09);
    }

    let leftX = getAPillarX(y) + 10;
    brush.set("soft_blend", col, random(0.65, 1.15));
    brush.flowLine(leftX, y + random(-2, 2), 1190 - leftX, 0);

    // Fine coloured-pencil cross-strokes for velvety pastel texture
    if (random() < 0.75) {
      let cPencil = lerpColor(col, color("#e8eff5"), random(-0.15, 0.2));
      brush.set("color_pencil", cPencil, random(0.35, 0.65));
      let sx = random(leftX, 950);
      brush.line(sx, y + random(-1.5, 1.5), min(1190, sx + random(140, 340)), y + random(-2, 2));
    }
  }

  // Low flat stratus cloud underbellies in the marine layer
  const cloudStrata = [
    { y: 135, x1: 220, x2: 1180, c: "#5a6573", w: 1.1 },
    { y: 195, x1: 190, x2: 1080, c: "#677483", w: 0.95 },
    { y: 262, x1: 280, x2: 1190, c: "#768494", w: 0.9 },
    { y: 318, x1: 170, x2: 960, c: "#8695a4", w: 0.8 },
    { y: 368, x1: 360, x2: 1190, c: "#9aa8b7", w: 0.75 },
    { y: 404, x1: 210, x2: 1150, c: "#b2c0cd", w: 0.65 }
  ];
  for (let cs of cloudStrata) {
    for (let k = 0; k < 14; k++) {
      let yy = cs.y + random(-12, 12);
      let xx1 = max(getAPillarX(yy) + 15, cs.x1 + random(-50, 50));
      let xx2 = min(1190, cs.x2 + random(-40, 40));
      brush.set("soft_blend", cs.c, cs.w * random(0.6, 1.1));
      brush.line(xx1, yy, xx2, yy + random(-2, 2));
    }
  }
  brush.noField();

  // 2C. Soft blended coloured-pencil ocean surface & swell lines
  for (let y = horizonY; y < 825; y += 3.4) {
    let t = map(y, horizonY, 825, 0, 1);
    let col;
    if (t < 0.2) {
      col = lerpColor(color("#b2bfca"), color("#8b99a7"), t / 0.2);
    } else if (t < 0.55) {
      col = lerpColor(color("#8b99a7"), color("#667380"), (t - 0.2) / 0.35);
    } else {
      col = lerpColor(color("#667380"), color("#424c57"), (t - 0.55) / 0.45);
    }
    let leftX = getAPillarX(y) + 10;
    brush.set("soft_blend", col, random(0.65, 1.1));
    brush.line(leftX, y, 1190, y + random(-1.5, 1.5));

    // Subtle swell highlights and troughs in coloured pencil
    let swellWave = sin(pow(t, 0.65) * 720 + noise(y * 0.03) * 90);
    let pencilCol = swellWave > 0
      ? lerpColor(col, color("#d4dfe8"), 0.25 * swellWave)
      : lerpColor(col, color("#333b44"), -0.28 * swellWave);
    brush.set("color_pencil", pencilCol, random(0.35, 0.7));
    for (let s = 0; s < 3; s++) {
      let sx = random(leftX, 1020);
      let len = random(90, 260) * (0.5 + 0.7 * t);
      brush.line(sx, y + random(-1, 1), min(1190, sx + len), y + random(-1, 1));
    }
  }

  // 2D. THE FAINT COASTAL PIER (extending from right x=1195 out to x=350 at y~466)
  const pierStartX = 355;
  const pierEndX = 1195;
  const pierDeckY = 463;

  // Soft misty water reflection beneath the pier pilings
  for (let x = pierStartX; x < pierEndX; x += 4.5) {
    let pNorm = map(x, pierStartX, pierEndX, 0, 1);
    let reflDepth = map(pNorm, 0, 1, 24, 62) * random(0.75, 1.2);
    let reflCol = lerpColor(color("#626d78"), color("#47505a"), pNorm * 0.8);
    brush.set("color_pencil", reflCol, random(0.3, 0.55));
    brush.line(x + random(-1, 1), horizonY + 3, x + random(-2, 2), horizonY + 3 + reflDepth);
  }
  // Horizontal water ripples cutting across the pier reflection
  for (let y = horizonY + 5; y < horizonY + 65; y += 3.5) {
    let c = lerpColor(color("#9aa7b3"), color("#74828f"), map(y, horizonY, horizonY + 65, 0, 1));
    brush.set("color_pencil", c, 0.42);
    brush.line(pierStartX - 20, y, pierEndX, y + random(-0.5, 0.5));
  }

  // Distant low headland / breakwater silhouette behind the right end of the pier
  brush.noStroke();
  brush.wash("#6b747f", 95);
  brush.beginShape(0.2);
  brush.vertex(740, horizonY);
  brush.vertex(830, horizonY - 9);
  brush.vertex(960, horizonY - 14);
  brush.vertex(1100, horizonY - 18);
  brush.vertex(1195, horizonY - 16);
  brush.vertex(1195, horizonY + 2);
  brush.endShape(true);
  brush.noWash();

  // Pier vertical timber pilings & cross-bracing
  let pilingX = pierStartX;
  while (pilingX < pierEndX) {
    let pNorm = map(pilingX, pierStartX, pierEndX, 0, 1);
    let deckY = pierDeckY - pNorm * 5;
    let baseY = horizonY + 2 + pNorm * 5;
    let pCol = lerpColor(color("#555e68"), color("#394048"), pNorm);

    // Main outer piling
    brush.set("color_pencil", pCol, map(pNorm, 0, 1, 0.38, 0.78));
    brush.line(pilingX, deckY, pilingX, baseY);
    // Secondary inner piling slightly offset
    brush.set("color_pencil", lerpColor(pCol, color("#68737f"), 0.35), map(pNorm, 0, 1, 0.3, 0.6));
    brush.line(pilingX + 2.5 + pNorm * 2, deckY + 1, pilingX + 2.5 + pNorm * 2, baseY);

    // Subtle X-brace between bents
    let step = map(pNorm, 0, 1, 7.5, 19);
    if (pilingX + step < pierEndX && random() < 0.75) {
      brush.set("2H", pCol, 0.28);
      brush.line(pilingX, deckY + 2, pilingX + step, baseY - 1);
      brush.line(pilingX + step, deckY + 2, pilingX, baseY - 1);
    }
    pilingX += step;
  }

  // Pier horizontal deck & railing
  for (let k = 0; k < 6; k++) {
    let dy = k * 0.9;
    let deckCol = k < 2 ? "#626b75" : "#404750";
    brush.set("color_pencil", deckCol, 0.55);
    brush.line(pierStartX - 2, pierDeckY + dy, pierEndX, pierDeckY - 5 + dy);
  }

  // Small weathered pier structures (end shed & mid-pier boathouse)
  const sheds = [
    { x: 372, w: 26, h: 11, roofH: 6, c: "#4e5660", rc: "#5d6671" },
    { x: 545, w: 48, h: 15, roofH: 9, c: "#464e58", rc: "#57606b" },
    { x: 602, w: 24, h: 11, roofH: 5, c: "#4c545e", rc: "#5d6670" }
  ];
  for (let sh of sheds) {
    let pNorm = map(sh.x, pierStartX, pierEndX, 0, 1);
    let by = pierDeckY - pNorm * 5;
    // Wall shading with vertical pencil strokes
    brush.set("color_pencil", sh.c, 0.45);
    for (let sx = sh.x; sx <= sh.x + sh.w; sx += 2.2) {
      brush.line(sx, by, sx, by - sh.h);
    }
    // Gable roof shading
    brush.set("color_pencil", sh.rc, 0.48);
    for (let r = 0; r <= 1; r += 0.15) {
      let ry = by - sh.h - r * sh.roofH;
      let rx1 = sh.x - 2 + r * (sh.w * 0.35);
      let rx2 = sh.x + sh.w + 2 - r * (sh.w * 0.35);
      brush.line(rx1, ry, rx2, ry);
    }
  }

  // Faint pier lamp posts with barely-there pale pastel amber dawn glints
  const lampXs = [362, 430, 505, 590, 685, 795, 920, 1060];
  for (let lx of lampXs) {
    let pNorm = map(lx, pierStartX, pierEndX, 0, 1);
    let by = pierDeckY - pNorm * 5;
    let lh = map(pNorm, 0, 1, 12, 21);
    brush.set("2H", "#505963", 0.32);
    brush.line(lx, by, lx, by - lh);
    // Soft misty dawn lamp halo
    brush.set("soft_blend", "#e8c89e", 0.32);
    brush.line(lx - 2, by - lh, lx + 2, by - lh);
    brush.set("white_pencil", "#f7e4c8", 0.38);
    brush.line(lx - 0.6, by - lh, lx + 0.6, by - lh);
  }

  // Soft marine mist veil over the pier & horizon so it recedes behind the glass
  for (let i = 0; i < 38; i++) {
    let my = random(horizonY - 28, horizonY + 26);
    let mx1 = random(240, 750);
    let mx2 = min(1190, mx1 + random(180, 460));
    brush.set("soft_blend", "#c4d0da", random(0.45, 0.85));
    brush.line(mx1, my, mx2, my + random(-1, 1));
  }

  // =========================================================================
  // 3. WINDSHIELD CONDENSATION FILM & GRAVITY RUNNEL TRAILS
  // =========================================================================
  // Overall damp micro-fog on the glass (soft pastel haze)
  brush.set("spray", "#b8c3cd", 0.45);
  for (let i = 0; i < 45; i++) {
    let fy = random(75, 780);
    let fx1 = max(getAPillarX(fy) + 25, random(120, 700));
    let fx2 = min(1180, fx1 + random(160, 420));
    brush.line(fx1, fy, fx2, fy + random(-8, 8));
  }

  // Define 4 gravity runnel trails where heavy droplets slid partway down the glass
  const runnels = [
    { x0: 385, y0: 155, len: 175, drift: -14, clearW: 15 },
    { x0: 642, y0: 210, len: 215, drift: -10, clearW: 17 },
    { x0: 875, y0: 130, len: 190, drift: -8, clearW: 15 },
    { x0: 1035, y0: 310, len: 165, drift: -6, clearW: 14 }
  ];

  for (let rn of runnels) {
    rn.pts = [];
    let steps = 16;
    for (let s = 0; s <= steps; s++) {
      let u = s / steps;
      let rx = rn.x0 + u * rn.drift + (noise(rn.x0 * 0.1, u * 4) - 0.5) * 14;
      let ry = rn.y0 + u * rn.len;
      rn.pts.push([rx, ry]);
    }
    // Draw the slightly darker/clearer glass wake along the runnel
    for (let s = 0; s < rn.pts.length - 1; s++) {
      let [x1, y1] = rn.pts[s];
      let [x2, y2] = rn.pts[s + 1];
      let wakeCol = y1 < horizonY ? "#7c8998" : "#566370";
      brush.set("soft_blend", wakeCol, 0.55);
      brush.line(x1, y1, x2, y2);
      // Faint pale water-film edges on either side of the wake
      brush.set("color_pencil", "#cad6e0", 0.28);
      brush.line(x1 - 5, y1, x2 - 5, y2);
      brush.line(x1 + 5, y1, x2 + 5, y2);
    }
  }

  // Helper: distance from point (x, y) to any runnel wake (excluding the terminal drop at the end)
  function distToRunnelWake(x, y) {
    let minDist = 9999;
    for (let rn of runnels) {
      for (let i = 0; i < rn.pts.length - 2; i++) {
        let [px, py] = rn.pts[i];
        let d = dist(x, y, px, py);
        if (d < minDist) minDist = d;
      }
    }
    return minDist;
  }

  // =========================================================================
  // 4. GENERATE OBSESSIVE DENSITY OF DEW DROPLETS (1,600+ LENSES)
  // =========================================================================
  const droplets = [];

  function canPlaceDrop(x, y, r, pad = 2.2) {
    if (!isOnWindshield(x, y, r + 4)) return false;
    if (distToRunnelWake(x, y) < r + 8) return false;
    for (let d of droplets) {
      let dx = x - d.x;
      let dy = y - d.y;
      let minD = r + d.r + pad;
      if (dx * dx + dy * dy < minD * minD) return false;
    }
    return true;
  }

  // 4A. Place heavy terminal droplets at the bottom of each gravity runnel
  for (let rn of runnels) {
    let [tx, ty] = rn.pts[rn.pts.length - 1];
    droplets.push({
      x: tx,
      y: ty + 4,
      r: random(17, 21),
      sag: 1.18,
      tilt: random(-6, 6),
      isTerminal: true
    });
    // Tiny satellite beads left along the borders of the runnel track
    for (let i = 1; i < rn.pts.length - 2; i += 2) {
      let [px, py] = rn.pts[i];
      let side = random() < 0.5 ? -1 : 1;
      let sx = px + side * random(7, 10);
      let sy = py + random(-3, 3);
      let sr = random(2.0, 3.8);
      if (isOnWindshield(sx, sy, sr + 2)) {
        droplets.push({ x: sx, y: sy, r: sr, sag: 1.02, tilt: 0 });
      }
    }
  }

  // 4B. Pack Hero Lenses (r = 12.5 to 22 px)
  for (let attempt = 0; attempt < 1200 && droplets.length < 62; attempt++) {
    let x = random(110, 1175);
    let y = random(70, 775);
    let r = random(12.5, 22.0);
    if (canPlaceDrop(x, y, r, 4.5)) {
      droplets.push({
        x,
        y,
        r,
        sag: map(r, 12.5, 22, 1.04, 1.14),
        tilt: random(-8, 8)
      });
    }
  }

  // 4C. Pack Medium Lenses (r = 6.5 to 12.2 px)
  for (let attempt = 0; attempt < 5500 && droplets.length < 285; attempt++) {
    let x = random(95, 1182);
    let y = random(60, 790);
    let r = random(6.5, 12.2);
    if (canPlaceDrop(x, y, r, 3.0)) {
      droplets.push({
        x,
        y,
        r,
        sag: map(r, 6.5, 12.2, 1.0, 1.06),
        tilt: random(-10, 10)
      });
    }
  }

  // 4D. Pack Small Lenses (r = 3.3 to 6.3 px)
  for (let attempt = 0; attempt < 14000 && droplets.length < 780; attempt++) {
    let x = random(85, 1186);
    let y = random(55, 798);
    let r = random(3.3, 6.3);
    if (canPlaceDrop(x, y, r, 1.8)) {
      droplets.push({
        x,
        y,
        r,
        sag: 1.0,
        tilt: random(-12, 12)
      });
    }
  }

  // 4E. Pack Obsessive Micro-Beads (r = 1.3 to 3.1 px) filling interstitial glass
  for (let attempt = 0; attempt < 26000 && droplets.length < 1720; attempt++) {
    let x = random(80, 1188);
    let y = random(52, 804);
    let r = random(1.3, 3.1);
    if (canPlaceDrop(x, y, r, 1.1)) {
      droplets.push({
        x,
        y,
        r,
        sag: 1.0,
        tilt: 0
      });
    }
  }

  // Sort droplets top-to-bottom for natural layering
  droplets.sort((a, b) => a.y - b.y);

  // =========================================================================
  // 5. RENDER EVERY DROPLET AS AN INVERTED OPTICAL LENS IN COLOURED PENCIL
  // =========================================================================
  // Dial center for computing warm amber refraction on lower droplets
  const dialX = 462;
  const dialY = 1085;

  // Helper: build an arc of points inside a droplet of radius (rx, ry)
  function makeDropArc(cx, cy, rx, ry, aStart, aEnd, steps = 5) {
    let pts = [];
    for (let i = 0; i <= steps; i++) {
      let a = lerp(aStart, aEnd, i / steps);
      pts.push([cx + rx * cos(a), cy + ry * sin(a)]);
    }
    return pts;
  }

  for (let d of droplets) {
    let { x, y, r, sag } = d;
    let rx = r * random(0.95, 1.03);
    let ry = r * sag;

    // Determine how much warm amber glow from the dashboard dial reaches this droplet
    let distToDial = dist(x, y, dialX, dialY - 180);
    let amberFactor = constrain(map(y, 440, 800, 0, 1), 0, 1) *
                      constrain(map(distToDial, 520, 80, 0, 1), 0, 1);

    // Check if the droplet is aligned horizontally with the coastal pier
    let hasPierInLens = x > 345 && x < 1190;

    // -----------------------------------------------------------------------
    // TIER 1: MICRO-BEADS (r < 3.2 px) — crisp two-tone pencil & white catchlight
    // -----------------------------------------------------------------------
    if (r < 3.2) {
      // Dark top refraction & tiny bottom contact shadow
      brush.set("color_pencil", "#2b323b", map(r, 1.3, 3.2, 0.28, 0.45));
      brush.line(x - rx * 0.75, y - ry * 0.45, x + rx * 0.75, y - ry * 0.45);
      brush.set("color_pencil", "#3d4652", 0.26);
      brush.line(x - rx * 0.55, y + ry * 0.85, x + rx * 0.55, y + ry * 0.85);

      // Luminous lower sky belly (or warm amber tint near the bottom)
      let bellyCol = amberFactor > 0.28
        ? lerpColor(color("#d8e4ed"), color("#f5ba72"), amberFactor * 0.85)
        : "#d8e4ed";
      brush.set("color_pencil", bellyCol, map(r, 1.3, 3.2, 0.3, 0.48));
      brush.line(x - rx * 0.6, y + ry * 0.38, x + rx * 0.6, y + ry * 0.38);

      // Crisp white pencil catchlight at upper-left
      brush.set("white_pencil", "#ffffff", map(r, 1.3, 3.2, 0.34, 0.58));
      brush.line(x - rx * 0.38, y - ry * 0.32, x + rx * 0.15, y - ry * 0.36);
      continue;
    }

    // -----------------------------------------------------------------------
    // TIER 2: SMALL LENSES (3.2 <= r < 6.5 px)
    // -----------------------------------------------------------------------
    if (r < 6.5) {
      // 1. Soft cast shadow beneath bottom rim
      brush.set("color_pencil", "#363e48", 0.38);
      brush.spline(makeDropArc(x, y + ry * 0.18, rx * 0.92, ry * 0.95, 25, 155, 4), 0.5);

      // 2. Inverted dark horizon/sea/cowl in upper half of droplet
      let topDark = hasPierInLens ? "#252c34" : "#303842";
      brush.set("color_pencil", topDark, 0.46);
      brush.spline(makeDropArc(x, y, rx * 0.86, ry * 0.86, 195, 345, 4), 0.5);
      brush.set("color_pencil", "#46505c", 0.42);
      brush.spline(makeDropArc(x, y, rx * 0.58, ry * 0.52, 190, 350, 4), 0.5);

      // 3. Inverted bright marine-layer sky in lower belly of droplet
      brush.set("color_pencil", "#bfd0de", 0.46);
      brush.spline(makeDropArc(x, y, rx * 0.64, ry * 0.58, 20, 160, 4), 0.5);
      brush.set("color_pencil", "#e3edf5", 0.48);
      brush.spline(makeDropArc(x, y, rx * 0.82, ry * 0.80, 30, 150, 4), 0.5);

      // Optional warm amber refraction rim on lower droplets
      if (amberFactor > 0.12) {
        let ambCol = lerpColor(color("#e89648"), color("#ffd48a"), amberFactor * 0.6);
        brush.set("color_pencil", ambCol, 0.42 * (0.5 + amberFactor));
        brush.spline(makeDropArc(x, y, rx * 0.86, ry * 0.86, 55, 135, 3), 0.5);
      }

      // 4. White pencil specular catchlight in upper-left dark dome
      brush.set("white_pencil", "#ffffff", map(r, 3.2, 6.5, 0.5, 0.78));
      brush.line(x - rx * 0.42, y - ry * 0.42, x + rx * 0.08, y - ry * 0.48);
      continue;
    }

    // -----------------------------------------------------------------------
    // TIER 3: MEDIUM & HERO LENSES (r >= 6.5 px) — Full Inverted World
    // -----------------------------------------------------------------------
    let isHero = r >= 12.2;

    // 1. Soft exterior cast shadow / contact rim under the bottom of the droplet
    brush.set("soft_blend", "#323943", map(r, 6.5, 22, 0.35, 0.65));
    brush.spline(makeDropArc(x, y + ry * 0.16, rx * 0.96, ry * 0.98, 20, 160, 6), 0.5);
    brush.set("color_pencil", "#282e36", map(r, 6.5, 22, 0.36, 0.52));
    brush.spline(makeDropArc(x, y + ry * 0.08, rx * 0.95, ry * 0.96, 28, 152, 6), 0.5);

    // 2. Inverted Upper Dome (holds the dark cowl, dark sea, and inverted pier!)
    let upperPasses = isHero ? 5 : 3;
    for (let p = 0; p < upperPasses; p++) {
      let frac = map(p, 0, upperPasses - 1, 0.92, 0.32);
      // Outer top rim is darkest (cowl/deep water), grading toward mid-grey horizon near center
      let domeCol;
      if (p === 0) {
        domeCol = color("#20262e");
      } else if (p === 1) {
        domeCol = hasPierInLens ? color("#2c343e") : color("#353e4a");
      } else {
        domeCol = lerpColor(color("#414b57"), color("#667380"), p / upperPasses);
      }
      brush.set("color_pencil", domeCol, map(r, 6.5, 22, 0.42, 0.62));
      let span = map(p, 0, upperPasses - 1, 82, 62);
      brush.spline(
        makeDropArc(x, y - ry * (1 - frac) * 0.12, rx * frac, ry * frac, 270 - span, 270 + span, 6),
        0.5
      );
    }

    // 3. Inverted Horizon & Miniature Inverted Pier across the center of the lens!
    // Because the lens is wide-angle, the horizon line curves slightly inside the droplet
    let invHorizY = y - ry * 0.06;
    brush.set("color_pencil", "#525d69", map(r, 6.5, 22, 0.35, 0.52));
    brush.spline([
      [x - rx * 0.85, invHorizY + ry * 0.12],
      [x, invHorizY - ry * 0.04],
      [x + rx * 0.85, invHorizY + ry * 0.12]
    ], 0.5);

    if (hasPierInLens && isHero) {
      // Tiny inverted pier wedge & microscopic inverted pilings inside hero droplets!
      brush.set("color_pencil", "#2b313a", 0.48);
      brush.spline([
        [x - rx * 0.82, invHorizY + ry * 0.09],
        [x - rx * 0.1, invHorizY - ry * 0.03],
        [x + rx * 0.45, invHorizY + ry * 0.03]
      ], 0.4);
      // Tiny inverted vertical ticks (pilings pointing UP toward the dark water in the top dome!)
      brush.set("2H", "#343b46", 0.32);
      for (let px = -0.65; px <= 0.35; px += 0.22) {
        let tx = x + rx * px;
        let ty = invHorizY + abs(px) * ry * 0.08;
        brush.line(tx, ty, tx, ty - ry * 0.16);
      }
    }

    // 4. Inverted Lower Belly (holds the luminous pastel blue-grey overcast sky!)
    let lowerPasses = isHero ? 5 : 3;
    for (let p = 0; p < lowerPasses; p++) {
      let frac = map(p, 0, lowerPasses - 1, 0.35, 0.88);
      // Inner belly is soft slate-blue sky; outer bottom crescent is bright horizon glow
      let skyCol = lerpColor(color("#96a6b5"), color("#e4eef5"), p / (lowerPasses - 1));
      if (amberFactor > 0.08 && p >= lowerPasses - 2) {
        skyCol = lerpColor(skyCol, color("#f5be76"), amberFactor * 0.55);
      }
      brush.set("color_pencil", skyCol, map(r, 6.5, 22, 0.44, 0.65));
      let span = map(p, 0, lowerPasses - 1, 58, 76);
      brush.spline(
        makeDropArc(x, y + ry * (1 - frac) * 0.08, rx * frac, ry * frac, 90 - span, 90 + span, 6),
        0.5
      );
    }

    // Extra luminous crescent right inside the bottom rim of hero droplets
    if (isHero) {
      let rimGlow = amberFactor > 0.2
        ? lerpColor(color("#eef6fc"), color("#ffdf9e"), amberFactor * 0.75)
        : color("#eef6fc");
      brush.set("white_pencil", rimGlow, 0.52);
      brush.spline(makeDropArc(x, y, rx * 0.78, ry * 0.80, 42, 138, 5), 0.5);
    }

    // Warm amber refraction glint on lower droplets from the dashboard dial
    if (amberFactor > 0.1) {
      let ambRim = lerpColor(color("#e08538"), color("#ffd280"), amberFactor);
      brush.set("color_pencil", ambRim, map(r, 6.5, 22, 0.4, 0.68) * (0.4 + 0.6 * amberFactor));
      brush.spline(makeDropArc(x, y, rx * 0.88, ry * 0.88, 52, 132, 4), 0.5);
    }

    // 5. Delicate lateral contour strokes to close the spherical tension
    brush.set("color_pencil", "#3b434e", 0.35);
    brush.spline(makeDropArc(x, y, rx * 0.94, ry * 0.94, 145, 215, 4), 0.5);
    brush.spline(makeDropArc(x, y, rx * 0.94, ry * 0.94, -35, 35, 4), 0.5);

    // 6. WHITE PENCIL CATCHLIGHT (Primary upper-left sky reflection + secondary lower glint)
    let hlW = map(r, 6.5, 22, 0.68, 1.05);
    brush.set("white_pencil", "#ffffff", hlW);
    brush.spline(makeDropArc(x, y, rx * 0.62, ry * 0.60, 218, 268, 4), 0.5);

    if (isHero) {
      // Double-stroke curved window catchlight in hero droplets
      brush.set("white_pencil", "#ffffff", hlW * 0.88);
      brush.spline(makeDropArc(x, y, rx * 0.50, ry * 0.48, 222, 264, 4), 0.5);
      // Tiny secondary internal caustics pinpoint at lower-right rim
      brush.set("white_pencil", "#f2f8fd", 0.52);
      brush.line(x + rx * 0.42, y + ry * 0.58, x + rx * 0.54, y + ry * 0.48);
    }
  }

  // =========================================================================
  // 6. WINDSHIELD WIPER BLADE (RESTING ALONG LOWER GLASS WITH BEADED DEW)
  // =========================================================================
  // Wiper sweeps from right-center pivot (x=980, y=822) across to left (x=140, y=792)
  function getWiperY(x) {
    let u = map(x, 140, 1020, 0, 1);
    return 790 + u * 26 - 14 * sin(u * 180);
  }

  // Dark rubber blade & articulated metal frame shaded in charcoal & dark slate pencil
  for (let x = 140; x <= 1040; x += 3) {
    let wy = getWiperY(x);
    let bladeThick = x < 780 ? 15 : map(x, 780, 1040, 15, 22);
    brush.set("charcoal", "#1e2228", 0.65);
    brush.line(x, wy, x, wy + bladeThick);
  }

  // Longitudinal graphite & coloured-pencil strokes along the wiper blade
  for (let offset = 0; offset <= 15; offset += 2.2) {
    let pts = [];
    for (let x = 135; x <= 1045; x += 45) {
      pts.push([x, getWiperY(x) + offset]);
    }
    let col = offset < 3 ? "#8e9ba8" : (offset < 8 ? "#323842" : "#1a1e24");
    let brName = offset < 3 ? "color_pencil" : "2B";
    brush.set(brName, col, offset < 3 ? 0.52 : 0.65);
    brush.spline(pts, 0.4);
  }

  // Secondary upper wiper bracket truss (between x = 340 and x = 760)
  let bracketPts = [];
  for (let x = 340; x <= 760; x += 35) {
    let u = map(x, 340, 760, 0, 1);
    let arch = 11 * sin(u * 180);
    bracketPts.push([x, getWiperY(x) - arch]);
  }
  brush.set("2B", "#252a32", 0.75);
  brush.spline(bracketPts, 0.4);
  brush.set("color_pencil", "#7f8c99", 0.42);
  brush.spline(bracketPts.map(p => [p[0], p[1] - 1.5]), 0.4);

  // Subtle warm amber reflection along the underside bevel of the wiper near the binnacle
  let wiperAmberPts = [];
  for (let x = 250; x <= 680; x += 30) {
    wiperAmberPts.push([x, getWiperY(x) + 12]);
  }
  brush.set("color_pencil", "#d9823b", 0.45);
  brush.spline(wiperAmberPts, 0.4);

  // Tiny dewdrops beaded along the top rubber edge of the wiper blade
  for (let x = 155; x < 980; x += random(9, 22)) {
    let wy = getWiperY(x) - 1.5;
    let br = random(1.8, 3.8);
    brush.set("color_pencil", "#22272f", 0.4);
    brush.line(x - br, wy, x + br, wy);
    brush.set("color_pencil", "#c5d3e0", 0.38);
    brush.line(x - br * 0.6, wy + 1, x + br * 0.6, wy + 1);
    brush.set("white_pencil", "#ffffff", 0.5);
    brush.line(x - br * 0.4, wy - 1.2, x + br * 0.2, wy - 1.2);
  }

  // =========================================================================
  // 7. CABIN INTERIOR FRAMING: A-PILLAR, ROOF HEADER & DASHBOARD COWL
  // =========================================================================

  // 7A. LEFT A-PILLAR (x = 0 to getAPillarX(y))
  brush.noStroke();
  brush.wash("#1c2026", 215);
  brush.beginShape(0);
  brush.vertex(0, 0);
  brush.vertex(getAPillarX(0) + 6, 0);
  brush.vertex(getAPillarX(450) + 6, 450);
  brush.vertex(getAPillarX(900) + 6, 900);
  brush.vertex(0, 900);
  brush.endShape(true);
  brush.noWash();

  // Dense coloured-pencil & charcoal shading on the A-pillar trim
  for (let y = 0; y < 880; y += 3.5) {
    let px = getAPillarX(y);
    let c = lerpColor(color("#16191e"), color("#2b313a"), noise(y * 0.015));
    brush.set("charcoal", c, random(0.6, 1.0));
    brush.line(0, y, px, y - 18);
  }
  // Diagonal cross-hatching along the A-pillar length
  for (let offset = 4; offset < 180; offset += 4.5) {
    let isRim = offset < 18;
    let col = isRim
      ? lerpColor(color("#758290"), color("#38404a"), offset / 18)
      : "#1d2127";
    brush.set("color_pencil", col, isRim ? 0.52 : 0.6);
    brush.line(getAPillarX(0) - offset, 0, max(0, getAPillarX(860) - offset), 860);
  }
  // Rubber weatherstrip seal along the inner edge of the A-pillar
  brush.set("2B", "#121519", 0.85);
  brush.line(getAPillarX(0) + 4, 0, getAPillarX(850) + 4, 850);
  brush.set("color_pencil", "#8b98a6", 0.45);
  brush.line(getAPillarX(0) + 1, 0, getAPillarX(850) + 1, 850);

  // 7B. TOP ROOF HEADER & REARVIEW MIRROR BRACKET (Upper Right)
  brush.noStroke();
  brush.wash("#191c22", 220);
  brush.beginShape(0);
  brush.vertex(0, 0);
  brush.vertex(1200, 0);
  for (let x = 1200; x >= 0; x -= 60) {
    brush.vertex(x, getRoofY(x));
  }
  brush.endShape(true);
  brush.noWash();

  for (let x = 0; x <= 1200; x += 5) {
    let ry = getRoofY(x);
    brush.set("charcoal", "#1b1f25", 0.7);
    brush.line(x, 0, x, ry);
  }
  // Soft cool dawn rim highlight along the lower lip of the headliner
  let roofEdgePts = [];
  for (let x = 180; x <= 1200; x += 40) {
    roofEdgePts.push([x, getRoofY(x)]);
  }
  brush.set("color_pencil", "#5b6673", 0.55);
  brush.spline(roofEdgePts, 0.4);

  // Corner of the rearview mirror housing peeking in at upper-right (x = 1030..1200, y = 45..135)
  brush.noStroke();
  brush.wash("#16191e", 235);
  brush.beginShape(0.2);
  brush.vertex(1045, 58);
  brush.vertex(1200, 52);
  brush.vertex(1200, 142);
  brush.vertex(1055, 134);
  brush.vertex(1035, 98);
  brush.endShape(true);
  brush.noWash();

  for (let y = 56; y <= 138; y += 3) {
    brush.set("color_pencil", y > 128 ? "#697684" : "#22272f", 0.52);
    brush.line(1042, y - 4, 1200, y + 4);
  }

  // 7C. DASHBOARD COWL & INSTRUMENT BINNACLE HOOD (y = getDashY(x) to 1200)
  brush.noStroke();
  brush.wash("#181b20", 235);
  brush.beginShape(0);
  for (let x = 0; x <= 1200; x += 40) {
    brush.vertex(x, getDashY(x));
  }
  brush.vertex(1200, 1200);
  brush.vertex(0, 1200);
  brush.endShape(true);
  brush.noWash();

  // Textured coloured-pencil shading across the dashboard top plane & binnacle arch
  for (let r = 0; r < 380; r += 3.2) {
    let pts = [];
    for (let x = 0; x <= 1200; x += 45) {
      pts.push([x, getDashY(x) + r]);
    }
    // Top 22px of the dashboard catches cool dawn sky light; lower recesses drop into deep charcoal
    let col;
    if (r < 8) {
      col = lerpColor(color("#6e7b88"), color("#3f4752"), r / 8);
    } else if (r < 32) {
      col = lerpColor(color("#3f4752"), color("#20242b"), (r - 8) / 24);
    } else {
      col = lerpColor(color("#20242b"), color("#14171c"), constrain((r - 32) / 180, 0, 1));
    }
    brush.set(r < 28 ? "color_pencil" : "charcoal", col, r < 28 ? 0.55 : 0.78);
    brush.spline(pts, 0.4);
  }

  // Fine vinyl-grain cross-hatching on the upper dashboard & binnacle hood
  brush.set("2H", "#313740", 0.34);
  for (let i = 0; i < 160; i++) {
    let x = random(20, 1180);
    let y = getDashY(x) + random(4, 95);
    brush.line(x, y, x + random(25, 65), y + random(-8, 8));
  }

  // Recessed shadow cave inside the instrument binnacle (centered around x = 475, y = 1060)
  brush.noStroke();
  brush.wash("#0f1115", 230);
  brush.beginShape(0.4);
  brush.vertex(205, 1200);
  brush.vertex(225, 955);
  brush.vertex(335, 875);
  brush.vertex(475, 858);
  brush.vertex(625, 878);
  brush.vertex(735, 965);
  brush.vertex(755, 1200);
  brush.endShape(true);
  brush.noWash();

  // =========================================================================
  // 8. THE AMBER DASHBOARD DIAL ALONG THE BOTTOM EDGE (THE ONLY WARMTH)
  // =========================================================================
  // Primary speedometer/tachometer dial at (dialX = 462, dialY = 1085)
  // Plus a smaller secondary fuel/temp gauge to its right at (subX = 648, subY = 1118)
  const subX = 648;
  const subY = 1118;

  // 8A. Concentric soft pastel amber washes for the warm instrument glow
  brush.noStroke();
  const amberGlowRings = [
    { x: dialX, y: dialY, r: 235, c: "#4a2412", a: 42 },
    { x: dialX, y: dialY, r: 190, c: "#733616", a: 50 },
    { x: dialX, y: dialY, r: 152, c: "#9e4b1c", a: 62 },
    { x: dialX, y: dialY, r: 120, c: "#c96626", a: 72 },
    { x: dialX, y: dialY, r: 92, c: "#e38439", a: 78 },
    { x: subX, y: subY, r: 95, c: "#6e3416", a: 48 },
    { x: subX, y: subY, r: 65, c: "#ad5622", a: 62 }
  ];
  for (let g of amberGlowRings) {
    brush.wash(g.c, g.a);
    brush.circle(g.x, g.y, g.r, 0.08);
  }

  // Dark inner dial face centers so the numbers, ticks, and needles glow around the perimeter
  brush.wash("#1a1412", 210);
  brush.circle(dialX, dialY, 96, 0.04);
  brush.circle(subX, subY, 52, 0.04);
  brush.noWash();

  // 8B. Soft blended pastel amber aura radiating into the binnacle & lower windshield
  for (let i = 0; i < 95; i++) {
    let ang = random(175, 365);
    let rad = random(70, 240);
    let gx = dialX + cos(ang) * rad * 1.15;
    let gy = dialY + sin(ang) * rad * 0.85;
    let t = map(rad, 70, 240, 0, 1);
    let c = lerpColor(color("#f5a653"), color("#693216"), t);
    brush.set("soft_blend", c, random(0.45, 0.85));
    brush.line(gx - random(18, 42), gy, gx + random(18, 42), gy + random(-6, 6));
  }

  // 8C. Warm amber grazing light on the underside lip of the instrument binnacle hood!
  for (let pass = 0; pass < 7; pass++) {
    let hoodLipPts = [];
    for (let x = 235; x <= 715; x += 25) {
      let u = map(x, 235, 715, -1, 1);
      let archY = 955 - 96 * (1 - u * u) + pass * 2.4;
      hoodLipPts.push([x, archY]);
    }
    let lipCol = lerpColor(color("#f7b96b"), color("#5e2d14"), pass / 6);
    brush.set("color_pencil", lipCol, map(pass, 0, 6, 0.65, 0.4));
    brush.spline(hoodLipPts, 0.45);
  }

  // Faint warm amber reflection on the inside lower windshield glass just above the binnacle
  for (let i = 0; i < 28; i++) {
    let rx = random(310, 620);
    let ry = random(735, 785);
    brush.set("soft_blend", "#d9823b", random(0.25, 0.45));
    brush.line(rx - 22, ry, rx + 22, ry + random(-2, 2));
  }

  // 8D. Main Dial Bezel, Glowing Scale Arc, Tick Marks, Odometer & Illuminated Needle
  const dialR = 114;

  // Outer metallic/amber-lit bezel rings
  brush.set("color_pencil", "#8c461e", 0.58);
  brush.arc(dialX, dialY, dialR + 8, 155, 385);
  brush.set("color_pencil", "#d97a34", 0.62);
  brush.arc(dialX, dialY, dialR + 3, 160, 380);
  brush.set("color_pencil", "#f7b465", 0.55);
  brush.arc(dialX, dialY, dialR, 165, 375);
  brush.set("color_pencil", "#b35b24", 0.45);
  brush.arc(dialX, dialY, dialR - 14, 165, 375);

  // Radial major & minor tick marks around the speedometer arc (160° to 380°)
  for (let a = 160; a <= 380; a += 4.4) {
    let isMajor = Math.round((a - 160) / 4.4) % 5 === 0;
    let rOuter = dialR - 3;
    let rInner = isMajor ? dialR - 17 : dialR - 10;
    let x1 = dialX + rOuter * cos(a);
    let y1 = dialY + rOuter * sin(a);
    let x2 = dialX + rInner * cos(a);
    let y2 = dialY + rInner * sin(a);

    if (isMajor) {
      // Soft amber bloom behind major ticks
      brush.set("soft_blend", "#f29441", 0.45);
      brush.line(x1, y1, x2, y2);
      // Crisp glowing pastel gold-cream tick mark
      brush.set("white_pencil", "#ffe4ab", 0.68);
      brush.line(x1, y1, x2, y2);

      // Tiny blurred numeral glyph block just inside each major tick
      let nx = dialX + (dialR - 27) * cos(a);
      let ny = dialY + (dialR - 27) * sin(a);
      brush.set("color_pencil", "#f7b261", 0.52);
      brush.line(nx - 4, ny - 2, nx + 4, ny - 2);
      brush.line(nx - 4, ny + 2, nx + 4, ny + 2);
      brush.set("white_pencil", "#ffebc2", 0.38);
      brush.line(nx - 2.5, ny, nx + 2.5, ny);
    } else {
      brush.set("color_pencil", "#e88a3c", 0.42);
      brush.line(x1, y1, x2, y2);
    }
  }

  // Glowing digital odometer / trip rectangle in the lower center of the main dial
  let odoW = 54, odoH = 16;
  brush.noStroke();
  brush.wash("#d96b26", 130);
  brush.rect(dialX, dialY + 42, odoW + 8, odoH + 6, "center");
  brush.wash("#f7a84f", 160);
  brush.rect(dialX, dialY + 42, odoW, odoH, "center");
  brush.noWash();
  // Odometer digit strokes
  brush.set("white_pencil", "#fff0c7", 0.48);
  for (let dx = -20; dx <= 20; dx += 7) {
    brush.line(dialX + dx - 2, dialY + 39, dialX + dx + 2, dialY + 39);
    brush.line(dialX + dx + 2, dialY + 39, dialX + dx + 2, dialY + 45);
    brush.line(dialX + dx - 2, dialY + 45, dialX + dx + 2, dialY + 45);
  }

  // Main Dial Needle resting at idle / 0 mph (pointing down-left at angle = 166°)
  let needleAng = 166;
  let nxTip = dialX + (dialR - 6) * cos(needleAng);
  let nyTip = dialY + (dialR - 6) * sin(needleAng);
  // Warm orange glow around needle
  brush.set("soft_blend", "#eb7328", 0.7);
  brush.line(dialX, dialY, nxTip, nyTip);
  brush.set("color_pencil", "#ff9e44", 0.85);
  brush.line(dialX, dialY, nxTip, nyTip);
  brush.set("white_pencil", "#fff2d1", 0.65);
  brush.line(dialX, dialY, nxTip, nyTip);

  // Center needle cap
  brush.set("color_pencil", "#2b201b", 0.8);
  brush.circle(dialX, dialY, 14, 0.05);
  brush.set("color_pencil", "#f29b48", 0.52);
  brush.arc(dialX, dialY, 15, 190, 340);

  // 8E. Secondary Smaller Gauge at (subX = 648, subY = 1118)
  const subR = 60;
  brush.set("color_pencil", "#bd6126", 0.52);
  brush.arc(subX, subY, subR + 2, 170, 360);
  brush.set("color_pencil", "#f09e4a", 0.48);
  brush.arc(subX, subY, subR, 175, 355);

  for (let a = 175; a <= 355; a += 15) {
    let isMaj = (a - 175) % 45 === 0;
    let x1 = subX + (subR - 2) * cos(a);
    let y1 = subY + (subR - 2) * sin(a);
    let x2 = subX + (subR - (isMaj ? 12 : 7)) * cos(a);
    let y2 = subY + (subR - (isMaj ? 12 : 7)) * sin(a);
    brush.set(isMaj ? "white_pencil" : "color_pencil", isMaj ? "#ffdfa1" : "#e08136", isMaj ? 0.55 : 0.38);
    brush.line(x1, y1, x2, y2);
  }
  // Sub-dial needle pointing to ~half tank (angle = 252°)
  let subNeedleAng = 252;
  brush.set("color_pencil", "#ff9e44", 0.68);
  brush.line(subX, subY, subX + (subR - 6) * cos(subNeedleAng), subY + (subR - 6) * sin(subNeedleAng));
  brush.set("white_pencil", "#ffefd0", 0.48);
  brush.line(subX, subY, subX + (subR - 8) * cos(subNeedleAng), subY + (subR - 8) * sin(subNeedleAng));

  // =========================================================================
  // 9. FOREGROUND STEERING WHEEL RIM (CATCHING DAWN LIGHT ABOVE & AMBER BELOW)
  // =========================================================================
  // The top leather rim of the steering wheel arcs across the lower foreground,
  // framing the glowing amber instrument dial behind it.
  const wheelCX = 455;
  const wheelCY = 1355;
  const wheelOuterR = 458;
  const wheelInnerR = 398;
  const wheelMidR = (wheelOuterR + wheelInnerR) * 0.5;
  const wheelTubeHalf = (wheelOuterR - wheelInnerR) * 0.5; // 30 px

  // Base dark charcoal wash along the steering wheel rim
  brush.noStroke();
  brush.wash("#14171c", 235);
  brush.beginShape(0.3);
  for (let a = 205; a <= 335; a += 5) {
    brush.vertex(wheelCX + wheelOuterR * cos(a), wheelCY + wheelOuterR * sin(a));
  }
  for (let a = 335; a >= 205; a -= 5) {
    brush.vertex(wheelCX + wheelInnerR * cos(a), wheelCY + wheelInnerR * sin(a));
  }
  brush.endShape(true);
  brush.noWash();

  // Concentric coloured-pencil & charcoal shading across the tubular leather rim
  for (let dr = -wheelTubeHalf; dr <= wheelTubeHalf; dr += 2.0) {
    let norm = dr / wheelTubeHalf; // -1 at inner rim (facing dial), +1 at outer rim (facing windshield)
    let r = wheelMidR + dr;

    // Color across the leather tube:
    // Outer top bevel (norm > 0.55) catches cool pale grey-blue dawn light from the windshield
    // Middle core (-0.45 <= norm <= 0.55) is deep matte charcoal leather
    // Inner bottom bevel (norm < -0.45) catches warm reflected amber-gold from the instrument dial!
    let pts = [];
    for (let a = 202; a <= 338; a += 4) {
      pts.push([wheelCX + r * cos(a), wheelCY + r * sin(a)]);
    }

    if (norm > 0.55) {
      let t = map(norm, 0.55, 1.0, 0, 1);
      let c = lerpColor(color("#282e37"), color("#7c8998"), pow(t, 1.3));
      brush.set("color_pencil", c, 0.55);
      brush.spline(pts, 0.45);
    } else if (norm >= -0.48) {
      let c = lerpColor(color("#15181e"), color("#232830"), 1 - abs(norm));
      brush.set("charcoal", c, 0.72);
      brush.spline(pts, 0.45);
    } else {
      // Inner rim: warm amber glow strongest near the center-top of the arch (242° to 302°)
      let t = map(norm, -0.48, -1.0, 0, 1);
      let darkCol = lerpColor(color("#221c1a"), color("#472818"), t);
      brush.set("color_pencil", darkCol, 0.55);
      brush.spline(pts, 0.45);

      // Overlaid warm amber-gold rim reflection right in front of the glowing dial
      let amberPts = [];
      for (let a = 236; a <= 310; a += 4) {
        amberPts.push([wheelCX + r * cos(a), wheelCY + r * sin(a)]);
      }
      let ambCol = lerpColor(color("#8a431b"), color("#f5a855"), pow(t, 1.2));
      brush.set("color_pencil", ambCol, 0.58 * (0.4 + 0.6 * t));
      brush.spline(amberPts, 0.45);
    }
  }

  // Crisp cool dawn pencil highlight along the very crown of the steering wheel leather
  let crownPts = [];
  for (let a = 228; a <= 312; a += 4) {
    crownPts.push([wheelCX + (wheelOuterR - 3) * cos(a), wheelCY + (wheelOuterR - 3) * sin(a)]);
  }
  brush.set("color_pencil", "#9aa8b6", 0.48);
  brush.spline(crownPts, 0.45);

  // Crisp warm amber-peach pencil highlight along the inner bottom seam of the wheel rim
  let innerSeamPts = [];
  for (let a = 246; a <= 298; a += 4) {
    innerSeamPts.push([wheelCX + (wheelInnerR + 2) * cos(a), wheelCY + (wheelInnerR + 2) * sin(a)]);
  }
  brush.set("white_pencil", "#ffd38c", 0.52);
  brush.spline(innerSeamPts, 0.45);

  noLoop();
}

