// ============================================================================
// GEOMETRY & DRAWING HELPERS
// ============================================================================

function washPoly(pts, col, alpha, curvature = 0.25) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, alpha);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function ellipsePoly(cx, cy, rx, ry, n = 40, rotDeg = 0) {
  let pts = [];
  let ca = Math.cos(rotDeg * DEG2RAD);
  let sa = Math.sin(rotDeg * DEG2RAD);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let ux = Math.cos(a) * rx;
    let uy = Math.sin(a) * ry;
    pts.push([cx + ux * ca - uy * sa, cy + ux * sa + uy * ca]);
  }
  return pts;
}

function washEllipse(cx, cy, rx, ry, col, alpha, n = 40, rotDeg = 0, curvature = 0.3) {
  washPoly(ellipsePoly(cx, cy, rx, ry, n, rotDeg), col, alpha, curvature);
}

function arcSplinePts(cx, cy, rx, ry, startDeg, endDeg, steps = 14, rotDeg = 0, peakPressure = 1.0) {
  let pts = [];
  let ca = Math.cos(rotDeg * DEG2RAD);
  let sa = Math.sin(rotDeg * DEG2RAD);
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let deg = startDeg + (endDeg - startDeg) * t;
    let rad = deg * DEG2RAD;
    let ux = Math.cos(rad) * rx;
    let uy = Math.sin(rad) * ry;
    let x = cx + ux * ca - uy * sa;
    let y = cy + ux * sa + uy * ca;
    let p = Math.sin(t * Math.PI) * peakPressure + 0.12;
    pts.push([x, y, p]);
  }
  return pts;
}

function drawArcStroke(brushName, col, weight, cx, cy, rx, ry, startDeg, endDeg, steps = 14, rotDeg = 0, peakP = 1.0) {
  let pts = arcSplinePts(cx, cy, rx, ry, startDeg, endDeg, steps, rotDeg, peakP);
  brush.noFill();
  brush.noWash();
  brush.set(brushName, col, weight);
  brush.spline(pts, 0.45);
  brush.noStroke();
}

// Helmet outer silhouette generator (sculpted astronaut dome with slight visor cheek flare)
function helmetOuterPoly(n = 72, scaleX = 1.0, scaleY = 1.0, offX = 0, offY = 0) {
  let pts = [];
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let ca = Math.cos(a);
    let sa = Math.sin(a);

    // Subtle aerodynamic helmet shaping: slightly broader cheek/jaw and flattened base neck
    let rModX = 1.0 + 0.028 * Math.sin(a) - 0.022 * Math.cos(2 * a);
    let rModY = 1.0 - (sa > 0.65 ? 0.045 * Math.pow((sa - 0.65) / 0.35, 1.6) : 0);
    // Left-front visor brow/cheek protrusion
    let visorBump = ca < -0.15 ? 0.025 * Math.exp(-Math.pow((sa + 0.08) / 0.65, 2)) : 0;

    let x = TV_CX + offX + ca * TV_RX * (rModX + visorBump) * scaleX;
    let y = TV_CY + offY + sa * TV_RY * rModY * scaleY;
    pts.push([x, y]);
  }
  return pts;
}

// Visor cowling opening polygon (slightly squared-circle Apollo faceplate contour)
function visorOpeningPoly(cx, cy, rx, ry, n = 64, superExp = 0.09) {
  let pts = [];
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let ca = Math.cos(a);
    let sa = Math.sin(a);
    // Subtle squircle modulation so it reads like a moulded astronaut visor bezel
    let mod = 1.0 + superExp * Math.cos(4 * a) * 0.22 - 0.018 * Math.sin(a);
    pts.push([cx + ca * rx * mod, cy + sa * ry * mod]);
  }
  return pts;
}

// Curvilinear fisheye projection onto the convex CRT screen
function screenProject(u, v) {
  let r2 = u * u + v * v;
  // Barrel distortion of a spherical convex mirror
  let k = 0.62;
  let inv = 1.0 / Math.sqrt(1.0 + k * r2);
  // Slight worm's-eye upward Foreshortening inside the reflection
  let uProj = u * inv;
  let vProj = (v - 0.035 * (1.0 - Math.min(1.2, r2))) * inv;

  // Clamp strictly inside the glass boundary
  let mag = Math.sqrt(uProj * uProj + vProj * vProj);
  if (mag > 0.985) {
    uProj = (uProj / mag) * 0.985;
    vProj = (vProj / mag) * 0.985;
  }

  // Apply the slight squircle modulation of the CRT glass
  let ang = Math.atan2(vProj, uProj);
  let mod = 1.0 + 0.09 * Math.cos(4 * ang) * 0.22 - 0.018 * Math.sin(ang);

  return [
    SCR_CX + uProj * SCR_RX * mod,
    SCR_CY + vProj * SCR_RY * mod
  ];
}

function screenGridPoly(u0, v0, u1, v1, stepsU = 8, stepsV = 8) {
  let pts = [];
  for (let i = 0; i <= stepsU; i++) {
    pts.push(screenProject(u0 + (u1 - u0) * (i / stepsU), v0));
  }
  for (let j = 1; j <= stepsV; j++) {
    pts.push(screenProject(u1, v0 + (v1 - v0) * (j / stepsV)));
  }
  for (let i = stepsU - 1; i >= 0; i--) {
    pts.push(screenProject(u0 + (u1 - u0) * (i / stepsU), v1));
  }
  for (let j = stepsV - 1; j >= 1; j--) {
    pts.push(screenProject(u0, v0 + (v1 - v0) * (j / stepsV)));
  }
  return pts;
}

function screenCurvePoly(uvPts) {
  let pts = [];
  for (let i = 0; i < uvPts.length; i++) {
    pts.push(screenProject(uvPts[i][0], uvPts[i][1]));
  }
  return pts;
}

// ============================================================================
// 1. DAYLIGHT WALL & SUNBEAM ATMOSPHERE
// ============================================================================

function renderDaylightWall() {
  // Base warm cream daylight wash across entire canvas
  washPoly([[0, 0], [1200, 0], [1200, 1200], [0, 1200]], "#faf3e3", 255, 0);

  // Upper wall atmospheric gradient: warm cream on left, soft atomic-turquoise sky bounce on right
  for (let i = 0; i < 14; i++) {
    let t = i / 13;
    let r = 980 - t * 680;
    washEllipse(220, 180, r * 1.15, r * 0.9, "#fffdf7", 18);
  }

  // Cool atomic turquoise ambient daylight bounce on the right wall zone
  for (let i = 0; i < 12; i++) {
    let t = i / 11;
    let rx = 620 - t * 380;
    let ry = 560 - t * 320;
    washEllipse(1060, 380, rx, ry, "#85e2f0", 11);
    washEllipse(1120, 620, rx * 0.85, ry * 0.75, "#3dc6db", 8);
  }

  // Warm biscuit depth near lower wall / right horizon
  for (let i = 0; i < 10; i++) {
    let h = 340 - i * 28;
    washPoly([
      [0, HORIZON_Y - h],
      [1200, HORIZON_Y - h * 1.2],
      [1200, HORIZON_Y + 4],
      [0, HORIZON_Y + 4]
    ], "#e8dac2", 14, 0);
  }

  // Diagonal shaft of clean bright sunlight streaming from top-left toward lower-right
  for (let i = 0; i < 10; i++) {
    let spread = i * 18;
    washPoly([
      [0, 0],
      [680 + spread, 0],
      [1200, 520 + spread * 0.8],
      [1200, 860],
      [340 - spread, 860],
      [0, 420 - spread * 0.6]
    ], "#ffffff", 11, 0);
  }

  // Subtle airbrushed wall texture & tangerine radiosity halo around the helmet
  for (let i = 0; i < 9; i++) {
    let r = 480 - i * 18;
    washEllipse(TV_CX - 15, TV_CY + 10, r, r * 0.96, "#ff7e40", 6);
  }

  // Clean architectural baseboard shadow line at horizon
  washPoly([[0, HORIZON_Y - 14], [1200, HORIZON_Y - 14], [1200, HORIZON_Y], [0, HORIZON_Y]], "#fffcf5", 190, 0);
  brush.set("micro_pen", "#b8aa93", 1.1);
  brush.line(0, HORIZON_Y - 14, 1200, HORIZON_Y - 14);
  brush.set("micro_pen", "#8f806a", 1.5);
  brush.line(0, HORIZON_Y, 1200, HORIZON_Y);
  brush.noStroke();
}

// ============================================================================
// 2. WHITE SHAG-FREE TERRAZZO FLOOR
// ============================================================================

function renderTerrazzoFloor() {
  // Base polished white/cream terrazzo slab
  washPoly([[0, HORIZON_Y], [1200, HORIZON_Y], [1200, 1200], [0, 1200]], "#f5eee0", 255, 0);

  // Subtle depth gradient from horizon to foreground
  for (let i = 0; i < 12; i++) {
    let y0 = HORIZON_Y + i * 12;
    washPoly([[0, HORIZON_Y], [1200, HORIZON_Y], [1200, y0 + 25], [0, y0 + 25]], "#dfd4c0", 12, 0);
  }

  // Bright daylight specular pool on left-center foreground floor
  for (let i = 0; i < 10; i++) {
    let rx = 640 - i * 48;
    let ry = 180 - i * 13;
    washEllipse(380, 1045, rx, ry, "#ffffff", 18);
  }

  // Atomic turquoise ambient reflection on right side of floor
  for (let i = 0; i < 8; i++) {
    washEllipse(1020, 980, 380 - i * 35, 110 - i * 9, "#a5edf7", 12);
  }

  // Generate perspective-foreshortened terrazzo aggregate stone chips in color batches
  const chipPalettes = [
    { col: "#e8531e", alpha: 185, weight: 0.16 }, // Tangerine / terracotta
    { col: "#f5935b", alpha: 170, weight: 0.12 }, // Warm coral
    { col: "#14b5c9", alpha: 185, weight: 0.15 }, // Atomic turquoise
    { col: "#7ce3f0", alpha: 165, weight: 0.10 }, // Pale aqua
    { col: "#e09f36", alpha: 165, weight: 0.11 }, // Warm ochre
    { col: "#c7b69b", alpha: 175, weight: 0.14 }, // Travertine beige
    { col: "#3c4750", alpha: 185, weight: 0.08 }, // Basalt charcoal
    { col: "#8d99a3", alpha: 165, weight: 0.07 }, // Cool silver-grey
    { col: "#ffffff", alpha: 220, weight: 0.07 }  // Pure white marble
  ];

  let buckets = chipPalettes.map(() => []);
  let accentChips = [];

  const totalChips = 680;
  for (let i = 0; i < totalChips; i++) {
    // Bias distribution slightly so both horizon and foreground have crisp density
    let u = random();
    let t = Math.pow(u, 1.15); // 0 at horizon, 1 at bottom edge
    let cy = HORIZON_Y + 5 + t * (1200 - HORIZON_Y - 2);
    let cx = random(-20, 1220);

    // Perspective scale & vertical foreshortening
    let perspScale = 0.22 + 0.98 * Math.pow(t, 1.3);
    let aspectY = 0.24 + 0.26 * t;
    let baseR = random(4.5, 16.5) * perspScale;

    // Pick palette bucket by weight
    let rw = random();
    let accum = 0;
    let bIdx = 0;
    for (let k = 0; k < chipPalettes.length; k++) {
      accum += chipPalettes[k].weight;
      if (rw <= accum) {
        bIdx = k;
        break;
      }
    }

    // Build angular 5-to-7-sided stone chip polygon
    let sides = floor(random(5, 8));
    let pts = [];
    let rotOffset = random(0, Math.PI * 2);
    for (let s = 0; s < sides; s++) {
      let ang = rotOffset + (s / sides) * Math.PI * 2 + random(-0.22, 0.22);
      let rad = baseR * random(0.68, 1.22);
      pts.push([
        cx + Math.cos(ang) * rad,
        cy + Math.sin(ang) * rad * aspectY
      ]);
    }
    buckets[bIdx].push(pts);

    if (t > 0.52 && baseR > 8.5 && random() < 0.35) {
      accentChips.push({ pts, bIdx });
    }
  }

  // Render chips batched by color
  brush.noStroke();
  brush.noFill();
  for (let b = 0; b < buckets.length; b++) {
    brush.wash(chipPalettes[b].col, chipPalettes[b].alpha);
    let list = buckets[b];
    for (let i = 0; i < list.length; i++) {
      let pts = list[i];
      brush.beginShape(0.05);
      for (let j = 0; j < pts.length; j++) {
        brush.vertex(pts[j][0], pts[j][1]);
      }
      brush.endShape(true);
    }
  }
  brush.noWash();

  // Crisp micro-edges on larger foreground aggregate chips
  for (let i = 0; i < accentChips.length; i++) {
    let pts = accentChips[i].pts;
    brush.set("micro_pen", "#ffffff", 0.55);
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
    brush.set("micro_pen", "#9c8f7a", 0.5);
    brush.line(pts[2][0], pts[2][1], pts[3][0], pts[3][1]);
  }
  brush.noStroke();

  // Brass / zinc terrazzo divider strips in worm's-eye perspective
  const vpX = 588;
  const vpY = 670;
  const rayBottomX = [-260, 190, 620, 1060, 1480];
  for (let i = 0; i < rayBottomX.length; i++) {
    let bx = rayBottomX[i];
    let tH = (HORIZON_Y - vpY) / (1200 - vpY);
    let hx = vpX + (bx - vpX) * tH;
    brush.set("micro_pen", "#b5a68e", 0.95);
    brush.line(hx, HORIZON_Y, bx, 1200);
    brush.set("micro_pen", "#ffffff", 0.75);
    brush.line(hx + 1.5, HORIZON_Y, bx + 2.2, 1200);
  }

  // Two horizontal perspective slab seams
  const seamYs = [916, 1054];
  for (let i = 0; i < seamYs.length; i++) {
    let sy = seamYs[i];
    brush.set("micro_pen", "#b8aa93", 0.9 + i * 0.25);
    brush.line(0, sy, 1200, sy);
    brush.set("micro_pen", "#ffffff", 0.8 + i * 0.2);
    brush.line(0, sy + 1.6, 1200, sy + 1.6);
  }
  brush.noStroke();
}

