function renderTangerineHelmetShell() {
  // 1. Crisp base silhouette of the monumental tangerine helmet
  let baseHull = helmetOuterPoly(84, 1.0, 1.0, 0, 0);
  washPoly(baseHull, "#ff4d12", 255, 0.25);
  washPoly(baseHull, "#f54207", 140, 0.25);

  // 2. Deep volumetric core shadow on right & lower-right belly (30 smooth airbrush wash layers)
  for (let i = 0; i < 28; i++) {
    let t = i / 27;
    let sx = lerp(0.99, 0.52, t);
    let sy = lerp(0.99, 0.55, t);
    let ox = lerp(4, 118, t);
    let oy = lerp(4, 72, t);
    let col = t < 0.35 ? "#d92b00" : (t < 0.7 ? "#a81800" : "#6e0a00");
    washPoly(helmetOuterPoly(64, sx, sy, ox, oy), col, 15, 0.25);
  }

  // 3. Radiant sunlit tangerine gradations toward upper-left dome & brow
  for (let i = 0; i < 26; i++) {
    let t = i / 25;
    let sx = lerp(0.96, 0.22, t);
    let sy = lerp(0.95, 0.20, t);
    let ox = lerp(-6, -135, t);
    let oy = lerp(-6, -148, t);
    let col = t < 0.3
      ? "#ff6221"
      : (t < 0.6 ? "#ff7d3b" : (t < 0.85 ? "#ffa364" : "#ffd19e"));
    washPoly(helmetOuterPoly(60, sx, sy, ox, oy), col, 16, 0.25);
  }

  // 4. Airbrush & satin-spray blending passes along spherical parallels
  for (let i = 0; i < 14; i++) {
    let t = i / 13;
    let r = lerp(TV_RX * 0.96, TV_RX * 0.55, t);
    // Warm sunlit upper-left sweep
    drawArcStroke("airbrush_xl", "#ff9654", 1.3, TV_CX - 12, TV_CY - 8, r, r * 0.97, -165, -35, 16, 0, 0.9);
    // Deep burnt crimson-orange core shadow sweep on lower-right
    drawArcStroke("airbrush_xl", "#7d0c00", 1.3, TV_CX + 10, TV_CY + 8, r, r * 0.97, -15, 105, 16, 0, 0.9);
  }

  // Subtle fibreglass satin spray sheen over midtones
  for (let i = 0; i < 8; i++) {
    let r = TV_RX * (0.72 + i * 0.03);
    drawArcStroke("satin_spray", "#ffb37a", 0.9, TV_CX - 25, TV_CY - 20, r, r * 0.96, -155, -55, 14, 0, 0.8);
    drawArcStroke("satin_spray", "#ff591c", 0.9, TV_CX, TV_CY, r, r * 0.96, -45, 75, 14, 0, 0.8);
  }

  // 5. Crucial hyperreal rim bounce-lights!
  // A. Cream & bright tangerine terrazzo floor bounce wrapping around the bottom chin & belly
  for (let i = 0; i < 9; i++) {
    let inset = 4 + i * 3.5;
    let col = i < 4 ? "#ffb884" : "#ff7336";
    drawArcStroke("airbrush_soft", col, 1.1 - i * 0.08, TV_CX, TV_CY - 2, TV_RX - inset, TV_RY - inset, 25, 152, 20, 0, 1.0);
  }

  // B. Atomic turquoise ambient sky reflection hugging the right-hand shadow rim
  for (let i = 0; i < 8; i++) {
    let inset = 3 + i * 3.2;
    let col = i < 3 ? "#a8f3fc" : "#2bc9de";
    drawArcStroke("airbrush_soft", col, 0.95 - i * 0.08, TV_CX + 2, TV_CY, TV_RX - inset, TV_RY - inset, -52, 38, 18, 0, 0.95);
  }

  // 6. Sculpted Astronaut Visor Cowling / Chamfered Lip Surround
  // Because of the worm's-eye view, we see the underside of the upper visor overhang
  // and the sunlit top shelf of the lower visor chin guard!
  const cowlingCX = SCR_CX + 4;
  const cowlingCY = SCR_CY + 2;
  const cowlingRX = SCR_RX + 34;
  const cowlingRY = SCR_RY + 32;

  // Outer chamfer bevel ridge around visor opening
  for (let i = 0; i < 7; i++) {
    let dr = i * 3;
    // Upper brow ridge catching top sunlight
    drawArcStroke("airbrush_fine", "#ffc58f", 1.3, cowlingCX, cowlingCY - 4, cowlingRX + 8 - dr, cowlingRY + 8 - dr, -155, -28, 18, 0, 1.0);
    // Right cheek chamfer shadow
    drawArcStroke("airbrush_fine", "#780b00", 1.4, cowlingCX + 3, cowlingCY, cowlingRX + 4 - dr, cowlingRY + 4 - dr, -22, 62, 16, 0, 1.0);
  }

  // Worm's-eye underside of upper visor brow lip (in warm deep shadow with floor bounce)
  for (let i = 0; i < 8; i++) {
    let t = i / 7;
    let rx = lerp(cowlingRX, SCR_RX + 14, t);
    let ry = lerp(cowlingRY, SCR_RY + 12, t);
    let col = t < 0.5 ? "#6e0a00" : "#b82200";
    drawArcStroke("airbrush_fine", col, 1.5, cowlingCX, cowlingCY - 2, rx, ry, -162, -18, 22, 0, 1.0);
  }

  // Worm's-eye upward-facing shelf of the lower visor chin trough (blazing with top daylight!)
  for (let i = 0; i < 9; i++) {
    let t = i / 8;
    let rx = lerp(cowlingRX, SCR_RX + 14, t);
    let ry = lerp(cowlingRY, SCR_RY + 13, t);
    let col = t < 0.35 ? "#ff6826" : (t < 0.75 ? "#ffa364" : "#ffe0ba");
    drawArcStroke("airbrush_fine", col, 1.5, cowlingCX, cowlingCY + 3, rx, ry, 18, 162, 22, 0, 1.0);
  }

  // 7. Insistently real Fibreglass Mould Seams (parting lines)
  // Main meridional mould seam from top antenna mount down the right hemisphere to the neck ring
  const seamPtsDark = [
    [586, 134, 0.5],
    [685, 152, 0.8],
    [786, 218, 0.95],
    [866, 326, 1.0],
    [906, 442, 0.9],
    [912, 514, 0.6],
    [896, 598, 0.95],
    [846, 706, 1.0],
    [768, 795, 0.9],
    [714, 838, 0.5]
  ];
  const seamPtsLight = seamPtsDark.map(p => [p[0] - 1.9, p[1] - 0.8, p[2]]);

  brush.set("micro_pen", "#5c0900", 1.05);
  brush.spline(seamPtsDark, 0.45);
  brush.set("micro_pen", "#ffb882", 0.85);
  brush.spline(seamPtsLight, 0.45);

  // Bright specular glint where the mould seam crosses the upper highlight zone
  brush.set("micro_pen", "#ffffff", 0.95);
  brush.spline(seamPtsLight.slice(0, 5), 0.45);

  // Secondary visor-cheek mould parting seams at 10 o'clock and 8 o'clock
  // Left temple seam
  brush.set("micro_pen", "#8f1900", 0.9);
  brush.line(235, 312, 294, 336);
  brush.set("micro_pen", "#ffe3bf", 0.85);
  brush.line(235, 310.3, 294, 334.3);

  // Lower-left jaw seam
  brush.set("micro_pen", "#7d1200", 0.95);
  brush.line(252, 652, 312, 622);
  brush.set("micro_pen", "#ffc28a", 0.85);
  brush.line(252, 650.2, 312, 620.2);

  // Crisp outer shell contour micro-refinement
  drawArcStroke("micro_pen", "#ffcaa0", 0.9, TV_CX, TV_CY, TV_RX, TV_RY, -165, -70, 20, 0, 0.9);
  drawArcStroke("micro_pen", "#4a0600", 1.0, TV_CX, TV_CY, TV_RX, TV_RY, 10, 95, 18, 0, 0.9);
  brush.noStroke();
}

