  drawArcStroke("airbrush_fine", "#6bdce8", 1.1, SCR_CX + 3, SCR_CY, bezelRX - 5, bezelRY - 5, -35, 45, 14, 0, 0.9);

  // 2. Deep charcoal-black rubber CRT gasket seating the convex glass
  const gasketRX = SCR_RX + 8;
  const gasketRY = SCR_RY + 8;
  washPoly(visorOpeningPoly(SCR_CX, SCR_CY, gasketRX, gasketRY, 68), "#0f1318", 255, 0.25);

  // Subtle rubber specular highlight along lower-left gasket lip
  drawArcStroke("micro_pen", "#758896", 1.3, SCR_CX, SCR_CY + 1, gasketRX - 2, gasketRY - 2, 30, 155, 20, 0, 0.95);
  drawArcStroke("micro_pen", "#050709", 1.6, SCR_CX, SCR_CY, gasketRX, gasketRY, -165, 20, 22, 0, 1.0);
  brush.noStroke();
}

// ============================================================================
// 8. CONVEX GREY CRT SCREEN & DISTORTED FISHEYE REFLECTION
// ============================================================================

function renderConvexScreenAndReflections() {
  // --------------------------------------------------------------------------
  // A. Base Convex Grey CRT Glass Dome
  // --------------------------------------------------------------------------
  let screenOutline = visorOpeningPoly(SCR_CX, SCR_CY, SCR_RX, SCR_RY, 72);
  washPoly(screenOutline, "#1b2229", 255, 0.25);

  // Concentric spherical phosphor glass tone (warm-cool neutral slate grey)
  for (let i = 0; i < 18; i++) {
    let t = i / 17;
    let s = lerp(0.98, 0.22, t);
    let ox = lerp(0, -32, t);
    let oy = lerp(0, -28, t);
    let col = t < 0.35 ? "#252e37" : (t < 0.75 ? "#333f4a" : "#43525e");
    washPoly(visorOpeningPoly(SCR_CX + ox, SCR_CY + oy, SCR_RX * s, SCR_RY * s, 56), col, 22, 0.25);
  }

  // Thick glass faceplate internal phosphor edge glow inside the dark rim
  drawArcStroke("airbrush_fine", "#637785", 1.2, SCR_CX, SCR_CY, SCR_RX - 5, SCR_RY - 5, 110, 245, 18, 0, 0.9);

  // --------------------------------------------------------------------------
  // B. Curvilinear Distorted Reflection of Sunlit Picture Window & Room
  // --------------------------------------------------------------------------
  // 1. Reflected interior cream wall on the right & upper-right of the convex screen
  washPoly(screenGridPoly(0.36, -0.92, 0.96, 0.22, 6, 8), "#7a786e", 55, 0.2);
  washPoly(screenGridPoly(0.42, -0.82, 0.92, 0.12, 6, 8), "#a69e8e", 45, 0.2);
  // Atomic turquoise ambient wall shadow reflected on right side of screen
  washPoly(screenGridPoly(0.46, -0.58, 0.95, 0.28, 6, 8), "#2c6d7a", 50, 0.2);

  // 2. Reflected terrazzo floor wrapping around the bottom hemisphere of the screen
  washPoly(screenGridPoly(-0.92, 0.24, 0.92, 0.95, 10, 6), "#4f5250", 65, 0.2);
  washPoly(screenGridPoly(-0.78, 0.36, 0.78, 0.92, 10, 6), "#7d796e", 55, 0.2);
  washPoly(screenGridPoly(-0.62, 0.48, 0.52, 0.88, 8, 5), "#a89f8e", 45, 0.2);

  // 3. The Sunlit Picture Window (bowed into spherical fisheye trapezoids!)
  // Window occupies u in [-0.92, +0.44], v in [-0.94, +0.10]
  // Divided into 3 columns: [-0.92..-0.44], [-0.40..+0.02], [+0.06..+0.44]
  // and 2 rows: transom [-0.94..-0.54] and main lower panes [-0.50..+0.10]
  const winCols = [
    [-0.91, -0.45],
    [-0.41, 0.01],
    [0.05, 0.43]
  ];
  const winRows = [
    [-0.92, -0.55], // Upper transom panes (atomic turquoise sky)
    [-0.50, 0.09]   // Lower main picture panes (blazing sunlit sky & horizon)
  ];

  // Soft daylight bloom behind the entire window reflection
  for (let i = 0; i < 6; i++) {
    let pad = i * 0.035;
    washPoly(
      screenGridPoly(-0.93 - pad, -0.94 - pad, 0.46 + pad, 0.12 + pad, 10, 8),
      "#8cebf7",
      18,
      0.25
    );
  }

  for (let r = 0; r < winRows.length; r++) {
    for (let c = 0; c < winCols.length; c++) {
      let u0 = winCols[c][0];
      let u1 = winCols[c][1];
      let v0 = winRows[r][0];
      let v1 = winRows[r][1];

      // Base sky tone: richer atomic turquoise on upper-right, blazing white/aqua on left
      let baseCol = r === 0
        ? (c === 0 ? "#6beaf7" : (c === 1 ? "#2ad4e8" : "#0faec4"))
        : (c === 0 ? "#ffffff" : (c === 1 ? "#c7f8ff" : "#7cebf7"));
      let baseAlpha = r === 0 ? 155 : (c === 0 ? 225 : 175);

      washPoly(screenGridPoly(u0, v0, u1, v1, 7, 6), baseCol, baseAlpha, 0.2);

      // Warm sunlit horizon / architectural terrace band at bottom of lower panes
      if (r === 1) {
        washPoly(screenGridPoly(u0, -0.12, u1, v1, 6, 4), "#fff6db", c === 0 ? 210 : 155, 0.2);
        washPoly(screenGridPoly(u0, -0.02, u1, v1, 6, 4), "#ffe4b3", 95, 0.2);
      }
    }
  }

  // Intense solar glow across the left & center window panes
  for (let i = 0; i < 8; i++) {
    let t = i / 7;
    let u0 = lerp(-0.88, -0.62, t);
    let u1 = lerp(0.12, -0.25, t);
    let v0 = lerp(-0.82, -0.52, t);
    let v1 = lerp(0.06, -0.18, t);
    washPoly(screenGridPoly(u0, v0, u1, v1, 6, 6), "#ffffff", 26, 0.25);
  }

  // Curvilinear window mullions & transom bars warped by the spherical screen
  const mullionUs = [-0.91, -0.43, 0.03, 0.44];
  for (let u of mullionUs) {
    let pts = [];
    for (let k = 0; k <= 12; k++) {
      let v = -0.92 + (1.02 * k) / 12;
      let p = screenProject(u, v);
      pts.push([p[0], p[1], 0.9]);
    }
    brush.set("micro_pen", "#263842", 1.8);
    brush.spline(pts, 0.45);
    let ptsHi = pts.map(p => [p[0] + 1.5, p[1], 0.8]);
    brush.set("micro_pen", "#dff9fc", 0.95);
    brush.spline(ptsHi, 0.45);
  }

  const transomVs = [-0.92, -0.525, 0.095];
  for (let v of transomVs) {
    let pts = [];
    for (let k = 0; k <= 14; k++) {
      let u = -0.91 + (1.35 * k) / 14;
      let p = screenProject(u, v);
      pts.push([p[0], p[1], 0.9]);
    }
    brush.set("micro_pen", "#263842", 1.8);
    brush.spline(pts, 0.45);
    let ptsHi = pts.map(p => [p[0], p[1] + 1.5, 0.8]);
    brush.set("micro_pen", "#dff9fc", 0.95);
    brush.spline(ptsHi, 0.45);
  }
  brush.noStroke();

  // --------------------------------------------------------------------------
  // C. The Child's Wide-Eyed Face (Fisheye Distorted in the Convex Screen)
  // --------------------------------------------------------------------------
  renderReflectedChildFace();

  // --------------------------------------------------------------------------
  // D. Convex Glass Vignette, Scanline Sheen & Fresnel Rim Shadow
  // --------------------------------------------------------------------------
  // Subtle curved CRT scanline / shadow-mask texture across the screen
  for (let k = -18; k <= 18; k++) {
    let v = k * 0.05;
    let uMax = Math.sqrt(Math.max(0.05, 0.92 - v * v));
    let pts = [];
    for (let s = 0; s <= 12; s++) {
      let u = -uMax + (2 * uMax * s) / 12;
      let p = screenProject(u, v);
      pts.push([p[0], p[1], 0.6]);
    }
    brush.set("micro_pen", k % 2 === 0 ? "#12181e" : "#4b5f6b", 0.45);
    brush.spline(pts, 0.45);
  }
  brush.noStroke();

  // Deep curved Fresnel shadow around the perimeter of the convex glass
  for (let i = 0; i < 9; i++) {
    let inset = i * 3.2;
    drawArcStroke("airbrush_fine", "#0d1217", 1.6 - i * 0.14, SCR_CX, SCR_CY, SCR_RX - inset, SCR_RY - inset, -180, 180, 32, 0, 1.0);
  }
}

function renderReflectedChildFace() {
  // Helper for drawing closed smooth shapes in (u, v) spherical reflection coordinates
  function washUVEllipse(uc, vc, ru, rv, col, alpha, n = 32, rotDeg = 0) {
    let uvPts = [];
    let ca = Math.cos(rotDeg * DEG2RAD);
    let sa = Math.sin(rotDeg * DEG2RAD);
    for (let i = 0; i < n; i++) {
      let a = (i / n) * Math.PI * 2;
      let du = Math.cos(a) * ru;
      let dv = Math.sin(a) * rv;
      uvPts.push([uc + du * ca - dv * sa, vc + du * sa + dv * ca]);
    }
    washPoly(screenCurvePoly(uvPts), col, alpha, 0.3);
  }

  // 1. Backlit halo around the child's head against the bright window reflection
  for (let i = 0; i < 7; i++) {
    let s = 1.0 + i * 0.045;
    washUVEllipse(0.02, 0.08, 0.56 * s, 0.56 * s, "#b8f4fc", 14, 36);
  }

  // 2. Child's shoulders & Space-Age ringer T-shirt at bottom of screen
  washPoly(screenCurvePoly([
    [-0.68, 0.92], [-0.54, 0.68], [-0.24, 0.58],
    [0.28, 0.58], [0.58, 0.68], [0.72, 0.92],
    [0.35, 0.96], [-0.35, 0.96]
  ]), "#1b2830", 160, 0.25);

  // Cream & atomic-turquoise ringer collar reflection
  washPoly(screenCurvePoly([
    [-0.48, 0.88], [-0.36, 0.69], [0.02, 0.64],
    [0.40, 0.69], [0.52, 0.88], [0.02, 0.94]
  ]), "#8fa3ad", 85, 0.25);
  washPoly(screenCurvePoly([
    [-0.28, 0.64], [0.02, 0.72], [0.32, 0.64],
    [0.26, 0.59], [0.02, 0.66], [-0.22, 0.59]
  ]), "#1ebbd1", 95, 0.25);

  // 3. Tousled Hair & Cranium Silhouette (dark warm umber-slate with sunlit rim locks)
  const hairUV = [
    [-0.56, 0.16], [-0.62, -0.06], [-0.58, -0.28], [-0.42, -0.44],
    [-0.18, -0.52], [0.08, -0.53], [0.34, -0.47], [0.52, -0.32],
    [0.61, -0.10], [0.58, 0.15], [0.46, 0.28], [-0.44, 0.28]
  ];
  washPoly(screenCurvePoly(hairUV), "#19181b", 190, 0.3);
  washPoly(screenCurvePoly(hairUV.map(p => [p[0] * 0.94, p[1] * 0.94])), "#29201d", 145, 0.3);

  // Warm chestnut & sunlit golden-orange rim highlights along top-left tousled bangs
  washUVEllipse(-0.22, -0.42, 0.26, 0.11, "#8c4d2b", 75, 28, -18);
  washUVEllipse(-0.36, -0.30, 0.18, 0.12, "#d47c42", 70, 24, -35);
  washUVEllipse(-0.12, -0.47, 0.22, 0.06, "#ffe4b5", 95, 24, -8);
  washUVEllipse(0.24, -0.42, 0.20, 0.07, "#6be3f2", 65, 24, 16);

  // Ears peeking through hair on left & right (strongly foreshortened near sphere sides)
  washUVEllipse(-0.52, 0.18, 0.07, 0.14, "#4a3832", 140, 20, -10);
  washUVEllipse(-0.51, 0.18, 0.05, 0.10, "#9e6248", 95, 20, -10);
  washUVEllipse(0.55, 0.18, 0.07, 0.14, "#2d282b", 150, 20, 10);

  // 4. Child's Face Oval (bulging cheeks & forehead, tapered chin due to fisheye lens)
  const faceUV = [
    [-0.44, -0.12], [-0.34, -0.30], [0.02, -0.34], [0.38, -0.30],
    [0.47, -0.12], [0.49, 0.14], [0.42, 0.38], [0.24, 0.56],
    [0.02, 0.63], [-0.20, 0.56], [-0.39, 0.38], [-0.47, 0.14]
  ];
  // Dark glass-tinted skin foundation
  washPoly(screenCurvePoly(faceUV), "#2d2b2e", 175, 0.35);
  washPoly(screenCurvePoly(faceUV.map(p => [p[0] * 0.96, p[1] * 0.96])), "#4f3a34", 120, 0.35);

  // Soft airbrush planes of the face:
  // Warm tangerine bounce from the TV bezel onto cheeks, temples, and jaw
  for (let i = 0; i < 8; i++) {
    let t = i / 7;
    let s = lerp(0.95, 0.45, t);
    // Left sunlit cheek & forehead
    washUVEllipse(-0.18, 0.14, 0.28 * s, 0.32 * s, t < 0.5 ? "#9c5238" : "#d9825b", 22);
    // Right cheek (cooler glass shadow + warm orange cheek glow)
    washUVEllipse(0.24, 0.18, 0.25 * s, 0.28 * s, t < 0.5 ? "#423d42" : "#874b39", 22);
    // Forehead dome highlight
    washUVEllipse(-0.04, -0.16, 0.32 * s, 0.15 * s, t < 0.5 ? "#ad7055" : "#e8b496", 20);
    // Chin pad
    washUVEllipse(0.02, 0.53, 0.16 * s, 0.09 * s, "#b86b4d", 18);
  }

  // Tangerine radiosity glow on full lower cheeks & nose underside
  washUVEllipse(-0.28, 0.24, 0.16, 0.14, "#ff6b2b", 35, 24, -12);
  washUVEllipse(0.29, 0.25, 0.15, 0.13, "#ff5d1f", 30, 24, 12);
  washUVEllipse(0.02, 0.31, 0.14, 0.07, "#ff6829", 32, 24, 0);

  // Creamy sunlit highlights on left cheekbone, brow bone, and bridge/tip of nose
  for (let i = 0; i < 6; i++) {
    let s = 1.0 - i * 0.14;
    washUVEllipse(-0.22, 0.18, 0.14 * s, 0.09 * s, "#ffd8bd", 22, 24, -14);
    washUVEllipse(-0.14, -0.16, 0.18 * s, 0.08 * s, "#ffe7d1", 22, 24, -8);
    washUVEllipse(0.02, 0.04, 0.055 * s, 0.13 * s, "#f5c5a6", 20, 20, 0);
  }

  // 5. Tousled Bangs Falling Across the Forehead
  const bangLocks = [
    [[-0.44, -0.18], [-0.34, -0.34], [-0.20, -0.12], [-0.36, -0.08]],
    [[-0.24, -0.36], [-0.06, -0.38], [-0.08, -0.14], [-0.20, -0.16]],
    [[-0.04, -0.38], [0.16, -0.36], [0.10, -0.15], [-0.02, -0.18]],
    [[0.16, -0.36], [0.36, -0.28], [0.28, -0.10], [0.14, -0.16]],
    [[0.34, -0.28], [0.46, -0.12], [0.40, 0.02], [0.30, -0.12]]
  ];
  for (let i = 0; i < bangLocks.length; i++) {
    washPoly(screenCurvePoly(bangLocks[i]), i < 2 ? "#2b1d17" : "#1c181a", 165, 0.3);
  }

  // 6. THE WIDE-EYED WONDER: Large Magnified Eyes in the Convex Mirror
  const eyes = [
    { uc: -0.215, vc: 0.025, rot: -7, isLeft: true },
    { uc: 0.255, vc: 0.025, rot: 7, isLeft: false }
  ];

  for (let e of eyes) {
    let uc = e.uc;
    let vc = e.vc;
    let rot = e.rot;

    // Eye socket shadow & upper eyelid fold
    washUVEllipse(uc, vc - 0.01, 0.165, 0.125, "#1f2229", 130, 28, rot);
    washUVEllipse(uc, vc + 0.01, 0.15, 0.105, "#15191f", 180, 28, rot);

    // Wide-open sclera (almond-round, slightly bowed by spherical lens)
    washUVEllipse(uc, vc, 0.132, 0.086, "#7b929e", 195, 30, rot);
    washUVEllipse(uc - 0.01, vc - 0.004, 0.115, 0.074, "#bdd2dc", 185, 28, rot);
    washUVEllipse(uc - 0.02, vc - 0.008, 0.092, 0.058, "#e6f4f9", 150, 24, rot);

    // Large wonder-struck Iris (outer limbal ring + warm hazel/turquoise stroma)
    let irisU = uc + (e.isLeft ? 0.012 : -0.012);
    let irisV = vc - 0.003;
    washUVEllipse(irisU, irisV, 0.074, 0.072, "#121b21", 235, 28, 0);
    washUVEllipse(irisU, irisV, 0.064, 0.062, "#2d5763", 215, 28, 0);
    washUVEllipse(irisU + 0.005, irisV + 0.008, 0.052, 0.048, "#7d5130", 170, 24, 0);
    washUVEllipse(irisU + 0.008, irisV + 0.014, 0.038, 0.032, "#c27d44", 135, 20, 0);

    // Radial iris fibers
    let irisCenter = screenProject(irisU, irisV);
    for (let k = 0; k < 16; k++) {
      let ang = (k / 16) * Math.PI * 2;
      let pOut = screenProject(irisU + Math.cos(ang) * 0.06, irisV + Math.sin(ang) * 0.058);
      brush.set("micro_pen", k % 2 === 0 ? "#5bd6e6" : "#d99252", 0.55);
      brush.line(irisCenter[0], irisCenter[1], pOut[0], pOut[1]);
    }
    brush.noStroke();

    // Deep dilated pupil
    washUVEllipse(irisU, irisV, 0.034, 0.033, "#06080a", 250, 24, 0);

    // Miniature reflection of the sunlit picture window & tangerine TV shell inside the cornea!
    washUVEllipse(irisU - 0.024, irisV - 0.022, 0.024, 0.017, "#9ef4ff", 230, 16, -15);
    washUVEllipse(irisU - 0.022, irisV - 0.020, 0.017, 0.012, "#ffffff", 255, 16, -15);
    washUVEllipse(irisU + 0.020, irisV + 0.022, 0.015, 0.009, "#ff6d2b", 215, 14, 15);
    washUVEllipse(irisU - 0.042, irisV + 0.018, 0.008, 0.006, "#ffffff", 210, 12, 0);

    // Tear duct & wet lower waterline
    let ductU = uc + (e.isLeft ? 0.118 : -0.118);
    washUVEllipse(ductU, vc + 0.012, 0.018, 0.012, "#a84c42", 180, 12, 0);
    washUVEllipse(ductU, vc + 0.010, 0.008, 0.006, "#ffffff", 220, 10, 0);

    // Upper eyelid lash line & crease
    let lashPts = [];
    let creasePts = [];
    for (let s = 0; s <= 10; s++) {
      let t = (s / 10) * Math.PI;
      let du = -Math.cos(t) * 0.138;
      let dv = -Math.sin(t) * 0.088;
      let pL = screenProject(uc + du, vc + dv);
      let pC = screenProject(uc + du * 1.06, vc + dv * 1.25 - 0.018);
      lashPts.push([pL[0], pL[1], Math.sin(t) * 1.1 + 0.2]);
      creasePts.push([pC[0], pC[1], Math.sin(t) * 0.8 + 0.15]);
    }
    brush.set("micro_pen", "#0b0e12", 1.65);
    brush.spline(lashPts, 0.45);
    brush.set("micro_pen", "#1c1a1d", 1.05);
    brush.spline(creasePts, 0.45);

    // Raised arched eyebrow (wide-eyed curiosity)
    let browPts = [];
    for (let s = 0; s <= 8; s++) {
      let t = s / 8;
      let bu = uc + (t - 0.5) * 0.27;
      let bv = vc - 0.145 - Math.sin(t * Math.PI) * 0.038 + (e.isLeft ? -t * 0.015 : (1 - t) * -0.015);
      let pB = screenProject(bu, bv);
      browPts.push([pB[0], pB[1], Math.sin(t * Math.PI) * 1.1 + 0.25]);
    }
    brush.set("airbrush_fine", "#221815", 0.9);
    brush.spline(browPts, 0.45);
    brush.noStroke();
  }

  // 7. Foreshortened Button Nose (closest to the convex screen, magnified!)
  const noseU = 0.02;
  const noseV = 0.205;
  // Soft shadow beneath nose tip
  washUVEllipse(noseU, noseV + 0.055, 0.115, 0.052, "#1c1a1e", 160, 24, 0);
  // Bulbous foreshortened nose tip & alar wings
  for (let i = 0; i < 7; i++) {
    let s = 1.0 - i * 0.12;
    washUVEllipse(noseU, noseV, 0.105 * s, 0.078 * s, i < 3 ? "#8c4d38" : (i < 5 ? "#d18260" : "#ffd6b8"), 28, 24, 0);
  }
  // Glossy specular dot on the tip of the child's nose
  washUVEllipse(noseU - 0.018, noseV - 0.016, 0.036, 0.025, "#fff4e6", 130, 18, -12);
  washUVEllipse(noseU - 0.020, noseV - 0.018, 0.016, 0.011, "#ffffff", 185, 14, -12);

  // Two distinct foreshortened nostrils
  washUVEllipse(noseU - 0.048, noseV + 0.042, 0.025, 0.015, "#0d1014", 225, 16, 18);
  washUVEllipse(noseU + 0.048, noseV + 0.042, 0.025, 0.015, "#0d1014", 225, 16, -18);
  // Warm tangerine rim bounce on nostril rims
  washUVEllipse(noseU, noseV + 0.036, 0.028, 0.012, "#ff6e30", 85, 14, 0);

  // 8. Parted Lips in Awe (curved along the lower latitude of the screen)
  const mouthU = 0.02;
  const mouthV = 0.43;
  // Philtrum dimple
  washUVEllipse(mouthU, noseV + 0.11, 0.028, 0.038, "#302424", 90, 16, 0);

  // Upper lip (Cupid's bow)
  washPoly(screenCurvePoly([
    [mouthU - 0.155, mouthV + 0.01],
    [mouthU - 0.065, mouthV - 0.038],
    [mouthU, mouthV - 0.024],
    [mouthU + 0.065, mouthV - 0.038],
    [mouthU + 0.155, mouthV + 0.01],
    [mouthU, mouthV + 0.018]
  ]), "#7a352e", 175, 0.3);

  // Lower lip (full, catching tangerine & daylight gloss)
  washUVEllipse(mouthU, mouthV + 0.036, 0.135, 0.044, "#9e463b", 165, 24, 0);
  washUVEllipse(mouthU - 0.01, mouthV + 0.038, 0.095, 0.028, "#d9735f", 140, 20, 0);
  washUVEllipse(mouthU - 0.02, mouthV + 0.036, 0.048, 0.014, "#ffd5c2", 160, 16, -5);

  // Parted mouth opening & hint of upper teeth
  washUVEllipse(mouthU, mouthV + 0.008, 0.098, 0.022, "#121519", 230, 20, 0);
  washUVEllipse(mouthU, mouthV + 0.002, 0.062, 0.010, "#cad8de", 175, 16, 0);
}

