  brush.spline([
    [270, 342, 0.5], [304, 272, 1.0], [358, 214, 1.0], [422, 176, 0.5]
  ], 0.45);
  brush.spline([
    [286, 348, 0.4], [322, 282, 0.9], [374, 228, 0.9], [430, 190, 0.4]
  ], 0.45);

  // Secondary split window pane gloss patch on top-center dome
  const crownGloss = [
    [454, 152], [526, 138], [552, 158], [478, 174]
  ];
  washPoly(crownGloss, "#ffffff", 235, 0.25);
  brush.set("gloss_marker_thin", "#ffffff", 1.1);
  brush.spline([[460, 162, 0.5], [504, 150, 1.0], [544, 155, 0.5]], 0.4);
  brush.noStroke();

  // 2. Razor-sharp pure-white marker arcs snapped along the visor cowling rim bevel!
  // Upper-left visor chamfer highlight (9 o'clock to 12 o'clock)
  drawArcStroke("gloss_marker", "#ffffff", 0.95, SCR_CX + 4, SCR_CY + 2, SCR_RX + 36, SCR_RY + 34, -158, -98, 16, 0, 1.0);
  drawArcStroke("gloss_marker_thin", "#ffffff", 1.1, SCR_CX + 4, SCR_CY + 2, SCR_RX + 35, SCR_RY + 33, -90, -52, 12, 0, 0.9);

  // Lower visor chin-shelf specular highlight (5 o'clock to 7:30, catching overhead sun!)
  drawArcStroke("gloss_marker", "#ffffff", 0.85, SCR_CX + 2, SCR_CY + 4, SCR_RX + 23, SCR_RY + 22, 48, 128, 18, 0, 1.0);
  drawArcStroke("gloss_marker_thin", "#ffffff", 1.15, SCR_CX + 2, SCR_CY + 4, SCR_RX + 25, SCR_RY + 24, 32, 146, 20, 0, 1.0);

  // Left outer cheek vertical-curved ribbon highlight
  drawArcStroke("gloss_marker", "#ffffff", 0.8, TV_CX, TV_CY, TV_RX - 14, TV_RY - 14, 152, 196, 16, 0, 0.95);
  drawArcStroke("gloss_marker_thin", "#ffffff", 1.0, TV_CX, TV_CY, TV_RX - 10, TV_RY - 10, 142, 204, 16, 0, 0.9);

  // Turquoise-white crisp rim glint on right upper dome
  drawArcStroke("gloss_marker_thin", "#d4fbff", 1.0, TV_CX, TV_CY, TV_RX - 12, TV_RY - 12, -52, -14, 14, 0, 0.95);
  drawArcStroke("gloss_marker_thin", "#ffffff", 0.8, TV_CX, TV_CY, TV_RX - 12, TV_RY - 12, -42, -22, 10, 0, 0.9);

  // --------------------------------------------------------------------------
  // B. Pure-White Glossy Surface Highlights on the Convex CRT Glass
  // --------------------------------------------------------------------------
  // Direct Fresnel hot-spot in the upper-left window reflection on the glass
  const glassHotspot = screenGridPoly(-0.84, -0.44, -0.48, -0.14, 6, 5);
  washPoly(glassHotspot, "#ffffff", 245, 0.25);

  let hotArc1 = [];
  let hotArc2 = [];
  for (let k = 0; k <= 10; k++) {
    let t = k / 10;
    let p1 = screenProject(lerp(-0.86, -0.46, t), lerp(-0.38, -0.46, t));
    let p2 = screenProject(lerp(-0.85, -0.52, t), lerp(-0.22, -0.30, t));
