  renderScreenDustMotes();
}

function renderFingerprintSmudge(cx, cy, rx, ry, rotDeg) {
  // 1. Oily skin-lipid sheen halo diffusing the dark glass & window edge reflection
  for (let i = 0; i < 6; i++) {
    let s = 1.15 - i * 0.14;
    washEllipse(cx, cy, rx * s, ry * s, i % 2 === 0 ? "#9cb6c4" : "#ffe8cc", 11, 28, rotDeg);
  }

  // Directional finger-wipe drag tail
  let ca = Math.cos(rotDeg * DEG2RAD);
  let sa = Math.sin(rotDeg * DEG2RAD);
  washEllipse(cx + sa * 12, cy - ca * 12, rx * 0.75, ry * 0.9, "#8aa4b3", 9, 24, rotDeg + 8);

  // 2. Concentric dermal ridge whorls & loops (broken micro-arcs)
  const numRidges = 24;
  for (let r = 1; r <= numRidges; r++) {
    let t = r / numRidges;
    let curRX = rx * (0.12 + 0.88 * t);
    let curRY = ry * (0.14 + 0.86 * t);
    // Offset whorl core slightly toward upper loop
    let coreX = cx - sa * (1 - t) * 5;
    let coreY = cy + ca * (1 - t) * 5;

    // Draw 2 or 3 broken ridge segments per whorl ring
    let segCount = r < 6 ? 1 : (r < 15 ? 2 : 3);
    for (let s = 0; s < segCount; s++) {
      let baseStart = (s / segCount) * 360 + r * 17 + random(-18, 18);
      let span = random(55, 115);
      let pts = [];
      let steps = 7;
      for (let k = 0; k <= steps; k++) {
        let deg = baseStart + (span * k) / steps;
        let rad = deg * DEG2RAD;
        // Loop/arch pinch at bottom of thumbprint
        let pinch = Math.sin(rad) > 0.3 ? 1.0 + 0.18 * Math.sin(rad) : 1.0;
        let ux = Math.cos(rad) * curRX;
        let uy = Math.sin(rad) * curRY * pinch;
        let px = coreX + ux * ca - uy * sa;
        let py = coreY + ux * sa + uy * ca;
        pts.push([px, py, Math.sin((k / steps) * Math.PI) * 0.75 + 0.15]);
      }
      let col = (r + s) % 3 === 0 ? "#ffffff" : "#bfd6e3";
      brush.set("micro_pen", col, 0.42);
      brush.spline(pts, 0.45);
    }
  }
  brush.noStroke();
}

function renderScreenDustMotes() {
  // CRT screens hold static electricity that attracts tiny dust specks & micro-lint,
  // catching the oblique sunlight with a faint double-reflection in the thick front glass
  const numMotes = 165;
  for (let i = 0; i < numMotes; i++) {
    // Sample polar coordinates inside the screen
    let rad = Math.sqrt(random()) * 0.95;
    let ang = random(0, Math.PI * 2);
    let u = Math.cos(ang) * rad;
    let v = Math.sin(ang) * rad;
    let pt = screenProject(u, v);
    let x = pt[0];
    let y = pt[1];

    // Brightness is strongest in the upper-left sunlit zone and near the fingerprint
    let sunDist = Math.hypot(u + 0.35, v + 0.25);
    let isLit = sunDist < 0.75 || random() < 0.45;
    let size = random(0.6, 2.1);

    // Ghost internal reflection offset (2.2px down-right through the thick CRT glass faceplate)
    brush.set("dust_tip", "#4e626e", size * 0.45);
    brush.line(x + 2.2, y + 2.0, x + 2.2 + size * 0.5, y + 2.0 + size * 0.3);

    // Primary surface dust mote pinpoint
    let col = isLit
      ? (random() < 0.65 ? "#ffffff" : "#fff4d4")
      : (random() < 0.5 ? "#bcebf5" : "#d8e6ed");
    brush.set("dust_tip", col, size * 0.62);
    brush.line(x, y, x + size * 0.65, y + size * 0.35);
  }

  // 18 tiny curved static-clung lint micro-fibers on the glass
  for (let i = 0; i < 18; i++) {
    let rad = Math.sqrt(random()) * 0.88;
    let ang = random(0, Math.PI * 2);
    let pt = screenProject(Math.cos(ang) * rad, Math.sin(ang) * rad);
    let x = pt[0];
    let y = pt[1];
    let fAng = random(0, Math.PI * 2);
    let len = random(3.5, 8.5);
    let midX = x + Math.cos(fAng) * len * 0.5 + random(-1.8, 1.8);
    let midY = y + Math.sin(fAng) * len * 0.5 + random(-1.8, 1.8);
    let endX = x + Math.cos(fAng) * len;
    let endY = y + Math.sin(fAng) * len;

    // Ghost shadow on inner phosphor plane
    brush.set("micro_pen", "#425461", 0.38);
    brush.spline([[x + 2.2, y + 2.0, 0.3], [midX + 2.2, midY + 2.0, 0.6], [endX + 2.2, endY + 2.0, 0.3]], 0.5);

    // Bright sunlit lint fiber on outer glass
    brush.set("micro_pen", i % 3 === 0 ? "#fff6de" : "#ffffff", 0.52);
    brush.spline([[x, y, 0.3], [midX, midY, 0.85], [endX, endY, 0.3]], 0.5);
  }

  // A few extra dust motes catching sunlight on the glossy tangerine brow ridge
  for (let i = 0; i < 28; i++) {
    let deg = random(-160, -35);
    let rad = deg * DEG2RAD;
    let rFrac = random(0.84, 0.98);
    let x = TV_CX + Math.cos(rad) * TV_RX * rFrac;
    let y = TV_CY + Math.sin(rad) * TV_RY * rFrac;
    brush.set("dust_tip", "#ffffff", random(0.5, 1.0));
    brush.line(x, y, x + 0.8, y + 0.4);
  }

  brush.noStroke();
}

