// 1. DUSKY TWILIGHT DINER BACKDROP
// ============================================================================

function drawTwilightDinerBackdrop() {
  // Base twilight sky/interior washes from y = 0 to 740
  const bands = [
    { y0: 0, y1: 180, col: TWI_VOID, op: 245 },
    { y0: 150, y1: 340, col: TWI_DEEP, op: 230 },
    { y0: 300, y1: 500, col: TWI_PLUM, op: 220 },
    { y0: 460, y1: 630, col: TWI_MAUVE, op: 210 },
    { y0: 590, y1: 745, col: TWI_DUSK, op: 205 }
  ];

  for (let b of bands) {
    fillPolyWash(
      [[0, b.y0], [1200, b.y0], [1200, b.y1], [0, b.y1]],
      b.col,
      b.op
    );
  }

  // Layered horizontal & diagonal alcohol marker strokes for rich twilight depth
  for (let y = 10; y < 740; y += 9) {
    let t = y / 740;
    let col =
      t < 0.28
        ? TWI_VOID
        : t < 0.52
        ? TWI_DEEP
        : t < 0.76
        ? TWI_PLUM
        : TWI_MAUVE;
    brush.set("chisel_marker", col, random(1.8, 3.2));
    let xStart = random(-20, 40);
    let xEnd = random(1160, 1220);
    brush.line(xStart, y + random(-3, 3), xEnd, y + random(-3, 3));
  }

  // Distant twilight neon diner window strips (out-of-focus marker glow)
  // Mint neon tube reflection across upper-mid background
  for (let i = -3; i <= 3; i++) {
    let opCol = abs(i) <= 1 ? MINT_PALE : abs(i) === 2 ? MINT_BRIGHT : MINT_MID;
    let w = abs(i) === 0 ? 1.8 : 2.8;
    brush.set("chisel_marker", opCol, w);
    brush.line(60, 260 + i * 5, 340, 260 + i * 5);
    brush.line(860, 260 + i * 5, 1140, 260 + i * 5);
  }
  // Crisp clean paper neon core
  brush.set("paper_spec", PAPER, 0.9);
  brush.line(70, 260, 330, 260);
  brush.line(870, 260, 1130, 260);

  // Bubblegum pink neon horizon tube at y = 595
  for (let i = -4; i <= 4; i++) {
    let col = abs(i) <= 1 ? PINK_LIGHT : abs(i) <= 2 ? PINK_BUBBLE : PINK_DARK;
    brush.set("chisel_marker", col, abs(i) <= 1 ? 1.6 : 2.8);
    brush.line(0, 595 + i * 5, 1200, 595 + i * 5);
  }
  brush.set("paper_spec", PAPER, 0.95);
  brush.line(20, 595, 1180, 595);

  // Subtle vertical diner window mullion shadows
  for (let x of [170, 1030]) {
    fillPolyWash([[x - 14, 0], [x + 14, 0], [x + 14, 730], [x - 14, 730]], TWI_VOID, 180);
    brush.set("fine_marker", MINT_MID, 0.9);
    brush.line(x + 15, 0, x + 15, 725);
  }

  // Stainless steel diner backsplash rail at y = 715..746
  fillPolyWash([[0, 715], [1200, 715], [1200, 746], [0, 746]], CHROME_DARK, 240);
  fillPolyWash([[0, 720], [1200, 720], [1200, 731], [0, 731]], CHROME_LIGHT, 200);
  brush.set("paper_spec", PAPER, 1.1);
  brush.line(0, 723, 1200, 723);
  brush.set("rotring", INK, 0.8);
  brush.line(0, 715, 1200, 715);
  brush.line(0, 746, 1200, 746);
}

// ============================================================================
// 2. PERSPECTIVE CHECKERBOARD DINER COUNTER
// ============================================================================

function drawCheckerboardCounter() {
  const yTop = 746;
  const yBot = 1126;
  const vpX = 600;
  const vpY = 420;

  // Base cream/mint wash for the counter surface
  fillPolyWash([[0, yTop], [1200, yTop], [1200, yBot], [0, yBot]], CREAM_MID, 160);

  // Compute perspective rows (8 rows expanding toward viewer)
  const numRows = 8;
  const rowYs = [];
  for (let r = 0; r <= numRows; r++) {
    let t = r / numRows;
    let eased = pow(t, 1.52);
    rowYs.push(lerp(yTop, yBot, eased));
  }

  // Compute columns radiating from vanishing point (vpX, vpY)
  const numCols = 14; // -7 to +7 around center
  function getGridPt(colIdx, yVal) {
    // At yBot, each tile is 145px wide
    let xAtBot = 600 + colIdx * 145;
    let t = (yVal - vpY) / (yBot - vpY);
    let x = vpX + (xAtBot - vpX) * t;
    return [x, yVal];
  }

  // Draw tiles
  for (let r = 0; r < numRows; r++) {
    let y0 = rowYs[r];
    let y1 = rowYs[r + 1];
    for (let c = -numCols; c < numCols; c++) {
      let p00 = getGridPt(c, y0);
      let p10 = getGridPt(c + 1, y0);
      let p11 = getGridPt(c + 1, y1);
      let p01 = getGridPt(c, y1);

      // Skip if completely offscreen
      if (Math.max(p00[0], p10[0], p11[0], p01[0]) < -20) continue;
      if (Math.min(p00[0], p10[0], p11[0], p01[0]) > 1220) continue;

      let isDark = (r + c + 100) % 2 === 0;
      let poly = [p00, p10, p11, p01];

      if (isDark) {
        // Dusky twilight plum-black tile
        let darkCol = r < 3 ? TWI_DEEP : TWI_VOID;
        fillPolyWash(poly, darkCol, 235);
        hatchPolyMarker(poly, "fine_marker", TWI_PLUM, 0.9, 6, 12, { rand: 0.03 });
      } else {
        // Mint-tinted cream diner tile (leaving brightest areas near center as crisp paper)
        let distFromCenter = abs(c + 0.5);
        let lightCol =
          distFromCenter > 4
            ? CREAM_SHADOW
            : r < 2
            ? MINT_PALE
            : CREAM_BRIGHT;
        fillPolyWash(poly, lightCol, distFromCenter < 2.5 ? 95 : 175);
        hatchPolyMarker(
          poly,
          "fine_marker",
          r % 2 === 0 ? MINT_PALE : PINK_LIGHT,
          0.7,
          9,
          0,
          { rand: 0.02 }
        );
      }

      // Crisp tile grout lines in pen
      brush.set("rotring", INK, 0.55);
      brush.line(p00[0], p00[1], p10[0], p10[1]);
      brush.line(p10[0], p10[1], p11[0], p11[1]);
    }
  }

  // Glossy horizontal tabletop streak highlights (reserved clean paper strips)
  brush.set("paper_spec", PAPER, 1.3);
  for (let i = 0; i < 18; i++) {
    let sy = random(760, 1110);
    let sx = random(60, 960);
    let slen = random(60, 210);
    brush.line(sx, sy, sx + slen, sy);
  }

  // Art-Deco Ribbed Chrome Diner Counter Front Apron (y = 1126 to 1200)
  fillPolyWash([[0, 1126], [1200, 1126], [1200, 1200], [0, 1200]], CHROME_DARK, 245);
  const ribYs = [
    { y: 1130, col: PAPER, w: 1.5, brush: "paper_spec" },
    { y: 1136, col: CHROME_LIGHT, w: 1.8, brush: "fine_marker" },
    { y: 1143, col: MINT_BRIGHT, w: 1.2, brush: "fine_marker" },
    { y: 1152, col: TWI_VOID, w: 2.2, brush: "chisel_marker" },
    { y: 1160, col: PAPER, w: 1.3, brush: "paper_spec" },
    { y: 1167, col: PINK_BUBBLE, w: 1.4, brush: "fine_marker" },
    { y: 1176, col: CHROME_MID, w: 2.0, brush: "chisel_marker" },
    { y: 1185, col: PAPER, w: 1.1, brush: "paper_spec" },
    { y: 1193, col: TWI_VOID, w: 2.5, brush: "chisel_marker" }
  ];
  for (let rb of ribYs) {
    brush.set(rb.brush, rb.col, rb.w);
    brush.line(0, rb.y, 1200, rb.y);
  }

  // Vertical chrome seam plates along the counter edge
  for (let x of [160, 600, 1040]) {
    fillPolyWash([[x - 10, 1126], [x + 10, 1126], [x + 10, 1200], [x - 10, 1200]], CHROME_LIGHT, 210);
    brush.set("paper_spec", PAPER, 1.0);
    brush.line(x - 3, 1126, x - 3, 1200);
    brush.set("rotring", INK, 0.8);
    brush.line(x - 10, 1126, x - 10, 1200);
    brush.line(x + 10, 1126, x + 10, 1200);
  }

  brush.set("rotring", INK, 1.1);
  brush.line(0, 1126, 1200, 1126);
}

// ============================================================================
// 3. COUNTER REFLECTIONS & CAST SHADOW
// ============================================================================

function drawCounterReflectionsAndShadow() {
  // Glossy candy-apple red & bubblegum reflection pool directly in front of machine base
  for (let i = 0; i < 28; i++) {
    let t = i / 27;
    let y = lerp(1005, 1120, t);
    let halfW = lerp(245, 155, t) + sin(i * 35) * 14;
    let col = i % 3 === 0 ? CANDY_RED : i % 3 === 1 ? CANDY_DARK : PINK_MID;
    brush.set("chisel_marker", col, 1.8);
    brush.line(600 - halfW, y, 600 + halfW, y);
  }

  // Deep cast shadow ellipse under the cast-metal base (centered at 600, 1005)
  let shadowOuter = makeEllipsePts(600, 1008, 285, 54, 0, 48);
  fillPolyWash(shadowOuter, TWI_VOID, 195);

  let shadowCore = makeEllipsePts(600, 1004, 252, 40, 0, 48);
  fillPolyWash(shadowCore, INK, 240);

  // Crisp glossy tabletop streaks cutting across the reflection pool
  brush.set("paper_spec", PAPER, 1.1);
  brush.line(430, 1058, 770, 1058);
  brush.line(475, 1086, 725, 1086);
  brush.line(510, 1106, 690, 1106);
}

// ============================================================================
// 4. BACK OF GLASS GLOBE
// ============================================================================

function drawGlobeBack(cx, cy, r) {
  // Outer twilight glass halo & dark interior cavity
  let outerPts = makeCirclePts(cx, cy, r, 64);
  fillPolyWash(outerPts, TWI_DEEP, 215);

  let innerPts = makeCirclePts(cx, cy, r - 9, 64);
  fillPolyWash(innerPts, TWI_VOID, 235);

  // Upper interior dome glow (where glass is empty above the gumball pile)
  let domePts = [];
  for (let a = 195; a <= 345; a += 5) {
    domePts.push([cx + cos(a) * (r - 12), cy + sin(a) * (r - 12)]);
  }
  fillPolyWash(domePts, TWI_PLUM, 185);

  // Mint & pink back-wall glass refraction arcs
  brush.set("fine_marker", MINT_MID, 1.6);
  brush.arc(cx, cy, r - 5, 150, 240);
  brush.set("fine_marker", PINK_MID, 1.6);
  brush.arc(cx, cy, r - 5, 300, 390);
}

