    let bossPts = makeCirclePts(bx, by, 21, 24);
    fillPolyWash(bossPts, CHROME_DARK, 245);
    let bossIn = makeCirclePts(bx - 2, by - 2, 16, 20);
    fillPolyWash(bossIn, side === -1 ? MINT_PALE : PINK_LIGHT, 220);

    // Coin slot / dark pupil slit
    fillPolyWash(
      [[bx - 3, by - 11], [bx + 3, by - 11], [bx + 3, by + 11], [bx - 3, by + 11]],
      INK,
      250
    );
    brush.set("paper_spec", PAPER, 1.1);
    brush.arc(bx, by, 17, 195, 290);
    brush.set("rotring", INK, 0.8);
    brush.circle(bx, by, 21, 0.01);
  }

  // Turn-Crank Handle Boss at center (cx, 814)
  let hubPts = makeCirclePts(cx, 814, 24, 24);
  fillPolyWash(hubPts, CHROME_DARK, 250);
  // Winged turn handle bar (tilted at a jaunty 14 deg angle)
  let handleWing = [
    [cx - 58, 796],
    [cx + 58, 822],
    [cx + 54, 836],
    [cx - 62, 810]
  ];
  fillPolyWash(handleWing, CHROME_MID, 245);
  brush.set("paper_spec", PAPER, 1.5);
  brush.line(cx - 55, 800, cx + 55, 825);
  brush.set("rotring", INK, 0.9);
  brush.line(cx - 58, 796, cx + 58, 822);
  brush.line(cx - 62, 810, cx + 54, 836);

  // 2) THE CHEEKY, UNSETTLING CHROME GRIN (Chute Flap & Dispenser Mouth, y = 870 to 972)
  // Wide upturned crescent bezel shaped like a vintage kustom-kulture bumper grin
  let grinOuter = [];
  for (let u = -1; u <= 1; u += 0.08) {
    // Upturned corners at u = +-1!
    let gx = cx + u * 124;
    let gy = 892 + (1 - u * u) * 18 - pow(abs(u), 3) * 16;
    grinOuter.push([gx, gy]);
  }
  for (let u = 1; u >= -1; u -= 0.08) {
    let gx = cx + u * 116;
    let gy = 936 + (1 - u * u) * 38 - pow(abs(u), 2.5) * 18;
    grinOuter.push([gx, gy]);
  }
  fillPolyWash(grinOuter, CHROME_LIGHT, 240);

  // Dark mouth recess inside the grin
  let grinMouth = [];
  for (let u = -0.88; u <= 0.88; u += 0.08) {
    let gx = cx + u * 114;
    let gy = 900 + (1 - u * u) * 16 - pow(abs(u), 3) * 12;
    grinMouth.push([gx, gy]);
  }
  for (let u = 0.88; u >= -0.88; u -= 0.08) {
    let gx = cx + u * 106;
    let gy = 928 + (1 - u * u) * 34 - pow(abs(u), 2.5) * 14;
    grinMouth.push([gx, gy]);
  }
  fillPolyWash(grinMouth, INK, 250);

  // ONE PEEKING WET EYEBALL inside the dark dispenser grin!
  drawWetEyeball(cx + 12, 926, 26, "mint", -0.06, -0.08, 4);

  // Vertical chrome grille teeth / chute flap ribs across the grin
  for (let u = -0.76; u <= 0.76; u += 0.19) {
    // Leave a slightly wider gap around u ~ 0.1 so the peeking eyeball stares right through!
    if (abs(u - 0.09) < 0.12) continue;
    let tx = cx + u * 112;
    let tyTop = 900 + (1 - u * u) * 16 - pow(abs(u), 3) * 12;
    let tyBot = 926 + (1 - u * u) * 32 - pow(abs(u), 2.5) * 14;

    fillPolyWash(
      [[tx - 5, tyTop], [tx + 5, tyTop], [tx + 4, tyBot], [tx - 4, tyBot]],
      CHROME_MID,
      235
    );
    brush.set("paper_spec", PAPER, 1.1);
    brush.line(tx - 1, tyTop + 1, tx - 1, tyBot - 1);
    brush.set("rotring", INK, 0.75);
    brush.line(tx - 5, tyTop, tx - 4, tyBot);
    brush.line(tx + 5, tyTop, tx + 4, tyBot);
  }

  // Crisp paper specular highlights on the upper and lower chrome lips of the grin
  let upperLipSpec = [];
  let lowerLipSpec = [];
  for (let u = -0.92; u <= 0.92; u += 0.1) {
    upperLipSpec.push([cx + u * 120, 895 + (1 - u * u) * 17 - pow(abs(u), 3) * 14]);
    lowerLipSpec.push([cx + u * 112, 933 + (1 - u * u) * 36 - pow(abs(u), 2.5) * 16]);
  }
  brush.set("paper_spec", PAPER, 1.45);
  brush.spline(upperLipSpec, 0.5);
  brush.spline(lowerLipSpec, 0.5);

  // Outer ink contours of shield, grin, and machine body silhouette
  brush.set("rotring", INK, 0.95);
  let pShield = new brush.Polygon(shieldPts);
  pShield.draw("rotring", INK, 0.9);
  let pGrin = new brush.Polygon(grinOuter);
  pGrin.draw("rotring", INK, 1.0);

  // Left and right silhouette ink outlines of the cast-iron body
  let leftSil = [];
  let rightSil = [];
  for (let y = yStart; y <= yEnd; y += 10) {
    leftSil.push([cx - getBodyHalfWidth(y), y]);
    rightSil.push([cx + getBodyHalfWidth(y), y]);
  }
  brush.set("rotring", INK, 1.05);
  brush.spline(leftSil, 0.5);
  brush.spline(rightSil, 0.5);
}

