  brush.arc(cx, cy, r * 0.74, 198, 242);

  // Secondary lower-left glass streak
  brush.set("paper_spec", PAPER, 1.6);
  brush.arc(cx, cy, r * 0.84, 152, 178);
  brush.arc(cx, cy, r * 0.78, 156, 174);

  // Upper-right curved glass reflection arc
  brush.set("fine_marker", MINT_PALE, 1.6);
  brush.arc(cx, cy, r * 0.84, 295, 342);
