  // Outer glass globe contour in crisp ink
  brush.set("rotring", INK, 1.05);
  brush.circle(cx, cy, r, 0.01);
  brush.set("rotring", INK, 0.6);
  brush.circle(cx, cy, r - 6, 0.01);

  // 3. TOP CAST-CHROME & CANDY-RED ACORN LOCK FINIAL (y = 104 to 176)
  // Seated cap ring on top of globe (y = 152 to 176)
  let capBase = [];
  for (let u = -1; u <= 1; u += 0.1) {
