  }
  for (let u = 1; u >= -1; u -= 0.1) {
    capBase.push([cx + u * 128, 172 + (1 - u * u) * 14]);
  }
  fillPolyWash(capBase, CANDY_DARK, 245);

  // Candy-red & paper highlights on top cap ring
  fillPolyWash(
    [[cx - 85, 152], [cx - 20, 156], [cx - 24, 178], [cx - 96, 172]],
    CANDY_RED,
    235
  );
  brush.set("paper_spec", PAPER, 1.5);
  brush.line(cx - 65, 154, cx - 68, 174);
  brush.line(cx - 50, 156, cx - 52, 176);

  // Chrome dome & lock nut finial (y = 104 to 154)
  let domeCap = [
    [cx - 72, 152],
    [cx - 54, 128],
    [cx - 18, 118],
    [cx + 18, 118],
    [cx + 54, 128],
    [cx + 72, 152]
  ];
