  );
  brush.set("paper_spec", PAPER, 1.6);
  brush.line(cx - 34, 150, cx - 22, 124);
  brush.line(cx - 18, 150, cx - 10, 122);

  // Acorn key-lock tip at (cx, 108)
  let acornPts = makeEllipsePts(cx, 108, 16, 14, 0, 20);
  fillPolyWash(acornPts, CHROME_DARK, 250);
  brush.set("paper_spec", PAPER, 1.3);
  brush.arc(cx, 108, 11, 190, 290);

  brush.set("rotring", INK, 0.95);
  let pCap = new brush.Polygon(capBase);
  pCap.draw("rotring", INK, 0.95);
  let pDome = new brush.Polygon(domeCap);
