// 8. HOT-ROD BLACK PEN PINSTRIPE FLOURISHES CURLING OFF THE BASE
// ============================================================================

function drawSymmetricSpline(cx, pts, brushName, col, weight, curvature = 0.65) {
  let leftPts = pts.map((p) => [cx - p[0], p[1], p[2] !== undefined ? p[2] : 1.0]);
  let rightPts = pts.map((p) => [cx + p[0], p[1], p[2] !== undefined ? p[2] : 1.0]);

  brush.set(brushName, col, weight);
  brush.spline(leftPts, curvature);
  brush.spline(rightPts, curvature);
}

function drawTeardrop(x, y, angleDeg, len, wid, col) {
  let ca = cos(angleDeg);
  let sa = sin(angleDeg);
  let pts = [
    [x, y],
    [x + ca * len * 0.65 - sa * wid, y + sa * len * 0.65 + ca * wid],
    [x + ca * len, y + sa * len],
    [x + ca * len * 0.65 + sa * wid, y + sa * len * 0.65 - ca * wid]
  ];
  fillPolyWash(pts, col, 250);
  brush.set("rotring", INK, 0.55);
  let p = new brush.Polygon(pts);
  p.draw("rotring", INK, 0.55);
}

function drawHotRodPinstripes(cx) {
