  const teardrops = [
    { dx: 0, y: 982, a: 90, l: 28, w: 6, col: INK },
    { dx: 0, y: 1052, a: 90, l: 34, w: 7, col: CANDY_RED },
    { dx: 325, y: 954, a: -25, l: 26, w: 5.5, col: INK },
    { dx: 465, y: 942, a: -40, l: 24, w: 5, col: INK },
    { dx: 322, y: 1055, a: 18, l: 26, w: 5.5, col: INK }
  ];

  for (let td of teardrops) {
    if (td.dx === 0) {
      drawTeardrop(cx, td.y, td.a, td.l, td.w, td.col);
    } else {
      drawTeardrop(cx - td.dx, td.y, 180 - td.a, td.l, td.w, td.col);
      drawTeardrop(cx + td.dx, td.y, td.a, td.l, td.w, td.col);
    }
  }

  // Fine cross-tick accents along the master pinstripe stems
  for (let dx of [265, 280, 295]) {
    let ty = 1006 - (dx - 265) * 0.35;
    brush.set("rotring", INK, 0.7);
    brush.line(cx - dx, ty - 9, cx - dx - 6, ty + 9);
    brush.line(cx + dx, ty - 9, cx + dx + 6, ty + 9);
  }
}

// Hyperrealistic Linocut / Wood-Engraving of a Cast-Iron Skillet with a Fried Egg
// Rendered entirely with p5.brush via swelling, tapering gouge marks and flow-field lines

const PAPER_BG = "#efe5d4";
const PAPER_WARM = "#e3d4bc";
const PAPER_LIGHT = "#f7f0e4";
const INK_BLACK = "#110d0a";
const INK_UMBER = "#281c14";
const INK_EARTH = "#4a3423";

// 3D Skillet & Scene Geometry Constants (scaled for 1200x1200)
const CX = 648;
const CY = 566;
const KAPPA = 0.63;       // Foreshortening ratio for steep 3/4 view (~51 deg)
const SZ = 0.775;         // Vertical projection scale
const R_FLOOR = 328;      // Cooking floor radius
const R_RIM_IN = 384;     // Inner top rim radius
const R_RIM_OUT = 408;    // Outer top rim radius
const R_BASE = 338;       // Exterior bottom base radius
const H_WALL = 120;       // Skillet wall height in 3D Z units

// Handle & Pour Spout Angles (in pan plane radians)
const PHI_HANDLE = 2.47;                  // ~141.5 deg (sweeping toward bottom-left)
const PHI_HELPER = PHI_HANDLE - Math.PI;  // ~-38.5 deg (top-right helper tab)
const PHI_SPOUT1 = PHI_HANDLE - Math.PI / 2; // ~51.5 deg (bottom-right pour spout)
const PHI_SPOUT2 = PHI_HANDLE + Math.PI / 2; // ~231.5 deg (top-left pour spout)

// Egg Center & Yolk Center in Pan-Floor (X, Y) Coordinates
const EX = 16;
const EY = -16;
const YX = 32;
const YY = -28;
const RY_X = 76;
const RY_Y = 76 * KAPPA;
const HY_DOME = 55;

let blisters = [];
let laceHoles = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(RADIANS);
  randomSeed(42719);
  noiseSeed(8319);

  // Register custom linocut gouge and engraving burin brushes
  brush.add("v_gouge", {
    type: "default",
    weight: 1.35,
    scatter: 0.01,
    sharpness: 0.96,
    grain: 26,
    opacity: 255,
    spacing: 0.12,
    pressure: [0.04, 1.35, 0.04],
    noise: 0.16
  });

  brush.add("u_gouge", {
    type: "default",
    weight: 2.1,
    scatter: 0.015,
    sharpness: 0.93,
    grain: 22,
    opacity: 255,
    spacing: 0.14,
    pressure: [0.08, 1.4, 0.08],
    noise: 0.2
  });

  brush.add("burin_flow", {
    type: "default",
    weight: 1.45,
    scatter: 0.01,
    sharpness: 0.95,
    grain: 24,
    opacity: 255,
    spacing: 0.13,
    pressure: [0.25, 1.15, 0.25],
    noise: 0.14
  });

  initEggMicroGeometry();
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAPER_BG);

  // 1. Warm earth-toned rag paper border & subtle relief-print chatter in negative space
  drawPaperAndPrintChatter();

  // 2. Heavy cast shadow under skillet & handle, carved with tapering gouge marks
  drawTabletopCastShadow();

  // 3. Solid printer's-black base silhouettes for the iron skillet
  drawSkilletSolidSilhouettes();

  // 4. Back & side interior sloped wall gouges (hoop contours & vertical relief grooves)
  drawInteriorSlopedWall();

  // 5. Seasoned cast-iron floor: dense parallel flow-field gouges & oil-sheen rings
  drawSeasonedIronFloor();

  // 6. Fried Egg: crispy lacy bubbling edges, undulating albumen, steam blisters & domed yolk
  drawFriedEgg();

  // 7. Bare white oil spatter flecks across the hot iron floor, walls, and egg perimeter
  drawOilSpatterFlecks();

  // 8. Front exterior cast-iron belly (occluding the front floor edge)
  drawExteriorFrontBelly();

  // 9. Top rim & both pour spouts (360-degree swelling contour & bevel gouges)
  drawTopRimAndSpouts();

  // 10. Helper handle (top-right) & main handle with teardrop hole (bottom-left)
  drawHelperHandle();
  drawMainHandle();

  noLoop();
}

// ============================================================================
// GEOMETRY & LIGHTING HELPERS
// ============================================================================

function toScreen(X, Y, Z = 0) {
  return [CX + X, CY + Y * KAPPA - Z * SZ];
}

function angleDiff(a, b) {
  return Math.atan2(Math.sin(a - b), Math.cos(a - b));
}

function spoutFlare(phi) {
  let d1 = angleDiff(phi, PHI_SPOUT1);
  let d2 = angleDiff(phi, PHI_SPOUT2);
  return 28 * Math.exp(-Math.pow(d1 / 0.165, 2)) + 26 * Math.exp(-Math.pow(d2 / 0.165, 2));
}

function wallRadius(s, phi) {
  let baseR = lerp(R_FLOOR, R_RIM_IN, Math.pow(s, 0.88));
  return baseR + Math.pow(s, 2.1) * spoutFlare(phi);
}

function outerRimRadius(phi) {
  return R_RIM_OUT + 0.96 * spoutFlare(phi);
}

function frontInnerRimYAtX(X) {
  let clamped = constrain(X / R_RIM_IN, -0.999, 0.999);
  let phi = Math.acos(clamped); // phi in [0, PI] (front half)
  let r = wallRadius(1.0, phi);
  let Y = r * Math.sin(phi);
  return CY + Y * KAPPA - H_WALL * SZ;
}

function eggRadius(a) {
  return (
    194 +
    23 * Math.cos(a - 0.35) -
    18 * Math.sin(2 * a + 0.8) +
    15 * Math.cos(3 * a - 1.1) +
    10 * Math.sin(4 * a + 2.0) +
    7.5 * Math.cos(6 * a - 0.5) +
    5.5 * Math.sin(9 * a + 1.4) +
    4.2 * Math.cos(14 * a - 0.9) +
    3.2 * Math.sin(21 * a + 0.4)
  );
}

function thickAlbumenRadius(a) {
  return (
    108 +
    12 * Math.cos(a - 0.5) -
    9 * Math.sin(2 * a + 0.4) +
    6 * Math.cos(3 * a - 0.8) +
    3.5 * Math.sin(5 * a + 1.1)
  );
}

function isInsideEgg(X, Y, scaleMult = 1.0) {
  let dx = X - EX;
  let dy = Y - EY;
  let r = Math.hypot(dx, dy);
  let a = Math.atan2(dy, dx);
  return r < eggRadius(a) * scaleMult;
}

function safeSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    let d = Math.hypot(pts[i][0] - prev[0], pts[i][1] - prev[1]);
    if (d >= 2.2) clean.push(pts[i]);
  }
  if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  } else if (clean.length >= 3) {
    brush.spline(clean, curvature);
  }
}

function fillShapePoints(pts, col, opacity = 255, curvature = 0.2) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, opacity);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function initEggMicroGeometry() {
  // Generate non-overlapping steam blisters on the egg white
  let attempts = 0;
  while (blisters.length < 28 && attempts < 800) {
    attempts++;
    let a = random(TWO_PI);
    let rMax = eggRadius(a);
    let frac = random(0.38, 0.83);
    let r = frac * rMax;
    let bx = EX + r * Math.cos(a);
    let by = EY + r * Math.sin(a);
    // Keep outside yolk + margin
    if (Math.hypot(bx - YX, by - YY) < RY_X + 22) continue;
    let rad = random(5.5, 17.5) * (1.0 - 0.35 * frac);
    let ok = true;
    for (let b of blisters) {
      if (Math.hypot(bx - b.x, by - b.y) < rad + b.r + 7) {
        ok = false;
        break;
      }
    }
    if (ok) {
      blisters.push({
        x: bx,
        y: by,
        r: rad,
        popped: random() < 0.24
      });
    }
  }

  // Generate lacy edge perforations around the perimeter of the egg white
  for (let i = 0; i < 115; i++) {
    let a = (i / 115) * TWO_PI + random(-0.02, 0.02);
    let rEgg = eggRadius(a);
    let r = rEgg * random(0.84, 0.975);
    let hx = EX + r * Math.cos(a);
    let hy = EY + r * Math.sin(a);
    let rx = random(2.8, 8.5);
    let ry = rx * random(0.55, 0.95);
    laceHoles.push({ x: hx, y: hy, rx, ry, angle: a + random(-0.4, 0.4) });
  }
}

// ============================================================================
// 1. PAPER GROUND & RELIEF PRINT CHATTER
// ============================================================================

function drawPaperAndPrintChatter() {
  // Subtle dry-media warm paper border toning (muted earth-tone rag deckle feel)
  brush.noFill();
  brush.noWash();
  for (let i = 0; i < 140; i++) {
    let edge = i % 4;
    let x1, y1, x2, y2;
    let spread = random(18, 95);
    if (edge === 0) {
      x1 = random(40, 1160);
      y1 = random(12, spread);
      x2 = x1 + random(-90, 90);
      y2 = y1 + random(-8, 8);
    } else if (edge === 1) {
      x1 = random(40, 1160);
      y1 = 1200 - random(12, spread);
      x2 = x1 + random(-90, 90);
      y2 = y1 + random(-8, 8);
    } else if (edge === 2) {
      x1 = random(12, spread);
      y1 = random(40, 1160);
      x2 = x1 + random(-8, 8);
      y2 = y1 + random(-90, 90);
    } else {
      x1 = 1200 - random(12, spread);
      y1 = random(40, 1160);
      x2 = x1 + random(-8, 8);
      y2 = y1 + random(-90, 90);
    }
    brush.set("v_gouge", PAPER_WARM, random(0.35, 0.95));
    brush.line(x1, y1, x2, y2);
  }

  // Classic linocut "chatter" marks in the negative space following the tabletop grain
  for (let i = 0; i < 95; i++) {
    let angle = random(TWO_PI);
    let distR = random(435, 560);
    let sx = CX + distR * Math.cos(angle);
    let sy = CY - 25 + distR * 0.68 * Math.sin(angle);
    if (sx < 45 || sx > 1155 || sy < 45 || sy > 1155) continue;

    // Tangent direction around the block
    let tx = -Math.sin(angle);
    let ty = 0.68 * Math.cos(angle);
    let tLen = Math.hypot(tx, ty);
    tx /= tLen;
    ty /= tLen;

    let segLen = random(18, 52);
    let pts = [
      [sx - tx * segLen * 0.5, sy - ty * segLen * 0.5],
      [sx + random(-2, 2), sy + random(-2, 2)],
      [sx + tx * segLen * 0.5, sy + ty * segLen * 0.5]
    ];
    let col = random() < 0.65 ? INK_EARTH : INK_BLACK;
    brush.set("v_gouge", col, random(0.18, 0.42));
    safeSpline(pts, 0.4);
  }
}

// ============================================================================
// 2. TABLETOP CAST SHADOW (SOLID BLACK + TAPERING GOUGE FEATHERING)
// ============================================================================

function drawTabletopCastShadow() {
  // Solid black core cast shadow shifted toward bottom-right (opposite top-left light)
  let shadowPts = [];
  let steps = 90;
  for (let i = 0; i < steps; i++) {
    let phi = (i / steps) * TWO_PI;
    let isShadowSide = Math.sin(phi - 0.55) > -0.2;
    let stretch = isShadowSide ? 46 + 34 * Math.max(0, Math.sin(phi - 0.52)) : 6;
    let r = R_BASE + stretch;
    let sx = CX + 28 + r * Math.cos(phi);
    let sy = CY + 22 + r * KAPPA * Math.sin(phi);
    shadowPts.push([sx, sy]);
  }
  fillShapePoints(shadowPts, INK_BLACK, 255, 0.25);

  // Solid black cast shadow directly under the floating main handle (bottom-left)
  let handleShadowPts = [];
  let uHx = Math.cos(PHI_HANDLE);
  let uHy = Math.sin(PHI_HANDLE);
  let vHx = -uHy;
  let vHy = uHx;

  for (let t = 0; t <= 290; t += 14) {
    let w = handleHalfWidth(t) * 0.92;
    let r = R_BASE + t * 0.88;
    let X = r * uHx + w * vHx + 24;
    let Y = r * uHy + w * vHy + 32;
    handleShadowPts.push(toScreen(X, Y, 0));
  }
  for (let t = 290; t >= 0; t -= 14) {
    let w = handleHalfWidth(t) * 0.92;
    let r = R_BASE + t * 0.88;
    let X = r * uHx - w * vHx + 24;
    let Y = r * uHy - w * vHy + 32;
    handleShadowPts.push(toScreen(X, Y, 0));
  }
  fillShapePoints(handleShadowPts, INK_BLACK, 255, 0.2);

  // Linocut gouge hatching across the cast shadow edge (interlocking black & white gouges)
  let hatchAngle = 0.32; // ~18 deg parallel tabletop gouges
  let cosH = Math.cos(hatchAngle);
  let sinH = Math.sin(hatchAngle);

  for (let i = 0; i < 190; i++) {
    let phi = random(-0.45, 2.35);
    let baseR = R_BASE + 28 + 38 * Math.max(0, Math.sin(phi - 0.52));
    let r = baseR + random(-28, 38);
    let cx = CX + 28 + r * Math.cos(phi);
    let cy = CY + 22 + r * KAPPA * Math.sin(phi);
    let len = random(35, 95);

    let p1 = [cx - cosH * len * 0.5, cy - sinH * len * 0.5];
    let p2 = [cx, cy + random(-2, 2)];
    let p3 = [cx + cosH * len * 0.5, cy + sinH * len * 0.5];

    if (r > baseR - 4) {
      // Black tapering gouges extending out onto the off-white tabletop
      let w = map(r, baseR - 4, baseR + 40, 1.35, 0.22, true);
      brush.set("v_gouge", INK_BLACK, w);
      safeSpline([p1, p2, p3], 0.35);
    } else {
      // White tapering gouges biting back into the solid black shadow
      let w = map(r, baseR - 30, baseR, 0.25, 1.25, true);
      brush.set("v_gouge", PAPER_BG, w);
      safeSpline([p1, p2, p3], 0.35);
    }
  }

  // Feathering gouges along the handle cast shadow
  for (let i = 0; i < 85; i++) {
    let t = random(15, 295);
    let side = random(-1.45, 1.45);
    let w = handleHalfWidth(t) * side;
    let r = R_BASE + t * 0.88;
    let X = r * uHx + w * vHx + 24;
    let Y = r * uHy + w * vHy + 32;
    let [sx, sy] = toScreen(X, Y, 0);
    let len = random(28, 65);
    let pts = [
      [sx - cosH * len * 0.5, sy - sinH * len * 0.5],
      [sx, sy + 1.5],
      [sx + cosH * len * 0.5, sy + sinH * len * 0.5]
    ];
    let col = Math.abs(side) > 0.82 ? INK_BLACK : PAPER_BG;
    brush.set("v_gouge", col, random(0.35, 1.05));
    safeSpline(pts, 0.3);
  }
}

// ============================================================================
// 3. SKILLET SOLID BLACK BASE SILHOUETTES
// ============================================================================

function handleHalfWidth(t) {
  // t from 0 (outer rim) to 310 (tip)
  if (t < 0) return 68;
  if (t > 310) return 0;
  let neckFlare = 42 * Math.exp(-t / 28);
  let shaft = 26 + 15 * Math.exp(-Math.pow((t - 232) / 52, 2));
  let tipTaper = t > 245 ? Math.sqrt(Math.max(0, 1 - Math.pow((t - 245) / 65, 2))) : 1.0;
  return (shaft + neckFlare) * tipTaper;
}

function drawSkilletSolidSilhouettes() {
  // A. Exterior base & front belly silhouette
  let bellyPts = [];
  for (let i = 0; i <= 60; i++) {
    let phi = map(i, 0, 60, -0.15, Math.PI + 0.15);
    let r = outerRimRadius(phi);
    bellyPts.push(toScreen(r * Math.cos(phi), r * Math.sin(phi), H_WALL));
  }
  for (let i = 60; i >= 0; i--) {
    let phi = map(i, 0, 60, -0.15, Math.PI + 0.15);
    bellyPts.push(toScreen(R_BASE * Math.cos(phi), R_BASE * Math.sin(phi), 0));
  }
  fillShapePoints(bellyPts, INK_BLACK, 255, 0.15);

  // B. Full 360-degree top rim & cavity silhouette
  let rimPts = [];
  let steps = 120;
  for (let i = 0; i < steps; i++) {
    let phi = (i / steps) * TWO_PI;
    let r = outerRimRadius(phi);
    rimPts.push(toScreen(r * Math.cos(phi), r * Math.sin(phi), H_WALL));
  }
  fillShapePoints(rimPts, INK_BLACK, 255, 0.2);
}

// ============================================================================
// 4. INTERIOR SLOPED WALL (HOOP CONTOURS & VERTICAL CARVED GROOVES)
// ============================================================================

function wallLuminance(s, phi) {
  // Concave wall normal faces inward (-cos(phi), -sin(phi)).
  // Light from top-left shines strongly onto the right/bottom-right interior wall (phi ~ -0.35).
  let directLight = Math.max(0, Math.cos(phi + 0.32));
  let specBand = Math.pow(Math.max(0, Math.cos(phi + 0.22)), 5.0) * 0.55;
  let bounceFromEgg = Math.max(0, Math.cos(phi - 2.35)) * 0.14 * (1.0 - s * 0.5);

  // Pour spout vertical cylindrical highlight streaks
  let dSpout1 = angleDiff(phi, PHI_SPOUT1);
  let dSpout2 = angleDiff(phi, PHI_SPOUT2);
  let spoutSpec1 = 0.58 * Math.exp(-Math.pow((dSpout1 + 0.05) / 0.08, 2)) * Math.pow(s, 0.7);
  let spoutSpec2 = 0.48 * Math.exp(-Math.pow((dSpout2 - 0.06) / 0.08, 2)) * Math.pow(s, 0.7);

  // Ambient occlusion near the floor corner (s = 0) and bright bevel near top rim (s = 1)
  let verticalProfile = 0.25 + 0.75 * Math.pow(s, 0.65);
  let grain = 0.85 + 0.3 * noise(Math.cos(phi) * 3 + 10, Math.sin(phi) * 3 + 10, s * 4);

  let lum = (0.04 + 0.28 * directLight + specBand + bounceFromEgg + spoutSpec1 + spoutSpec2) * verticalProfile * grain;
  return constrain(lum, 0.0, 0.92);
}

function drawInteriorSlopedWall() {
  // 1. Circumferential hoop gouges sweeping around the visible back/side interior wall
  let numHoops = 32;
  for (let k = 1; k < numHoops; k++) {
    let s = k / numHoops;
    let z = s * H_WALL;

    // Visible interior wall spans from phi ~ -3.45 around back (-PI/2) to phi ~ +1.15
    let phiStart = -3.48;
    let phiEnd = 1.18;
    let totalSteps = 130;

    let seg = [];
    let segLumSum = 0;

    for (let i = 0; i <= totalSteps; i++) {
      let phi = map(i, 0, totalSteps, phiStart, phiEnd);
      let r = wallRadius(s, phi);
      let X = r * Math.cos(phi);
      let Y = r * Math.sin(phi);
      let [sx, sy] = toScreen(X, Y, z);

      // Clip against front inner rim
      if (Math.sin(phi) > 0.25 && sy > frontInnerRimYAtX(X) - 2) {
        if (seg.length >= 3) {
          let avgL = segLumSum / seg.length;
          if (avgL > 0.06) {
            brush.set("v_gouge", avgL > 0.55 ? PAPER_LIGHT : PAPER_BG, map(avgL, 0.06, 0.9, 0.22, 1.55, true));
            safeSpline(seg, 0.45);
          }
        }
        seg = [];
        segLumSum = 0;
        continue;
      }

      let lum = wallLuminance(s, phi);
      seg.push([sx, sy]);
      segLumSum += lum;

      // Break hoop into natural linocut gouge scoops every 9-16 steps
      if (seg.length >= 11 || i === totalSteps) {
        let avgL = segLumSum / seg.length;
        if (avgL > 0.055) {
          let w = map(avgL, 0.055, 0.9, 0.2, 1.65, true);
          let col = avgL > 0.58 ? PAPER_LIGHT : PAPER_BG;
          brush.set("v_gouge", col, w);
          safeSpline(seg, 0.45);
        }
        seg = [[sx, sy]];
        segLumSum = lum;
      }
    }
  }

  // 2. Steep radial/curved wall contour gouges following the 3D frustum slope
  let numRadial = 175;
  for (let i = 0; i < numRadial; i++) {
    let phi = map(i, 0, numRadial, -3.42, 1.12) + random(-0.008, 0.008);
    let lumMid = wallLuminance(0.55, phi);
    if (lumMid < 0.07 && random() < 0.55) continue;

    let s0 = random(0.06, 0.28);
    let s1 = random(0.72, 0.96);
    let sMid = (s0 + s1) * 0.5;

    let r0 = wallRadius(s0, phi);
    let rMid = wallRadius(sMid, phi + 0.012);
    let r1 = wallRadius(s1, phi);

    let p0 = toScreen(r0 * Math.cos(phi), r0 * Math.sin(phi), s0 * H_WALL);
    let pMid = toScreen(rMid * Math.cos(phi + 0.012), rMid * Math.sin(phi + 0.012), sMid * H_WALL);
    let p1 = toScreen(r1 * Math.cos(phi), r1 * Math.sin(phi), s1 * H_WALL);

    if (p0[1] > frontInnerRimYAtX(r0 * Math.cos(phi)) - 2) continue;

    let w = map(lumMid, 0.06, 0.9, 0.22, 1.35, true);
    brush.set("v_gouge", lumMid > 0.6 ? PAPER_LIGHT : PAPER_BG, w);
    safeSpline([p0, pMid, p1], 0.4);
  }
}

// ============================================================================
// 5. SEASONED IRON FLOOR: DENSE PARALLEL FLOW-FIELD LINES
// ============================================================================

function floorLuminance(X, Y) {
  let rFloor = Math.hypot(X, Y);
  if (rFloor > R_FLOOR - 2) return 0;

  // Distance to egg perimeter for the glossy hot-oil halo meniscus
  let dxE = X - EX;
  let dyE = Y - EY;
  let rE = Math.hypot(dxE, dyE);
  let aE = Math.atan2(dyE, dxE);
  let rEgg = eggRadius(aE);
  let distFromEgg = rE - rEgg;

  // Crisp cast shadow of the crispy egg edge on the bottom-right side of the egg
  let shadowSide = Math.max(0, Math.cos(aE - 0.65));
  if (distFromEgg > 0 && distFromEgg < 14 + 12 * shadowSide) {
    return 0.02;
  }

  // Hot frying oil puddle halo surrounding the egg (15 to 68 px outside egg boundary)
  let oilMeniscus = 0;
  if (distFromEgg >= 10 && distFromEgg < 78) {
    // Sharp outer oil rim reflection + shimmering inner puddle
    let outerRing = Math.exp(-Math.pow((distFromEgg - 52) / 9.5, 2)) * 0.52;
    let innerSheen = Math.exp(-Math.pow((distFromEgg - 28) / 14.0, 2)) * 0.34;
    let angleMod = 0.55 + 0.45 * Math.cos(aE + 2.2);
    oilMeniscus = (outerRing + innerSheen) * angleMod;
  }

  // Broad anisotropic specular reflection across the seasoned iron from top-left light
  let uDiag = (X * 0.72 + Y * 0.69) / R_FLOOR;
  let vDiag = (-X * 0.69 + Y * 0.72) / R_FLOOR;
  let mainSheen = Math.exp(-Math.pow(vDiag - 0.08, 2) / 0.22) * (0.28 - 0.12 * uDiag);

  // Ambient occlusion shadow near the top-left interior wall base
  let wallShadow = 1.0;
  if (X < 0 && Y < 0) {
    wallShadow = constrain(map(rFloor, R_FLOOR - 75, R_FLOOR - 5, 1.0, 0.12), 0.12, 1.0);
  } else {
    wallShadow = constrain(map(rFloor, R_FLOOR - 35, R_FLOOR, 1.0, 0.35), 0.35, 1.0);
  }

  // Pebbly seasoned iron micro-texture
  let ironGrain = 0.72 + 0.56 * noise(X * 0.022 + 50, Y * 0.022 + 50);

  let lum = (0.04 + mainSheen + oilMeniscus) * wallShadow * ironGrain;
  return constrain(lum, 0.0, 0.85);
}

function drawSeasonedIronFloor() {
  // Primary family of dense parallel flow-field lines carving the seasoned iron
  let flowAngle = -0.27; // ~-15.5 deg aligned with skillet perspective axis
  let cosF = Math.cos(flowAngle);
  let sinF = Math.sin(flowAngle);

  let spacing = 3.1;
  let stepU = 9.0;

  for (let vBase = -R_FLOOR + 4; vBase <= R_FLOOR - 4; vBase += spacing) {
    let uMax = Math.sqrt(Math.max(0, R_FLOOR * R_FLOOR - vBase * vBase)) - 3;
    if (uMax < 20) continue;

    let seg = [];
    let lumSum = 0;

    for (let u = -uMax; u <= uMax; u += stepU) {
      // Smooth flow-field warp + subtle deflection around the egg puddle
      let warp =
        14.0 * (noise(u * 0.0045 + 10, vBase * 0.0045 + 20) - 0.5) +
        6.5 * Math.sin(u * 0.011 + vBase * 0.006);

      let v = vBase + warp;
      let X = u * cosF - v * sinF;
      let Y = u * sinF + v * cosF;

      // Gentle radial deflection around the egg's oil halo
      let dxE = X - EX;
      let dyE = Y - EY;
      let rE = Math.hypot(dxE, dyE);
      let aE = Math.atan2(dyE, dxE);
      let rEgg = eggRadius(aE);
      if (rE > rEgg * 0.95 && rE < rEgg + 65) {
        let push = 9.5 * Math.exp(-Math.pow((rE - rEgg - 18) / 24, 2));
        X += (dxE / (rE + 0.001)) * push;
        Y += (dyE / (rE + 0.001)) * push;
      }

      let rFloor = Math.hypot(X, Y);
      let [sx, sy] = toScreen(X, Y, 0);
      let clippedByRim = sy > frontInnerRimYAtX(X) - 2.5;
      let insideEgg = isInsideEgg(X, Y, 0.96);

      if (rFloor >= R_FLOOR - 3 || clippedByRim || insideEgg) {
        if (seg.length >= 3) {
          let avgL = lumSum / seg.length;
          if (avgL > 0.05) {
            let w = map(avgL, 0.05, 0.82, 0.2, 1.55, true);
            brush.set("v_gouge", avgL > 0.52 ? PAPER_LIGHT : PAPER_BG, w);
            safeSpline(seg, 0.45);
          }
        }
        seg = [];
        lumSum = 0;
        continue;
      }

      let lum = floorLuminance(X, Y);
      seg.push([sx, sy]);
      lumSum += lum;

      // Break long streamlines into swelling/tapering gouge scoops where tone changes
      if (seg.length >= 9) {
        let avgL = lumSum / seg.length;
        if (avgL > 0.05) {
          let w = map(avgL, 0.05, 0.82, 0.2, 1.6, true);
          let col = avgL > 0.52 ? PAPER_LIGHT : PAPER_BG;
          brush.set("v_gouge", col, w);
          safeSpline(seg, 0.45);
        }
        // Overlap by 1 point for visual flow continuity
        seg = [[sx, sy]];
        lumSum = lum;
      }
    }

    if (seg.length >= 3) {
      let avgL = lumSum / seg.length;
      if (avgL > 0.05) {
        let w = map(avgL, 0.05, 0.82, 0.2, 1.55, true);
        brush.set("v_gouge", avgL > 0.52 ? PAPER_LIGHT : PAPER_BG, w);
        safeSpline(seg, 0.45);
      }
    }
  }

  // Secondary pass: concentric cast-iron machining & oil-halo gouge arcs in the brightest zones
  for (let k = 0; k < 130; k++) {
    let a0 = random(TWO_PI);
    let span = random(0.18, 0.48);
    let isHalo = random() < 0.58;
    let rBase = isHalo ? eggRadius(a0) + random(16, 62) : random(185, R_FLOOR - 10);
    let cx0 = isHalo ? EX : 0;
    let cy0 = isHalo ? EY : 0;

    let pts = [];
    let lumSum = 0;
    for (let j = 0; j <= 6; j++) {
      let a = a0 + map(j, 0, 6, -span * 0.5, span * 0.5);
      let r = isHalo ? eggRadius(a) + (rBase - eggRadius(a0)) : rBase;
      let X = cx0 + r * Math.cos(a);
      let Y = cy0 + r * Math.sin(a);
      if (Math.hypot(X, Y) > R_FLOOR - 5 || isInsideEgg(X, Y, 0.98)) continue;
      let [sx, sy] = toScreen(X, Y, 0);
      if (sy > frontInnerRimYAtX(X) - 3) continue;
      pts.push([sx, sy]);
      lumSum += floorLuminance(X, Y);
    }

    if (pts.length >= 3) {
      let avgL = lumSum / pts.length;
      if (avgL > 0.22) {
        let w = map(avgL, 0.22, 0.85, 0.28, 1.35, true);
        brush.set("v_gouge", avgL > 0.5 ? PAPER_LIGHT : PAPER_BG, w);
        safeSpline(pts, 0.5);
      }
    }
  }
}

// ============================================================================
// 6. THE FRIED EGG (LACY EDGES, ALBUMEN CONTOURS, BLISTERS & DOMED YOLK)
// ============================================================================

function drawFriedEgg() {
  // --- A. Solid Off-White Base for the Egg White (Albumen) ---
  let eggBasePts = [];
  let steps = 160;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * TWO_PI;
    let r = eggRadius(a) * 0.965;
    let X = EX + r * Math.cos(a);
    let Y = EY + r * Math.sin(a);
    eggBasePts.push(toScreen(X, Y, 2));
  }
  fillShapePoints(eggBasePts, PAPER_BG, 255, 0.25);

  // Inner brighter highlight wash for the raised thick albumen pillow
  let thickPts = [];
  for (let i = 0; i < 90; i++) {
    let a = (i / 90) * TWO_PI;
    let r = thickAlbumenRadius(a);
    let X = EX + 8 + r * Math.cos(a);
    let Y = EY - 6 + r * Math.sin(a);
    thickPts.push(toScreen(X, Y, 5));
  }
  fillShapePoints(thickPts, PAPER_LIGHT, 255, 0.3);

  // --- B. Lacy, Bubbling Egg-White Edges ---
  // 1. White lacy tendrils & bridges reaching out onto the black cast-iron floor
  for (let i = 0; i < 210; i++) {
    let a = (i / 210) * TWO_PI + random(-0.015, 0.015);
    let r0 = eggRadius(a) * random(0.88, 0.94);
    let r1 = eggRadius(a) * random(0.99, 1.055);
    let aMid = a + random(-0.035, 0.035);
    let rMid = (r0 + r1) * 0.5;

    let p0 = toScreen(EX + r0 * Math.cos(a), EY + r0 * Math.sin(a), 1);
    let pMid = toScreen(EX + rMid * Math.cos(aMid), EY + rMid * Math.sin(aMid), 1);
    let p1 = toScreen(EX + r1 * Math.cos(a), EY + r1 * Math.sin(a), 0);

    brush.set("v_gouge", random() < 0.6 ? PAPER_LIGHT : PAPER_BG, random(0.55, 1.45));
    safeSpline([p0, pMid, p1], 0.5);
  }

  // 2. Perforated lace holes where the black iron skillet floor peeks through the crispy edge
  for (let h of laceHoles) {
    let holePts = [];
    for (let k = 0; k < 8; k++) {
      let th = (k / 8) * TWO_PI;
      let lx = h.rx * Math.cos(th);
      let ly = h.ry * Math.sin(th);
      let rx = lx * Math.cos(h.angle) - ly * Math.sin(h.angle);
      let ry = lx * Math.sin(h.angle) + ly * Math.cos(h.angle);
      holePts.push(toScreen(h.x + rx, h.y + ry, 1));
    }
    fillShapePoints(holePts, INK_BLACK, 255, 0.35);

    // Crisp dark browned ring around each lace perforation
    brush.set("v_gouge", random() < 0.45 ? INK_UMBER : INK_BLACK, random(0.35, 0.85));
    let arcPts = [holePts[0], holePts[2], holePts[4], holePts[6], holePts[0]];
    safeSpline(arcPts, 0.5);
  }

  // 3. Swelling, tapering black & deep-earth gouge strokes carving the browned, crispy lacy edge
  for (let i = 0; i < 260; i++) {
    let a0 = (i / 260) * TWO_PI + random(-0.01, 0.01);
    let span = random(0.04, 0.11);
    let rFrac = random(0.86, 1.02);
    let pts = [];
    for (let j = 0; j <= 4; j++) {
      let a = a0 + map(j, 0, 4, -span * 0.5, span * 0.5);
      let r = eggRadius(a) * (rFrac + 0.02 * Math.sin(j * 1.4));
      pts.push(toScreen(EX + r * Math.cos(a), EY + r * Math.sin(a), 1.5));
    }
    // Shadow side (bottom-right) has heavier crispy black marks
    let shadowWeight = 0.65 + 0.55 * Math.max(0, Math.cos(a0 - 0.65));
    let col = random() < 0.35 ? INK_EARTH : random() < 0.5 ? INK_UMBER : INK_BLACK;
    brush.set("v_gouge", col, random(0.35, 1.15) * shadowWeight);
    safeSpline(pts, 0.5);
  }

  // --- C. Egg-White Topographic Contours & Thick Albumen Step ---
  // Concentric contour-following engraving lines wrapping across the albumen
  let numAlbumenRings = 36;
  for (let k = 0; k < numAlbumenRings; k++) {
    let tRing = map(k, 0, numAlbumenRings - 1, 0.28, 0.91);
    let totalSteps = 110;
    let seg = [];
    let weightSum = 0;

    for (let i = 0; i <= totalSteps; i++) {
      let a = (i / totalSteps) * TWO_PI;
      let rOuter = eggRadius(a);
      let rThick = thickAlbumenRadius(a);

      // Blend smoothly from thick albumen contour to outer egg contour
      let r = tRing < 0.56
        ? map(tRing, 0.28, 0.56, RY_X + 6, rThick)
        : map(tRing, 0.56, 0.91, rThick, rOuter * 0.89);

      let X = EX + (1.0 - tRing) * 10 + r * Math.cos(a);
      let Y = EY - (1.0 - tRing) * 8 + r * Math.sin(a);

      // Skip points inside the yolk base
      let dxY = X - YX;
      let dyY = Y - YY;
      if (Math.hypot(dxY, dyY) < RY_X - 2) {
        if (seg.length >= 3) {
          brush.set("v_gouge", INK_BLACK, weightSum / seg.length);
          safeSpline(seg, 0.45);
        }
        seg = [];
        weightSum = 0;
        continue;
      }

      // Compute local shading on the white albumen:
      // 1) Cast shadow directly to the bottom-right of the domed yolk
      let distYolk = Math.hypot(dxY, dyY) - RY_X;
      let angleYolk = Math.atan2(dyY, dxY);
      let yolkShadow = 0;
      if (distYolk >= -2 && distYolk < 44) {
        let dirMatch = Math.max(0, Math.cos(angleYolk - 0.62));
        yolkShadow = Math.pow(dirMatch, 1.8) * Math.exp(-Math.pow(distYolk / 22, 2)) * 1.45;
      }

      // 2) Subtle ridge shadow along the outer edge of the thick inner albumen (tRing ~ 0.56)
      let ridgeDist = Math.abs(tRing - 0.56);
      let ridgeShade = Math.exp(-Math.pow(ridgeDist / 0.055, 2)) * (0.22 + 0.45 * Math.max(0, Math.cos(a - 0.55)));

      // 3) Outer border undulation near the lacy edge (tRing > 0.80)
      let edgeShade = tRing > 0.78 ? map(tRing, 0.78, 0.91, 0.0, 0.42) * (0.6 + 0.4 * Math.sin(a * 7)) : 0;

      // 4) Gentle surface wave across the white
      let waveShade = Math.max(0, Math.sin(a * 3 - 0.8 + tRing * 6)) * 0.14;

      let shade = yolkShadow + ridgeShade + edgeShade + waveShade;

      // Leave the sunlit upper-left plains of the egg white mostly bare off-white paper!
      if (shade > 0.11) {
        let zWhite = tRing < 0.56 ? 5.0 : 2.0;
        seg.push(toScreen(X, Y, zWhite));
        weightSum += map(shade, 0.11, 1.4, 0.18, 1.55, true);

        if (seg.length >= 10) {
          brush.set("v_gouge", INK_BLACK, weightSum / seg.length);
          safeSpline(seg, 0.45);
          seg = [seg[seg.length - 1]];
          weightSum = map(shade, 0.11, 1.4, 0.18, 1.55, true);
        }
      } else {
        if (seg.length >= 3) {
          brush.set("v_gouge", INK_BLACK, weightSum / seg.length);
          safeSpline(seg, 0.45);
        }
        seg = [];
        weightSum = 0;
      }
    }
    if (seg.length >= 3) {
      brush.set("v_gouge", INK_BLACK, weightSum / seg.length);
      safeSpline(seg, 0.45);
    }
  }

  // Radial/cross-contour burin strokes in the deep crescent shadow cast by the yolk onto the white
  for (let i = 0; i < 62; i++) {
    let a = map(i, 0, 61, -0.35, 1.65);
    let dirMatch = Math.max(0, Math.cos(a - 0.62));
    if (dirMatch < 0.15) continue;
    let rStart = RY_X - 1;
    let rEnd = RY_X + 10 + 30 * Math.pow(dirMatch, 1.4);
    let p0 = toScreen(YX + rStart * Math.cos(a), YY + rStart * Math.sin(a), 5);
    let p1 = toScreen(
      YX + ((rStart + rEnd) * 0.5) * Math.cos(a + 0.04),
      YY + ((rStart + rEnd) * 0.5) * Math.sin(a + 0.04),
      5
    );
    let p2 = toScreen(YX + rEnd * Math.cos(a), YY + rEnd * Math.sin(a), 5);
    brush.set("v_gouge", INK_BLACK, 0.35 + 1.05 * dirMatch);
    safeSpline([p0, p1, p2], 0.4);
  }

  // --- D. Steam Blisters / Bubbles on the Albumen ---
  for (let b of blisters) {
    let [bx, by] = toScreen(b.x, b.y, 3.5);
    let rx = b.r;
    let ry = b.r * KAPPA;

    if (b.popped) {
      // Popped blister crater: dark inner crescent on top-left + raised white rim + outer bottom-right shadow
      let innerPts = [];
      for (let j = 0; j <= 6; j++) {
        let th = map(j, 0, 6, -2.7, -0.3);
        innerPts.push([bx + rx * 0.65 * Math.cos(th), by + ry * 0.65 * Math.sin(th)]);
      }
      brush.set("v_gouge", INK_BLACK, 0.65);
      safeSpline(innerPts, 0.5);
    }

    // Concentric crescent contour strokes on the lower-right slope and cast shadow of each blister dome
    for (let ring = 0; ring < 3; ring++) {
      let scaleR = 0.78 + ring * 0.22;
      let arcPts = [];
      for (let j = 0; j <= 7; j++) {
        let th = map(j, 0, 7, -0.45 + ring * 0.12, 2.05 - ring * 0.12);
        arcPts.push([bx + rx * scaleR * Math.cos(th), by + ry * scaleR * Math.sin(th) - (2 - ring) * 1.2]);
      }
      let w = ring === 1 ? 0.68 : 0.38;
      brush.set("v_gouge", INK_BLACK, w);
      safeSpline(arcPts, 0.5);
    }
  }

  // --- E. The Domed Egg Yolk ---
  drawDomedYolk();
}

function yolkPointScreen(theta, phi) {
  let [yx0, yy0] = toScreen(YX, YY, 5.0);
  let sx = yx0 + RY_X * Math.sin(theta) * Math.cos(phi);
  let sy = yy0 + RY_Y * Math.sin(theta) * Math.sin(phi) - HY_DOME * Math.pow(Math.cos(theta), 0.92);
  return [sx, sy];
}

function yolkMaxTheta(phi) {
  let s = Math.sin(phi);
  if (s >= 0) return Math.PI / 2;
  return Math.atan2(RY_Y, HY_DOME * Math.abs(s));
}

function yolkLuminance(theta, phi) {
  // 3D hemisphere unit normal
  let nx = Math.sin(theta) * Math.cos(phi);
  let ny = Math.sin(theta) * Math.sin(phi);
  let nz = Math.cos(theta);

  // Primary studio/window light from top-left (-0.54, -0.48, 0.69)
  let ndotl = Math.max(0, -0.54 * nx - 0.48 * ny + 0.69 * nz);

  // Crisp glossy window highlight on upper-left dome (divided by a thin window mullion bar!)
  let dTheta = theta - 0.48;
  let dPhi = angleDiff(phi, -2.22);
  let inWindow = Math.abs(dTheta) < 0.22 && Math.abs(dPhi) < 0.48;
  let mullionBar = Math.abs(dPhi + 0.04) < 0.045 || Math.abs(dTheta - 0.02) < 0.032;
  let windowSpec = 0;
  if (inWindow && !mullionBar) {
    windowSpec = 0.85;
  } else {
    // Soft glossy halo around window reflection
    windowSpec = 0.38 * Math.exp(-(dTheta * dTheta) / 0.045 - (dPhi * dPhi) / 0.18);
  }

  // Translucent bounce light along the lower-right rim from the surrounding white albumen
  let bounceRim = 0;
  if (theta > 0.88 && theta < 1.48) {
    let rimDir = Math.max(0, Math.cos(phi - 0.65));
    bounceRim = 0.46 * Math.pow(rimDir, 1.5) * Math.sin(map(theta, 0.88, 1.48, 0, Math.PI));
  }

  // Dark meniscus ring right at the equator base (theta > 1.44)
  let meniscusDark = theta > 1.42 ? map(theta, 1.42, Math.PI / 2, 1.0, 0.15) : 1.0;

  let lum = (0.08 + 0.56 * Math.pow(ndotl, 1.15) + windowSpec + bounceRim) * meniscusDark;
  return constrain(lum, 0.03, 0.98);
}

function drawDomedYolk() {
  // 1. Solid dark base silhouette for the 3D domed yolk (horizon curve on back + equator on front)
  let yolkSil = [];
  let steps = 120;
  for (let i = 0; i < steps; i++) {
    let phi = (i / steps) * TWO_PI;
    let thMax = yolkMaxTheta(phi);
    yolkSil.push(yolkPointScreen(thMax, phi));
  }
  fillShapePoints(yolkSil, INK_BLACK, 255, 0.25);

  // 2. Latitude contour gouge rings wrapping around the 3D hemisphere of the yolk
  let numLat = 44;
  for (let k = 1; k < numLat; k++) {
    let theta = map(k, 0, numLat, 0.04, Math.PI / 2 - 0.02);
    let ringSteps = 96;
    let seg = [];
    let lumSum = 0;

    for (let i = 0; i <= ringSteps; i++) {
      let phi = (i / ringSteps) * TWO_PI;
      if (theta > yolkMaxTheta(phi) - 0.015) {
        if (seg.length >= 3) {
          let avgL = lumSum / seg.length;
          if (avgL > 0.09) {
            let col = avgL > 0.62 ? PAPER_LIGHT : PAPER_BG;
            brush.set("v_gouge", col, map(avgL, 0.09, 0.95, 0.22, 1.85, true));
            safeSpline(seg, 0.5);
          }
        }
        seg = [];
        lumSum = 0;
        continue;
      }

      let pt = yolkPointScreen(theta, phi);
      let lum = yolkLuminance(theta, phi);
      seg.push(pt);
      lumSum += lum;

      if (seg.length >= 9) {
        let avgL = lumSum / seg.length;
        if (avgL > 0.09) {
          let col = avgL > 0.62 ? PAPER_LIGHT : PAPER_BG;
          brush.set("v_gouge", col, map(avgL, 0.09, 0.95, 0.22, 1.85, true));
          safeSpline(seg, 0.5);
        }
        seg = [pt];
        lumSum = lum;
      }
    }
    if (seg.length >= 3) {
      let avgL = lumSum / seg.length;
      if (avgL > 0.09) {
        let col = avgL > 0.62 ? PAPER_LIGHT : PAPER_BG;
        brush.set("v_gouge", col, map(avgL, 0.09, 0.95, 0.22, 1.85, true));
        safeSpline(seg, 0.5);
      }
    }
  }

  // 3. Meridian / curving cross-contour gouge lines arching over the dome of the yolk
  let numMeridians = 72;
  for (let m = 0; m < numMeridians; m++) {
    let phi0 = (m / numMeridians) * TWO_PI;
    let thMax = yolkMaxTheta(phi0) - 0.03;
    let seg = [];
    let lumSum = 0;

    for (let s = 0; s <= 18; s++) {
      let theta = map(s, 0, 18, 0.08, thMax);
      // Slight spiral twist for organic wood-engraving cross-contour feel
      let phi = phi0 + 0.14 * Math.sin(theta * 1.5);
      let pt = yolkPointScreen(theta, phi);
      let lum = yolkLuminance(theta, phi);
      seg.push(pt);
      lumSum += lum;

      if (seg.length >= 6) {
        let avgL = lumSum / seg.length;
        if (avgL > 0.14) {
          let col = avgL > 0.6 ? PAPER_LIGHT : PAPER_BG;
          brush.set("v_gouge", col, map(avgL, 0.14, 0.95, 0.2, 1.65, true));
          safeSpline(seg, 0.45);
        }
        seg = [pt];
        lumSum = lum;
      }
    }
    if (seg.length >= 3) {
      let avgL = lumSum / seg.length;
      if (avgL > 0.14) {
        let col = avgL > 0.6 ? PAPER_LIGHT : PAPER_BG;
        brush.set("v_gouge", col, map(avgL, 0.14, 0.95, 0.2, 1.65, true));
        safeSpline(seg, 0.45);
      }
    }
  }

  // 4. Crisp solid white gouges for the two glossy window-pane reflections on the upper-left yolk dome
  for (let pane = 0; pane < 2; pane++) {
    let phiMin = pane === 0 ? -2.65 : -2.14;
    let phiMax = pane === 0 ? -2.23 : -1.76;
    for (let r = 0; r < 9; r++) {
      let theta = map(r, 0, 8, 0.3, 0.65);
      let pts = [];
      for (let c = 0; c <= 5; c++) {
        let phi = map(c, 0, 5, phiMin, phiMax);
        pts.push(yolkPointScreen(theta, phi));
      }
      brush.set("u_gouge", PAPER_LIGHT, 1.15);
      safeSpline(pts, 0.5);
    }
  }

  // 5. Fine black & deep-umber burin engraving strokes refining the yolk's core shadow and highlight edges
  for (let k = 0; k < 45; k++) {
    let theta = random(0.22, 1.46);
    let phi0 = random(TWO_PI);
    let span = random(0.22, 0.55);
    let pts = [];
    let lumSum = 0;
    for (let j = 0; j <= 5; j++) {
      let phi = phi0 + map(j, 0, 5, -span * 0.5, span * 0.5);
      if (theta > yolkMaxTheta(phi) - 0.02) continue;
      pts.push(yolkPointScreen(theta, phi));
      lumSum += yolkLuminance(theta, phi);
    }
    if (pts.length >= 3) {
      let avgL = lumSum / pts.length;
      if (avgL < 0.68) {
        let w = map(avgL, 0.05, 0.68, 1.35, 0.25, true);
        let col = random() < 0.35 ? INK_UMBER : INK_BLACK;
        brush.set("v_gouge", col, w);
        safeSpline(pts, 0.5);
      }
    }
  }
}

// ============================================================================
// 7. BARE WHITE FLECKS (OIL SPATTER & DROPLETS)
// ============================================================================

function drawOilSpatterFlecks() {
  // 1. Fine bare white oil-spatter flecks radiating around the frying egg onto the black iron floor
  for (let i = 0; i < 290; i++) {
    let a = random(TWO_PI);
    let rEgg = eggRadius(a);
    // Concentrated near the sizzling lacy edge, sparser toward the walls
    let dist = rEgg + 6 + Math.pow(random(), 1.65) * 145;
    let X = EX + dist * Math.cos(a);
    let Y = EY + dist * Math.sin(a);

    if (Math.hypot(X, Y) > R_FLOOR - 6) continue;
    let [sx, sy] = toScreen(X, Y, 0);
    if (sy > frontInnerRimYAtX(X) - 4) continue;

    // Tiny gouge flick (comma, crescent, or sharp pinprick of bare white paper)
    let flickLen = random(2.4, 6.2);
    let flickAng = a + random(-0.6, 0.6);
    let p0 = [sx, sy];
    let p1 = [
      sx + Math.cos(flickAng) * flickLen * 0.5 - Math.sin(flickAng) * 1.2,
      sy + Math.sin(flickAng) * flickLen * 0.5 + Math.cos(flickAng) * 1.2
    ];
    let p2 = [sx + Math.cos(flickAng) * flickLen, sy + Math.sin(flickAng) * flickLen];

    brush.set("v_gouge", PAPER_LIGHT, random(0.45, 1.25));
    safeSpline([p0, p1, p2], 0.5);
  }

  // 2. Larger beaded oil droplets on the black skillet floor (each with a bright white crescent highlight)
  for (let i = 0; i < 34; i++) {
    let a = random(TWO_PI);
    let dist = eggRadius(a) + random(14, 92);
    let X = EX + dist * Math.cos(a);
    let Y = EY + dist * Math.sin(a);
    if (Math.hypot(X, Y) > R_FLOOR - 14) continue;
    let [sx, sy] = toScreen(X, Y, 0);
    if (sy > frontInnerRimYAtX(X) - 6) continue;

    let dropR = random(3.2, 6.8);
    // Dark oil bead core
    brush.set("u_gouge", INK_BLACK, dropR * 0.45);
    brush.circle(sx, sy, dropR, 0.15);

    // Crisp white top-left specular crescent gouge
    let cPts = [];
    for (let j = 0; j <= 4; j++) {
      let th = map(j, 0, 4, -2.8, -0.7);
      cPts.push([sx + dropR * 0.85 * Math.cos(th), sy + dropR * 0.65 * Math.sin(th)]);
    }
    brush.set("v_gouge", PAPER_LIGHT, random(0.55, 0.95));
    safeSpline(cPts, 0.5);
  }

  // 3. Oil spatter flecks splashing up onto the back/side interior cast-iron wall
  for (let i = 0; i < 85; i++) {
    let phi = random(-3.2, 0.85);
    let s = random(0.08, 0.82);
    let r = wallRadius(s, phi);
    let [sx, sy] = toScreen(r * Math.cos(phi), r * Math.sin(phi), s * H_WALL);
    if (sy > frontInnerRimYAtX(r * Math.cos(phi)) - 4) continue;

    let len = random(2.5, 5.5);
    let ang = random(TWO_PI);
    brush.set("v_gouge", PAPER_LIGHT, random(0.4, 0.95));
    brush.line(sx, sy, sx + Math.cos(ang) * len, sy + Math.sin(ang) * len);
  }
}

// ============================================================================
// 8. FRONT EXTERIOR CAST-IRON BELLY
// ============================================================================

function drawExteriorFrontBelly() {
  // Re-assert solid black for the front exterior wall (cleanly occluding the front floor crescent)
  let bellyPts = [];
  let steps = 70;
  for (let i = 0; i <= steps; i++) {
    let phi = map(i, 0, steps, -0.05, Math.PI + 0.05);
    let r = outerRimRadius(phi);
    bellyPts.push(toScreen(r * Math.cos(phi), r * Math.sin(phi), H_WALL));
  }
  for (let i = steps; i >= 0; i--) {
    let phi = map(i, 0, steps, -0.05, Math.PI + 0.05);
    bellyPts.push(toScreen(R_BASE * Math.cos(phi), R_BASE * Math.sin(phi), 0));
  }
  fillShapePoints(bellyPts, INK_BLACK, 255, 0.15);

  // Exterior cast-iron belly lighting: left front side (phi ~ 2.1 - 2.9) catches top-left light;
  // right front side (phi ~ 0.2 - 1.3) falls into deep rich black with subtle rim bounce.
  for (let k = 1; k < 14; k++) {
    let s = k / 14; // 0 = base, 1 = outer top rim
    let z = s * H_WALL;
    let seg = [];
    let lumSum = 0;

    for (let i = 0; i <= 75; i++) {
      let phi = map(i, 0, 75, 0.02, Math.PI - 0.02);
      let r = lerp(R_BASE, outerRimRadius(phi), Math.pow(s, 0.78));
      let [sx, sy] = toScreen(r * Math.cos(phi), r * Math.sin(phi), z);

      // Exterior normal points outward (+cos(phi), +sin(phi))
      let extLight = Math.max(0, -0.62 * Math.cos(phi) + 0.35 * Math.sin(phi));
      let spoutLip = 0.45 * Math.exp(-Math.pow(angleDiff(phi, PHI_SPOUT1) / 0.14, 2)) * s;
      let lum = (0.04 + 0.48 * extLight + spoutLip) * Math.sin(s * Math.PI);

      seg.push([sx, sy]);
      lumSum += lum;

      if (seg.length >= 8 || i === 75) {
        let avgL = lumSum / seg.length;
        if (avgL > 0.07) {
          brush.set("v_gouge", PAPER_BG, map(avgL, 0.07, 0.65, 0.22, 1.3, true));
          safeSpline(seg, 0.45);
        }
        seg = [[sx, sy]];
        lumSum = lum;
      }
    }
  }

  // Short vertical curved relief gouges along the pebbly exterior belly wall
  for (let i = 0; i < 110; i++) {
    let phi = map(i, 0, 109, 0.05, Math.PI - 0.05);
    let extLight = Math.max(0, -0.62 * Math.cos(phi) + 0.35 * Math.sin(phi));
    let spoutLip = 0.45 * Math.exp(-Math.pow(angleDiff(phi, PHI_SPOUT1) / 0.14, 2));
    let lum = 0.05 + 0.48 * extLight + spoutLip;
    if (lum < 0.09 && random() < 0.65) continue;

    let s0 = random(0.12, 0.32);
    let s1 = random(0.68, 0.92);
    let sMid = (s0 + s1) * 0.5;

    let r0 = lerp(R_BASE, outerRimRadius(phi), Math.pow(s0, 0.78));
    let rMid = lerp(R_BASE, outerRimRadius(phi), Math.pow(sMid, 0.78));
    let r1 = lerp(R_BASE, outerRimRadius(phi), Math.pow(s1, 0.78));

    let p0 = toScreen(r0 * Math.cos(phi), r0 * Math.sin(phi), s0 * H_WALL);
    let pMid = toScreen(rMid * Math.cos(phi), rMid * Math.sin(phi), sMid * H_WALL);
    let p1 = toScreen(r1 * Math.cos(phi), r1 * Math.sin(phi), s1 * H_WALL);

    brush.set("v_gouge", PAPER_BG, map(lum, 0.08, 0.65, 0.2, 1.15, true));
    safeSpline([p0, pMid, p1], 0.4);
  }
}

// ============================================================================
// 9. TOP RIM & POUR SPOUTS (SWELLING CONTOUR & BEVEL GOUGE MARKS)
// ============================================================================

function rimLuminance(tAcross, phi) {
  // tAcross in [0, 1] from inner rim edge to outer rim edge
  // Top flat face catches strong overhead light; inner bevel catches light on back/right;
  // outer bevel catches light on top-left and front-left.
  let topFlat = 0.42 + 0.28 * Math.cos(phi + 0.65);
  let innerBevel = (1.0 - tAcross) * Math.max(0, Math.cos(phi + 0.25)) * 0.52;
  let outerBevel = tAcross * Math.max(0, Math.cos(phi - 2.45)) * 0.55;

  // Dramatic specular pinch along the curved lips of both pour spouts
  let d1 = angleDiff(phi, PHI_SPOUT1);
  let d2 = angleDiff(phi, PHI_SPOUT2);
  let spoutRim1 = 0.45 * Math.exp(-Math.pow((d1 - 0.07) / 0.11, 2));
  let spoutRim2 = 0.48 * Math.exp(-Math.pow((d2 + 0.06) / 0.11, 2));

  return constrain(topFlat + innerBevel + outerBevel + spoutRim1 + spoutRim2, 0.12, 0.96);
}

function drawTopRimAndSpouts() {
  // 1. Solid black collar for the 360-degree top rim (ensuring crisp inner and outer edges)
  let steps = 140;
  let nSegs = 28;
  for (let s = 0; s < nSegs; s++) {
    let phiA = (s / nSegs) * TWO_PI;
    let phiB = ((s + 1) / nSegs) * TWO_PI;
    let quadPts = [];
    for (let j = 0; j <= 5; j++) {
      let phi = lerp(phiA, phiB, j / 5);
      let rOut = outerRimRadius(phi);
      quadPts.push(toScreen(rOut * Math.cos(phi), rOut * Math.sin(phi), H_WALL));
    }
    for (let j = 5; j >= 0; j--) {
      let phi = lerp(phiA, phiB, j / 5);
      let rIn = wallRadius(1.0, phi);
      quadPts.push(toScreen(rIn * Math.cos(phi), rIn * Math.sin(phi), H_WALL));
    }
    fillShapePoints(quadPts, INK_BLACK, 255, 0.1);
  }

  // 2. Swelling, tapering circumferential gouge tracks following the curvature of the pan rim & pour spouts
  let numTracks = 9;
  for (let tr = 0; tr < numTracks; tr++) {
    let tAcross = map(tr, 0, numTracks - 1, 0.08, 0.92);
    let seg = [];
    let lumSum = 0;

    for (let i = 0; i <= steps; i++) {
      let phi = (i / steps) * TWO_PI;
      let rIn = wallRadius(1.0, phi);
      let rOut = outerRimRadius(phi);
      let r = lerp(rIn, rOut, tAcross);
      // Slight domed bevel height across the rim thickness
      let zBevel = H_WALL + 2.5 * Math.sin(tAcross * Math.PI);
      let pt = toScreen(r * Math.cos(phi), r * Math.sin(phi), zBevel);
      let lum = rimLuminance(tAcross, phi);

      seg.push(pt);
      lumSum += lum;

      if (seg.length >= 9 || i === steps) {
        let avgL = lumSum / seg.length;
        let w = map(avgL, 0.12, 0.96, 0.28, 1.75, true);
        let col = avgL > 0.62 ? PAPER_LIGHT : PAPER_BG;
        brush.set("v_gouge", col, w);
        safeSpline(seg, 0.45);
        seg = [pt];
        lumSum = lum;
      }
    }
  }

  // 3. Radial cross-bevel gouges carving the rounded cast-iron lip
  for (let i = 0; i < 160; i++) {
    let phi = (i / 160) * TWO_PI;
    let lum = rimLuminance(0.5, phi);
    if (lum < 0.25 && i % 2 === 0) continue;

    let rIn = wallRadius(1.0, phi) + 1.5;
    let rOut = outerRimRadius(phi) - 1.5;
    let rMid = (rIn + rOut) * 0.5;

    let p0 = toScreen(rIn * Math.cos(phi), rIn * Math.sin(phi), H_WALL);
    let pMid = toScreen(rMid * Math.cos(phi + 0.008), rMid * Math.sin(phi + 0.008), H_WALL + 2.5);
    let p1 = toScreen(rOut * Math.cos(phi), rOut * Math.sin(phi), H_WALL);

    brush.set("v_gouge", lum > 0.65 ? PAPER_LIGHT : PAPER_BG, map(lum, 0.15, 0.95, 0.22, 1.15, true));
    safeSpline([p0, pMid, p1], 0.4);
  }
}

// ============================================================================
// 10. HELPER HANDLE (TOP-RIGHT) & MAIN HANDLE (BOTTOM-LEFT)
// ============================================================================

function drawHelperHandle() {
  let uHx = Math.cos(PHI_HELPER);
  let uHy = Math.sin(PHI_HELPER);
  let vHx = -uHy;
  let vHy = uHx;

  function helperPt(t, s, zOff = 0) {
    // t in [0, 64] outward from outer rim, s in [-1, 1] across width
    let halfW = 74 * Math.sqrt(Math.max(0, 1 - Math.pow(t / 64, 1.85)));
    let r = R_RIM_OUT - 4 + t;
    let X = r * uHx + s * halfW * vHx;
    let Y = r * uHy + s * halfW * vHy;
    return toScreen(X, Y, H_WALL + zOff);
  }

  // 1. 3D underside thickness & top face solid black silhouette
  let botPts = [];
  let topPts = [];
  for (let i = 0; i <= 32; i++) {
    let ang = map(i, 0, 32, -Math.PI / 2, Math.PI / 2);
    let t = 64 * Math.cos(ang);
    let s = Math.sin(ang);
    topPts.push(helperPt(t, s, 0));
    botPts.push(helperPt(t, s, -16));
  }
  fillShapePoints(botPts, INK_BLACK, 255, 0.2);
  fillShapePoints(topPts, INK_BLACK, 255, 0.2);

  // 2. Elongated slot hole in the center of the helper handle
  let slotTop = [];
  let slotBot = [];
  for (let i = 0; i < 24; i++) {
    let th = (i / 24) * TWO_PI;
    let t = 28 + 11 * Math.cos(th);
    let s = 0.48 * Math.sin(th);
    slotTop.push(helperPt(t, s, 0));
    slotBot.push(helperPt(t, s, -11));
  }
  // Paper tabletop showing through the bottom of the slot
  fillShapePoints(slotBot, PAPER_BG, 255, 0.25);

  // 3. Carved white gouge contours on the helper handle loop
  for (let ring = 0; ring < 5; ring++) {
    let rFrac = map(ring, 0, 4, 0.58, 0.94);
    let pts = [];
    for (let i = 0; i <= 24; i++) {
      let ang = map(i, 0, 24, -Math.PI / 2 + 0.1, Math.PI / 2 - 0.1);
      let t = 64 * rFrac * Math.cos(ang);
      let s = rFrac * Math.sin(ang);
      pts.push(helperPt(t, s, 1.5));
    }
    brush.set("v_gouge", ring === 2 ? PAPER_LIGHT : PAPER_BG, ring === 2 ? 1.15 : 0.65);
    safeSpline(pts, 0.45);
  }
}

function drawMainHandle() {
  let uHx = Math.cos(PHI_HANDLE);
  let uHy = Math.sin(PHI_HANDLE);
  let vHx = -uHy;
  let vHy = uHx;

  function handle3D(t, wOffset, zDelta = 0) {
    let r = R_RIM_OUT - 6 + t;
    let X = r * uHx + wOffset * vHx;
    let Y = r * uHy + wOffset * vHy;
    let Z = H_WALL + 0.11 * t + zDelta;
    return toScreen(X, Y, Z);
  }

  function holeHalfWidth(t) {
    // Teardrop hanging hole from t = 172 to t = 278
    if (t <= 172 || t >= 278) return 0;
    let u = (t - 172) / (278 - 172); // 0 to 1
    return 18.5 * Math.pow(u, 0.68) * Math.sqrt(Math.max(0, 1 - u * u));
  }

  // 1. Solid black 3D thickness side-wall (shifted down by Z = -20)
  let sideWallPts = [];
  for (let t = 0; t <= 310; t += 8) {
    sideWallPts.push(handle3D(t, handleHalfWidth(t), 0));
  }
  for (let t = 310; t >= 0; t -= 8) {
    sideWallPts.push(handle3D(t, -handleHalfWidth(t), 0));
  }
  let botWallPts = [];
  for (let t = 0; t <= 310; t += 8) {
    botWallPts.push(handle3D(t, handleHalfWidth(t), -21));
  }
  for (let t = 310; t >= 0; t -= 8) {
    botWallPts.push(handle3D(t, -handleHalfWidth(t), -21));
  }
  fillShapePoints(botWallPts, INK_BLACK, 255, 0.15);
  fillShapePoints(sideWallPts, INK_BLACK, 255, 0.15);

  // 2. Teardrop hanging hole: inner 3D iron wall + bright tabletop paper peeking through
  let holeThroughPts = [];
  for (let t = 180; t <= 274; t += 6) {
    let hw = holeHalfWidth(t) * 0.88;
    if (hw > 1) holeThroughPts.push(handle3D(t, hw, -16));
  }
  for (let t = 274; t >= 180; t -= 6) {
    let hw = holeHalfWidth(t) * 0.88;
    if (hw > 1) holeThroughPts.push(handle3D(t, -hw, -16));
  }
  fillShapePoints(holeThroughPts, PAPER_BG, 255, 0.25);

  // Vertical gouge marks on the visible inner 3D wall of the teardrop hole (facing top-left light)
  for (let t = 178; t <= 274; t += 5.5) {
    let hw = holeHalfWidth(t);
    if (hw < 2) continue;
    let pTop = handle3D(t, -hw, 0);
    let pBot = handle3D(t, -hw, -15);
    brush.set("v_gouge", PAPER_LIGHT, 0.85);
    brush.line(pTop[0], pTop[1], pBot[0], pBot[1]);
  }

  // 3. Longitudinal flow-field gouge lines sweeping along the top face of the handle
  // and splitting around the teardrop hole
  let numTracks = 15;
  for (let k = 0; k < numTracks; k++) {
    let sNorm = map(k, 0, numTracks - 1, -0.92, 0.92); // across handle width
    let seg = [];
    let lumSum = 0;

    for (let t = 2; t <= 306; t += 8) {
      let outerW = handleHalfWidth(t);
      let holeW = holeHalfWidth(t);

      let wPos;
      if (holeW > 0.5) {
        // Route lines cleanly around the left or right cheek of the teardrop hole
        if (Math.abs(sNorm) < 0.08) continue;
        let sign = sNorm >= 0 ? 1 : -1;
        let cheekFrac = map(Math.abs(sNorm), 0.08, 0.92, 0.12, 0.92);
        wPos = sign * lerp(holeW + 2.5, outerW - 1.5, cheekFrac);
      } else {
        wPos = sNorm * outerW;
      }

      // Handle lighting: raised left ridge (sNorm > 0.55, facing top-left light) and right rim bevel
      // catch bright specular highlights; dished center channel has rich mid-tone relief.
      let ridgeLight =
        0.55 * Math.exp(-Math.pow((sNorm - 0.72) / 0.22, 2)) +
        0.42 * Math.exp(-Math.pow((sNorm + 0.78) / 0.18, 2)) +
        0.22 * (1.0 - Math.abs(sNorm));

      // Bright bevel around the teardrop hole rim
      let holeBevel = holeW > 0 && Math.abs( sNorm ) < 0.32 ? 0.45 : 0;
      let lum = constrain(0.12 + ridgeLight + holeBevel, 0.12, 0.95);

      let pt = handle3D(t, wPos, 1.5);
      seg.push(pt);
      lumSum += lum;

      if (seg.length >= 7 || t >= 300) {
        if (seg.length >= 3) {
          let avgL = lumSum / seg.length;
          let w = map(avgL, 0.12, 0.95, 0.28, 1.65, true);
          brush.set("v_gouge", avgL > 0.6 ? PAPER_LIGHT : PAPER_BG, w);
          safeSpline(seg, 0.45);
        }
        seg = [pt];
        lumSum = lum;
      }
    }
  }

  // 4. Short curved cross-contour gouges on the 3D upper-left thickness wall of the handle
  for (let t = 8; t <= 300; t += 5.5) {
    let outerW = handleHalfWidth(t);
    let pTop = handle3D(t, outerW, 0);
    let pMid = handle3D(t + 1.5, outerW + 1.5, -9);
    let pBot = handle3D(t, outerW, -18);
    let lum = 0.45 + 0.35 * Math.sin((t / 310) * Math.PI);
    brush.set("v_gouge", PAPER_BG, map(lum, 0.3, 0.85, 0.35, 1.15, true));
    safeSpline([pTop, pMid, pBot], 0.4);
  }

  // 5. Crisp highlight gouge wrapping around the rounded tip of the handle and teardrop hole edge
  let holeRimPts = [];
  for (let t = 172; t <= 278; t += 6) {
    let hw = holeHalfWidth(t) + 2.2;
    holeRimPts.push(handle3D(t, -hw, 2));
  }
  brush.set("v_gouge", PAPER_LIGHT, 1.25);
  safeSpline(holeRimPts, 0.45);
}

// Hyperreal Brass Zipper on Navy Nylon — Swiss Grid Specimen
// p5.js 2.x + p5.brush

const PAL = {
  redField:    "#B53724", // Flat muted earth-toned signal red
  redShadow1:  "#7A1F12", // Cast shadow outer penumbra on red
  redShadow2:  "#420E07", // Tight contact shadow on red
  ruleBlack:   "#14110F", // Swiss grid & rule bar carbon black

  navyVoid:    "#090D12", // Deepest crevice between teeth/tape
  navyDark:    "#111721", // Dark navy nylon shadow weave
  navyBase:    "#192230", // Primary muted navy nylon
  navyMid:     "#253244", // Woven rib & herringbone highlight
  navyLight:   "#36475E", // Corded bead crest & stitch catch-light
  navyFray1:   "#485B73", // Translucent frayed nylon filament
  navyFray2:   "#637791", // Fine glint on unravelled tip

  brassVoid:   "#1A1107", // Deepest umber reflection / crevice
  brassD1:     "#2E1F0D", // Dark raw umber shadow
  brassD2:     "#493216", // Deep antique bronze
  brassM1:     "#684920", // Muted earth ochre-umbrage
  brassM2:     "#88622E", // Warm aged brass midtone
  brassM3:     "#A87D3E", // Rich golden ochre brass
  brassL1:     "#C69B54", // Bright metallic brass
  brassL2:     "#DFB973", // Polished gold-brass plane
  brassL3:     "#F1D89E", // High-key specular brass
  brassRim:    "#FBF0D4", // Bevel edge catch-light
  specular:    "#FFFFFF"  // Pinpoint reflection core
};

const CX = 900;          // Hard off-centre zipper vertical axis
const SLIDER_Y = 625;    // Vertical center of the brass slider
const SPLIT_Y = 612;     // Point where interlocking teeth diverge
const TOP_Y = 355;       // Top cut edge of navy nylon tape
const BOT_Y = 1035;      // Bottom cut edge of navy nylon tape
const TAPE_W = 134;      // Width of each nylon tape half

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4219);
  noiseSeed(4219);
  background(PAL.redField);
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Strict Swiss Grid Discipline & Black Rule Bar
  drawSwissGrid();

  // 2. Contact & Cast Shadows on the Flat Signal Red Field
  drawSpecimenDropShadows();

  // 3. Navy Nylon Tape Halves (Woven Twill, Cord Bead, Chain Stitch)
  drawNavyNylonTapes();

  // 4. Frayed Nylon Threads at the Tape Edges
  drawFrayedTapeEdges();

  // 5. Interlocking Brass Teeth (Closed Run, Bottom/Top Stops, Open Run)
  drawAllBrassTeeth();

  // 6. Marker-Shaded Scratched Brass Slider & Hanging Pull Tab + Pinpoint Reflection
  drawBrassSliderAndPull();

  noLoop();
}

// ============================================================================
// PRIMITIVE HELPERS (Strict p5.brush state discipline)
// ============================================================================

function washPoly(pts, col, alpha = 255) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, alpha);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function strokePoly(pts, bName, col, weight, closed = true, curvature = 0) {
  if (!pts || pts.length < 2) return;
  brush.noWash();
  brush.noFill();
  brush.noHatch();
  brush.set(bName, col, weight);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

function drawLine(x1, y1, x2, y2, bName, col, weight) {
  brush.noWash();
  brush.noFill();
  brush.set(bName, col, weight);
  brush.line(x1, y1, x2, y2);
}

function drawSpline(pts, bName, col, weight, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  brush.noWash();
  brush.noFill();
  brush.set(bName, col, weight);
  brush.spline(pts, curvature);
}

// ============================================================================
// TAPE GEOMETRY PARAMETRICS
// ============================================================================

// Returns the x-coordinate of the inner corded edge of the tape at height y
// side: -1 for left tape, +1 for right tape
function getInnerEdgeX(y, side) {
  const baseGap = 13.5; // Half-width of the locked teeth channel
  if (y >= SPLIT_Y) {
    return CX + side * baseGap;
  } else {
    let t = constrain((SPLIT_Y - y) / (SPLIT_Y - TOP_Y), 0, 1);
    let flare = 92 * pow(t, 1.48);
    // Slight organic wave near the top cut
    let wave = sin(t * 140) * 1.8 * t;
    return CX + side * (baseGap + flare + wave);
  }
}

// Returns the local tangent angle (in degrees, where 0 is straight down +y)
function getTapeTangentDeg(y, side) {
  let dy = 2;
  let x1 = getInnerEdgeX(y - dy, side);
  let x2 = getInnerEdgeX(y + dy, side);
  return atan2(x2 - x1, 2 * dy); // angle relative to +y axis
}

// Converts tape-local coordinates (distFromInner, y, side) to canvas [x, y]
function tapePoint(y, distFromInner, side) {
  let ix = getInnerEdgeX(y, side);
  let ang = getTapeTangentDeg(y, side);
  // Normal pointing outward from centerline
  let nx = side * cos(ang);
  let ny = -side * sin(ang);
  return [ix + nx * distFromInner, y + ny * distFromInner];
}

// ============================================================================
// 1. SWISS GRID DISCIPLINE & RULE BAR
// ============================================================================

function drawSwissGrid() {
  brush.noField();

  // Heavy black architectural rule bar running along the left edge
  washPoly([
    [54, 54],
    [74, 54],
    [74, 1146],
    [54, 1146]
  ], PAL.ruleBlack, 255);

  // Crisp edge definition on the black rule bar
  strokePoly([
    [54, 54],
    [74, 54],
    [74, 1146],
    [54, 1146]
  ], "rotring", PAL.ruleBlack, 0.45, true, 0);

  // Secondary parallel hair-rule beside the main bar
  drawLine(84, 54, 84, 1146, "rotring", PAL.ruleBlack, 0.42);

  // Outer perimeter Swiss frame rules
  drawLine(54, 54, 1146, 54, "rotring", PAL.ruleBlack, 0.45);
  drawLine(54, 1146, 1146, 1146, "rotring", PAL.ruleBlack, 0.45);
  drawLine(1146, 54, 1146, 1146, "rotring", PAL.ruleBlack, 0.45);

  // Asymmetric horizontal modular subdivisions (leaving vast empty fields)
  const hRules = [148, 355, 825, 1065];
  for (let y of hRules) {
    drawLine(84, y, 1146, y, "rotring", PAL.ruleBlack, 0.36);
  }

  // Asymmetric vertical modular subdivisions
  const vRules = [312, 648];
  for (let x of vRules) {
    drawLine(x, 54, x, 1146, "rotring", PAL.ruleBlack, 0.36);
  }

  // Secondary sub-module rules in the top-left header band only
  drawLine(198, 54, 198, 148, "rotring", PAL.ruleBlack, 0.32);
  drawLine(480, 54, 480, 148, "rotring", PAL.ruleBlack, 0.32);
  drawLine(84, 101, 648, 101, "rotring", PAL.ruleBlack, 0.28);

  // Minimal Swiss index blocks (pure geometric typographic placeholders)
  washPoly([[98, 68], [156, 68], [156, 78], [98, 78]], PAL.ruleBlack, 255);
  washPoly([[98, 84], [128, 84], [128, 89], [98, 89]], PAL.ruleBlack, 255);

  washPoly([[212, 68], [244, 68], [244, 78], [212, 78]], PAL.ruleBlack, 255);
  washPoly([[326, 68], [395, 68], [395, 78], [326, 78]], PAL.ruleBlack, 255);
  washPoly([[326, 115], [362, 115], [362, 123], [326, 123]], PAL.ruleBlack, 255);

  // Bottom-left specimen index bar
  washPoly([[98, 1082], [184, 1082], [184, 1094], [98, 1094]], PAL.ruleBlack, 255);
  drawLine(98, 1104, 260, 1104, "rotring", PAL.ruleBlack, 0.35);
  drawLine(98, 1112, 220, 1112, "rotring", PAL.ruleBlack, 0.35);

  // Precision Swiss calibration ticks along the x = 648 division line
  for (let y = 160; y <= 810; y += 25) {
    let tickLen = (y % 100 === 60) ? 10 : 5;
    drawLine(648 - tickLen, y, 648, y, "rotring", PAL.ruleBlack, 0.3);
  }

  // Registration crosshairs at key empty grid nodes
  const crossNodes = [[312, 355], [312, 825], [648, 355], [648, 1065]];
  for (let [cx, cy] of crossNodes) {
    drawLine(cx - 9, cy, cx + 9, cy, "rotring", PAL.ruleBlack, 0.45);
    drawLine(cx, cy - 9, cx, cy + 9, "rotring", PAL.ruleBlack, 0.45);
    brush.set("rotring", PAL.ruleBlack, 0.35);
    brush.circle(cx, cy, 4.5, 0.05);
  }
}

// ============================================================================
// 2. SPECIMEN DROP SHADOWS ON THE FLAT SIGNAL RED FIELD
// ============================================================================

function drawSpecimenDropShadows() {
  const step = 12;

  for (let side of [-1, 1]) {
    // Outer soft penumbra shadow (+8, +9 offset)
    let outerShadowPts = [];
    for (let y = TOP_Y; y <= BOT_Y; y += step) {
      let p = tapePoint(y, 0, side);
      outerShadowPts.push([p[0] + 8, p[1] + 9]);
    }
    for (let y = BOT_Y; y >= TOP_Y; y -= step) {
      let p = tapePoint(y, TAPE_W, side);
      outerShadowPts.push([p[0] + 8, p[1] + 9]);
    }
    washPoly(outerShadowPts, PAL.redShadow1, 165);

    // Tight contact shadow (+3.5, +4.5 offset)
    let tightShadowPts = [];
    for (let y = TOP_Y; y <= BOT_Y; y += step) {
      let p = tapePoint(y, 0, side);
      tightShadowPts.push([p[0] + 3.5, p[1] + 4.5]);
    }
    for (let y = BOT_Y; y >= TOP_Y; y -= step) {
      let p = tapePoint(y, TAPE_W, side);
      tightShadowPts.push([p[0] + 3.5, p[1] + 4.5]);
    }
    washPoly(tightShadowPts, PAL.redShadow2, 220);
  }

  // Dark recess shadow behind the locked teeth channel
  washPoly([
    [CX - 18, SPLIT_Y - 10],
    [CX + 18, SPLIT_Y - 10],
    [CX + 18, BOT_Y + 4],
    [CX - 18, BOT_Y + 4]
  ], PAL.navyVoid, 245);
}

// ============================================================================
// 3. HYPERREAL NAVY NYLON TAPES
// ============================================================================

function drawNavyNylonTapes() {
  const step = 10;

  for (let side of [-1, 1]) {
    // A. Base Navy Nylon Body Polygon
    let bodyPts = [];
    for (let y = TOP_Y; y <= BOT_Y; y += step) {
      bodyPts.push(tapePoint(y, 2, side));
    }
    for (let y = BOT_Y; y >= TOP_Y; y -= step) {
      // Subtle organic edge waviness on the outer selvedge
      let selvedgeWave = sin(y * 2.5 + side * 40) * 0.7;
      bodyPts.push(tapePoint(y, TAPE_W + selvedgeWave, side));
    }
    washPoly(bodyPts, PAL.navyBase, 255);

    // B. Darker Recessed Stitch Corridor (between d = 22 and d = 38)
    let stitchZonePts = [];
    for (let y = TOP_Y; y <= BOT_Y; y += step) {
      stitchZonePts.push(tapePoint(y, 22, side));
    }
    for (let y = BOT_Y; y >= TOP_Y; y -= step) {
      stitchZonePts.push(tapePoint(y, 38, side));
    }
    washPoly(stitchZonePts, PAL.navyDark, 230);

    // C. Outer Selvedge Band (between d = 116 and d = 134)
    let selvedgePts = [];
    for (let y = TOP_Y; y <= BOT_Y; y += step) {
      selvedgePts.push(tapePoint(y, 116, side));
    }
    for (let y = BOT_Y; y >= TOP_Y; y -= step) {
      selvedgePts.push(tapePoint(y, TAPE_W, side));
    }
    washPoly(selvedgePts, PAL.navyDark, 190);

    // D. Raised Cylindrical Inner Cord Bead (where teeth crimp onto the tape, d = 0..13)
    let cordBasePts = [];
    for (let y = TOP_Y; y <= BOT_Y; y += step) {
      cordBasePts.push(tapePoint(y, 0, side));
    }
    for (let y = BOT_Y; y >= TOP_Y; y -= step) {
      cordBasePts.push(tapePoint(y, 13, side));
    }
    washPoly(cordBasePts, PAL.navyDark, 255);

    // Highlight crest along the cylindrical cord bead (d = 2.5..7.5)
    let cordCrestPts = [];
    for (let y = TOP_Y; y <= BOT_Y; y += step) {
      cordCrestPts.push(tapePoint(y, 2.5, side));
    }
    for (let y = BOT_Y; y >= TOP_Y; y -= step) {
      cordCrestPts.push(tapePoint(y, 7.5, side));
    }
    washPoly(cordCrestPts, PAL.navyMid, 240);

    // Deep groove shadow right behind the cord bead (d = 12..15.5)
    let groovePts = [];
    for (let y = TOP_Y; y <= BOT_Y; y += step) {
      groovePts.push(tapePoint(y, 12, side));
    }
    for (let y = BOT_Y; y >= TOP_Y; y -= step) {
      groovePts.push(tapePoint(y, 15.5, side));
    }
    washPoly(groovePts, PAL.navyVoid, 235);

    // E. Microscopic Woven Twill / Herringbone Rib Texture
    for (let y = TOP_Y + 2; y <= BOT_Y - 2; y += 3.0) {
      let isHighlightRib = (Math.floor(y / 3.0) % 2 === 0);
      let ribCol = isHighlightRib ? PAL.navyMid : PAL.navyVoid;
      let ribWeight = isHighlightRib ? 0.34 : 0.28;

      // 1. Cord bead cross-wrapping threads
      let c1 = tapePoint(y, 0.8, side);
      let c2 = tapePoint(y + 1.2, 11.5, side);
      drawLine(c1[0], c1[1], c2[0], c2[1], "rotring", isHighlightRib ? PAL.navyLight : PAL.navyVoid, 0.28);

      // 2. Inner neck zone ribs (d = 15..24)
      let n1 = tapePoint(y, 15, side);
      let n2 = tapePoint(y, 24, side);
      drawLine(n1[0], n1[1], n2[0], n2[1], "rotring", ribCol, ribWeight);

      // 3. Main herringbone twill body (d = 38..115) — angled V-weave segments
      let chevronMidA = tapePoint(y + 1.8, 64, side);
      let chevronMidB = tapePoint(y - 0.4, 90, side);
      let bStart = tapePoint(y, 38, side);
      let bEnd = tapePoint(y + 1.2, 115, side);

      drawLine(bStart[0], bStart[1], chevronMidA[0], chevronMidA[1], "2H", ribCol, ribWeight * 1.15);
      drawLine(chevronMidA[0], chevronMidA[1], chevronMidB[0], chevronMidB[1], "2H", ribCol, ribWeight * 1.15);
      drawLine(chevronMidB[0], chevronMidB[1], bEnd[0], bEnd[1], "2H", ribCol, ribWeight * 1.15);

      // Occasional subtle sheen variation on the nylon ribs
      if (isHighlightRib && ((Math.floor(y) % 9) === 0)) {
        let s1 = tapePoint(y, 44, side);
        let s2 = tapePoint(y + 1.4, 62, side);
        drawLine(s1[0], s1[1], s2[0], s2[1], "rotring", PAL.navyLight, 0.24);
      }

      // 4. Outer selvedge tight horizontal weave (d = 117..133.5)
      let e1 = tapePoint(y, 117, side);
      let e2 = tapePoint(y, TAPE_W - 0.5, side);
      drawLine(e1[0], e1[1], e2[0], e2[1], "rotring", isHighlightRib ? PAL.navyLight : PAL.navyVoid, 0.3);
    }

    // F. Longitudinal Warp Lines & Double Chain-Stitching
    const warpDists = [13, 25, 37, 64, 90, 116, 124, 131];
    for (let d of warpDists) {
      let pts = [];
      for (let y = TOP_Y; y <= BOT_Y; y += 14) {
        pts.push(tapePoint(y, d, side));
      }
      strokePoly(pts, "rotring", PAL.navyVoid, 0.28, false, 0.2);
    }

    // Double industrial lock-stitch lines at d = 28.5 and d = 33.5
    for (let stitchD of [28.5, 33.5]) {
      for (let y = TOP_Y + 4; y <= BOT_Y - 6; y += 7.5) {
        let pA = tapePoint(y, stitchD, side);
        let pB = tapePoint(y + 4.8, stitchD, side);
        // Dark needle-hole shadow
        drawLine(pA[0], pA[1] - 0.8, pB[0], pB[1] + 0.8, "rotring", PAL.navyVoid, 0.52);
        // Raised nylon stitch thread highlight
        drawLine(pA[0], pA[1], pB[0], pB[1], "rotring", PAL.navyLight, 0.34);
        drawLine(pA[0] + side * 0.4, pA[1] + 0.5, pB[0] + side * 0.4, pB[1] - 0.5, "rotring", PAL.navyFray1, 0.2);
      }
    }
  }
}

// ============================================================================
// 4. FRAYED NYLON THREAD AT THE TAPE EDGES
// ============================================================================

function drawFrayedTapeEdges() {
  for (let side of [-1, 1]) {
    // A. Raw Cut Top Edge Fraying (y ≈ TOP_Y)
    for (let d = 2; d <= TAPE_W; d += 1.6) {
      let basePt = tapePoint(TOP_Y + random(-1.5, 1.5), d, side);
      let frayLen = random(7, 26) * (0.5 + 0.8 * noise(d * 0.12, side + 10));
      if (random() < 0.18) frayLen *= 1.85; // Occasional long unruly filament

      let ang = getTapeTangentDeg(TOP_Y, side) + 180 + random(-24, 24);
      let midX = basePt[0] + sin(ang) * (frayLen * 0.5) + random(-3.5, 3.5);
      let midY = basePt[1] + cos(ang) * (frayLen * 0.5);
      let tipX = basePt[0] + sin(ang) * frayLen + random(-8, 8);
      let tipY = basePt[1] + cos(ang) * frayLen;

      // Cast shadow of frayed filament onto the signal red ground
      drawSpline([
        [basePt[0] + 2, basePt[1] + 2],
        [midX + 2.5, midY + 2.5],
        [tipX + 3, tipY + 3]
      ], "rotring", PAL.redShadow2, 0.22, 0.6);

      // Filament stroke
      let col = random([PAL.navyDark, PAL.navyBase, PAL.navyMid, PAL.navyLight, PAL.navyFray1]);
      let w = random(0.18, 0.34);
      drawSpline([basePt, [midX, midY], [tipX, tipY]], "rotring", col, w, 0.65);
    }

    // Horizontal cross-weft threads unravelling & dangling near the top cut
    for (let i = 0; i < 9; i++) {
      let yOff = TOP_Y + random(-6, 5);
      let p1 = tapePoint(yOff, random(4, 35), side);
      let p2 = tapePoint(yOff + random(-4, 4), random(55, 100), side);
      let p3 = tapePoint(yOff + random(-8, 10), TAPE_W + random(8, 28), side);
      drawSpline([p1, p2, p3], "rotring", random([PAL.navyBase, PAL.navyLight, PAL.navyFray2]), 0.24, 0.7);
    }

    // B. Raw Cut Bottom Edge Fraying (y ≈ BOT_Y)
    for (let d = 2; d <= TAPE_W; d += 1.6) {
      let basePt = tapePoint(BOT_Y + random(-1.5, 1.5), d, side);
      let frayLen = random(8, 30) * (0.5 + 0.8 * noise(d * 0.15, side + 30));
      if (random() < 0.22) frayLen *= 1.9;

      let ang = random(-22, 22);
      let midX = basePt[0] + sin(ang) * (frayLen * 0.5) + random(-4, 4);
      let midY = basePt[1] + cos(ang) * (frayLen * 0.5);
      let tipX = basePt[0] + sin(ang) * frayLen + random(-9, 9);
      let tipY = basePt[1] + cos(ang) * frayLen;

      drawSpline([
        [basePt[0] + 2, basePt[1] + 2],
        [midX + 2.5, midY + 2.5],
        [tipX + 3, tipY + 3]
      ], "rotring", PAL.redShadow2, 0.22, 0.6);

      let col = random([PAL.navyDark, PAL.navyBase, PAL.navyMid, PAL.navyLight, PAL.navyFray1, PAL.navyFray2]);
      drawSpline([basePt, [midX, midY], [tipX, tipY]], "rotring", col, random(0.18, 0.34), 0.65);
    }

    // Horizontal loose weft threads at bottom cut
    for (let i = 0; i < 10; i++) {
      let yOff = BOT_Y + random(-4, 8);
      let p1 = tapePoint(yOff, random(5, 45), side);
      let p2 = tapePoint(yOff + random(-5, 6), random(60, 110), side);
      let p3 = tapePoint(yOff + random(-8, 14), TAPE_W + random(10, 32), side);
      drawSpline([p1, p2, p3], "rotring", random([PAL.navyBase, PAL.navyLight, PAL.navyFray1]), 0.24, 0.7);
    }

    // C. Outer Selvedge Edge Micro-Fraying & Broken Loops along the entire length
    for (let y = TOP_Y + 8; y <= BOT_Y - 8; y += random(5, 13)) {
      let pBase = tapePoint(y, TAPE_W - 1, side);
      let isLongFray = (random() < 0.28);
      let outDist = isLongFray ? random(10, 28) : random(3.5, 9);
      let yDrift = random(-14, 18);

      let pMid = tapePoint(y + yDrift * 0.45, TAPE_W + outDist * 0.55, side);
      let pTip = [
        pBase[0] + side * outDist + random(-3, 3),
        pBase[1] + yDrift
      ];

      // Tiny shadow on red field
      drawSpline([
        [pBase[0] + 1.5, pBase[1] + 1.5],
        [pMid[0] + 2, pMid[1] + 2],
        [pTip[0] + 2.5, pTip[1] + 2.5]
      ], "rotring", PAL.redShadow2, 0.18, 0.6);

      let col = isLongFray
        ? random([PAL.navyMid, PAL.navyLight, PAL.navyFray1, PAL.navyFray2])
        : random([PAL.navyDark, PAL.navyBase, PAL.navyMid]);
      drawSpline([pBase, pMid, pTip], "rotring", col, isLongFray ? 0.22 : 0.26, 0.65);

      // Occasional tiny closed loop of snagged selvedge thread
      if (random() < 0.35) {
        let pLoopBack = tapePoint(y + random(3, 6), TAPE_W - 1, side);
        drawSpline([pBase, pMid, pLoopBack], "rotring", PAL.navyMid, 0.22, 0.75);
      }
    }
  }
}

// ============================================================================
// 5. CRISP FINE-PEN INTERLOCKING & OPEN BRASS TEETH
// ============================================================================

function drawAllBrassTeeth() {
  // A. Closed Interlocking Teeth Run (below the slider: y = 668 down to 992)
  const pitch = 6.2; // Vertical spacing between alternating left/right teeth
  let idx = 0;
  for (let y = 668; y <= 992; y += pitch) {
    let side = (idx % 2 === 0) ? -1 : 1;
    drawLockedBrassTooth(y, side);
    idx++;
  }

  // B. Heavy Crimped Brass Bottom Stop (at y = 996..1016)
  drawBrassBottomStop(996);

  // C. Disengaged Open Brass Teeth (above the slider: y = 590 up to 388)
  for (let side of [-1, 1]) {
    for (let y = 586; y >= 390; y -= 12.2) {
      drawOpenBrassTooth(y, side);
    }
    // Top Stop lug crimped onto each cord above the last tooth
    drawBrassTopStop(376, side);
  }
}

function drawLockedBrassTooth(y, side) {
  // Each tooth reaches from its crimped shoulder on `side` across the centerline `CX`
  let shoulderX = CX + side * 21.5;
  let cordEdgeX = CX + side * 11.5;
  let headTipX  = CX - side * 6.8;
  let neckH = 3.6;
  let headH = 4.6;

  // 1. Dark cast shadow underneath the tooth onto the navy cord and recess
  washPoly([
    [shoulderX, y - neckH + 1.5],
    [headTipX - side * 1.2, y - headH + 1.5],
    [headTipX - side * 1.2, y + headH + 2.2],
    [shoulderX, y + neckH + 2.2]
  ], PAL.navyVoid, 230);

  // 2. Main Brass Tooth Silhouette (Base bronze-ochre tone)
  let toothPoly = [
    [shoulderX, y - neckH],
    [cordEdgeX, y - neckH],
    [CX + side * 2.0, y - neckH * 0.82],
    [CX - side * 1.5, y - headH],
    [headTipX, y - headH * 0.65],
    [headTipX, y + headH * 0.65],
    [CX - side * 1.5, y + headH],
    [CX + side * 2.0, y + neckH * 0.82],
    [cordEdgeX, y + neckH],
    [shoulderX, y + neckH]
  ];
  washPoly(toothPoly, PAL.brassM2, 255);

  // 3. Lower Bevel Shadow Plane (Dark umber bronze)
  washPoly([
    [shoulderX, y + 0.6],
    [headTipX, y + 0.6],
    [headTipX, y + headH * 0.65],
    [CX - side * 1.5, y + headH],
    [shoulderX, y + neckH]
  ], PAL.brassD2, 245);

  // 4. Upper Bevel Highlight Plane (Polished warm gold)
  washPoly([
    [shoulderX + side * -1.0, y - neckH + 0.5],
    [cordEdgeX, y - neckH + 0.5],
    [CX - side * 1.5, y - headH + 0.6],
    [headTipX, y - headH * 0.5],
    [headTipX, y - 0.3],
    [shoulderX + side * -1.0, y - 0.3]
  ], PAL.brassL2, 250);

  // 5. Specular Glint on the Rounded Interlocking Head & Crimp Shoulder
  drawLine(
    CX - side * 1.0, y - headH * 0.55,
    headTipX + side * 1.2, y - headH * 0.45,
    "rotring", PAL.brassRim, 0.38
  );
  drawLine(
    shoulderX - side * 1.5, y - neckH * 0.55,
    cordEdgeX + side * 1.5, y - neckH * 0.55,
    "rotring", PAL.brassL3, 0.34
  );

  // 6. Stamped Central Locking Dimple on the Tooth Crown
  let dimpleX = CX - side * 2.2;
  washPoly([
    [dimpleX - 1.6, y - 1.3],
    [dimpleX + 1.6, y - 1.3],
    [dimpleX + 1.6, y + 1.3],
    [dimpleX - 1.6, y + 1.3]
  ], PAL.brassD1, 240);
  drawLine(dimpleX - 1.4, y + 1.4, dimpleX + 1.4, y + 1.4, "rotring", PAL.brassL3, 0.25);

  // 7. Crisp Fine-Pen Mechanical Outline
  strokePoly(toothPoly, "rotring", PAL.brassVoid, 0.3, true, 0.08);
}

function drawOpenBrassTooth(y, side) {
  // Position and orient tooth perpendicular to the curving inner cord edge
  let base = tapePoint(y, 8.5, side); // Crimped on cord
  let ang = getTapeTangentDeg(y, side);

  // Unit vector pointing INWARD toward the zipper centerline
  let ix = -side * cos(ang);
  let iy = side * sin(ang);
  // Unit vector pointing DOWN along the tape tangent
  let tx = sin(ang);
  let ty = cos(ang);

  function localPt(inwardDist, tangentDist) {
    return [
      base[0] + ix * inwardDist + tx * tangentDist,
      base[1] + iy * inwardDist + ty * tangentDist
    ];
  }

  // Drop shadow on red/cord
  washPoly([
    localPt(-1.5, -3.2),
    localPt(16.5, -3.8),
    localPt(16.5, 5.2),
    localPt(-1.5, 4.8)
  ], PAL.redShadow2, 210);

  // Tooth profile with interlocking protrusion bump on top and hollow pocket underneath
  let toothPts = [
    localPt(0, -3.6),     // Outer shoulder top
    localPt(8.5, -3.5),   // Neck top
    localPt(11.5, -5.2),  // Locking scoop crown top (protruding bump)
    localPt(15.2, -3.8),  // Nose upper chamfer
    localPt(16.0, 0.0),   // Nose tip
    localPt(14.8, 3.6),   // Nose lower chamfer
    localPt(11.0, 2.4),   // Locking scoop underside hollow
    localPt(8.5, 3.6),    // Neck bottom
    localPt(0, 3.6)       // Outer shoulder bottom
  ];
  washPoly(toothPts, PAL.brassM2, 255);

  // Lower dark bronze bevel
  washPoly([
    localPt(0, 0.4),
    localPt(15.5, 0.4),
    localPt(14.8, 3.6),
    localPt(11.0, 2.4),
    localPt(8.5, 3.6),
    localPt(0, 3.6)
  ], PAL.brassD2, 245);

  // Upper bright brass bevel
  washPoly([
    localPt(0.5, -3.1),
    localPt(8.5, -3.0),
    localPt(11.5, -4.6),
    localPt(15.0, -3.2),
    localPt(15.2, -0.4),
    localPt(0.5, -0.4)
  ], PAL.brassL2, 250);

  // Stamped dimple & specular glint
  let d1 = localPt(10.5, -1.2);
  let d2 = localPt(13.2, -1.2);
  drawLine(d1[0], d1[1], d2[0], d2[1], "rotring", PAL.brassD1, 0.48);

  let s1 = localPt(1.2, -2.2);
  let s2 = localPt(14.2, -2.5);
  drawLine(s1[0], s1[1], s2[0], s2[1], "rotring", PAL.brassRim, 0.34);

  // Crisp fine-pen outline
  strokePoly(toothPts, "rotring", PAL.brassVoid, 0.3, true, 0.08);
}

function drawBrassBottomStop(y) {
  let xL = CX - 23;
  let xR = CX + 23;
  let h = 18;

  // Shadow
  washPoly([[xL + 2, y + 2], [xR + 3, y + 2], [xR + 3, y + h + 4], [xL + 2, y + h + 4]], PAL.navyVoid, 245);

  // Base block with notched top/bottom corners
  let stopPts = [
    [xL + 3, y], [xR - 3, y],
    [xR, y + 3], [xR, y + h - 3],
    [xR - 3, y + h], [xL + 3, y + h],
    [xL, y + h - 3], [xL, y + 3]
  ];
  washPoly(stopPts, PAL.brassM1, 255);

  // Metallic gradient bands across the bottom stop
  washPoly([[xL + 2, y + 2], [xR - 2, y + 2], [xR - 2, y + 7], [xL + 2, y + 7]], PAL.brassL2, 250);
  washPoly([[xL + 2, y + 7], [xR - 2, y + 7], [xR - 2, y + 12], [xL + 2, y + 12]], PAL.brassD2, 245);
  washPoly([[xL + 2, y + 12], [xR - 2, y + 12], [xR - 2, y + h - 2], [xL + 2, y + h - 2]], PAL.brassM3, 250);

  // Vertical crimp grooves on left and right legs
  drawLine(CX - 13, y + 2, CX - 13, y + h - 2, "rotring", PAL.brassVoid, 0.42);
  drawLine(CX + 13, y + 2, CX + 13, y + h - 2, "rotring", PAL.brassVoid, 0.42);
  drawLine(xL + 4, y + 3.5, xR - 4, y + 3.5, "rotring", PAL.brassRim, 0.4);

  strokePoly(stopPts, "rotring", PAL.brassVoid, 0.38, true, 0.05);
}

function drawBrassTopStop(y, side) {
  let p1 = tapePoint(y - 7, -1, side);
  let p2 = tapePoint(y - 7, 13, side);
  let p3 = tapePoint(y + 7, 13, side);
  let p4 = tapePoint(y + 7, -1, side);
  washPoly([p1, p2, p3, p4], PAL.brassM2, 255);

  let h1 = tapePoint(y - 5, 1, side);
  let h2 = tapePoint(y - 5, 11, side);
  let h3 = tapePoint(y, 11, side);
  let h4 = tapePoint(y, 1, side);
  washPoly([h1, h2, h3, h4], PAL.brassL2, 250);

  strokePoly([p1, p2, p3, p4], "rotring", PAL.brassVoid, 0.35, true, 0.05);
}

// ============================================================================
// 6. MARKER-SHADED SCRATCHED BRASS SLIDER & PULL TAB + PINPOINT REFLECTION
// ============================================================================

function drawBrassSliderAndPull() {
  // --------------------------------------------------------------------------
  // PART A: CAST SHADOW OF SLIDER & HANGING PULL TAB ONTO TAPE & TEETH
  // --------------------------------------------------------------------------
  // Slider body cast shadow
  washPoly([
    [CX - 50, SLIDER_Y - 52],
    [CX + 62, SLIDER_Y - 52],
    [CX + 48, SLIDER_Y + 68],
    [CX - 36, SLIDER_Y + 68]
  ], PAL.navyVoid, 225);

  // Pull tab cast shadow (offset down-right onto the locked teeth & right navy tape)
  washPoly([
    [CX - 22, SLIDER_Y + 55],
    [CX + 56, SLIDER_Y + 55],
    [CX + 54, SLIDER_Y + 252],
    [CX - 36, SLIDER_Y + 252]
  ], PAL.navyVoid, 215);

  washPoly([
    [CX - 28, SLIDER_Y + 60],
    [CX + 48, SLIDER_Y + 60],
    [CX + 46, SLIDER_Y + 244],
    [CX - 40, SLIDER_Y + 244]
  ], PAL.navyVoid, 245);

  // --------------------------------------------------------------------------
  // PART B: SLIDER BODY (Y-SHAPED SHIELD WITH RAISED SIDE FLANGES)
  // --------------------------------------------------------------------------
  const sTop = SLIDER_Y - 58; // 567
  const sBot = SLIDER_Y + 56; // 681

  function sliderHalfWidth(y) {
    let t = constrain((y - sTop) / (sBot - sTop), 0, 1);
    if (t < 0.12) {
      // Rounded top shoulders
      return map(t, 0, 0.12, 42, 54);
    } else if (t < 0.48) {
      // Wide upper throat tapering inward
      return map(t, 0.12, 0.48, 54, 41);
    } else if (t < 0.88) {
      // Lower straight-tapered trunk
      return map(t, 0.48, 0.88, 41, 36);
    } else {
      // Rounded bottom exit lip
      return map(t, 0.88, 1.0, 36, 26);
    }
  }

  // Dark throat interiors at top-left and top-right where open teeth enter
  washPoly([
    [CX - 46, sTop + 2], [CX - 14, sTop + 2],
    [CX - 14, sTop + 18], [CX - 48, sTop + 18]
  ], PAL.brassVoid, 255);
  washPoly([
    [CX + 14, sTop + 2], [CX + 46, sTop + 2],
    [CX + 48, sTop + 18], [CX + 14, sTop + 18]
  ], PAL.brassVoid, 255);

  // Marker-shaded horizontal & angled metallic gradient bands on Slider Body
  const sliderPalette = [
    PAL.brassL2, PAL.brassL3, PAL.brassL1, PAL.brassM2,
    PAL.brassD2, PAL.brassD1, PAL.brassD2, PAL.brassM1,
    PAL.brassM3, PAL.brassL1, PAL.brassL3, PAL.brassL2,
    PAL.brassM3, PAL.brassM1, PAL.brassD1, PAL.brassD2,
    PAL.brassM2, PAL.brassL1, PAL.brassM1, PAL.brassD2
  ];

  let numSlices = sliderPalette.length;
  let sliceH = (sBot - sTop) / numSlices;

  for (let i = 0; i < numSlices; i++) {
    let y1 = sTop + i * sliceH;
    let y2 = y1 + sliceH + 0.8;
    let hw1 = sliderHalfWidth(y1);
    let hw2 = sliderHalfWidth(y2);
    let col = sliderPalette[i];

    let bandPts = [
      [CX - hw1, y1],
      [CX + hw1, y1],
      [CX + hw2, y2],
      [CX - hw2, y2]
    ];
    washPoly(bandPts, col, 250);

    // Genuine marker stroke pass across the metallic plane
    drawLine(CX - hw1 + 3, (y1 + y2) * 0.5, CX + hw1 - 3, (y1 + y2) * 0.5, "marker", col, 0.45);
  }

  // Raised Left & Right Guide Flange Rims (6px wide metallic bevels along slider sides)
  for (let side of [-1, 1]) {
    let outerRim = [];
    let innerRim = [];
    for (let y = sTop + 6; y <= sBot - 6; y += 6) {
      let hw = sliderHalfWidth(y);
      outerRim.push([CX + side * hw, y]);
      innerRim.push([CX + side * (hw - 6.5), y]);
    }
    let flangePoly = outerRim.concat(innerRim.slice().reverse());
    washPoly(flangePoly, side === -1 ? PAL.brassL2 : PAL.brassD2, 235);

    // Specular inner step line of the flange
    strokePoly(innerRim, "rotring", side === -1 ? PAL.brassVoid : PAL.brassL3, 0.35, false, 0.2);
    strokePoly(outerRim, "rotring", side === -1 ? PAL.brassRim : PAL.brassL1, 0.38, false, 0.2);
  }

  // Top center wedge / splitter diamond detail at the top of the slider
  washPoly([
    [CX - 15, sTop], [CX + 15, sTop],
    [CX + 9, sTop + 22], [CX - 9, sTop + 22]
  ], PAL.brassM3, 250);
  drawLine(CX - 13, sTop + 2.5, CX + 13, sTop + 2.5, "rotring", PAL.brassRim, 0.45);

  // Full crisp fine-pen outline of the Slider Body
  let sliderOutline = [];
  for (let y = sTop; y <= sBot; y += 5) {
    sliderOutline.push([CX - sliderHalfWidth(y), y]);
  }
  for (let y = sBot; y >= sTop; y -= 5) {
    sliderOutline.push([CX + sliderHalfWidth(y), y]);
  }
  strokePoly(sliderOutline, "rotring", PAL.brassVoid, 0.45, true, 0.15);

  // Scratches on Slider Body
  for (let i = 0; i < 45; i++) {
    let sy = random(sTop + 8, sBot - 8);
    let hw = sliderHalfWidth(sy) - 8;
    let sx = CX + random(-hw, hw);
    let sLen = random(6, 22);
    let sAng = random(-25, 25);
    let isLight = random() < 0.55;
    drawLine(
      sx, sy,
      sx + cos(sAng) * sLen, sy + sin(sAng) * sLen,
      "rotring", isLight ? PAL.brassRim : PAL.brassVoid, random(0.16, 0.28)
    );
  }

  // --------------------------------------------------------------------------
  // PART C: HANGING BRASS PULL TAB (WITH RECESSED STAMPING & MARKER SHADING)
  // --------------------------------------------------------------------------
  // Pivot slightly by -2.2 degrees around the bridge hinge (CX, SLIDER_Y + 26)
  const pivotX = CX;
  const pivotY = SLIDER_Y + 26; // 651
  const pullAngle = -2.2;

  function pullPt(lx, ly) {
    let rx = lx * cos(pullAngle) - ly * sin(pullAngle);
    let ry = lx * sin(pullAngle) + ly * cos(pullAngle);
    return [pivotX + rx, pivotY + ry];
  }

  // Pull tab local y spans from ly = -14 (top of ring) to ly = +194 (bottom of paddle)
  const pTop = -14;
  const pBot = 194;

  function pullHalfWidth(ly) {
    if (ly < 28) {
      // Narrow top hinge neck
      return map(ly, -14, 28, 19, 23);
    } else if (ly < 54) {
      // Flaring bevel shoulders
      return map(ly, 28, 54, 23, 45);
    } else if (ly < 182) {
      // Main paddle body (subtle architectural taper from 45 to 41)
      return map(ly, 54, 182, 45, 41);
    } else {
      // Chamfered bottom corners
      return map(ly, 182, 194, 41, 31);
    }
  }

  // 1. Outer Bevel Under-Layer (Dark bronze base for the whole pull tab)
  let pullOuterPts = [];
  for (let ly = pTop; ly <= pBot; ly += 4) {
    pullOuterPts.push(pullPt(-pullHalfWidth(ly), ly));
  }
  for (let ly = pBot; ly >= pTop; ly -= 4) {
    pullOuterPts.push(pullPt(pullHalfWidth(ly), ly));
  }
  washPoly(pullOuterPts, PAL.brassD1, 255);

  // 2. Multi-Band Marker-Shaded Metallic Gradient across the Pull Tab Face
  const pullGradient = [
    PAL.brassM1, PAL.brassM3, PAL.brassL2, PAL.brassL3, // Hinge loop catch-light
    PAL.brassM2, PAL.brassD2, PAL.brassVoid, PAL.brassD1, // Deep shadow under bridge
    PAL.brassM1, PAL.brassM3, PAL.brassL2, PAL.brassL3, // Shoulder bright zone
    PAL.brassRim, PAL.brassL3, PAL.brassL2, PAL.brassL1, // High-key specular band
    PAL.brassM3, PAL.brassM2, PAL.brassM1, PAL.brassD2, // Mid-paddle transition
    PAL.brassD1, PAL.brassVoid, PAL.brassD1, PAL.brassD2, // Dark horizon core reflection
    PAL.brassM1, PAL.brassM2, PAL.brassM3, PAL.brassL1, // Lower warm gold recovery
    PAL.brassL2, PAL.brassL3, PAL.brassL1, PAL.brassM2, // Bottom kick-light
    PAL.brassM1, PAL.brassD2
  ];

  let pSlices = pullGradient.length;
  let pStep = (pBot - pTop) / pSlices;

  for (let i = 0; i < pSlices; i++) {
    let ly1 = pTop + i * pStep;
    let ly2 = ly1 + pStep + 0.9;
    let hw1 = pullHalfWidth(ly1);
    let hw2 = pullHalfWidth(ly2);
    let col = pullGradient[i];

    // Slight diagonal slant (+8px across width) for natural metallic reflection
    let band = [
      pullPt(-hw1, ly1 - 3),
      pullPt(hw1, ly1 + 4),
      pullPt(hw2, ly2 + 4),
      pullPt(-hw2, ly2 - 3)
    ];
    washPoly(band, col, 250);

    // Marker stroke texture along the diagonal reflection plane
    let mLeft = pullPt(-hw1 + 3, (ly1 + ly2) * 0.5 - 2.5);
    let mRight = pullPt(hw1 - 3, (ly1 + ly2) * 0.5 + 3.5);
    drawLine(mLeft[0], mLeft[1], mRight[0], mRight[1], "marker", col, 0.5);
  }

  // 3. 3D Perimeter Chamfer Bevels on the Pull Tab
  const bevelW = 5.5;
  // Left bright gold chamfer
  let leftBevel = [];
  for (let ly = 28; ly <= 184; ly += 6) leftBevel.push(pullPt(-pullHalfWidth(ly), ly));
  for (let ly = 184; ly >= 28; ly -= 6) leftBevel.push(pullPt(-pullHalfWidth(ly) + bevelW, ly));
  washPoly(leftBevel, PAL.brassL3, 235);

  // Right dark umber chamfer
  let rightBevel = [];
  for (let ly = 28; ly <= 184; ly += 6) rightBevel.push(pullPt(pullHalfWidth(ly) - bevelW, ly));
  for (let ly = 184; ly >= 28; ly -= 6) rightBevel.push(pullPt(pullHalfWidth(ly), ly));
  washPoly(rightBevel, PAL.brassD1, 235);

  // Bottom chamfer
  washPoly([
    pullPt(-38, 184), pullPt(38, 184),
    pullPt(31, 194), pullPt(-31, 194)
  ], PAL.brassD2, 245);

  // 4. Stamped Rectangular Hinge Slot Cutout (Revealing the Slider Body & Teeth underneath!)
  let slotPts = [
    pullPt(-12.5, -2),
    pullPt(12.5, -2),
    pullPt(12.5, 24),
    pullPt(-12.5, 24)
  ];
  washPoly(slotPts, PAL.brassVoid, 255);
  // Inner thickness rim of the punched slot
  washPoly([
    pullPt(-12.5, 20), pullPt(12.5, 20),
    pullPt(12.5, 24), pullPt(-12.5, 24)
  ], PAL.brassL2, 245);
  strokePoly(slotPts, "rotring", PAL.brassVoid, 0.42, true, 0);

  // 5. Recessed Stamped Well on the Pull Tab Paddle (ly = 62 to 174)
  let wellPts = [
    pullPt(-27, 62),
    pullPt(27, 62),
    pullPt(25, 174),
    pullPt(-25, 174)
  ];
  // Slight darkening inside the recessed well
  washPoly(wellPts, PAL.brassD2, 95);

  // Top & Left recessed step shadow
  strokePoly([
    pullPt(-25, 174), pullPt(-27, 62), pullPt(27, 62)
  ], "rotring", PAL.brassVoid, 0.55, false, 0);

  // Bottom & Right recessed catch-light rim
  strokePoly([
    pullPt(27, 62), pullPt(25, 174), pullPt(-25, 174)
  ], "rotring", PAL.brassRim, 0.45, false, 0);

  // Embossed Tactile Grip Ridges & Stamped Industrial Mark inside the Well
  for (let ry of [138, 150, 162]) {
    let rL = pullPt(-18, ry);
    let rR = pullPt(18, ry);
    let rL2 = pullPt(-18, ry + 2.4);
    let rR2 = pullPt(18, ry + 2.4);
    drawLine(rL[0], rL[1], rR[0], rR[1], "rotring", PAL.brassRim, 0.42);
    drawLine(rL2[0], rL2[1], rR2[0], rR2[1], "rotring", PAL.brassVoid, 0.45);
  }

  // Stamped geometric numeral/grade emblem in upper well (ly = 84..116)
  let embPts = [
    pullPt(-12, 82), pullPt(12, 82),
    pullPt(12, 114), pullPt(-12, 114)
  ];
  strokePoly(embPts, "rotring", PAL.brassVoid, 0.35, true, 0);
  // Crisp debossed "5" inside the stamping box
  let num5 = [
    pullPt(6, 88), pullPt(-6, 88), pullPt(-6, 98),
    pullPt(5, 98), pullPt(6, 102), pullPt(5, 108),
    pullPt(-5, 108), pullPt(-6, 105)
  ];
  strokePoly(num5, "rotring", PAL.brassVoid, 0.52, false, 0.1);
  // Offset specular rim on the stamped "5"
  let num5Hi = num5.map(p => [p[0] + 0.9, p[1] + 0.9]);
  strokePoly(num5Hi, "rotring", PAL.brassL3, 0.3, false, 0.1);

  // --------------------------------------------------------------------------
  // PART D: SLIDER CROWN / NOSE BRIDGE (ARCHING OVER THE PULL TAB RING)
  // --------------------------------------------------------------------------
  // The raised central bridge loops from (CX, sTop + 16) down through the pull tab's slot to (CX, sBot - 10)
  const bTop = sTop + 16;
  const bBot = sBot - 10;
  const bHalfW = 10.5;

  // Ambient occlusion shadow on either side of the bridge
  washPoly([
    [CX - bHalfW - 4, bTop + 4], [CX + bHalfW + 4, bTop + 4],
    [CX + bHalfW + 4, bBot + 3], [CX - bHalfW - 4, bBot + 3]
  ], PAL.brassVoid, 220);

  // Bridge metallic reflection bands (high-arch cylinder shading)
  const bridgeColors = [
    PAL.brassD1, PAL.brassM2, PAL.brassL2, PAL.brassRim,
    PAL.specular, PAL.brassL3, PAL.brassM3, PAL.brassD2,
    PAL.brassVoid, PAL.brassD1, PAL.brassM2, PAL.brassL2,
    PAL.brassL3, PAL.brassM2, PAL.brassD1
  ];
  let bStep = (bBot - bTop) / bridgeColors.length;
  for (let i = 0; i < bridgeColors.length; i++) {
    let by1 = bTop + i * bStep;
    let by2 = by1 + bStep + 0.6;
    washPoly([
      [CX - bHalfW, by1], [CX + bHalfW, by1],
      [CX + bHalfW, by2], [CX - bHalfW, by2]
    ], bridgeColors[i], 255);
  }

  // Side bevel highlights on the bridge arch
  drawLine(CX - bHalfW + 1.5, bTop + 2, CX - bHalfW + 1.5, bBot - 2, "rotring", PAL.brassRim, 0.38);
  drawLine(CX + bHalfW - 1.5, bTop + 2, CX + bHalfW - 1.5, bBot - 2, "rotring", PAL.brassD1, 0.38);
  strokePoly([
    [CX - bHalfW, bTop], [CX + bHalfW, bTop],
    [CX + bHalfW, bBot], [CX - bHalfW, bBot]
  ], "rotring", PAL.brassVoid, 0.45, true, 0.08);

  // --------------------------------------------------------------------------
  // PART E: MICROSCOPIC SURFACE SCRATCHES & WEAR ON THE PULL TAB
  // --------------------------------------------------------------------------
  // Crisp outer perimeter outline of the Pull Tab (drawn up to the bridge overlap)
  strokePoly(pullOuterPts, "rotring", PAL.brassVoid, 0.46, true, 0.06);

  // Inner bevel boundary line
  let innerBevelRing = [];
  for (let ly = 28; ly <= 184; ly += 8) innerBevelRing.push(pullPt(-pullHalfWidth(ly) + bevelW, ly));
  for (let ly = 184; ly >= 28; ly -= 8) innerBevelRing.push(pullPt(pullHalfWidth(ly) - bevelW, ly));
  strokePoly(innerBevelRing, "rotring", PAL.brassM1, 0.28, true, 0.05);

  // 160 fine hairline scratches across the marker-shaded brass paddle
  for (let i = 0; i < 160; i++) {
    let ly = random(28, 188);
    let maxW = pullHalfWidth(ly) - 4;
    let lx = random(-maxW, maxW);
    let len = random(5, 34);
    if (random() < 0.15) len = random(35, 58); // Long diagonal pocket-wear scratch

    let ang = random(-65, 75);
    let p1 = pullPt(lx, ly);
    let p2 = pullPt(
      constrain(lx + cos(ang) * len, -maxW, maxW),
      constrain(ly + sin(ang) * len, 26, 190)
    );

    // Bright catch-light scratch or dark oxidized gouge
    let isBright = random() < 0.58;
    let scratchCol = isBright
      ? (random() < 0.4 ? PAL.specular : PAL.brassRim)
      : (random() < 0.5 ? PAL.brassVoid : PAL.brassD1);
    let scratchW = random(0.15, 0.30);

    drawLine(p1[0], p1[1], p2[0], p2[1], "rotring", scratchCol, scratchW);

    // Paired shadow/highlight micro-ridge on deeper gouges
    if (len > 26 && random() < 0.5) {
      drawLine(
        p1[0] + 0.7, p1[1] + 0.7,
        p2[0] + 0.7, p2[1] + 0.7,
        "rotring", isBright ? PAL.brassD1 : PAL.brassL3, 0.18
      );
    }
  }

  // Tiny edge nicks along the left bevel shoulder
  for (let ly = 42; ly <= 175; ly += random(9, 22)) {
    let hw = pullHalfWidth(ly);
    let n1 = pullPt(-hw, ly);
    let n2 = pullPt(-hw + random(2.5, 5.5), ly + random(-1.5, 2.0));
    drawLine(n1[0], n1[1], n2[0], n2[1], "rotring", PAL.brassRim, 0.32);
  }

  // --------------------------------------------------------------------------
  // PART F: THE PINPOINT SPECULAR REFLECTION
  // --------------------------------------------------------------------------
  // Primary pinpoint reflection at the upper-left bevel apex of the pull tab shoulder
  let specPos = pullPt(-pullHalfWidth(54) + 3.5, 54);
  drawPinpointReflection(specPos[0], specPos[1], 1.0);

  // Secondary smaller pinpoint glint on the apex of the slider crown bridge
  drawPinpointReflection(CX - 3.5, bTop + 18, 0.58);
}

function drawPinpointReflection(x, y, scaleFactor) {
  // 1. Warm golden optical bloom around the pinpoint
  let r1 = 15 * scaleFactor;
  let bloom1 = [];
  for (let a = 0; a < 360; a += 30) {
    bloom1.push([x + cos(a) * r1, y + sin(a) * r1]);
  }
  washPoly(bloom1, PAL.brassL3, 125);

  // 2. Tighter high-key cream halo
  let r2 = 8.5 * scaleFactor;
  let bloom2 = [];
  for (let a = 0; a < 360; a += 30) {
    bloom2.push([x + cos(a) * r2, y + sin(a) * r2]);
  }
  washPoly(bloom2, PAL.brassRim, 215);

  // 3. Intense pure white diamond-circle pinpoint core
  let rCore = 4.2 * scaleFactor;
  let corePts = [];
  for (let a = 0; a < 360; a += 45) {
    let rad = (a % 90 === 0) ? rCore * 1.35 : rCore * 0.75;
    corePts.push([x + cos(a) * rad, y + sin(a) * rad]);
  }
  washPoly(corePts, PAL.specular, 255);

  // 4. Razor-sharp optical diffraction rays
  const rayAngles = [0, 90, 32, 122, -45, 45];
  const rayLengths = [26, 24, 15, 14, 10, 10];
  for (let i = 0; i < rayAngles.length; i++) {
    let ang = rayAngles[i];
    let len = rayLengths[i] * scaleFactor;
    let w = (i < 2) ? 0.42 : 0.25;
    drawLine(
      x - cos(ang) * len, y - sin(ang) * len,
      x + cos(ang) * len, y + sin(ang) * len,
      "rotring", PAL.specular, w
    );
  }

  // Final intense center dot
  brush.noWash();
  brush.set("rotring", PAL.specular, 0.65 * scaleFactor);
  brush.circle(x, y, 2.0 * scaleFactor, 0.02);
}

// Hyperreal Winter Dusk at a Rural Railway Crossing
// p5.js 2.x + p5.brush in WEBGL mode

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  brush.scaleBrushes(3);

  // Custom fine technical nib for hyperreal metal & paint micro-details
  brush.add("techNib", {
    type: "default",
    weight: 0.35,
    scatter: 0.02,
    sharpness: 0.92,
    grain: 0.15,
    opacity: 235,
    spacing: 0.15,
    pressure: [0.85, 1.0, 0.85],
    noise: 0.15
  });

  // Custom frost & snow crust stipple brush
  brush.add("frostStipple", {
    type: "spray",
    weight: 0.8,
    scatter: 1.4,
    opacity: 190,
    spacing: 0.4,
    pressure: [0.6, 1.2, 0.6]
  });

  randomSeed(7482);
  noiseSeed(7482);
}

// Track centerline helper (gentle diagonal across the midground)
function trackY(x) {
  return 716 - 0.072 * x;
}

// Helper for drawing closed polygons with p5.brush native shape pipeline
function drawShapePoly(pts, curvature = 0, closeShape = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closeShape);
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm mulberry / cotton watercolor paper ground
  background("#fcf8f0");

  // Initialize default brush state so stroke state is always valid
  brush.set("rotring", "#11161d", 0.35);
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  // 1. Smooth graded sky wash (Bokashi from Prussian Blue to Soft Peach)
  drawSkyWash();

  // 2. Distant mountains, winter cedar forest & wayside structures
  drawDistantHorizon();

  // 3. Crisp layered watercolor snow planes, road & railway embankment
  drawSnowLandscapeAndRoad();

  // 4. Railway ballast, wooden sleepers, crossing planks & steel rails
  drawRailwayTrack();

  // 5. Telegraph poles, overhead catenary wires & lowered crossing barrier
  drawCrossingInfrastructure();

  // 6. Tire rut and solitary boot footprints in the fresh snow
  drawTireTrackAndFootprints();

  // 7. Foreground winter reeds & snow bank details behind bicycle
  drawBackgroundReedsAndDrifts();

  // 8. The parked black bicycle (hyperreal focal subject)
  drawParkedBicycle();

  // 9. Foreground snow crust overlap & tiny reserved falling snow flecks
  drawFallingSnowAndForegroundDetails();

  noLoop();
}

// ============================================================================
// 1. SKY GRADED WASH (PRUSSIAN BLUE TO SOFT PEACH)
// ============================================================================
function drawSkyWash() {
  const stops = [
    { y: 0, col: color("#061325") },   // Deepest Prussian zenith
    { y: 85, col: color("#0b213d") },  // Rich Prussian blue
    { y: 175, col: color("#143659") }, // Mid Prussian twilight
    { y: 265, col: color("#264f73") }, // Steel Prussian
    { y: 345, col: color("#466985") }, // Muted slate blue
    { y: 410, col: color("#787f8e") }, // Dusk lavender-slate transition
    { y: 465, col: color("#b68f88") }, // Warm rose-grey dusk
    { y: 510, col: color("#e3ac90") }, // Soft winter peach
    { y: 550, col: color("#f7c9a6") }, // Luminous peach horizon
    { y: 585, col: color("#fde4c8") }  // Pale apricot glow
  ];

  function getSkyColor(yVal) {
    if (yVal <= stops[0].y) return stops[0].col;
    if (yVal >= stops[stops.length - 1].y) return stops[stops.length - 1].col;
    for (let i = 0; i < stops.length - 1; i++) {
      if (yVal >= stops[i].y && yVal <= stops[i + 1].y) {
        let t = map(yVal, stops[i].y, stops[i + 1].y, 0, 1);
        return lerpColor(stops[i].col, stops[i + 1].col, t);
      }
    }
    return stops[0].col;
  }

  brush.noStroke();
  brush.noFill();

  // Multi-pass overlapping bokashi wash strips for seamless gradation
  const numBands = 68;
  const maxSkyY = 580;
  for (let i = 0; i < numBands; i++) {
    let y0 = map(i, 0, numBands, -25, maxSkyY - 15);
    let bandH = 38 + (i % 3) * 8;
    let c = getSkyColor(y0 + bandH * 0.5);
    brush.wash(c, 92);
    drawShapePoly([
      [-30, y0],
      [1230, y0 + random(-2, 2)],
      [1230, y0 + bandH + random(-2, 2)],
      [-30, y0 + bandH]
    ], 0);
  }
  brush.noWash();

  // Add subtle watercolor granulation layers so the sky feels painted on cold-press paper
  const texBands = [
    { y1: -20, y2: 160, col: "#091d36", alpha: 38 },
    { y1: 110, y2: 290, col: "#1a4066", alpha: 32 },
    { y1: 250, y2: 410, col: "#426580", alpha: 26 },
    { y1: 390, y2: 505, col: "#c49689", alpha: 28 },
    { y1: 475, y2: 575, col: "#f7c7a3", alpha: 36 }
  ];

  brush.fillBleed(0.06, "out");
  brush.fillTexture(0.38, 0.12);
  for (let b of texBands) {
    brush.fill(b.col, b.alpha);
    drawShapePoly([
      [-20, b.y1],
      [600, b.y1 + random(-4, 4)],
      [1220, b.y1],
      [1220, b.y2],
      [600, b.y2 + random(-4, 4)],
      [-20, b.y2]
    ], 0.1);
  }

  // Delicate flat stratocumulus dusk clouds near horizon (woodblock print style)
  brush.fillBleed(0.02, "out");
  brush.fillTexture(0.45, 0.28);
  const clouds = [
    { x: 180, y: 432, w: 310, h: 14, col: "#5b697d", op: 48 },
    { x: 860, y: 415, w: 380, h: 16, col: "#546378", op: 46 },
    { x: 520, y: 468, w: 260, h: 11, col: "#8c7a82", op: 42 },
    { x: 960, y: 482, w: 290, h: 10, col: "#b38b84", op: 45 }
  ];
  for (let cl of clouds) {
    brush.fill(cl.col, cl.op);
    drawShapePoly([
      [cl.x - cl.w * 0.5, cl.y],
      [cl.x - cl.w * 0.2, cl.y - cl.h * 0.6],
      [cl.x + cl.w * 0.25, cl.y - cl.h * 0.45],
      [cl.x + cl.w * 0.5, cl.y + cl.h * 0.1],
      [cl.x + cl.w * 0.18, cl.y + cl.h * 0.5],
      [cl.x - cl.w * 0.25, cl.y + cl.h * 0.4]
    ], 0.3);
  }
  brush.noFill();
}

