    drawShapePoly([[ix - 2, 278], [ix + 2, 278], [ix + 2, 271], [ix - 2, 271]], 0);
  }
  brush.noWash();

  // Far left distant pole (X = 52, Y = 140..715)
  drawPoleWithSnow(52, 140, 715, 13);
  brush.set("rotring", "#121820", 0.85);
  brush.line(12, 175, 92, 170);
  brush.line(16, 218, 88, 213);
  brush.set("cpencil", "#ffffff", 0.65);
  brush.line(12, 173, 92, 168);
  brush.line(16, 216, 88, 211);

  // --- B. Overhead Wires (Confident fine pen catenary curves across the sky) ---
  const wireSets = [
    { pts: [[-20, 155], [52, 170], [540, 238], [1045, 244], [1220, 235]], w: 0.35, snow: true },
    { pts: [[-20, 162], [52, 174], [540, 246], [1045, 246], [1220, 239]], w: 0.28, snow: false },
    { pts: [[-20, 198], [52, 213], [540, 278], [1045, 278], [1220, 268]], w: 0.32, snow: true },
    { pts: [[-20, 206], [52, 216], [540, 286], [1045, 280], [1220, 272]], w: 0.24, snow: false },
    // Lower signal cable to crossing mast
    { pts: [[52, 310], [135, 345], [215, 332], [490, 392], [755, 425], [1045, 385]], w: 0.3, snow: true }
  ];

  for (let ws of wireSets) {
    brush.set("rotring", "#121a24", ws.w);
    brush.spline(ws.pts, 0.45);
    if (ws.snow) {
      let snowPts = ws.pts.map(p => [p[0], p[1] - 1.3]);
      brush.set("techNib", "#f4f8fc", 0.24);
      brush.spline(snowPts, 0.45);
    }
  }

  // --- C. Right-side Barrier Catch Post & Far Signal Box (X = 755, Y = 515..668) ---
  drawRightCrossingPost(755, 668);

  // --- D. Main Foreground-Left Crossing Assembly (X = 115..245, Y = 185..745) ---
  drawLeftCrossingAssembly();

  // --- E. The Lowered Crossing Barrier Arm (X = 152 to 765, Y = 576 to 548) ---
  drawCrossingBarrierArm();
}

function drawPoleWithSnow(x, yTop, yBot, w) {
  brush.noStroke();
  brush.wash("#1a1c22", 240);
  drawShapePoly([
    [x - w * 0.42, yTop],
    [x + w * 0.42, yTop],
    [x + w * 0.55, yBot],
    [x - w * 0.55, yBot]
  ], 0);
  // Cold sky reflection on right side of pole
  brush.wash("#4e6278", 160);
  drawShapePoly([
    [x + w * 0.15, yTop],
    [x + w * 0.42, yTop],
    [x + w * 0.55, yBot],
    [x + w * 0.2, yBot]
  ], 0);
  // Snow cap on pole top
  brush.wash("#ffffff", 245);
  drawShapePoly([
    [x - w * 0.55, yTop],
    [x, yTop - 6],
    [x + w * 0.55, yTop],
    [x, yTop + 2]
  ], 0.2);
