function drawCrossbuckSign(cx, cy) {
  const armLen = 48;
  const armW = 8;
  const angles = [-32, 32];

  for (let a of angles) {
    let c = cos(a), s = sin(a);
    let nx = -s * armW, ny = c * armW;
    let p1 = [cx - c * armLen + nx, cy - s * armLen + ny];
    let p2 = [cx + c * armLen + nx, cy + s * armLen + ny];
    let p3 = [cx + c * armLen - nx, cy + s * armLen - ny];
    let p4 = [cx - c * armLen - nx, cy - s * armLen - ny];

    brush.noStroke();
    brush.wash("#f4f7fb", 248);
    drawShapePoly([p1, p2, p3, p4], 0);

    // High-contrast black graphic blocks on crossbuck blades
    for (let t = -0.65; t <= 0.65; t += 0.32) {
      if (abs(t) < 0.15) continue;
      let bx = cx + c * armLen * t;
      let by = cy + s * armLen * t;
      brush.wash("#12171f", 240);
      drawShapePoly([
        [bx - c * 4 + nx * 0.55, by - s * 4 + ny * 0.55],
        [bx + c * 4 + nx * 0.55, by + s * 4 + ny * 0.55],
        [bx + c * 4 - nx * 0.55, by + s * 4 - ny * 0.55],
        [bx - c * 4 - nx * 0.55, by - s * 4 - ny * 0.55]
      ], 0);
    }
    brush.noWash();

    // Crisp pen border & snow ribbon on upper edge of each blade
    brush.set("rotring", "#0b0f14", 0.38);
    drawShapePoly([p1, p2, p3, p4], 0);

    // Settled snow along upper edge (p1 to p2)
    brush.set("cpencil", "#ffffff", 0.75);
    brush.line(p1[0], p1[1] - 2, p2[0], p2[1] - 2);
  }
}

function drawWarningLamps(cx, cy) {
  // Horizontal crossbar
  brush.set("rotring", "#0d1218", 0.85);
  brush.line(cx - 32, cy, cx + 32, cy);
  brush.set("cpencil", "#ffffff", 0.55);
  brush.line(cx - 32, cy - 2, cx + 32, cy - 2);

  const lampX = [cx - 28, cx + 28];
  for (let i = 0; i < 2; i++) {
    let lx = lampX[i];
    // Black circular backing target plate
    brush.noStroke();
    brush.wash("#0b0f14", 248);
    brush.circle(lx, cy, 16, 0.05);

    // Snow perched on top of the black lamp hood
    brush.wash("#ffffff", 250);
    drawShapePoly([
      [lx - 14, cy - 11], [lx, cy - 19], [lx + 14, cy - 11], [lx, cy - 13]
    ], 0.25);

    // Left lamp actively flashing bright ruby-orange, right lamp dim warm ember
    if (i === 0) {
      // Soft watercolor glow halo in the twilight
      brush.fillBleed(0.25, "out");
      brush.fill("#ff4b2b", 75);
      brush.circle(lx, cy, 26, 0.1);
      brush.noFill();

      brush.wash("#ff2a14", 245);
      brush.circle(lx, cy, 8, 0.02);
      brush.wash("#ffcf87", 250);
      brush.circle(lx - 1, cy - 1, 3.5, 0.02);
    } else {
      brush.wash("#4a1412", 245);
      brush.circle(lx, cy, 8, 0.02);
      brush.wash("#a83224", 190);
      brush.circle(lx, cy, 4, 0.02);
    }
    brush.noWash();

    brush.set("rotring", "#06080b", 0.35);
    brush.circle(lx, cy, 16, 0.04);
  }
}

function drawCrossingBarrierArm() {
  // The barrier arm runs from counterweight at (145, 576) through pivot (215, 572) to catch post (762, 548)
  const xStart = 215, yStart = 572, hStart = 17;
  const xEnd = 762, yEnd = 548, hEnd = 9.5;

  // 1. Heavy Counterweight Assembly on the left of the pivot (X = 142..222, Y = 555..592)
  brush.noStroke();
  brush.wash("#12171e", 250);
  drawShapePoly([
    [142, 562], [224, 558], [224, 586], [142, 592]
  ], 0);
  // Heavy iron weight block at the tail end (X = 140..176)
  brush.wash("#222a34", 250);
  drawShapePoly([
    [138, 552], [176, 550], [176, 598], [138, 600]
  ], 0);
  // Yellow/ochre weathered warning stripe on counterweight
  brush.wash("#c99238", 215);
  drawShapePoly([
    [144, 556], [156, 555], [154, 596], [142, 597]
  ], 0);
  // Snow cushion settled on counterweight and pivot housing
  brush.wash("#ffffff", 250);
  drawShapePoly([
    [136, 552], [158, 543], [178, 549], [176, 553], [138, 554]
  ], 0.2);
  drawShapePoly([
    [176, 559], [202, 552], [226, 557], [224, 561], [176, 562]
  ], 0.2);
  brush.noWash();

  brush.set("rotring", "#07090d", 0.45);
  drawShapePoly([[138, 552], [176, 550], [176, 598], [138, 600]], 0);
  drawShapePoly([[176, 560], [224, 558], [224, 586], [176, 589]], 0);
  // Pivot wheel & bolts
  brush.circle(215, 572, 11, 0.03);
  brush.circle(215, 572, 4, 0.02);

  // 2. Hanging warning fringe / folding aluminum skirt under the barrier (X = 255..695)
  // Drawn first so the main boom arm sits cleanly over the top attachments
  brush.set("rotring", "#1d2630", 0.28);
  const skirtBottomOffset = 52;
  // Bottom tension wire of the skirt
  let xSkirt1 = 255, xSkirt2 = 695;
  let tS1 = (xSkirt1 - xStart) / (xEnd - xStart);
  let tS2 = (xSkirt2 - xStart) / (xEnd - xStart);
  let ySkirt1 = lerp(yStart, yEnd, tS1) + skirtBottomOffset;
  let ySkirt2 = lerp(yStart, yEnd, tS2) + skirtBottomOffset * 0.85;
  brush.line(xSkirt1, ySkirt1, xSkirt2, ySkirt2);

  // Vertical hanging rods and diagonal bracing wires
  for (let sx = xSkirt1; sx <= xSkirt2; sx += 18) {
    let t = (sx - xStart) / (xEnd - xStart);
    let syTop = lerp(yStart, yEnd, t) + lerp(hStart, hEnd, t) * 0.5;
    let syBot = lerp(ySkirt1, ySkirt2, (sx - xSkirt1) / (xSkirt2 - xSkirt1));
    brush.set("rotring", "#1a222c", 0.26);
    brush.line(sx, syTop, sx, syBot);
    // Tiny red/white warning tags on every second rod
    if (((sx - xSkirt1) / 18) % 2 === 0) {
      brush.set("pen", "#b83527", 0.45);
      brush.line(sx, syTop + 12, sx, syBot - 12);
    }
  }

  // 3. The Tapered Barrier Boom Arm (12 alternating high-contrast segments)
  const numSegs = 12;
  for (let i = 0; i < numSegs; i++) {
    let t0 = i / numSegs;
    let t1 = (i + 1) / numSegs;
    let x0 = lerp(xStart, xEnd, t0);
    let x1 = lerp(xStart, xEnd, t1);
    let yc0 = lerp(yStart, yEnd, t0);
    let yc1 = lerp(yStart, yEnd, t1);
    let h0 = lerp(hStart, hEnd, t0) * 0.5;
    let h1 = lerp(hStart, hEnd, t1) * 0.5;

    let isDark = (i % 2 === 0);
    brush.noStroke();
    brush.wash(isDark ? "#0e131a" : "#f4f7fb", 248);
    drawShapePoly([
      [x0, yc0 - h0],
      [x1, yc1 - h1],
      [x1, yc1 + h1],
      [x0, yc0 + h0]
    ], 0);

    // Subtle crimson reflector strip inside the white segments
    if (!isDark) {
      let xm0 = lerp(x0, x1, 0.35);
      let xm1 = lerp(x0, x1, 0.65);
      let ym0 = lerp(yc0, yc1, 0.35);
      let ym1 = lerp(yc0, yc1, 0.65);
      let hm = lerp(h0, h1, 0.5) * 0.7;
      brush.wash("#c93b2b", 225);
      drawShapePoly([
        [xm0, ym0 - hm], [xm1, ym1 - hm], [xm1, ym1 + hm], [xm0, ym0 + hm]
      ], 0);
    }

    // Bottom shadow bevel along the arm
    brush.wash("#07090d", 140);
    drawShapePoly([
      [x0, yc0 + h0 * 0.45],
      [x1, yc1 + h1 * 0.45],
      [x1, yc1 + h1],
      [x0, yc0 + h0]
    ], 0);
  }
  brush.noWash();

  // Crisp confident pen outlines of the barrier arm
  brush.set("rotring", "#080b10", 0.42);
  brush.line(xStart, yStart - hStart * 0.5, xEnd, yEnd - hEnd * 0.5);
  brush.line(xStart, yStart + hStart * 0.5, xEnd, yEnd + hEnd * 0.5);

  // Chipped paint micro-details along the barrier arm
  brush.set("techNib", "#8c9ba8", 0.3);
  for (let i = 0; i < 24; i++) {
    let t = random(0.05, 0.95);
    let cx = lerp(xStart, xEnd, t);
    let cy = lerp(yStart, yEnd, t) + random(-3, 4);
    brush.line(cx, cy, cx + random(2, 5), cy + random(-1, 1));
  }

  // 4. Fresh White Snow Settled Along the Entire Top Edge of the Barrier Arm!
  let snowTopPts = [];
  let snowBotPts = [];
  for (let s = 0; s <= 28; s++) {
    let t = s / 28;
    let sx = lerp(xStart, xEnd, t);
    let syBase = lerp(yStart - hStart * 0.5, yEnd - hEnd * 0.5, t);
    let snowThick = lerp(6.5, 3.8, t) + 1.5 * sin(s * 28);
    snowTopPts.push([sx, syBase - snowThick]);
    snowBotPts.unshift([sx, syBase + 0.8]);
  }
  brush.noStroke();
  brush.wash("#ffffff", 252);
  drawShapePoly(snowTopPts.concat(snowBotPts), 0.15);
  brush.noWash();

  // Subtle cool blue shadow line along bottom of the barrier snow cap
  brush.set("techNib", "#8ea7c2", 0.28);
  brush.line(xStart, yStart - hStart * 0.5, xEnd, yEnd - hEnd * 0.5);

  // Small red warning lantern mounted on top-center of the barrier arm (X = 468, Y = 556)
  brush.noStroke();
  brush.fillBleed(0.2, "out");
  brush.fill("#ff4526", 65);
  brush.circle(468, 550, 16, 0.1);
  brush.noFill();
  brush.wash("#141920", 250);
  drawShapePoly([[462, 556], [474, 555], [473, 545], [463, 546]], 0);
  brush.wash("#ff3319", 250);
  brush.circle(468, 550, 4.5, 0.02);
  brush.wash("#ffffff", 250);
  drawShapePoly([[461, 546], [468, 542], [475, 545], [468, 546]], 0.2);
  brush.noWash();
}

