// 7. BACKGROUND WINTER REEDS & WEIGH-STONE BESIDE THE ROAD
// ============================================================================
function drawBackgroundReedsAndDrifts() {
  // Weathered stone boundary marker half-buried in the right snowbank (X = 1095, Y = 775..855)
  brush.noStroke();
  brush.wash("#48586b", 220);
  drawShapePoly([
    [1082, 780], [1108, 776], [1114, 852], [1078, 856]
  ], 0.05);
  brush.wash("#242e3a", 230);
  drawShapePoly([
    [1108, 776], [1118, 782], [1122, 848], [1114, 852]
  ], 0.05);
  // Snow cap on the stone marker
  brush.wash("#ffffff", 250);
  drawShapePoly([
    [1079, 781], [1096, 769], [1119, 781], [1108, 783], [1082, 784]
  ], 0.25);
  brush.noWash();

  brush.set("rotring", "#141b24", 0.35);
  brush.line(1082, 780, 1078, 856);
  brush.line(1108, 776, 1114, 852);

  // Dry winter grasses & reeds poking crisply through the snowbanks
  const reedClusters = [
    { x: 1065, y: 855, n: 14, h: 58 },
    { x: 965, y: 745, n: 10, h: 42 },
    { x: 185, y: 742, n: 12, h: 48 },
    { x: 95, y: 855, n: 15, h: 65 }
  ];

  for (let rc of reedClusters) {
    for (let i = 0; i < rc.n; i++) {
      let rx = rc.x + random(-24, 24);
      let ry = rc.y + random(-8, 8);
      let tilt = random(-22, 28);
      let rh = rc.h * random(0.55, 1.15);
      let tipX = rx + sin(tilt) * rh;
      let tipY = ry - cos(tilt) * rh;

      // Shadow of reed stem on snow
      brush.set("techNib", "#7892ad", 0.24);
      brush.line(rx, ry, rx + rh * 0.45, ry + 4);

      // Crisp dark ochre/umber winter stem
      brush.set("rotring", "#2c221e", 0.3);
      brush.spline([
        [rx, ry],
        [(rx + tipX) * 0.5 + random(-3, 3), (ry + tipY) * 0.5],
        [tipX, tipY]
      ], 0.35);

      // Tiny frost/snow plume on seed head
      if (random() < 0.65) {
        brush.set("cpencil", "#ffffff", 0.55);
        brush.line(tipX, tipY, tipX + sin(tilt) * 6, tipY - cos(tilt) * 6);
      }
    }
  }
}

// ============================================================================
// 8. THE PARKED BLACK BICYCLE (HYPERREAL HERO SUBJECT)
// ============================================================================
function drawParkedBicycle() {
  // Key structural coordinates of the bicycle
  const FWC = { x: 535, y: 845 }; // Front wheel center
  const RWC = { x: 885, y: 870 }; // Rear wheel center
  const BB  = { x: 725, y: 875 }; // Bottom bracket (crank center)
  const ST  = { x: 768, y: 682 }; // Seat tube top lug
  const HTB = { x: 578, y: 710 }; // Head tube bottom lug
  const HTT = { x: 592, y: 642 }; // Head tube top lug
  const wheelR = 136;

  // --- 8.1 Cast Shadow of the Bicycle on the Snow ---
  drawBicycleCastShadow(FWC, RWC, BB);

  // --- 8.2 Far-side Components (Far Pedal, Far Stays, Kickstand) ---
  drawBicycleKickstandAndFarPedal(BB, RWC);

  // --- 8.3 Front & Rear Wheels (Tires, Rims, Hubs, 32 Tangential Spokes & Snow) ---
  drawBicycleWheel(FWC.x, FWC.y, wheelR * 0.96, wheelR, true);
  drawBicycleWheel(RWC.x, RWC.y, wheelR * 0.99, wheelR, false);

  // --- 8.4 Black Enameled Mudguards (Fenders) & Rear Carrier Rack ---
  drawFendersAndRearRack(FWC, RWC, ST, wheelR);

  // --- 8.5 Frozen Chain, Sprockets, Half-Chaincase & Near Pedal ---
  drawFrozenDrivetrain(BB, RWC);

  // --- 8.6 Main Black Enameled Frame (With Chipped Paint, Lugs & Snow) ---
  drawBicycleFrame(FWC, RWC, BB, ST, HTB, HTT);

  // --- 8.7 Vintage Sprung Leather Saddle with Fresh Settled Snow Cushion ---
  drawSaddleWithSnow(ST);

  // --- 8.8 Front Wire Basket with Settled Snow Drift & Dynamo Headlamp ---
  drawBasketWithSnowAndLamp(FWC, HTB, HTT);

  // --- 8.9 Swept-Back Handlebars, Bowden Brake Cables, Bell & Snow-Capped Grips ---
  drawHandlebarsAndGripsWithSnow(HTT, HTB, FWC, ST);
}

function drawBicycleCastShadow(FWC, RWC, BB) {
  brush.noStroke();
  brush.fillBleed(0.02, "out");
  brush.fillTexture(0.45, 0.35);

  // Cast shadow of front wheel (projected ellipse on snow plane)
  let sFWC = { x: FWC.x + 22, y: FWC.y + 148 };
  let sRWC = { x: RWC.x + 24, y: RWC.y + 145 };

  // Outer shadow ellipses & frame shadow bands in cobalt-Prussian twilight blue
  brush.fill("#435d78", 165);
  // Front wheel shadow ring
  let fwShadowOuter = [];
  for (let a = 0; a < 360; a += 15) {
    fwShadowOuter.push([sFWC.x + cos(a) * 128, sFWC.y + sin(a) * 24]);
  }
  drawShapePoly(fwShadowOuter, 0.25);

  // Rear wheel shadow ring
  let rwShadowOuter = [];
  for (let a = 0; a < 360; a += 15) {
    rwShadowOuter.push([sRWC.x + cos(a) * 134, sRWC.y + sin(a) * 25]);
  }
  drawShapePoly(rwShadowOuter, 0.25);

  // Frame, basket & saddle shadow linking the two wheel shadows
  drawShapePoly([
    [sFWC.x - 45, sFWC.y - 12],
    [sFWC.x + 35, sFWC.y - 36],
    [755, 985],
    [sRWC.x + 40, sRWC.y - 10],
    [sRWC.x - 20, sRWC.y + 12],
    [735, 1005]
  ], 0.15);

  // Basket shadow patch in front
  drawShapePoly([
    [455, 965], [525, 955], [545, 982], [472, 992]
  ], 0.15);
  brush.noFill();

  // Cut out inner snow ovals inside the wheel shadows so they read as hollow rim shadows
  brush.wash("#eef4fa", 185);
  let fwShadowInner = [];
  let rwShadowInner = [];
  for (let a = 0; a < 360; a += 18) {
    fwShadowInner.push([sFWC.x + cos(a) * 98, sFWC.y + sin(a) * 15]);
    rwShadowInner.push([sRWC.x + cos(a) * 104, sRWC.y + sin(a) * 16]);
  }
  drawShapePoly(fwShadowInner, 0.25);
  drawShapePoly(rwShadowInner, 0.25);
  brush.noWash();

  // Delicate spoke shadows across the snow inside the wheel shadow ovals
  brush.set("2H", "#647f9c", 0.3);
  for (let a = 0; a < 180; a += 22.5) {
    brush.line(
      sFWC.x + cos(a) * 105, sFWC.y + sin(a) * 17,
      sFWC.x - cos(a) * 105, sFWC.y - sin(a) * 17
    );
    brush.line(
      sRWC.x + cos(a) * 110, sRWC.y + sin(a) * 18,
      sRWC.x - cos(a) * 110, sRWC.y - sin(a) * 18
    );
  }
}

