// Helper for hyperreal black enameled (or chrome) bicycle frame tubes
function drawFrameTube(x1, y1, x2, y2, thick, hasSnowTop = false, isChrome = false) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy);
  if (len < 1) return;
  let ux = dx / len;
  let uy = dy / len;
  // Normal vector pointing upward (ny <= 0)
  let nx = -uy;
  let ny = ux;
  if (ny > 0) {
    nx = -nx;
    ny = -ny;
  }

  let r = thick * 0.5;
  let p1 = [x1 + nx * r, y1 + ny * r];
  let p2 = [x2 + nx * r, y2 + ny * r];
  let p3 = [x2 - nx * r, y2 - ny * r];
  let p4 = [x1 - nx * r, y1 - ny * r];

  // 1. Solid tube body
  brush.noStroke();
  brush.wash(isChrome ? "#7a8ea3" : "#080b10", 252);
  drawShapePoly([p1, p2, p3, p4], 0);
  brush.noWash();

  // 2. Cylindrical specular sky reflection along upper third of the tube
  let s1x = x1 + nx * (r * 0.48), s1y = y1 + ny * (r * 0.48);
  let s2x = x2 + nx * (r * 0.48), s2y = y2 + ny * (r * 0.48);
  brush.set("techNib", isChrome ? "#ffffff" : "#6c86a1", 0.36);
  brush.line(s1x, s1y, s2x, s2y);

  // Bright intermittent specular glints
  brush.set("rotring", isChrome ? "#ffffff" : "#b8cce0", 0.25);
  brush.line(
    lerp(s1x, s2x, 0.18), lerp(s1y, s2y, 0.18),
    lerp(s1x, s2x, 0.78), lerp(s1y, s2y, 0.78)
  );

  // 3. Subtle warm peach horizon reflection along lower side of tube
  let w1x = x1 - nx * (r * 0.42), w1y = y1 - ny * (r * 0.42);
  let w2x = x2 - nx * (r * 0.42), w2y = y2 - ny * (r * 0.42);
  brush.set("techNib", "#8c6d60", 0.25);
  brush.line(
    lerp(w1x, w2x, 0.15), lerp(w1y, w2y, 0.15),
    lerp(w1x, w2x, 0.85), lerp(w1y, w2y, 0.85)
  );

  // 4. Crisp ink outer edges
  brush.set("rotring", "#040608", 0.4);
  brush.line(p1[0], p1[1], p2[0], p2[1]);
  brush.line(p4[0], p4[1], p3[0], p3[1]);

  // 5. Hyperreal Chipped Paint & Rust Specks on Black Enamel
  if (!isChrome && len > 35) {
    let numChips = floor(len / 28);
    for (let i = 0; i < numChips; i++) {
      let t = random(0.12, 0.88);
      let off = random(-r * 0.55, r * 0.55);
      let cx = lerp(x1, x2, t) + nx * off;
      let cy = lerp(y1, y2, t) + ny * off;
      // Bare steel fleck
      brush.set("techNib", "#9cb0c4", 0.3);
      brush.line(cx, cy, cx + ux * 3.5, cy + uy * 3.5);
      // Tiny oxidized rust core
      if (i % 2 === 0) {
        brush.set("techNib", "#8a4126", 0.28);
        brush.line(cx + 0.5, cy + 0.5, cx + ux * 2, cy + uy * 2);
      }
    }
  }

  // 6. Settled Snow Ribbon along upper edge of horizontal/diagonal tubes
  if (hasSnowTop && abs(ux) > 0.35) {
    let snowTop = [], snowBot = [];
    let steps = 10;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let bx = lerp(p1[0], p2[0], t);
      let by = lerp(p1[1], p2[1], t);
      let sh = (3.5 + 2.2 * sin(t * 180)) * abs(ux);
      snowTop.push([bx + nx * sh, by + ny * sh]);
      snowBot.unshift([bx - nx * 0.8, by - ny * 0.8]);
    }
    brush.noStroke();
    brush.wash("#ffffff", 250);
    drawShapePoly(snowTop.concat(snowBot), 0.2);
    brush.noWash();
    brush.set("techNib", "#8ea7c2", 0.24);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

function drawCurvedForkBlade(xTop, yTop, xBot, yBot, thickTop, isNear) {
  let midX = (xTop + xBot) * 0.5 - 11; // Classic forward fork rake near bottom
  let midY = (yTop + yBot) * 0.5 + 8;

  let leftEdge = [
    [xTop - thickTop * 0.5, yTop],
    [midX - thickTop * 0.38, midY],
    [xBot - 2.8, yBot]
  ];
  let rightEdge = [
    [xBot + 2.8, yBot],
    [midX + thickTop * 0.38, midY],
    [xTop + thickTop * 0.5, yTop]
  ];

  brush.noStroke();
  brush.wash(isNear ? "#080b10" : "#121820", 252);
  drawShapePoly(leftEdge.concat(rightEdge), 0.25);
  brush.noWash();

  if (isNear) {
    // Specular edge highlight & chipped paint on fork blade
    brush.set("techNib", "#7a94b0", 0.35);
    brush.spline([
      [xTop - 1.5, yTop + 4],
      [midX - 1.2, midY],
      [xBot - 0.8, yBot - 4]
    ], 0.35);
    // Paint chips on fork
    brush.set("techNib", "#a6bacf", 0.3);
    brush.line(midX - 1, midY - 18, midX, midY - 14);
    brush.line(midX + 1, midY + 12, midX + 2, midY + 16);
    brush.set("techNib", "#8a4226", 0.28);
    brush.line(midX, midY - 16, midX + 1, midY - 14);

    // Snow tuft settled on fork crown shoulder
    brush.noStroke();
    brush.wash("#ffffff", 250);
    drawShapePoly([
      [xTop - 8, yTop + 2], [xTop, yTop - 5], [xTop + 8, yTop + 2], [xTop, yTop + 4]
    ], 0.25);
    brush.noWash();
  }

  brush.set("rotring", "#040608", 0.4);
  brush.spline(leftEdge, 0.35);
  brush.spline(rightEdge, 0.35);
}

function drawChromeCollar(cx, cy, w, h) {
  brush.noStroke();
  brush.wash("#b8cadb", 248);
  drawShapePoly([
    [cx - w * 0.5, cy - h * 0.5],
    [cx + w * 0.5, cy - h * 0.5],
    [cx + w * 0.5, cy + h * 0.5],
    [cx - w * 0.5, cy + h * 0.5]
  ], 0.1);
  brush.noWash();
  brush.set("rotring", "#0b0e13", 0.35);
  drawShapePoly([
    [cx - w * 0.5, cy - h * 0.5],
    [cx + w * 0.5, cy - h * 0.5],
    [cx + w * 0.5, cy + h * 0.5],
    [cx - w * 0.5, cy + h * 0.5]
  ], 0.1);
}

