function drawHandlebarGripWithSnow(x1, y1, x2, y2, thick) {
  let dx = x2 - x1, dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy);
  let ux = dx / len, uy = dy / len;
  let nx = -uy, ny = ux;
  if (ny > 0) { nx = -nx; ny = -ny; }
  let r = thick * 0.5;

  let p1 = [x1 + nx * r, y1 + ny * r];
  let p2 = [x2 + nx * r, y2 + ny * r];
  let p3 = [x2 - nx * r, y2 - ny * r];
  let p4 = [x1 - nx * r, y1 - ny * r];

  // Black rubber grip body
  brush.noStroke();
  brush.wash("#0b0e14", 255);
  drawShapePoly([p1, p2, p3, p4], 0.1);
  // Molded end flange at front (x1, y1) and rounded pommel at back (x2, y2)
  brush.circle(x2, y2, r * 1.15, 0.04);
  brush.noWash();

  // Tactile rubber grip ribs
  brush.set("rotring", "#263240", 0.32);
  for (let t = 0.12; t <= 0.88; t += 0.12) {
    let gx = lerp(x1, x2, t);
    let gy = lerp(y1, y2, t);
    brush.line(gx + nx * (r * 0.85), gy + ny * (r * 0.85), gx - nx * (r * 0.85), gy - ny * (r * 0.85));
  }
  brush.set("rotring", "#05070a", 0.42);
  drawShapePoly([p1, p2, p3, p4], 0.1);

  // Plump Fresh White Snow Cap Settled on Top of the Handlebar Grip!
  brush.noStroke();
  brush.wash("#8ea7c2", 240);
  drawShapePoly([
    [p1[0] - ux * 2, p1[1]],
    [p2[0] + ux * 3, p2[1]],
    [p2[0] + ux * 2 - nx * 2, p2[1] - ny * 2],
    [p1[0] - nx * 2, p1[1] - ny * 2]
  ], 0.2);

  brush.wash("#ffffff", 255);
  drawShapePoly([
    [p1[0] - ux * 2, p1[1] - 1],
    [lerp(p1[0], p2[0], 0.3) + nx * 6.5, lerp(p1[1], p2[1], 0.3) + ny * 6.5],
    [lerp(p1[0], p2[0], 0.75) + nx * 7.0, lerp(p1[1], p2[1], 0.75) + ny * 7.0],
    [p2[0] + ux * 4 + nx * 2, p2[1] + ny * 2],
    [p2[0] + ux * 2 - nx * 1, p2[1] - ny * 1],
    [p1[0] - nx * 1, p1[1] - ny * 1]
  ], 0.3);
  brush.noWash();

  brush.set("techNib", "#6b85a1", 0.26);
  brush.line(p1[0], p1[1], p2[0] + ux * 2, p2[1]);
}

