    gradX[ix] = new Float32Array(GRID_N + 1);
    gradY[ix] = new Float32Array(GRID_N + 1);
    let x = ix * GRID_STEP;
    for (let iy = 0; iy <= GRID_N; iy++) {
      let y = iy * GRID_STEP;
      gridF[ix][iy] = evalRawField(x, y);
    }
  }

  // Compute central-difference gradients for 3D meniscus lighting & bubble normals
  for (let ix = 1; ix < GRID_N; ix++) {
    for (let iy = 1; iy < GRID_N; iy++) {
      gradX[ix][iy] = (gridF[ix + 1][iy] - gridF[ix - 1][iy]) / (2 * GRID_STEP);
      gradY[ix][iy] = (gridF[ix][iy + 1] - gridF[ix][iy - 1]) / (2 * GRID_STEP);
    }
  }
}

function evalRawField(x, y) {
  // Subtle domain warping for organic fluid and radar reflectivity contours
  let wx = x + (noise(x * 0.004, y * 0.004, 1.2) - 0.5) * 34;
  let wy = y + (noise(x * 0.004, y * 0.004, 5.7) - 0.5) * 34;

  let sum = 0;

  for (let i = 0; i < capsules.length; i++) {
    let c = capsules[i];
    let vx = c.bx - c.ax;
    let vy = c.by - c.ay;
    let l2 = vx * vx + vy * vy;
    let t = constrain(((wx - c.ax) * vx + (wy - c.ay) * vy) / l2, 0, 1);
    let px = c.ax + t * vx;
    let py = c.ay + t * vy;
    let d2 = (wx - px) * (wx - px) + (wy - py) * (wy - py);
    let r2 = c.r * c.r;
    if (d2 < r2 * 3.2) {
      sum += c.w * Math.exp(-d2 / r2);
    }
  }

  for (let i = 0; i < metaballs.length; i++) {
    let m = metaballs[i];
    let d2 = (wx - m.x) * (wx - m.x) + (wy - m.y) * (wy - m.y);
    let r2 = m.r * m.r;
    if (d2 < r2 * 3.5) {
      sum += m.w * Math.exp(-d2 / r2);
    }
  }

  // Fine radar-edge scalloping where liquid is present
  if (sum > 0.35) {
    let n1 = noise(x * 0.011, y * 0.011, 9.1) - 0.5;
    let n2 = noise(x * 0.026, y * 0.026, 3.4) - 0.5;
    sum += (n1 * 0.14 + n2 * 0.05) * constrain(sum, 0, 1.5);
  }

  return sum;
}

function sampleField(x, y) {
  let gx = constrain(x / GRID_STEP, 0, GRID_N - 1.001);
  let gy = constrain(y / GRID_STEP, 0, GRID_N - 1.001);
  let ix = Math.floor(gx);
  let iy = Math.floor(gy);
  let fx = gx - ix;
  let fy = gy - iy;
  let v00 = gridF[ix][iy];
  let v10 = gridF[ix + 1][iy];
  let v01 = gridF[ix][iy + 1];
  let v11 = gridF[ix + 1][iy + 1];
  return (v00 * (1 - fx) + v10 * fx) * (1 - fy) + (v01 * (1 - fx) + v11 * fx) * fy;
}

function sampleGrad(x, y) {
  let ix = constrain(Math.round(x / GRID_STEP), 1, GRID_N - 1);
  let iy = constrain(Math.round(y / GRID_STEP), 1, GRID_N - 1);
  return { gx: gradX[ix][iy], gy: gradY[ix][iy] };
}

// Marching Squares contour extractor returning closed, smoothed polygon loops
function extractContours(threshold, smoothPasses = 2) {
  let segments = [];
  let edgeMap = new Map();

  function edgePoint(ix, iy, edge) {
    // edge 0: top (ix,iy)-(ix+1,iy), 1: right (ix+1,iy)-(ix+1,iy+1)
    // edge 2: bottom (ix,iy+1)-(ix+1,iy+1), 3: left (ix,iy)-(ix,iy+1)
    let x0, y0, x1, y1, v0, v1, key;
    if (edge === 0) {
      x0 = ix; y0 = iy; x1 = ix + 1; y1 = iy;
      v0 = gridF[ix][iy]; v1 = gridF[ix + 1][iy];
      key = `H_${ix}_${iy}`;
    } else if (edge === 1) {
      x0 = ix + 1; y0 = iy; x1 = ix + 1; y1 = iy + 1;
      v0 = gridF[ix + 1][iy]; v1 = gridF[ix + 1][iy + 1];
      key = `V_${ix + 1}_${iy}`;
    } else if (edge === 2) {
      x0 = ix; y0 = iy + 1; x1 = ix + 1; y1 = iy + 1;
      v0 = gridF[ix][iy + 1]; v1 = gridF[ix + 1][iy + 1];
      key = `H_${ix}_${iy + 1}`;
    } else {
      x0 = ix; y0 = iy; x1 = ix; y1 = iy + 1;
      v0 = gridF[ix][iy]; v1 = gridF[ix][iy + 1];
      key = `V_${ix}_${iy}`;
    }
    let denom = v1 - v0;
    let t = Math.abs(denom) < 1e-6 ? 0.5 : constrain((threshold - v0) / denom, 0.001, 0.999);
    return {
      x: (x0 + t * (x1 - x0)) * GRID_STEP,
      y: (y0 + t * (y1 - y0)) * GRID_STEP,
      key: key
    };
  }

  for (let ix = 0; ix < GRID_N; ix++) {
    for (let iy = 0; iy < GRID_N; iy++) {
      let b0 = gridF[ix][iy] >= threshold ? 1 : 0;
      let b1 = gridF[ix + 1][iy] >= threshold ? 2 : 0;
      let b2 = gridF[ix + 1][iy + 1] >= threshold ? 4 : 0;
      let b3 = gridF[ix][iy + 1] >= threshold ? 8 : 0;
      let code = b0 | b1 | b2 | b3;
      if (code === 0 || code === 15) continue;

      // Directed edges so interior (F >= threshold) stays consistently to the right/left
      let pairs = [];
      switch (code) {
        case 1:  pairs.push([3, 0]); break;
        case 2:  pairs.push([0, 1]); break;
        case 3:  pairs.push([3, 1]); break;
        case 4:  pairs.push([1, 2]); break;
        case 5:  pairs.push([3, 2], [1, 0]); break;
        case 6:  pairs.push([0, 2]); break;
        case 7:  pairs.push([3, 2]); break;
        case 8:  pairs.push([2, 3]); break;
        case 9:  pairs.push([2, 0]); break;
        case 10: pairs.push([0, 3], [2, 1]); break;
        case 11: pairs.push([2, 1]); break;
        case 12: pairs.push([1, 3]); break;
        case 13: pairs.push([1, 0]); break;
        case 14: pairs.push([0, 3]); break;
      }

      for (let p of pairs) {
        let pA = edgePoint(ix, iy, p[0]);
        let pB = edgePoint(ix, iy, p[1]);
        let seg = { a: pA, b: pB, used: false };
        segments.push(seg);
        if (!edgeMap.has(pA.key)) edgeMap.set(pA.key, []);
        edgeMap.get(pA.key).push(seg);
      }
    }
  }

  // Stitch segments into closed loops
  let loops = [];
  for (let seg of segments) {
    if (seg.used) continue;
    seg.used = true;
    let pts = [[seg.a.x, seg.a.y], [seg.b.x, seg.b.y]];
    let currKey = seg.b.key;
    let guard = 0;
    while (guard++ < 4000) {
      let candidates = edgeMap.get(currKey);
      if (!candidates) break;
      let nextSeg = null;
      for (let c of candidates) {
        if (!c.used) { nextSeg = c; break; }
      }
      if (!nextSeg) break;
      nextSeg.used = true;
      pts.push([nextSeg.b.x, nextSeg.b.y]);
      currKey = nextSeg.b.key;
      if (currKey === seg.a.key) break;
    }
    if (pts.length >= 6) {
      loops.push(smoothLoop(pts, smoothPasses));
    }
  }
  return loops;
}

function smoothLoop(pts, passes) {
  let curr = pts;
  for (let p = 0; p < passes; p++) {
    let next = [];
    let n = curr.length;
    for (let i = 0; i < n; i++) {
      let prev = curr[(i - 1 + n) % n];
      let me = curr[i];
      let nxt = curr[(i + 1) % n];
      next.push([
        0.25 * prev[0] + 0.5 * me[0] + 0.25 * nxt[0],
        0.25 * prev[1] + 0.5 * me[1] + 0.25 * nxt[1]
      ]);
    }
    curr = next;
  }
  return curr;
}

function decimateLoop(pts, stride = 3) {
  let out = [];
  for (let i = 0; i < pts.length; i += stride) {
    out.push([pts[i][0], pts[i][1]]);
  }
  return out;
}

function safeSpline(pts, curvature = 0.4) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let dx = pts[i][0] - clean[clean.length - 1][0];
    let dy = pts[i][1] - clean[clean.length - 1][1];
    if (dx * dx + dy * dy > 7.5) {
      clean.push(pts[i]);
    }
  }
  if (clean.length >= 3) {
    brush.spline(clean, curvature);
  } else if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  }
}

