// =========================================================================
// 1. POOL WATER & FINE PEN CAUSTIC NETWORK
// =========================================================================
function drawPoolWaterAndCaustics() {
  // Coping water edge line from left to right
  let pL = proj(-140, 2.2, -25);
  let pR = proj(140, 2.2, -25);
  let waterBottomL = [0, pL[1] + 55];
  let waterBottomR = [1200, pR[1] + 55];

  let waterPoly = [
    [0, 0],
    [1200, 0],
    waterBottomR,
    waterBottomL
  ];

  // Rich mineral turquoise marker base & watercolor depth
  fillPolygonWash(waterPoly, "#288387", 235);
  fillPolygonWatercolor(waterPoly, "#1f6e73", 95, 0.08, 0.45, 0.2);

  // Diagonal architectural marker streaks across the pool water
  hatchPolygon(waterPoly, "archMarker", "#237579", 1.3, 14, -12, { rand: 0.02 });
  hatchPolygon(waterPoly, "archMarker", "#359699", 1.1, 19, -12, { rand: 0.03 });
  hatchPolygon(waterPoly, "archMarker", "#41a6a8", 0.8, 28, 78, { rand: 0.03 });

  // Deeper turquoise shadow gradient near top-left and along the coping wall
  let deepTopPoly = [
    [0, 0],
    [1200, 0],
    [1200, 210],
    [0, 290]
  ];
  fillPolygonWatercolor(deepTopPoly, "#17585d", 85, 0.15, 0.4, 0.15);

  // Submerged pool wall shadow band just past the coping (-25 >= z >= -52)
  let wallShadowPoly = [
    proj(-130, -8.5, -25),
    proj(130, -8.5, -25),
    proj(130, -8.5, -52),
    proj(-130, -8.5, -52)
  ];
  fillPolygonWash(wallShadowPoly, "#164e53", 165);
  hatchPolygon(wallShadowPoly, "archMarker", "#113e42", 0.9, 10, -13, { rand: 0.01 });

  // Generate 3D cellular Voronoi/Delaunay-like caustic grid in water space (z from -26 to -260)
  let cols = 16;
  let rows = 11;
  let grid = [];
  for (let r = 0; r <= rows; r++) {
    grid[r] = [];
    let tz = r / rows;
    // Perspective-aware z distribution from -26 back to -285
    let z = -26 - Math.pow(tz, 1.38) * 260;
    for (let c = 0; c <= cols; c++) {
      let tx = (c / cols) * 2 - 1;
      let xSpan = 95 + Math.abs(z) * 0.62;
      let x = tx * xSpan;
      // Organic cellular perturbation
      let jx = (noise(c * 0.7 + 10, r * 0.7 + 20) - 0.5) * (14 + Math.abs(z) * 0.06);
      let jz = (noise(c * 0.7 + 50, r * 0.7 + 80) - 0.5) * (10 + Math.abs(z) * 0.08);
      let sp = proj(x + jx, -8.5, z + jz);
      grid[r][c] = [sp[0], sp[1], z];
    }
  }

  // Helper to draw a pinched, curved caustic cell loop
  function buildCausticCell(corners, shrink, pinch) {
    let cx = 0, cy = 0;
    for (let p of corners) { cx += p[0]; cy += p[1]; }
    cx /= corners.length;
    cy /= corners.length;

    let cellPts = [];
    let n = corners.length;
    for (let i = 0; i < n; i++) {
      let p0 = corners[i];
      let p1 = corners[(i + 1) % n];
      // Corner pulled slightly toward center
      let c0 = [cx + (p0[0] - cx) * shrink, cy + (p0[1] - cy) * shrink];
      let c1 = [cx + (p1[0] - cx) * shrink, cy + (p1[1] - cy) * shrink];
      // Midpoint of edge pinched further inward to form concave hourglass caustic ribs
      let mx = (p0[0] + p1[0]) * 0.5;
      let my = (p0[1] + p1[1]) * 0.5;
      let mIn = [cx + (mx - cx) * (shrink * pinch), cy + (my - cy) * (shrink * pinch)];

      cellPts.push(c0);
      cellPts.push(lerp2D(c0, mIn, 0.55));
      cellPts.push(mIn);
      cellPts.push(lerp2D(mIn, c1, 0.45));
    }
    return { cx, cy, pts: cellPts };
  }

  // Pass A: Dark refracted caustic shadow troughs on pool floor (offset down-left)
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      let p00 = grid[r][c];
      let p10 = grid[r][c + 1];
      let p11 = grid[r + 1][c + 1];
      let p01 = grid[r + 1][c];

      // Split some quads diagonally into 2 cells for authentic Voronoi topology
      let splitMode = (r + c) % 3;
      let subCells = [];
      if (splitMode === 0) {
        let mid1 = lerp2D(p00, p11, 0.46);
        let mid2 = lerp2D(p00, p11, 0.54);
        subCells.push([p00, p10, mid2, p01]);
        subCells.push([p10, p11, p01, mid1]);
      } else {
        subCells.push([p00, p10, p11, p01]);
      }

      for (let sc of subCells) {
        let cell = buildCausticCell(sc, 0.78, 0.74);
        let shadowPts = cell.pts.map(p => [p[0] - 4, p[1] + 7]);
        strokePolygon(shadowPts, "rotring", "#165559", 0.75, true);
      }
    }
  }

  // Pass B: Bright turquoise-cream wash inside caustic nodes (the Web intersections)
  brush.set("archMarker", "#58bdbd", 0.55);
  for (let r = 1; r < rows; r++) {
    for (let c = 1; c < cols; c++) {
      let pt = grid[r][c];
      if (pt[0] > 0 && pt[0] < 1200 && pt[1] > 0 && pt[1] < 640) {
        brush.line(pt[0] - 5, pt[1] - 1, pt[0] + 5, pt[1] + 1);
        brush.line(pt[0] - 1, pt[1] - 4, pt[0] + 1, pt[1] + 4);
      }
    }
  }

  // Pass C: Exact Fine Pen Caustic Light Lines (double-line Voronoi network + chromatic ochre rim)
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      let p00 = grid[r][c];
      let p10 = grid[r][c + 1];
      let p11 = grid[r + 1][c + 1];
      let p01 = grid[r + 1][c];

      let depthFactor = map(r, 0, rows, 1.0, 0.55);
      let cellOuter = buildCausticCell([p00, p10, p11, p01], 0.87, 0.77);
      let cellInner = buildCausticCell([p00, p10, p11, p01], 0.71, 0.68);

      // Subtle warm golden dispersion line along sun-side of caustic filament
      let goldPts = cellOuter.pts.map(p => [p[0] + 1.4, p[1] - 1.2]);
      strokePolygon(goldPts, "techPen", "#e6d4a2", 0.55 * depthFactor, true);

      // Outer fine pen caustic contour in pale seafoam-cream
      strokePolygon(cellOuter.pts, "techPen", "#d5f2ef", 0.82 * depthFactor, true);

      // Inner pinched caustic ring in crisp sun-bleached cream
      strokePolygon(cellInner.pts, "techPen", "#f7f2e4", 0.95 * depthFactor, true);

      // Secondary internal ripple rings inside larger cells
      if ((r * 7 + c * 3) % 4 === 0) {
        let microCell = buildCausticCell([p00, p10, p11, p01], 0.42, 0.82);
        strokePolygon(microCell.pts, "techPen", "#bde8e6", 0.55 * depthFactor, true);
      }

      // Connect vertices with fine bridge filaments across nodal hubs
      for (let k = 0; k < 4; k++) {
        let vtx = [p00, p10, p11, p01][k];
        let cPt = cellOuter.pts[k * 4];
        brush.set("techPen", "#f7f2e4", 0.9 * depthFactor);
        brush.line(vtx[0], vtx[1], cPt[0], cPt[1]);
        // Bright nodal flare cross-hatch at intersection
        brush.set("techPen", "#ffffff", 0.75 * depthFactor);
        brush.line(vtx[0] - 3.5 * depthFactor, vtx[1] - 0.8, vtx[0] + 3.5 * depthFactor, vtx[1] + 0.8);
      }
    }
  }

  // Fine horizontal surface tension shimmer scratches in technical pen
  brush.set("techPen", "#e3f5f3", 0.45);
  for (let i = 0; i < 95; i++) {
    let sx = random(20, 1180);
    let sy = random(15, 510);
    let len = random(8, 28);
    brush.line(sx, sy, sx + len, sy - len * 0.22);
  }
}

// =========================================================================
// 2. WATERLINE CERAMIC TILES UNDER THE COPING OVERHANG
// =========================================================================
function drawWaterlineTiles() {
  // Tile band sits at z = -25, y from -8.5 up to +0.5
  let tileCount = 38;
  let xMin = -115;
  let xMax = 115;
  let dx = (xMax - xMin) / tileCount;

  // Base dark strip for grout and overhang shadow
  let stripPoly = [
    proj(xMin, 0.6, -25),
    proj(xMax, 0.6, -25),
    proj(xMax, -8.5, -25),
    proj(xMin, -8.5, -25)
  ];
  fillPolygonWash(stripPoly, "#13292e", 245);

  for (let i = 0; i < tileCount; i++) {
    let x0 = xMin + i * dx + 0.35;
    let x1 = xMin + (i + 1) * dx - 0.35;

    // Two rows of 4.2cm square waterline tiles
    for (let row = 0; row < 2; row++) {
      let yTop = row === 0 ? 0.3 : -4.1;
      let yBot = row === 0 ? -3.7 : -8.2;

      let tPoly = [
        proj(x0, yTop, -25),
        proj(x1, yTop, -25),
        proj(x1, yBot, -25),
        proj(x0, yBot, -25)
      ];

      // Muted earth & mineral teal tile palette
      let isAccent = (i + row) % 4 === 0;
      let tileCol = isAccent ? "#7d5238" : ((i + row) % 2 === 0 ? "#1f4a52" : "#285a63");
      fillPolygonWash(tPoly, tileCol, 225);

      // Tiny diagonal glaze reflection on lower half of tile
      let glazePt1 = proj(x0 + 0.5, yBot + 1.2, -25);
      let glazePt2 = proj(x1 - 0.5, yBot + 0.8, -25);
      brush.set("techPen", isAccent ? "#b88766" : "#64a6ad", 0.55);
      brush.line(glazePt1[0], glazePt1[1], glazePt2[0], glazePt2[1]);
    }
  }

  // Deep shadow line directly beneath the coping bullnose overhang
  let overhangTop = [
    proj(xMin, 0.8, -25),
    proj(xMax, 0.8, -25),
    proj(xMax, -1.6, -25),
    proj(xMin, -1.6, -25)
  ];
  fillPolygonWash(overhangTop, "#1c1612", 210);

  // Crisp meniscus water line where turquoise water meets the tile band
  let wL = proj(xMin, -8.5, -25);
  let wR = proj(xMax, -8.5, -25);
  brush.set("techPen", "#c4ebe8", 0.85);
  brush.line(wL[0], wL[1], wR[0], wR[1]);
}

// =========================================================================
// 3. CONCRETE POOL DECK & BULLNOSE COPING SLABS
// =========================================================================
function drawDeckAndCoping() {
  let xMin = -130;
  let xMax = 130;

  // --- A. MAIN CONCRETE POOL DECK (z = 0 to z = 110, y = 0) ---
  let deckPoly = [
    proj(xMin, 0, 0),
    proj(xMax, 0, 0),
    [1200, 1200],
    [0, 1200]
  ];

  // Warm sun-baked travertine / concrete earth tone base
  fillPolygonWash(deckPoly, "#d9cbb6", 245);
  fillPolygonWatercolor(deckPoly, "#cbb9a0", 80, 0.05, 0.45, 0.2);

  // Individual concrete slabs separated by expansion joints (z = 0..46, 46..105; x divisions at -44, 18, 80)
  let xJoints = [-125, -44, 18, 80, 135];
  let zJoints = [0, 48, 108];

  for (let rz = 0; rz < zJoints.length - 1; rz++) {
    for (let cx = 0; cx < xJoints.length - 1; cx++) {
      let x0 = xJoints[cx];
      let x1 = xJoints[cx + 1];
      let z0 = zJoints[rz];
      let z1 = zJoints[rz + 1];

      let slabPoly = [
        proj(x0, 0, z0),
        proj(x1, 0, z0),
        proj(x1, 0, z1),
        proj(x0, 0, z1)
      ];

      // Slight tonal variation per concrete slab
      let tones = ["#ded1bd", "#d4c5ae", "#d8cab4", "#cfc0a8"];
      let slabCol = tones[(rz * 3 + cx) % tones.length];
      fillPolygonWash(slabPoly, slabCol, 150);

      // Directional architectural marker grain parallel to pool edge
      let streakCol = (rz + cx) % 2 === 0 ? "#cbbba3" : "#e3d7c5";
      hatchPolygon(slabPoly, "archMarker", streakCol, 0.95, 16, -13, { rand: 0.015 });
      // Subtle cross-trowel pencil texture
      hatchPolygon(slabPoly, "2H", "#b8a68e", 0.45, 11, 68, { rand: 0.04 });
    }
  }

  // Concrete aggregate micro-speckles (spray + tiny pen pits)
  brush.set("spray", "#a8957d", 0.65);
  for (let i = 0; i < 45; i++) {
    let rx = random(-90, 95);
    let rz = random(3, 88);
    let p = proj(rx, 0, rz);
    brush.line(p[0], p[1], p[0] + random(15, 45), p[1] + random(-8, 8));
  }
  brush.set("spray", "#f2eadc", 0.55);
  for (let i = 0; i < 35; i++) {
    let rx = random(-90, 95);
    let rz = random(3, 88);
    let p = proj(rx, 0, rz);
    brush.line(p[0], p[1], p[0] + random(15, 40), p[1] + random(-6, 6));
  }

  // Tiny aggregate pores & pebbles across the concrete
  for (let i = 0; i < 280; i++) {
    let rx = random(-95, 100);
    let rz = random(2, 92);
    let p = proj(rx, 0, rz);
    if (p[0] > 0 && p[0] < 1200 && p[1] > 450 && p[1] < 1200) {
      brush.set("techPen", i % 3 === 0 ? "#806e5b" : "#b5a38d", 0.45);
      brush.line(p[0], p[1], p[0] + random(1.2, 3.0), p[1] + random(-0.8, 0.8));
    }
  }

  // Ruled Expansion Joints on Deck
  // Transverse joints (along Z)
  for (let j = 1; j < xJoints.length - 1; j++) {
    let xJ = xJoints[j];
    let p0 = proj(xJ, 0, 0);
    let p1 = proj(xJ, 0, 108);
    let p0L = proj(xJ - 0.5, 0, 0);
    let p1L = proj(xJ - 0.5, 0, 108);
    // Sunlit bevel edge
    brush.set("rotring", "#f5ede0", 0.85);
    brush.line(p0L[0], p0L[1], p1L[0], p1L[1]);
    // Mastic fill & sharp groove shadow
    brush.set("rotring", "#8c7864", 1.1);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
    brush.set("techPen", "#4d3e31", 0.75);
    brush.line(p0[0] + 1, p0[1], p1[0] + 1, p1[1]);
  }

  // Longitudinal expansion joint at z = 48
  let jL0 = proj(xMin, 0, 48);
  let jR0 = proj(xMax, 0, 48);
  let jL1 = proj(xMin, 0, 48.6);
  let jR1 = proj(xMax, 0, 48.6);
  brush.set("rotring", "#f6efe2", 0.95);
  brush.line(jL1[0], jL1[1], jR1[0], jR1[1]);
  brush.set("rotring", "#7d6a56", 1.2);
  brush.line(jL0[0], jL0[1], jR0[0], jR0[1]);
  brush.set("techPen", "#47392c", 0.85);
  brush.line(jL0[0], jL0[1] - 1.2, jR0[0], jR0[1] - 1.2);

  // Two delicate hairline concrete curing cracks observed in fine pen
  drawConcreteCrack([[ -12, 0, 48 ], [ -10, 0, 41 ], [ -13, 0, 34 ], [ -11, 0, 27 ], [ -14, 0, 22 ]]);
  drawConcreteCrack([[ 58, 0, 48 ], [ 61, 0, 56 ], [ 59, 0, 64 ], [ 63, 0, 72 ]]);

  // --- B. BULLNOSE POOL COPING STONES (z = -25 to z = 0, y = 2.2) ---
  // Front vertical step face at z = 0 (y from 0 to 2.2)
  let stepFace = [
    proj(xMin, 2.2, 0),
    proj(xMax, 2.2, 0),
    proj(xMax, 0, 0),
    proj(xMin, 0, 0)
  ];
  fillPolygonWash(stepFace, "#b5a38c", 240);
  strokePolygon(stepFace, "techPen", "#5e4e3e", 0.7, false);

  // Bullnose front lip at z = -25 (y from 0.6 to 2.2)
  let bullnoseLip = [
    proj(xMin, 2.2, -24.2),
    proj(xMax, 2.2, -24.2),
    proj(xMax, 0.6, -25),
    proj(xMin, 0.6, -25)
  ];
  fillPolygonWash(bullnoseLip, "#cab9a2", 245);

  // Individual precast bullnose coping slabs every 34 cm
  let copingDivs = [-126, -92, -58, -24, 10, 44, 78, 112, 140];
  for (let i = 0; i < copingDivs.length - 1; i++) {
    let cx0 = copingDivs[i] + 0.4;
    let cx1 = copingDivs[i + 1] - 0.4;

    let cTop = [
      proj(cx0, 2.2, -24.2),
      proj(cx1, 2.2, -24.2),
      proj(cx1, 2.2, 0),
      proj(cx0, 2.2, 0)
    ];

    let cTone = i % 2 === 0 ? "#ebe2d2" : "#e5dac8";
    fillPolygonWash(cTop, cTone, 245);
    hatchPolygon(cTop, "archMarker", "#dfd3bf", 0.85, 12, -13, { rand: 0.01 });
    hatchPolygon(cTop, "2H", "#c4b49d", 0.35, 9, -13, { rand: 0.02 });

    // Ruled hard edges of each coping stone
    strokePolygon(cTop, "techPen", "#8a7865", 0.65, true);

    // Mortar joint gap between coping stones
    let mx0 = copingDivs[i + 1] - 0.4;
    let mx1 = copingDivs[i + 1] + 0.4;
    let mortarPoly = [
      proj(mx0, 2.2, -25),
      proj(mx1, 2.2, -25),
      proj(mx1, 2.2, 0),
      proj(mx0, 2.2, 0)
    ];
    fillPolygonWash(mortarPoly, "#9e8c77", 235);
    let mp0 = proj(mx0, 2.2, -25);
    let mp1 = proj(mx0, 2.2, 0);
    brush.set("techPen", "#57483a", 0.75);
    brush.line(mp0[0], mp0[1], mp1[0], mp1[1]);
  }

  // Bright sunlit highlight line along the bullnose front ridge and step-up ridge
  let bnL = proj(xMin, 2.2, -24.2);
  let bnR = proj(xMax, 2.2, -24.2);
  brush.set("rotring", "#faf5eb", 1.1);
  brush.line(bnL[0], bnL[1], bnR[0], bnR[1]);

  let stL = proj(xMin, 2.2, 0);
  let stR = proj(xMax, 2.2, 0);
  brush.set("rotring", "#f7f0e4", 0.95);
  brush.line(stL[0], stL[1], stR[0], stR[1]);

  // Crisp shadow line at base of coping step (z = 0, y = 0)
  let sbL = proj(xMin, 0, 0);
  let sbR = proj(xMax, 0, 0);
  brush.set("rotring", "#544537", 0.9);
  brush.line(sbL[0], sbL[1], sbR[0], sbR[1]);
}

function drawConcreteCrack(pts3D) {
  for (let i = 0; i < pts3D.length - 1; i++) {
    let a = proj(pts3D[i][0], pts3D[i][1], pts3D[i][2]);
    let b = proj(pts3D[i + 1][0], pts3D[i + 1][1], pts3D[i + 1][2]);
    brush.set("techPen", "#f5ede0", 0.45);
    brush.line(a[0] + 0.8, a[1] + 0.5, b[0] + 0.8, b[1] + 0.5);
    brush.set("techPen", "#5c4c3e", 0.5);
    brush.line(a[0], a[1], b[0], b[1]);
  }
}

// =========================================================================
// 4. SLICE OF BREEZE-BLOCK WALL AT LEFT EDGE & ITS GEOMETRIC SHADOW
// =========================================================================
function drawBreezeBlockWallAndShadow() {
  // Wall sits on left deck from z = -4 to z = 56, x from -66 (inner sunlit face) to -76 (outer face)
  let xIn = -64;
  let xOut = -74;
  let zStart = -4;
  let blockLen = 20; // 3 columns of blocks: [-4..16], [16..36], [36..56]
  let blockH = 20;   // 4 courses tall: y = [0..20], [20..40], [40..60], [60..80]
  let cols = 3;
  let rows = 4;

  // --- A. BREEZE-BLOCK WALL NOON SHADOW ON DECK & COPING ---
  // Since sun is at SUN_DX = -0.36, the wall casts its shadow to the left (x < -64),
  // AND the front corner at z = 56 casts a crisp diagonal shadow back to z = 56 - 80*0.68 = 1.6!
  let shBase0 = proj(xIn, 0, zStart);
  let shBase1 = proj(xIn, 0, zStart + cols * blockLen);
  let shTop1 = shadowHitWorld(xIn, rows * blockH, zStart + cols * blockLen);
  let shTop0 = shadowHitWorld(xIn, rows * blockH, zStart);

  let wallShadowPoly = [
    shBase0,
    shBase1,
    proj(shTop1[0], shTop1[1], shTop1[2]),
    proj(shTop0[0], shTop0[1], shTop0[2])
  ];
  fillPolygonWash(wallShadowPoly, "#665749", 215);
  hatchPolygon(wallShadowPoly, "archMarker", "#54463a", 0.9, 10, -13, { rand: 0.01 });

  // Cutout light squares projected onto the deck inside the wall's shadow!
  for (let r = 0; r < 2; r++) {
    for (let c = 0; c < cols; c++) {
      let z0 = zStart + c * blockLen + 4.5;
      let z1 = zStart + (c + 1) * blockLen - 4.5;
      let y0 = r * blockH + 4.5;
      let y1 = (r + 1) * blockH - 4.5;

      let h00 = shadowHitWorld(xOut, y0, z0);
      let h10 = shadowHitWorld(xOut, y0, z1);
      let h11 = shadowHitWorld(xOut, y1, z1);
      let h01 = shadowHitWorld(xOut, y1, z0);

      let lightPatch = [
        proj(h00[0], h00[1], h00[2]),
        proj(h10[0], h10[1], h10[2]),
        proj(h11[0], h11[1], h11[2]),
        proj(h01[0], h01[1], h01[2])
      ];
      fillPolygonWash(lightPatch, "#dfd2be", 220);
      strokePolygon(lightPatch, "techPen", "#524438", 0.5, true);
    }
  }

  // --- B. RENDER 3D BREEZE BLOCKS (BACK-TO-FRONT BY Z AND Y) ---
  for (let c = 0; c < cols; c++) {
    let z0 = zStart + c * blockLen + 0.35;
    let z1 = zStart + (c + 1) * blockLen - 0.35;
    let zm = (z0 + z1) * 0.5;

    for (let r = 0; r < rows; r++) {
      let y0 = r * blockH + 0.35;
      let y1 = (r + 1) * blockH - 0.35;
      let ym = (y0 + y1) * 0.5;

      // 1. Recessed inner cavity depth (between xOut and xIn)
      // Bottom inner lip of cutout (catches warm sun!)
      let cavBot = [
        proj(xIn, y0 + 3.2, z0 + 3.2),
        proj(xIn, y0 + 3.2, z1 - 3.2),
        proj(xOut, y0 + 3.2, z1 - 3.2),
        proj(xOut, y0 + 3.2, z0 + 3.2)
      ];
      fillPolygonWash(cavBot, "#b58b6c", 240);

      // Rear inner wall of cutout (in deep shade)
      let cavRear = [
        proj(xIn, y0 + 3.2, z0 + 3.2),
        proj(xOut, y0 + 3.2, z0 + 3.2),
        proj(xOut, y1 - 3.2, z0 + 3.2),
        proj(xIn, y1 - 3.2, z0 + 3.2)
      ];
      fillPolygonWash(cavRear, "#593f2c", 245);

      // Diagonal decorative X-ribs inside each breeze-block aperture (depth from xIn to xOut)
      let rib1Side = [
        proj(xIn, y0 + 3.2, zm - 1.1),
        proj(xOut, y0 + 3.2, zm - 1.1),
        proj(xOut, y1 - 3.2, zm - 1.1),
        proj(xIn, y1 - 3.2, zm - 1.1)
      ];
      fillPolygonWash(rib1Side, "#6e4f38", 245);
      strokePolygon(rib1Side, "techPen", "#3d2a1c", 0.55, true);

      let rib2Top = [
        proj(xIn, ym + 1.1, z0 + 3.2),
        proj(xIn, ym + 1.1, z1 - 3.2),
        proj(xOut, ym + 1.1, z1 - 3.2),
        proj(xOut, ym + 1.1, z0 + 3.2)
      ];
      fillPolygonWash(rib2Top, "#c9a182", 245);
      strokePolygon(rib2Top, "techPen", "#4a3525", 0.55, true);

      // 2. Sunlit East/Right Face of the Breeze Block (at x = xIn)
      // Frame border strips + central cross/diamond web
      let topBar = [
        proj(xIn, y1, z0),
        proj(xIn, y1, z1),
        proj(xIn, y1 - 3.2, z1),
        proj(xIn, y1 - 3.2, z0)
      ];
      let botBar = [
        proj(xIn, y0 + 3.2, z0),
        proj(xIn, y0 + 3.2, z1),
        proj(xIn, y0, z1),
        proj(xIn, y0, z0)
      ];
      let backBar = [
        proj(xIn, y1 - 3.2, z0),
        proj(xIn, y1 - 3.2, z0 + 3.2),
        proj(xIn, y0 + 3.2, z0 + 3.2),
        proj(xIn, y0 + 3.2, z0)
      ];
      let frontBar = [
        proj(xIn, y1 - 3.2, z1 - 3.2),
        proj(xIn, y1 - 3.2, z1),
        proj(xIn, y0 + 3.2, z1),
        proj(xIn, y0 + 3.2, z1 - 3.2)
      ];
      let vRib = [
        proj(xIn, y1 - 3.2, zm - 1.2),
        proj(xIn, y1 - 3.2, zm + 1.2),
        proj(xIn, y0 + 3.2, zm + 1.2),
        proj(xIn, y0 + 3.2, zm - 1.2)
      ];
      let hRib = [
        proj(xIn, ym + 1.2, z0 + 3.2),
        proj(xIn, ym + 1.2, z1 - 3.2),
        proj(xIn, ym - 1.2, z1 - 3.2),
        proj(xIn, ym - 1.2, z0 + 3.2)
      ];
      // Center diamond boss
      let diamond = [
        proj(xIn, ym + 4.2, zm),
        proj(xIn, ym, zm + 4.2),
        proj(xIn, ym - 4.2, zm),
        proj(xIn, ym, zm - 4.2)
      ];

      let blockCol = (r + c) % 2 === 0 ? "#d4af91" : "#cca485";
      for (let part of [topBar, botBar, backBar, frontBar, vRib, hRib, diamond]) {
        fillPolygonWash(part, blockCol, 245);
        hatchPolygon(part, "2H", "#a88264", 0.35, 7, 85, { rand: 0.03 });
      }

      // Crisp ruled technical pen outlines for the block face and its 4 geometric cutouts
      let outerFace = [
        proj(xIn, y1, z0),
        proj(xIn, y1, z1),
        proj(xIn, y0, z1),
        proj(xIn, y0, z0)
      ];
      strokePolygon(outerFace, "rotring", "#543b28", 0.75, true);
      strokePolygon(diamond, "techPen", "#543b28", 0.65, true);

      // 4 cutout inner perimeters
      let qZ = [[z0 + 3.2, zm - 1.2], [zm + 1.2, z1 - 3.2]];
      let qY = [[y0 + 3.2, ym - 1.2], [ym + 1.2, y1 - 3.2]];
      for (let iz = 0; iz < 2; iz++) {
        for (let iy = 0; iy < 2; iy++) {
          let hole = [
            proj(xIn, qY[iy][1], qZ[iz][0]),
            proj(xIn, qY[iy][1], qZ[iz][1]),
            proj(xIn, qY[iy][0], qZ[iz][1]),
            proj(xIn, qY[iy][0], qZ[iz][0])
          ];
          strokePolygon(hole, "rotring", "#473120", 0.7, true);
        }
      }

      // 3. If this is the frontmost column (c === cols - 1), draw the shaded front end-wall at z = z1
      if (c === cols - 1) {
        let endFace = [
          proj(xOut, y1, z1),
          proj(xIn, y1, z1),
          proj(xIn, y0, z1),
          proj(xOut, y0, z1)
        ];
        fillPolygonWash(endFace, "#967053", 250);
        hatchPolygon(endFace, "archMarker", "#7d5b41", 0.85, 8, 88, { rand: 0.02 });
        hatchPolygon(endFace, "2B", "#5e432e", 0.4, 6, 15, { rand: 0.04 });
        strokePolygon(endFace, "rotring", "#3d2a1b", 0.8, true);

        // Bright sunlit vertical corner arris at (xIn, z1)
        let cTop = proj(xIn, y1, z1);
        let cBot = proj(xIn, y0, z1);
        brush.set("rotring", "#f5e6d3", 1.0);
        brush.line(cTop[0], cTop[1], cBot[0], cBot[1]);
      }
    }
  }

  // Mortar bed joints between courses
  for (let r = 1; r < rows; r++) {
    let ym = r * blockH;
    let m0 = proj(xIn, ym, zStart);
    let m1 = proj(xIn, ym, zStart + cols * blockLen);
    let m2 = proj(xOut, ym, zStart + cols * blockLen);
    brush.set("rotring", "#634833", 1.1);
    brush.line(m0[0], m0[1], m1[0], m1[1]);
    brush.line(m1[0], m1[1], m2[0], m2[1]);
  }
}

// =========================================================================
// 5. RAZOR-SHARP NOON SHADOW OF THE LAWN CHAIR ACROSS THE COPING
// =========================================================================
function drawChairShadow() {
  // Helper to project a 3D quad in chair-local coords onto the stepped deck/coping shadow surface
  function getShadowQuadPts(p0, p1, p2, p3, subdiv = 8) {
    let poly = [];
    let edges = [[p0, p1], [p1, p2], [p2, p3], [p3, p0]];
    for (let e of edges) {
      for (let s = 0; s < subdiv; s++) {
        let pt = lerp3D(e[0], e[1], s / subdiv);
        let sp = projChairShadow(pt[0], pt[1], pt[2]);
        poly.push([sp[0], sp[1]]);
      }
    }
    return poly;
  }

  // Helper to draw a tubular frame member's shadow
  function drawTubeShadow(ptsLocal, halfW) {
    for (let i = 0; i < ptsLocal.length - 1; i++) {
      let a = ptsLocal[i];
      let b = ptsLocal[i + 1];
      let q = getShadowQuadPts(
        [a[0] - halfW, a[1], a[2] - halfW * 0.5],
        [a[0] + halfW, a[1], a[2] + halfW * 0.5],
        [b[0] + halfW, b[1], b[2] + halfW * 0.5],
        [b[0] - halfW, b[1], b[2] - halfW * 0.5],
        4
      );
      fillPolygonWash(q, "#5c4d40", 230);
      strokePolygon(q, "techPen", "#42362c", 0.55, true);
    }
  }

  let W = 20.5;

  // --- A. SHADOW OF SEAT WEBBING STRAPS ---
  let seatXCenters = [-14.0, -7.0, 0.0, 7.0, 14.0];
  let seatZCenters = [-8.5, -1.2, 6.1, 13.4];
  let sw = 2.55; // half-width of 5.1cm strap

  // 5 Longitudinal Seat Straps
  for (let i = 0; i < 5; i++) {
    let xc = seatXCenters[i];
    let q = getShadowQuadPts(
      [xc - sw, 24.5, -13.5],
      [xc + sw, 24.5, -13.5],
      [xc + sw, 26.5, 20.5],
      [xc - sw, 26.5, 20.5],
      10
    );
    fillPolygonWash(q, "#615143", 210);
    hatchPolygon(q, "archMarker", "#524437", 0.8, 9, -13, { rand: 0.01 });
    strokePolygon(q, "techPen", "#42362b", 0.5, true);
  }

  // 4 Transverse Seat Straps
  for (let j = 0; j < 4; j++) {
    let zc = seatZCenters[j];
    let yc = map(zc, -13.5, 20.5, 24.5, 26.5);
    let q = getShadowQuadPts(
      [-19.3, yc, zc - sw],
      [19.3, yc, zc - sw],
      [19.3, yc, zc + sw],
      [-19.3, yc, zc + sw],
      10
    );
    fillPolygonWash(q, "#57483b", 215);
    strokePolygon(q, "techPen", "#3d3127", 0.5, true);
  }

  // --- B. SHADOW OF BACKREST WEBBING STRAPS (CAST RIGHT ACROSS THE COPING!) ---
  let backT = [0.16, 0.39, 0.62, 0.85];
  // Backrest plane goes from (ly=26.5, lz=-13.8) at t=0 to (ly=63.5, lz=-24.0) at t=1
  function backPt(lx, t) {
    return [lx, 26.5 + t * 37.0, -13.8 - t * 10.2];
  }

  // 5 Vertical Backrest Straps
  for (let i = 0; i < 5; i++) {
    let xc = seatXCenters[i];
    let b0 = backPt(xc - sw, 0);
    let b1 = backPt(xc + sw, 0);
    let t1 = backPt(xc + sw, 1);
    let t0 = backPt(xc - sw, 1);
    let q = getShadowQuadPts(b0, b1, t1, t0, 12);
    // Notice top portion hits water (-25), main portion hits coping and deck!
    fillPolygonWash(q, "#594a3d", 215);
    hatchPolygon(q, "archMarker", "#4a3d31", 0.8, 9, -13, { rand: 0.01 });
    strokePolygon(q, "techPen", "#3b3026", 0.55, true);
  }

  // 4 Horizontal Backrest Straps
  let dt = 0.068;
  for (let j = 0; j < 4; j++) {
    let tc = backT[j];
    let b0 = backPt(-19.3, tc - dt);
    let b1 = backPt(19.3, tc - dt);
    let t1 = backPt(19.3, tc + dt);
    let t0 = backPt(-19.3, tc + dt);
    let q = getShadowQuadPts(b0, b1, t1, t0, 12);
    fillPolygonWash(q, "#4f4135", 220);
    strokePolygon(q, "techPen", "#382d24", 0.55, true);
  }

  // --- C. SHADOW OF TUBULAR FRAME & ARMRESTS ---
  for (let side of [-1, 1]) {
    let sx = side * W;
    // Leg loop shadow
    drawTubeShadow([
      [sx, 39, 18], [sx, 3, 17], [sx, 0.5, 14.5],
      [sx, 0.5, -13.5], [sx, 3, -16], [sx, 39, -11]
    ], 1.1);

    // Armrest shadow (wider flat bar)
    let armQ = getShadowQuadPts(
      [sx - 1.7, 39.5, -18.5],
      [sx + 1.7, 39.5, -18.5],
      [sx + 1.7, 39.5, 20.5],
      [sx - 1.7, 39.5, 20.5],
      10
    );
    fillPolygonWash(armQ, "#4a3c30", 235);
    strokePolygon(armQ, "techPen", "#362b22", 0.65, true);
  }

  // Seat U-frame & Backrest U-frame shadows
  drawTubeShadow([
    [-19.3, 24.5, -13.5], [-19.3, 26.5, 19], [-16, 26.5, 20.5],
    [16, 26.5, 20.5], [19.3, 26.5, 19], [19.3, 24.5, -13.5]
  ], 1.1);

  drawTubeShadow([
    [-19.3, 19, -11], [-19.3, 61, -23.3], [-16, 63.5, -24],
    [16, 63.5, -24], [19.3, 61, -23.3], [19.3, 19, -11]
  ], 1.1);

  // Re-strike the coping step highlight/shadow line where the chair shadow crosses z = 0 and z = -24.2
  // so the architectural step remains razor-sharp inside the cast shadow
  let stL = proj(-20, 2.2, 0);
  let stR = proj(45, 2.2, 0);
  brush.set("techPen", "#33281f", 0.85);
  brush.line(stL[0], stL[1], stR[0], stR[1]);

  let bnL = proj(-25, 2.2, -24.2);
  let bnR = proj(35, 2.2, -24.2);
  brush.set("techPen", "#33281f", 0.85);
  brush.line(bnL[0], bnL[1], bnR[0], bnR[1]);
}

// =========================================================================
// 6. THE FOLDING ALUMINIUM LAWN CHAIR (TUBING, WEBBING, SCUFFS & FRAYING)
// =========================================================================

// Render a 3D cylindrical aluminium tube with specular highlight, core shadow, bounce light & scuffs
function drawAluminiumTube3D(ptsLocal, radiusPx = 7.2, scuffSeed = 10) {
  let pts2D = ptsLocal.map(p => projChair(p[0], p[1], p[2]));
  if (pts2D.length < 2) return;

  // Compute smooth unit normals at each vertex in 2D screen space
  let normals = [];
  for (let i = 0; i < pts2D.length; i++) {
    let pPrev = pts2D[Math.max(0, i - 1)];
    let pNext = pts2D[Math.min(pts2D.length - 1, i + 1)];
    let tx = pNext[0] - pPrev[0];
    let ty = pNext[1] - pPrev[1];
    let len = Math.hypot(tx, ty) || 1;
    // Normal pointing towards top-left (sunlit side)
    let nx = -ty / len;
    let ny = tx / len;
    if (ny > 0.2 || (Math.abs(ny) <= 0.2 && nx > 0)) {
      nx = -nx;
      ny = -ny;
    }
    normals.push([nx, ny]);
  }

  function buildStrip(o1, o2) {
    let poly = [];
    for (let i = 0; i < pts2D.length; i++) {
      poly.push([
        pts2D[i][0] + normals[i][0] * radiusPx * o1,
        pts2D[i][1] + normals[i][1] * radiusPx * o1
      ]);
    }
    for (let i = pts2D.length - 1; i >= 0; i--) {
      poly.push([
        pts2D[i][0] + normals[i][0] * radiusPx * o2,
        pts2D[i][1] + normals[i][1] * radiusPx * o2
      ]);
    }
    return poly;
  }

  // 1. Full aluminium body base wash (oxidized warm silver)
  let fullPoly = buildStrip(-1.0, 1.0);
  fillPolygonWash(fullPoly, "#ccc6bc", 250);

  // 2. Warm concrete deck bounce light strip along the shaded edge (+0.55 to +1.0)
  let bouncePoly = buildStrip(0.55, 1.0);
  fillPolygonWash(bouncePoly, "#d6c8b4", 230);

  // 3. Dark metallic core reflection band (+0.05 to +0.62)
  let corePoly = buildStrip(0.05, 0.62);
  fillPolygonWash(corePoly, "#70695f", 235);

  // 4. Midtone brushed anodized band (-0.35 to +0.08)
  let midPoly = buildStrip(-0.35, 0.08);
  fillPolygonWash(midPoly, "#b5afa4", 220);

  // 5. Crisp noon sun specular highlight ribbon (-0.78 to -0.32)
  let specPoly = buildStrip(-0.78, -0.32);
  fillPolygonWash(specPoly, "#faf7ef", 250);

  // 6. Ruled hard outer edges in technical pen
  let sunEdge = [];
  let shadeEdge = [];
  let specLine = [];
  for (let i = 0; i < pts2D.length; i++) {
    sunEdge.push([
      pts2D[i][0] - normals[i][0] * radiusPx,
      pts2D[i][1] - normals[i][1] * radiusPx
    ]);
    shadeEdge.push([
      pts2D[i][0] + normals[i][0] * radiusPx,
      pts2D[i][1] + normals[i][1] * radiusPx
    ]);
    specLine.push([
      pts2D[i][0] - normals[i][0] * radiusPx * 0.55,
      pts2D[i][1] - normals[i][1] * radiusPx * 0.55
    ]);
  }
  strokePolygon(sunEdge, "techPen", "#6e675d", 0.65, false);
  strokePolygon(shadeEdge, "rotring", "#332e29", 0.85, false);
  strokePolygon(specLine, "techPen", "#ffffff", 0.7, false);

  // 7. Precisely observed surface scuffs, oxidation pits & folding friction scratches
  for (let i = 0; i < pts2D.length - 1; i++) {
    let a = pts2D[i];
    let b = pts2D[i + 1];
    let segLen = Math.hypot(b[0] - a[0], b[1] - a[1]);
    let numScuffs = Math.floor(segLen / 18);
    let n = normals[i];

    for (let s = 0; s < numScuffs; s++) {
      let h = noise(scuffSeed + i * 3.1 + s * 7.3);
      if (h > 0.36) {
        let t = (s + 0.25 + (h * 10) % 0.5) / Math.max(1, numScuffs);
        let cx = a[0] + (b[0] - a[0]) * t;
        let cy = a[1] + (b[1] - a[1]) * t;
        let s0 = (noise(scuffSeed + s * 13) - 0.6) * radiusPx * 0.85;
        let s1 = s0 + radiusPx * (0.45 + (h * 7) % 0.55);

        // Dark scratch groove across tube curvature
        brush.set("techPen", "#453e37", 0.5);
        brush.line(cx + n[0] * s0, cy + n[1] * s0, cx + n[0] * s1, cy + n[1] * s1);
        // Tiny bright burr catch beside scratch
        brush.set("techPen", "#fcfaf2", 0.45);
        brush.line(
          cx + n[0] * s0 + 0.9,
          cy + n[1] * s0 + 0.9,
          cx + n[0] * s1 + 0.9,
          cy + n[1] * s1 + 0.9
        );
      }
    }
  }
}

function drawRivet2D(x, y, r = 3.2) {
  let pts = [];
  for (let a = 0; a < 360; a += 45) {
    let rad = a * Math.PI / 180;
    pts.push([x + Math.cos(rad) * r, y + Math.sin(rad) * r]);
  }
  fillPolygonWash(pts, "#d9d3c7", 250);
  // Crescent cast shadow under dome rivet
  brush.set("rotring", "#2e2722", 0.85);
  brush.line(x - r * 0.7, y + r * 0.7, x + r * 0.8, y + r * 0.5);
  brush.line(x + r * 0.8, y + r * 0.5, x + r * 0.6, y - r * 0.6);
  strokePolygon(pts, "techPen", "#474038", 0.6, true);
  // Bright dome specular dot
  brush.set("techPen", "#ffffff", 0.9);
  brush.line(x - r * 0.45, y - r * 0.35, x - r * 0.05, y - r * 0.35);
}

// Helper to generate smooth 3D rounded corners
function buildRoundedPath3D(corners, radius, steps = 5) {
  let out = [corners[0]];
  for (let i = 1; i < corners.length - 1; i++) {
    let pPrev = corners[i - 1];
    let pCurr = corners[i];
    let pNext = corners[i + 1];

    let v1 = [pPrev[0] - pCurr[0], pPrev[1] - pCurr[1], pPrev[2] - pCurr[2]];
    let v2 = [pNext[0] - pCurr[0], pNext[1] - pCurr[1], pNext[2] - pCurr[2]];
    let l1 = Math.hypot(v1[0], v1[1], v1[2]) || 1;
    let l2 = Math.hypot(v2[0], v2[1], v2[2]) || 1;
    let r = Math.min(radius, l1 * 0.45, l2 * 0.45);

    let startPt = [pCurr[0] + (v1[0] / l1) * r, pCurr[1] + (v1[1] / l1) * r, pCurr[2] + (v1[2] / l1) * r];
    let endPt = [pCurr[0] + (v2[0] / l2) * r, pCurr[1] + (v2[1] / l2) * r, pCurr[2] + (v2[2] / l2) * r];

    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let a = lerp3D(startPt, pCurr, t);
      let b = lerp3D(pCurr, endPt, t);
      out.push(lerp3D(a, b, t));
    }
  }
  out.push(corners[corners.length - 1]);
  return out;
}

// Draw a woven polypropylene webbing patch with warp ribs, weft grain, selvage stripes & frayed strands
function drawWebbingPatch3D(p00, p10, p11, p01, isTangerine, isLongitudinal, addFray = true, seed = 1) {
  let s00 = projChair(p00[0], p00[1], p00[2]);
  let s10 = projChair(p10[0], p10[1], p10[2]);
  let s11 = projChair(p11[0], p11[1], p11[2]);
  let s01 = projChair(p01[0], p01[1], p01[2]);

  let poly = [
    [s00[0], s00[1]],
    [s10[0], s10[1]],
    [s11[0], s11[1]],
    [s01[0], s01[1]]
  ];

  // Palette for Sun-Baked Tangerine vs Warm Bleached Cream-White
  let baseCol = isTangerine ? "#d95722" : "#efe8d8";
  let crownCol = isTangerine ? "#eb713b" : "#faf5ea";
  let stripeCol = isTangerine ? "#b03b0c" : "#d4c8b4";
  let ribCol = isTangerine ? "#9e3308" : "#c4b7a1";
  let edgeCol = isTangerine ? "#6e2104" : "#786c5b";

  // 1. Flat saturated marker base
  fillPolygonWash(poly, baseCol, 250);

  // 2. Arched sunlit crown highlight in the middle of the over-weave patch
  let c00 = lerp2D(poly[0], poly[3], 0.22);
  let c10 = lerp2D(poly[1], poly[2], 0.22);
  let c11 = lerp2D(poly[1], poly[2], 0.78);
  let c01 = lerp2D(poly[0], poly[3], 0.78);
  fillPolygonWash([c00, c10, c11, c01], crownCol, 155);

  // 3. Longitudinal warp threads & classic dual selvage stripes along the strap edges
  // Notice: p00->p01 and p10->p11 are the two side edges of the strap segment
  let ribs = 7;
  for (let r = 1; r < ribs; r++) {
    let u = r / ribs;
    let a = lerp2D(poly[0], poly[1], u);
    let b = lerp2D(poly[3], poly[2], u);
    let isSelvage = (r === 1 || r === ribs - 1);
    brush.set("techPen", isSelvage ? stripeCol : ribCol, isSelvage ? 0.65 : 0.38);
    brush.line(a[0], a[1], b[0], b[1]);
  }

  // 4. Transverse polypropylene weave texture (weft)
  let wefts = 6;
  for (let w = 1; w < wefts; w++) {
    let v = w / wefts;
    let a = lerp2D(poly[0], poly[3], v);
    let b = lerp2D(poly[1], poly[2], v);
    brush.set("techPen", ribCol, 0.32);
    brush.line(a[0], a[1], b[0], b[1]);
  }

  // 5. Ruled hard edges along the two sides of the strap
  brush.set("rotring", edgeCol, 0.7);
  brush.line(poly[0][0], poly[0][1], poly[3][0], poly[3][1]);
  brush.line(poly[1][0], poly[1][1], poly[2][0], poly[2][1]);

  // Subtle crease line at ends where the adjacent perpendicular strap crosses over
  brush.set("techPen", edgeCol, 0.45);
  brush.line(poly[0][0], poly[0][1], poly[1][0], poly[1][1]);
  brush.line(poly[3][0], poly[3][1], poly[2][0], poly[2][1]);

  // 6. Precisely observed fraying web strands along the strap edges
  if (addFray && noise(seed * 4.7) > 0.34) {
    let side = noise(seed * 9.1) > 0.5 ? 0 : 1;
    let eStart = side === 0 ? poly[0] : poly[1];
    let eEnd = side === 0 ? poly[3] : poly[2];
    let outDir = side === 0
      ? [poly[0][0] - poly[1][0], poly[0][1] - poly[1][1]]
      : [poly[1][0] - poly[0][0], poly[1][1] - poly[0][1]];
    let dLen = Math.hypot(outDir[0], outDir[1]) || 1;
    let nx = outDir[0] / dLen;
    let ny = outDir[1] / dLen;

    let numThreads = 1 + Math.floor(noise(seed * 13.3) * 3);
    for (let f = 0; f < numThreads; f++) {
      let t = 0.2 + ((seed * 0.19 + f * 0.31) % 0.65);
      let fx = eStart[0] + (eEnd[0] - eStart[0]) * t;
      let fy = eStart[1] + (eEnd[1] - eStart[1]) * t;

      // Tiny frayed notch on strap edge
      brush.set("techPen", "#4a382b", 0.55);
      brush.line(fx - nx * 1.5, fy - ny * 1.5, fx + nx * 1.0, fy + ny * 1.0);

      // Curled polypropylene filament sticking out + its tiny 1.5px dark shadow
      let fLen = 4.5 + noise(seed + f * 5) * 7.5;
      let curlX = fx + nx * fLen + (noise(seed + f * 11) - 0.5) * 6;
      let curlY = fy + ny * fLen + (noise(seed + f * 17) - 0.5) * 6;
      let tipX = curlX + (noise(seed + f * 23) - 0.5) * 5;
      let tipY = curlY + (noise(seed + f * 29) - 0.3) * 5;

      // Filament cast shadow
      brush.set("techPen", "#382b20", 0.42);
      brush.line(fx + 1.5, fy + 2.2, curlX + 1.5, curlY + 2.2);
      brush.line(curlX + 1.5, curlY + 2.2, tipX + 1.5, tipY + 2.2);

      // Sunlit frayed filament (bright tangerine-orange or cream-white)
      let threadCol = isTangerine ? "#ff915c" : "#fcf8f0";
      brush.set("techPen", threadCol, 0.52);
      brush.line(fx, fy, curlX, curlY);
      brush.line(curlX, curlY, tipX, tipY);
    }
  }
}

// Draw the folded wrap of a strap around an aluminium frame tube
function drawStrapTubeWrap3D(pA0, pA1, pB0, pB1, isTangerine, seed = 1) {
  let sA0 = projChair(pA0[0], pA0[1], pA0[2]);
  let sA1 = projChair(pA1[0], pA1[1], pA1[2]);
  let sB1 = projChair(pB1[0], pB1[1], pB1[2]);
  let sB0 = projChair(pB0[0], pB0[1], pB0[2]);

  let poly = [
    [sA0[0], sA0[1]],
    [sA1[0], sA1[1]],
    [sB1[0], sB1[1]],
    [sB0[0], sB0[1]]
  ];

  let baseCol = isTangerine ? "#e05f28" : "#f4ede0";
  let crownCol = isTangerine ? "#f58553" : "#ffffff";
  let shadowCol = isTangerine ? "#822805" : "#9c8f7b";
  let edgeCol = isTangerine ? "#5e1c03" : "#665b4b";

  fillPolygonWash(poly, baseCol, 250);

  // Specular highlight band across the bent strap knuckle
  let m0 = lerp2D(poly[0], poly[3], 0.35);
  let m1 = lerp2D(poly[1], poly[2], 0.35);
  let m2 = lerp2D(poly[1], poly[2], 0.68);
  let m3 = lerp2D(poly[0], poly[3], 0.68);
  fillPolygonWash([m0, m1, m2, m3], crownCol, 185);

  // Warp thread lines around bend
  for (let r = 1; r < 6; r++) {
    let u = r / 6;
    let a = lerp2D(poly[0], poly[1], u);
    let b = lerp2D(poly[3], poly[2], u);
    brush.set("techPen", shadowCol, 0.4);
    brush.line(a[0], a[1], b[0], b[1]);
  }

  strokePolygon(poly, "rotring", edgeCol, 0.7, true);

  // Metal V-clip / rivet edge peeking at inner crease
  let clip0 = lerp2D(poly[0], poly[1], 0.25);
  let clip1 = lerp2D(poly[0], poly[1], 0.75);
  brush.set("techPen", "#474039", 0.75);
  brush.line(clip0[0], clip0[1], clip1[0], clip1[1]);
}

function drawFoldingLawnChair() {
  let W = 20.5;
  let seatX = [-14.0, -7.0, 0.0, 7.0, 14.0];
  let seatZ = [-8.5, -1.2, 6.1, 13.4];
  let sw = 2.55; // half-width of 5.1cm strap

  // --- 1. LEFT GROUND LEG U-LOOP (FURTHER SIDE, lx = -20.5) ---
  let leftLegPts = buildRoundedPath3D([
    [-W, 39.2, 18.2],
    [-W, 1.2, 17.0],
    [-W, 1.2, -15.5],
    [-W, 39.2, -10.8]
  ], 3.8, 5);
  drawAluminiumTube3D(leftLegPts, 6.8, 101);

  // Black/charcoal ribbed rubber foot caps on left ground runner
  drawFootCap3D([-W, 1.2, 11.5], [-W, 1.2, 15.2], 7.6);
  drawFootCap3D([-W, 1.2, -14.0], [-W, 1.2, -10.2], 7.6);

  // Left folding diagonal aluminium flat strut
  drawFlatStrut3D([-19.9, 13.5, 16.5], [-19.9, 25.5, 2.5], 4.8);

  // --- 2. REAR SEAT SPREADER BAR & LOWER BACKREST CROSSBAR ---
  drawAluminiumTube3D([[-19.3, 24.5, -13.5], [19.3, 24.5, -13.5]], 6.4, 150);
  drawAluminiumTube3D([[-19.3, 26.8, -14.0], [19.3, 26.8, -14.0]], 6.2, 160);

  // --- 3. SEAT FRAME U-TUBE ---
  let seatFramePts = buildRoundedPath3D([
    [-19.3, 24.5, -13.5],
    [-19.3, 26.5, 20.5],
    [19.3, 26.5, 20.5],
    [19.3, 24.5, -13.5]
  ], 4.2, 6);
  drawAluminiumTube3D(seatFramePts, 7.2, 202);

  // --- 4. BACKREST FRAME U-TUBE ---
  let backFramePts = buildRoundedPath3D([
    [-19.3, 18.5, -11.2],
    [-19.3, 63.5, -24.0],
    [19.3, 63.5, -24.0],
    [19.3, 18.5, -11.2]
  ], 4.5, 6);
  drawAluminiumTube3D(backFramePts, 7.2, 303);

  // --- 5. WOVEN SEAT WEBBING (5 LONGITUDINAL x 4 TRANSVERSE BASKETWEAVE) ---
  // Helper for seat 3D coordinates with subtle body-weight sag in center
  function seatPt(lx, lz, lift = 0) {
    let u = (lz - (-13.5)) / (20.5 - (-13.5)); // 0 at rear, 1 at front
    let baseLy = 24.5 + u * 2.0;
    // Slight natural tension sag in middle of seat
    let sag = Math.sin(u * Math.PI) * (1 - Math.pow(lx / 20.0, 2)) * 0.9;
    return [lx, baseLy - sag + lift, lz];
  }

  // Longitudinal colors: [Tangerine, White, Tangerine, White, Tangerine]
  // Transverse colors: [White, Tangerine, White, Tangerine]
  let zKnots = [-13.5, -8.5 - sw, -8.5 + sw, -1.2 - sw, -1.2 + sw, 6.1 - sw, 6.1 + sw, 13.4 - sw, 13.4 + sw, 20.5];
  let xKnots = [-19.3, -14.0 - sw, -14.0 + sw, -7.0 - sw, -7.0 + sw, -sw, sw, 7.0 - sw, 7.0 + sw, 14.0 - sw, 14.0 + sw, 19.3];

  // Pass 5A: Draw all Longitudinal Seat Straps
  for (let i = 0; i < 5; i++) {
    let xc = seatX[i];
    let isTang = (i % 2 === 0);
    for (let kz = 0; kz < zKnots.length - 1; kz++) {
      let zA = zKnots[kz];
      let zB = zKnots[kz + 1];
      // Check if this segment is at a transverse intersection (kz = 1, 3, 5, 7)
      let jCross = (kz % 2 === 1) ? Math.floor(kz / 2) : -1;
      let isOver = (jCross === -1) || ((i + jCross) % 2 === 0);
      let lift = (jCross !== -1) ? (isOver ? 0.38 : -0.25) : 0.08;

      drawWebbingPatch3D(
        seatPt(xc - sw, zA, lift),
        seatPt(xc + sw, zA, lift),
        seatPt(xc + sw, zB, lift),
        seatPt(xc - sw, zB, lift),
        isTang,
        true,
        isOver,
        400 + i * 31 + kz * 7
      );
    }

    // Wrap around front seat rail (z = 20.5) & rear bar (z = -13.5)
    drawStrapTubeWrap3D(
      [xc - sw, 26.8, 19.8], [xc + sw, 26.8, 19.8],
      [xc - sw, 25.4, 21.3], [xc + sw, 25.4, 21.3],
      isTang, 500 + i
    );
    drawStrapTubeWrap3D(
      [xc - sw, 24.8, -12.9], [xc + sw, 24.8, -12.9],
      [xc - sw, 24.2, -14.2], [xc + sw, 24.2, -14.2],
      isTang, 520 + i
    );
  }

  // Pass 5B: Draw Transverse Seat Straps (and cast shadows at over/under crossings)
  for (let j = 0; j < 4; j++) {
    let zc = seatZ[j];
    let isTang = (j % 2 === 1); // [White, Tangerine, White, Tangerine]
    for (let kx = 0; kx < xKnots.length - 1; kx++) {
      let xA = xKnots[kx];
      let xB = xKnots[kx + 1];
      let iCross = (kx % 2 === 1) ? Math.floor(kx / 2) : -1;
      let transOver = (iCross === -1) || ((iCross + j) % 2 === 1);

      if (transOver) {
        let lift = (iCross !== -1) ? 0.42 : 0.12;
        drawWebbingPatch3D(
          seatPt(xA, zc - sw, lift),
          seatPt(xA, zc + sw, lift),
          seatPt(xB, zc + sw, lift),
          seatPt(xB, zc - sw, lift),
          isTang,
          false,
          true,
          600 + j * 41 + kx * 9
        );

        // If crossing over longitudinal strap iCross, cast a sharp shadow onto the longitudinal strap!
        if (iCross !== -1) {
          let shA = seatPt(xA, zc - sw - 0.9, 0.05);
          let shB = seatPt(xB, zc - sw - 0.9, 0.05);
          let shC = seatPt(xB, zc - sw, 0.05);
          let shD = seatPt(xA, zc - sw, 0.05);
          let pSh = [shA, shB, shC, shD].map(p => projChair(p[0], p[1], p[2]));
          fillPolygonWash(pSh, (iCross % 2 === 0) ? "#7d2505" : "#9c8e79", 210);
        }
      } else {
        // Longitudinal strap iCross is OVER this transverse strap -> cast shadow on transverse strap edges
        let shL0 = seatPt(xA - 0.8, zc - sw, 0.05);
        let shL1 = seatPt(xA, zc - sw, 0.05);
        let shL2 = seatPt(xA, zc + sw, 0.05);
        let shL3 = seatPt(xA - 0.8, zc + sw, 0.05);
        let pShL = [shL0, shL1, shL2, shL3].map(p => projChair(p[0], p[1], p[2]));
        fillPolygonWash(pShL, isTang ? "#7d2505" : "#9c8e79", 215);
      }
    }

    // Wrap around left and right seat rails (lx = -19.3 and +19.3)
    let yRail = seatPt(-19.3, zc, 0)[1];
    drawStrapTubeWrap3D(
      [-18.6, yRail + 0.3, zc - sw], [-18.6, yRail + 0.3, zc + sw],
      [-20.1, yRail - 0.4, zc - sw], [-20.1, yRail - 0.4, zc + sw],
      isTang, 650 + j
    );
    drawStrapTubeWrap3D(
      [18.6, yRail + 0.3, zc - sw], [18.6, yRail + 0.3, zc + sw],
      [20.1, yRail - 0.4, zc - sw], [20.1, yRail - 0.4, zc + sw],
      isTang, 670 + j
    );
  }

  // --- 6. WOVEN BACKREST WEBBING (5 VERTICAL x 4 HORIZONTAL BASKETWEAVE) ---
  let backTCenters = [0.16, 0.39, 0.62, 0.85];
  let dt = 0.068; // half-width of strap in t-space (approx 5.1cm)
  let tKnots = [
    0.0,
    backTCenters[0] - dt, backTCenters[0] + dt,
    backTCenters[1] - dt, backTCenters[1] + dt,
    backTCenters[2] - dt, backTCenters[2] + dt,
    backTCenters[3] - dt, backTCenters[3] + dt,
    1.0
  ];

  function backrestPt(lx, t, lift = 0) {
    // Normal to backrest leans forward (+z, +y)
    let ly = 26.8 + t * 36.7 + lift * 0.26;
    let lz = -14.0 - t * 10.0 + lift * 0.96;
    return [lx, ly, lz];
  }

  // Pass 6A: Draw all 5 Vertical Backrest Straps
  for (let i = 0; i < 5; i++) {
    let xc = seatX[i];
    let isTang = (i % 2 === 0); // [Tangerine, White, Tangerine, White, Tangerine]
    for (let kt = 0; kt < tKnots.length - 1; kt++) {
      let tA = tKnots[kt];
      let tB = tKnots[kt + 1];
      let jCross = (kt % 2 === 1) ? Math.floor(kt / 2) : -1;
      let isOver = (jCross === -1) || ((i + jCross) % 2 === 0);
      let lift = (jCross !== -1) ? (isOver ? 0.38 : -0.25) : 0.08;

      drawWebbingPatch3D(
        backrestPt(xc - sw, tA, lift),
        backrestPt(xc + sw, tA, lift),
        backrestPt(xc + sw, tB, lift),
        backrestPt(xc - sw, tB, lift),
        isTang,
        true,
        isOver,
        700 + i * 37 + kt * 11
      );
    }

    // Wrap around top backrest bar (t = 1.0, ly = 63.5, lz = -24.0)
    drawStrapTubeWrap3D(
      [xc - sw, 63.2, -23.1], [xc + sw, 63.2, -23.1],
      [xc - sw, 64.3, -24.5], [xc + sw, 64.3, -24.5],
      isTang, 780 + i
    );
    // Wrap around lower backrest bar (t = 0.0, ly = 26.8, lz = -14.0)
    drawStrapTubeWrap3D(
      [xc - sw, 27.3, -13.3], [xc + sw, 27.3, -13.3],
      [xc - sw, 26.2, -14.5], [xc + sw, 26.2, -14.5],
      isTang, 790 + i
    );
  }

  // Pass 6B: Draw 4 Horizontal Backrest Straps (and weave cast shadows)
  for (let j = 0; j < 4; j++) {
    let tc = backTCenters[j];
    let isTang = (j % 2 === 0); // [Tangerine, White, Tangerine, White]
    for (let kx = 0; kx < xKnots.length - 1; kx++) {
      let xA = xKnots[kx];
      let xB = xKnots[kx + 1];
      let iCross = (kx % 2 === 1) ? Math.floor(kx / 2) : -1;
      let horizOver = (iCross === -1) || ((iCross + j) % 2 === 1);

      if (horizOver) {
        let lift = (iCross !== -1) ? 0.42 : 0.12;
        drawWebbingPatch3D(
          backrestPt(xA, tc - dt, lift),
          backrestPt(xA, tc + dt, lift),
          backrestPt(xB, tc + dt, lift),
          backrestPt(xB, tc - dt, lift),
          isTang,
          false,
          true,
          800 + j * 43 + kx * 13
        );

        // Cast shadow beneath horizontal strap onto vertical strap below it
        if (iCross !== -1) {
          let sh0 = backrestPt(xA, tc - dt - 0.022, 0.05);
          let sh1 = backrestPt(xB, tc - dt - 0.022, 0.05);
          let sh2 = backrestPt(xB, tc - dt, 0.05);
          let sh3 = backrestPt(xA, tc - dt, 0.05);
          let pSh = [sh0, sh1, sh2, sh3].map(p => projChair(p[0], p[1], p[2]));
          fillPolygonWash(pSh, (iCross % 2 === 0) ? "#7d2505" : "#9c8e79", 215);
        }
      } else {
        // Vertical strap is over horizontal strap -> shadow on horizontal strap
        let sh0 = backrestPt(xA - 0.85, tc - dt, 0.05);
        let sh1 = backrestPt(xA, tc - dt, 0.05);
        let sh2 = backrestPt(xA, tc + dt, 0.05);
        let sh3 = backrestPt(xA - 0.85, tc + dt, 0.05);
        let pSh = [sh0, sh1, sh2, sh3].map(p => projChair(p[0], p[1], p[2]));
        fillPolygonWash(pSh, isTang ? "#7d2505" : "#9c8e79", 215);
      }
    }

    // Wrap around left & right backrest uprights (lx = -19.3 and +19.3)
    let pL0 = backrestPt(-18.6, tc - dt, 0.25);
    let pL1 = backrestPt(-18.6, tc + dt, 0.25);
    let pL2 = backrestPt(-20.1, tc - dt, -0.2);
    let pL3 = backrestPt(-20.1, tc + dt, -0.2);
    drawStrapTubeWrap3D(pL0, pL1, pL2, pL3, isTang, 860 + j);

    let pR0 = backrestPt(18.6, tc - dt, 0.25);
    let pR1 = backrestPt(18.6, tc + dt, 0.25);
    let pR2 = backrestPt(20.1, tc - dt, -0.2);
    let pR3 = backrestPt(20.1, tc + dt, -0.2);
    drawStrapTubeWrap3D(pR0, pR1, pR2, pR3, isTang, 880 + j);
  }

  // --- 7. RIGHT GROUND LEG U-LOOP (CLOSER FOREGROUND SIDE, lx = +20.5) ---
  let rightLegPts = buildRoundedPath3D([
    [W, 39.2, 18.2],
    [W, 1.2, 17.0],
    [W, 1.2, -15.5],
    [W, 39.2, -10.8]
  ], 3.8, 5);
  drawAluminiumTube3D(rightLegPts, 7.4, 909);

  // Ribbed rubber foot caps on right ground runner
  drawFootCap3D([W, 1.2, 11.5], [W, 1.2, 15.2], 8.2);
  drawFootCap3D([W, 1.2, -14.0], [W, 1.2, -10.2], 8.2);

  // Right folding diagonal aluminium strut
  drawFlatStrut3D([19.9, 13.5, 16.5], [19.9, 25.5, 2.5], 5.2);

  // --- 8. STAMPED ALUMINIUM HINGE BRACKETS & STEEL RIVETS ---
  for (let side of [-1, 1]) {
    let sx = side * 19.8;
    let r1 = projChair(sx, 26.2, 17.2);
    let r2 = projChair(sx, 24.5, -13.0);
    let r3 = projChair(sx, 39.2, -16.8);
    drawRivet2D(r1[0], r1[1], 3.3);
    drawRivet2D(r2[0], r2[1], 3.3);
    drawRivet2D(r3[0], r3[1], 3.3);
  }

  // --- 9. CONTOURED EXTRUDED ALUMINIUM ARMRESTS (LEFT & RIGHT) ---
  drawArmrest3D(-W, 7.0);
  drawArmrest3D(W, 7.5);
}

function drawFootCap3D(pA, pB, rPx) {
  let a = projChair(pA[0], pA[1], pA[2]);
  let b = projChair(pB[0], pB[1], pB[2]);
  let dx = b[0] - a[0];
  let dy = b[1] - a[1];
  let len = Math.hypot(dx, dy) || 1;
  let nx = -dy / len;
  let ny = dx / len;

  let poly = [
    [a[0] + nx * rPx, a[1] + ny * rPx],
    [b[0] + nx * rPx, b[1] + ny * rPx],
    [b[0] - nx * rPx, b[1] - ny * rPx],
    [a[0] - nx * rPx, a[1] - ny * rPx]
  ];
  fillPolygonWash(poly, "#38332e", 250);
  strokePolygon(poly, "rotring", "#1c1916", 0.75, true);

  // Molded rubber grip ribs
  for (let k = 1; k <= 3; k++) {
    let t = k / 4;
    let mx = a[0] + dx * t;
    let my = a[1] + dy * t;
    brush.set("techPen", "#6e665e", 0.55);
    brush.line(mx + nx * rPx * 0.8, my + ny * rPx * 0.8, mx - nx * rPx * 0.8, my - ny * rPx * 0.8);
  }
}

function drawFlatStrut3D(pA, pB, halfW) {
  let a = projChair(pA[0], pA[1], pA[2]);
  let b = projChair(pB[0], pB[1], pB[2]);
  let dx = b[0] - a[0];
  let dy = b[1] - a[1];
  let len = Math.hypot(dx, dy) || 1;
  let nx = -dy / len;
  let ny = dx / len;

  let poly = [
    [a[0] + nx * halfW, a[1] + ny * halfW],
    [b[0] + nx * halfW, b[1] + ny * halfW],
    [b[0] - nx * halfW, b[1] - ny * halfW],
    [a[0] - nx * halfW, a[1] - ny * halfW]
  ];
  fillPolygonWash(poly, "#c4beb4", 245);
  strokePolygon(poly, "rotring", "#423c35", 0.7, true);
  brush.set("techPen", "#f7f4ec", 0.65);
  brush.line(a[0] + nx * (halfW - 1), a[1] + ny * (halfW - 1), b[0] + nx * (halfW - 1), b[1] + ny * (halfW - 1));

  drawRivet2D(a[0], a[1], 3.0);
  drawRivet2D(b[0], b[1], 3.0);
}

function drawArmrest3D(lx, thicknessPx) {
  let hw = 1.85; // armrest half-width in cm
  let zRear = -18.5;
  let zFront = 19.5;
  let yTop = 39.8;

  // Top flat sunlit surface of contoured aluminium armrest
  let topPoly = [
    projChair(lx - hw, yTop, zRear),
    projChair(lx + hw, yTop, zRear),
    projChair(lx + hw, yTop, zFront),
    projChair(lx - hw, yTop, zFront)
  ];

  // Side skirt of armrest
  let sidePoly = [
    projChair(lx - hw, yTop, zRear),
    projChair(lx - hw, yTop, zFront),
    projChair(lx - hw, yTop - 1.5, zFront),
    projChair(lx - hw, yTop - 1.5, zRear)
  ];

  // Curved front knuckle hooking down over front leg upright
  let frontHook = [
    projChair(lx - hw, yTop, zFront),
    projChair(lx + hw, yTop, zFront),
    projChair(lx + hw, yTop - 3.2, zFront + 1.2),
    projChair(lx - hw, yTop - 3.2, zFront + 1.2)
  ];

  fillPolygonWash(sidePoly, "#7a7368", 250);
  strokePolygon(sidePoly, "rotring", "#332e29", 0.75, true);

  fillPolygonWash(frontHook, "#b5afa4", 250);
  strokePolygon(frontHook, "rotring", "#38322c", 0.75, true);

  fillPolygonWash(topPoly, "#e6e1d6", 250);
  hatchPolygon(topPoly, "archMarker", "#d4cfc3", 0.7, 7, -25, { rand: 0.01 });

  // Longitudinal grooved fluting lines along top of extruded aluminium armrest
  for (let g = -1; g <= 1; g++) {
    let gx = lx + g * 0.75;
    let p0 = projChair(gx, yTop, zRear + 1.5);
    let p1 = projChair(gx, yTop, zFront - 1.0);
    brush.set("techPen", g === 0 ? "#ffffff" : "#8c8478", 0.55);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  strokePolygon(topPoly, "rotring", "#453e37", 0.75, true);

  // Scuffs and sun-glint on the armrest
  for (let s = 0; s < 5; s++) {
    let zs = zRear + 4 + s * 6.5;
    let pA = projChair(lx - hw * 0.8, yTop, zs);
    let pB = projChair(lx + hw * 0.7, yTop, zs + 1.2);
    brush.set("techPen", "#524a42", 0.45);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
    brush.set("techPen", "#ffffff", 0.45);
    brush.line(pA[0], pA[1] - 1, pB[0], pB[1] - 1);
  }
}

// =========================================================================
// 7. FINAL ARCHITECTURAL DETAILS & BORDER
// =========================================================================
function drawFinalDetails() {
  // Subtle dry terracotta dust / leaf speck near the breeze-block wall base
  let crumbs = [[-56, 0, 32], [-52, 0, 38], [-58, 0, 44], [-49, 0, 29], [4, 0, 62]];
  for (let c of crumbs) {
    let p = proj(c[0], c[1], c[2]);
    brush.set("rotring", "#4a3829", 0.9);
    brush.line(p[0], p[1], p[0] + 2.5, p[1] + 0.8);
    brush.set("techPen", "#b88460", 0.7);
    brush.line(p[0] - 0.5, p[1] - 0.8, p[0] + 1.5, p[1]);
  }

  // Crisp ruled archival margin frame around the 1200x1200 canvas
  let m = 22;
  let outerFrame = [[0, 0], [1200, 0], [1200, 1200], [0, 1200]];
  let topBar = [[0, 0], [1200, 0], [1200, m], [0, m]];
  let botBar = [[0, 1200 - m], [1200, 1200 - m], [1200, 1200], [0, 1200]];
  let leftBar = [[0, 0], [m, 0], [m, 1200], [0, 1200]];
  let rightBar = [[1200 - m, 0], [1200, 0], [1200, 1200], [1200 - m, 1200]];

  for (let b of [topBar, botBar, leftBar, rightBar]) {
    fillPolygonWash(b, "#f4ede1", 255);
  }

  let innerBorder = [[m, m], [1200 - m, m], [1200 - m, 1200 - m], [m, 1200 - m]];
  strokePolygon(innerBorder, "rotring", "#3b3229", 0.85, true);
  strokePolygon(outerFrame, "rotring", "#3b3229", 1.2, true);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);
}

function draw() {
  translate(-width / 2, -height / 2);

  // =========================================================================
  // PALETTE: Muted Earth Tones + Duotone Electric Cyan & Deep Violet
  // =========================================================================
  const PAL = {
    paper: "#dfd2bf",       // Warm muted earth flyer paper
    paperLight: "#f4ece0",  // Highlighted paper crease
    paperDark: "#bfa98e",   // Aged pocket-worn paper shadow
    earthUmber: "#2e1c14",  // Deep burnt umber (tape oxide / dark ink)
    earthBlack: "#170e0b",  // Richest iron-oxide shadow
    earthRust: "#6e3b24",   // Warm oxide midtone
    earthOchre: "#b88752",  // Muted golden ochre reflection
    earthSand: "#caa87e",   // Dusty tan
    violetDeep: "#1d0c2e",  // Deep xerox violet
    violetMid: "#3c1b54",   // Bruised duotone plum
    violetSoft: "#6b4668",  // Muted violet-earth transition
    cyanElec: "#00cfe3",    // Electric duotone cyan
    cyanBright: "#6bf4ff",  // High-energy cyan tint
    cyanMuted: "#2e8896",   // Muted teal-cyan
    chromeWhite: "#ffffff", // Pure specular glint
    chromeGrey: "#78848c"   // Cool metallic neutral
  };

  background(PAL.paper);

  // Horizon geometry (tilted at -9 degrees for dynamic flyer energy)
  const horAngle = -9;
  const horRad = horAngle * Math.PI / 180;
  const horCos = Math.cos(horRad);
  const horSin = Math.sin(horRad);
  const vpX = 545;
  const vpY = 565;

  function horizonY(x) {
    return vpY + (x - vpX) * Math.tan(horRad);
  }

  // Cassette local-to-world transform (centred on starburst, tilted at -18 deg)
  const casCX = 600;
  const casCY = 510;
  const casAngle = -18;
  const casRad = casAngle * Math.PI / 180;
  const casCos = Math.cos(casRad);
  const casSin = Math.sin(casRad);

  function cPt(lx, ly) {
    return [
      casCX + lx * casCos - ly * casSin,
      casCY + lx * casSin + ly * casCos
    ];
  }

  // Helper: Draw a polygon with wash or fill safely
  function drawPolyWash(pts, col, opacity) {
    brush.noStroke();
    brush.noFill();
    brush.wash(col, opacity);
    brush.beginShape(0);
    for (let i = 0; i < pts.length; i++) {
      brush.vertex(pts[i][0], pts[i][1]);
    }
    brush.endShape(true);
    brush.noWash();
  }

  // =========================================================================
  // 1. DUOTONE GRADIENT SKY (Electric Cyan into Deep Violet) + MARKER BLENDS
  // =========================================================================
  // Base sky washes
  drawPolyWash([[0, 0], [1200, 0], [1200, horizonY(1200)], [0, horizonY(0)]], PAL.violetDeep, 220);
  drawPolyWash([[0, 220], [1200, 220 - 190], [1200, horizonY(1200)], [0, horizonY(0)]], PAL.violetMid, 160);
  drawPolyWash([[0, 390], [1200, 390 - 190], [1200, horizonY(1200)], [0, horizonY(0)]], PAL.cyanElec, 150);

  // Slick flat marker blends parallel to the tilted horizon
  const skyBands = 68;
  for (let i = 0; i <= skyBands; i++) {
    let t = i / skyBands; // 0 = top of sky, 1 = horizon
    let offset = (t - 1) * 650;
    let x1 = -100;
    let y1 = horizonY(x1) + offset;
    let x2 = 1300;
    let y2 = horizonY(x2) + offset;

    let col;
    if (t < 0.32) {
      col = lerpColor(color(PAL.violetDeep), color(PAL.violetMid), t / 0.32);
    } else if (t < 0.58) {
      col = lerpColor(color(PAL.violetMid), color(PAL.violetSoft), (t - 0.32) / 0.26);
    } else if (t < 0.78) {
      col = lerpColor(color(PAL.violetSoft), color(PAL.cyanElec), (t - 0.58) / 0.20);
    } else {
      col = lerpColor(color(PAL.cyanElec), color(PAL.cyanBright), (t - 0.78) / 0.22);
    }

    brush.set("marker", col, map(t, 0, 1, 3.4, 2.2));
    brush.line(x1, y1 + random(-3, 3), x2, y2 + random(-3, 3));
  }

  // Duotone photocopy scanline hatching across the sky
  for (let i = 0; i < 95; i++) {
    let t = i / 95;
    let offset = (t - 1) * 630;
    let x1 = -50;
    let y1 = horizonY(x1) + offset;
    let x2 = 1250;
    let y2 = horizonY(x2) + offset;
    let col = t < 0.6 ? PAL.violetDeep : PAL.cyanMuted;
    brush.set("rotring", col, t < 0.5 ? 0.55 : 0.38);
    brush.line(x1, y1, x2, y2);
  }

  // =========================================================================
  // 2. RECEDING WIREFRAME FLOOR IN FINE PEN
  // =========================================================================
  // Ground base wash: deep violet at horizon fading into muted earth umber
  drawPolyWash([[0, horizonY(0)], [1200, horizonY(1200)], [1200, 1200], [0, 1200]], PAL.violetDeep, 235);
  drawPolyWash([[0, horizonY(0) + 140], [1200, horizonY(1200) + 140], [1200, 1200], [0, 1200]], PAL.earthUmber, 175);

  // Slick marker under-streaks on the floor
  for (let i = 0; i < 42; i++) {
    let t = i / 41;
    let d = Math.pow(t, 1.5) * 720;
    let x1 = -100, y1 = horizonY(x1) + d;
    let x2 = 1300, y2 = horizonY(x2) + d;
    let col = lerpColor(color(PAL.violetMid), color(PAL.earthUmber), t);
    brush.set("marker", col, 2.8);
    brush.line(x1, y1, x2, y2);
  }

  // Horizon glow band
  brush.set("marker", PAL.cyanBright, 3.0);
  brush.line(-50, horizonY(-50), 1250, horizonY(1250));
  brush.set("rotring", PAL.chromeWhite, 0.9);
  brush.line(-50, horizonY(-50), 1250, horizonY(1250));

  // Receding perspective rays from Vanishing Point (vpX, vpY)
  const numFloorRays = 54;
  for (let i = -numFloorRays; i <= numFloorRays; i++) {
    // Project along a baseline parallel to the horizon at distance D = 650
    let u = i * 68;
    let bx = vpX + u * horCos - 650 * horSin;
    let by = vpY + u * horSin + 650 * horCos;

    // Slight cyan glow pass + crisp pen line
    let distFromCenter = Math.abs(i) / numFloorRays;
    let rayCol = distFromCenter < 0.45 ? PAL.cyanElec : lerpColor(color(PAL.cyanMuted), color(PAL.earthOchre), 0.5);
    brush.set("pen", rayCol, 0.55);
    brush.line(vpX, vpY, bx, by);

    if (i % 2 === 0) {
      brush.set("rotring", PAL.cyanBright, 0.32);
      brush.line(vpX, vpY, bx, by);
    }
  }

  // Receding horizontal grid lines (logarithmic depth spacing)
  const numDepthLines = 38;
  for (let i = 1; i <= numDepthLines; i++) {
    let t = i / numDepthLines;
    let d = Math.pow(t, 2.15) * 740;
    let x1 = -120;
    let y1 = horizonY(x1) + d / horCos;
    let x2 = 1320;
    let y2 = horizonY(x2) + d / horCos;

    let lineCol = t < 0.5
      ? lerpColor(color(PAL.cyanBright), color(PAL.cyanElec), t * 2)
      : lerpColor(color(PAL.cyanElec), color(PAL.earthSand), (t - 0.5) * 1.6);

    brush.set("rotring", lineCol, map(t, 0, 1, 0.35, 0.75));
    brush.line(x1, y1, x2, y2);
  }

  // =========================================================================
  // 3. CENTRED STARBURST (Graphic Euphoric Flyer Motif Behind Cassette)
  // =========================================================================
  const sbX = 595;
  const sbY = 525;

  // Soft spray & marker aura around starburst center
  brush.set("spray", PAL.cyanElec, 1.8);
  for (let i = 0; i < 24; i++) {
    let a = i * 15;
    let r = random(180, 420);
    brush.line(sbX, sbY, sbX + cos(a) * r, sbY + sin(a) * r);
  }

  // Alternating sharp polygon rays of the starburst
  const numStarRays = 36;
  for (let i = 0; i < numStarRays; i++) {
    let a = i * (360 / numStarRays) + casAngle;
    let a1 = a - (180 / numStarRays) * 0.72;
    let a2 = a + (180 / numStarRays) * 0.72;

    let rOuter = (i % 2 === 0) ? random(470, 560) : (i % 4 === 1 ? random(360, 430) : random(260, 320));
    let p0 = [sbX, sbY];
    let p1 = [sbX + cos(a1) * 130, sbY + sin(a1) * 130];
    let p2 = [sbX + cos(a) * rOuter, sbY + sin(a) * rOuter];
    let p3 = [sbX + cos(a2) * 130, sbY + sin(a2) * 130];

    let fillCol = (i % 3 === 0) ? PAL.paperLight : (i % 3 === 1 ? PAL.cyanBright : PAL.earthOchre);
    drawPolyWash([p0, p1, p2, p3], fillCol, i % 2 === 0 ? 195 : 135);

    // Crisp technical pen outlines & radial spikes
    brush.set("rotring", i % 2 === 0 ? PAL.violetDeep : PAL.cyanElec, 0.55);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.line(p3[0], p3[1], p2[0], p2[1]);

    // Extended speed-lines shooting past the starburst tips
    let rSpike1 = rOuter - 40;
    let rSpike2 = rOuter + random(40, 130);
    brush.set("rotring", i % 2 === 0 ? PAL.paperLight : PAL.cyanBright, 0.45);
    brush.line(sbX + cos(a) * rSpike1, sbY + sin(a) * rSpike1, sbX + cos(a) * rSpike2, sbY + sin(a) * rSpike2);
  }

  // Dark contrast starburst ring right behind cassette to make clear plastic pop
  for (let i = 0; i < 24; i++) {
    let a = i * 15 + 7.5;
    let a1 = a - 3.5, a2 = a + 3.5;
    let rOut = (i % 2 === 0) ? 350 : 270;
    drawPolyWash([
      [sbX, sbY],
      [sbX + cos(a1) * 90, sbY + sin(a1) * 90],
      [sbX + cos(a) * rOut, sbY + sin(a) * rOut],
      [sbX + cos(a2) * 90, sbY + sin(a2) * 90]
    ], PAL.violetDeep, 150);
  }

  // =========================================================================
  // 4. HYPERREAL AUDIO CASSETTE (Tilted, Clear Scratched Casing, Chrome Label)
  // =========================================================================
  // Cassette local dimensions: width = 660 (-330..330), height = 420 (-210..210)
  // 3D depth extrude vector in local space:
  const extX = -16;
  const extY = 38;

  // 4A. Drop shadow / photocopy smudge beneath the cassette
  let shadowPts = [
    cPt(-335 + extX * 1.9, -205 + extY * 1.9),
    cPt(335 + extX * 1.9, -205 + extY * 1.9),
    cPt(335 + extX * 2.2, 215 + extY * 2.2),
    cPt(-335 + extX * 2.2, 215 + extY * 2.2)
  ];
  drawPolyWash(shadowPts, PAL.violetDeep, 175);
  brush.set("spray", PAL.earthBlack, 1.8);
  for (let i = 0; i < 18; i++) {
    let sx = random(-330, 330);
    let pA = cPt(sx + extX * 1.4, 210 + extY * 1.4);
    let pB = cPt(sx + extX * 2.5 + random(-30, 30), 210 + extY * 2.5 + random(-15, 25));
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }

  // 4B. 3D Side & Bottom Acrylic Bevel Walls of the Cassette
  let leftWall = [cPt(-330, -198), cPt(-330, 198), cPt(-330 + extX, 198 + extY), cPt(-330 + extX, -198 + extY)];
  let botWall = [cPt(-318, 210), cPt(318, 210), cPt(318 + extX, 210 + extY), cPt(-318 + extX, 210 + extY)];
  drawPolyWash(leftWall, PAL.violetMid, 165);
  drawPolyWash(botWall, PAL.earthUmber, 185);

  // Clear plastic internal wall ribs along the left & bottom 3D bevels
  for (let ly = -180; ly <= 180; ly += 24) {
    let p1 = cPt(-330, ly), p2 = cPt(-330 + extX, ly + extY);
    brush.set("rotring", ly % 48 === 0 ? PAL.cyanBright : PAL.paperLight, 0.45);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  for (let lx = -300; lx <= 300; lx += 30) {
    let p1 = cPt(lx, 210), p2 = cPt(lx + extX, 210 + extY);
    brush.set("rotring", Math.abs(lx) < 220 ? PAL.earthOchre : PAL.cyanElec, 0.45);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Bottom head openings (where magnetic tape is exposed and spills out)
  const slotRanges = [[-205, -135], [-115, -55], [-40, 40], [55, 115], [135, 205]];
  for (let s of slotRanges) {
    let sp = [
      cPt(s[0], 208),
      cPt(s[1], 208),
      cPt(s[1] + extX * 0.85, 208 + extY * 0.85),
      cPt(s[0] + extX * 0.85, 208 + extY * 0.85)
    ];
    drawPolyWash(sp, PAL.earthBlack, 235);
    brush.set("rotring", PAL.cyanBright, 0.45);
    brush.line(sp[0][0], sp[0][1], sp[1][0], sp[1][1]);
  }

  // 4C. Clear Acrylic Casing Backplate & Refracted Interior
  let frontFacePts = [
    cPt(-318, -210), cPt(318, -210), cPt(330, -198),
    cPt(330, 198), cPt(318, 210), cPt(-318, 210),
    cPt(-330, 198), cPt(-330, -198)
  ];
  drawPolyWash(frontFacePts, PAL.violetDeep, 95);
  drawPolyWash(frontFacePts, PAL.paper, 55);

  // Internal acrylic mould geometry (visible through the clear plastic shell)
  brush.set("rotring", PAL.cyanMuted, 0.45);
  // Inner perimeter wall (8px inset)
  let innerWallPts = [
    cPt(-310, -200), cPt(310, -200), cPt(320, -190),
    cPt(320, 190), cPt(310, 200), cPt(-310, 200),
    cPt(-320, 190), cPt(-320, -190)
  ];
  for (let i = 0; i < innerWallPts.length; i++) {
    let a = innerWallPts[i];
    let b = innerWallPts[(i + 1) % innerWallPts.length];
    brush.set("rotring", PAL.paperLight, 0.5);
    brush.line(a[0], a[1], b[0], b[1]);
  }

  // Internal diagonal reinforcing ribs & guide posts in clear shell corners
  const internalLines = [
    [-320, -145, -240, -200], [320, -145, 240, -200],
    [-320, -110, -290, -110], [320, -110, 290, -110],
    [-320, 80, -250, 80], [320, 80, 250, 80],
    [-265, 80, -265, 195], [265, 80, 265, 195],
    [-235, 100, -235, 198], [235, 100, 235, 198]
  ];
  for (let l of internalLines) {
    let p1 = cPt(l[0], l[1]), p2 = cPt(l[2], l[3]);
    brush.set("rotring", PAL.paperLight, 0.48);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    let p3 = cPt(l[0] + 3, l[1] + 3), p4 = cPt(l[2] + 3, l[3] + 3);
    brush.set("pen", PAL.violetDeep, 0.4);
    brush.line(p3[0], p3[1], p4[0], p4[1]);
  }

  // Helper to draw a circle/ring in cassette-local coordinates
  function drawCassetteCircle(lx, ly, r, col, weight, bName = "rotring", steps = 36) {
    brush.set(bName, col, weight);
    for (let i = 0; i < steps; i++) {
      let a1 = (i / steps) * 360;
      let a2 = ((i + 1) / steps) * 360;
      let p1 = cPt(lx + cos(a1) * r, ly + sin(a1) * r);
      let p2 = cPt(lx + cos(a2) * r, ly + sin(a2) * r);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  function fillCassetteCircle(lx, ly, r, col, opacity, steps = 32) {
    let pts = [];
    for (let i = 0; i < steps; i++) {
      let a = (i / steps) * 360;
      pts.push(cPt(lx + cos(a) * r, ly + sin(a) * r));
    }
    drawPolyWash(pts, col, opacity);
  }

  // Bottom corner guide rollers (visible through clear lower corners)
  const rollers = [[-285, 162], [285, 162]];
  for (let rl of rollers) {
    fillCassetteCircle(rl[0], rl[1], 24, PAL.earthUmber, 180);
    drawCassetteCircle(rl[0], rl[1], 24, PAL.paperLight, 0.55);
    drawCassetteCircle(rl[0], rl[1], 18, PAL.cyanElec, 0.45);
    fillCassetteCircle(rl[0], rl[1], 8, PAL.earthOchre, 220);
    drawCassetteCircle(rl[0], rl[1], 8, PAL.chromeWhite, 0.5);
  }

  // 4D. Magnetic Tape Reels (Spools) & Wound Oxide Tape Packs
  // Left reel (fuller pack R=134), Right reel (partially unwound R=94 due to spilled loop)
  const reels = [
    { lx: -146, ly: -14, packR: 134 },
    { lx: 146, ly: -14, packR: 94 }
  ];

  for (let reel of reels) {
    // Subtle Circular guide ring moulded into the clear shell
    drawCassetteCircle(reel.lx, reel.ly, 140, PAL.paperLight, 0.4, "rotring", 48);

    // Dark magnetic oxide tape pack base
    fillCassetteCircle(reel.lx, reel.ly, reel.packR, PAL.earthBlack, 240, 48);

    // Concentric wound tape sheen + bow-tie specular reflection wedges
    for (let r = 56; r <= reel.packR; r += 3.2) {
      for (let s = 0; s < 48; s++) {
        let a1 = (s / 48) * 360;
        let a2 = ((s + 1) / 48) * 360;
        // Anisotropic bow-tie reflection on wound tape at 35 deg and 215 deg
        let sheen = Math.pow(Math.abs(Math.cos((a1 - 38) * Math.PI / 180)), 5);
        let sheen2 = Math.pow(Math.abs(Math.cos((a1 - 128) * Math.PI / 180)), 7);
        let col = PAL.earthUmber;
        let w = 0.65;
        if (sheen > 0.65) {
          col = sheen > 0.88 ? PAL.earthOchre : PAL.earthRust;
          w = 0.85;
        } else if (sheen2 > 0.75) {
          col = PAL.cyanMuted;
          w = 0.6;
        }
        let p1 = cPt(reel.lx + cos(a1) * r, reel.ly + sin(a1) * r);
        let p2 = cPt(reel.lx + cos(a2) * r, reel.ly + sin(a2) * r);
        brush.set("rotring", col, w);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }

    // Toothed white/ivory spool hub
    fillCassetteCircle(reel.lx, reel.ly, 55, PAL.paperLight, 235, 36);
    fillCassetteCircle(reel.lx, reel.ly, 42, PAL.violetDeep, 210, 36);
    drawCassetteCircle(reel.lx, reel.ly, 55, PAL.chromeWhite, 0.7, "rotring", 36);
    drawCassetteCircle(reel.lx, reel.ly, 42, PAL.paperDark, 0.6, "rotring", 36);

    // 3 slotted cutouts in the plastic hub flange
    for (let k = 0; k < 3; k++) {
      let ka = k * 120 + 25;
      let hx = reel.lx + cos(ka) * 48.5;
      let hy = reel.ly + sin(ka) * 48.5;
      fillCassetteCircle(hx, hy, 3.8, PAL.earthBlack, 220, 12);
    }

    // 6 inward drive sprocket teeth
    for (let t = 0; t < 6; t++) {
      let ta = t * 60 + 12;
      let t1 = cPt(reel.lx + cos(ta - 6) * 42, reel.ly + sin(ta - 6) * 42);
      let t2 = cPt(reel.lx + cos(ta + 6) * 42, reel.ly + sin(ta + 6) * 42);
      let t3 = cPt(reel.lx + cos(ta + 4) * 31, reel.ly + sin(ta + 4) * 31);
      let t4 = cPt(reel.lx + cos(ta - 4) * 31, reel.ly + sin(ta - 4) * 31);
      drawPolyWash([t1, t2, t3, t4], PAL.chromeWhite, 240);
      brush.set("rotring", PAL.earthUmber, 0.45);
      brush.line(t1[0], t1[1], t4[0], t4[1]);
      brush.line(t4[0], t4[1], t3[0], t3[1]);
      brush.line(t3[0], t3[1], t2[0], t2[1]);
    }
  }

  // Internal tape path from reels down to the bottom corner guide rollers
  let tpLeft1 = cPt(reels[0].lx - reels[0].packR * 0.92, reels[0].ly + reels[0].packR * 0.38);
  let tpLeft2 = cPt(-306, 155);
  let tpLeft3 = cPt(-285, 185);
  let tpLeft4 = cPt(-112, 206);
  brush.set("marker", PAL.earthUmber, 1.3);
  brush.line(tpLeft1[0], tpLeft1[1], tpLeft2[0], tpLeft2[1]);
  brush.line(tpLeft2[0], tpLeft2[1], tpLeft3[0], tpLeft3[1]);
  brush.line(tpLeft3[0], tpLeft3[1], tpLeft4[0], tpLeft4[1]);
  brush.set("rotring", PAL.cyanBright, 0.45);
  brush.line(tpLeft1[0], tpLeft1[1], tpLeft2[0], tpLeft2[1]);

  let tpRight1 = cPt(reels[1].lx + reels[1].packR * 0.92, reels[1].ly + reels[1].packR * 0.38);
  let tpRight2 = cPt(306, 155);
  let tpRight3 = cPt(285, 185);
  let tpRight4 = cPt(112, 206);
  brush.set("marker", PAL.earthUmber, 1.3);
  brush.line(tpRight1[0], tpRight1[1], tpRight2[0], tpRight2[1]);
  brush.line(tpRight2[0], tpRight2[1], tpRight3[0], tpRight3[1]);
  brush.line(tpRight3[0], tpRight3[1], tpRight4[0], tpRight4[1]);
  brush.set("rotring", PAL.earthOchre, 0.45);
  brush.line(tpRight1[0], tpRight1[1], tpRight2[0], tpRight2[1]);

  // =========================================================================
  // 4E. CHROME-LIKE LABEL REFLECTING A WARPED GRID (Type-Free)
  // =========================================================================
  // Label outer boundary: lx in [-294, 294], ly in [-174, 84], top chamfer = 26
  // Central window cutout: lx in [-212, 212], ly in [-70, 44]
  function isInsideLabel(lx, ly) {
    if (lx < -294 || lx > 294 || ly < -174 || ly > 84) return false;
    // Top corner chamfers
    if (lx + 294 + ( -174 - ly ) < -26) return false;
    if ((294 - lx) + ( -174 - ly ) < -26) return false;
    // Subtract central window
    if (lx > -212 && lx < 212 && ly > -70 && ly < 44) return false;
    return true;
  }

  // Base metallic chrome washes on the 4 frame sections of the label
  let topLabelBar = [cPt(-268, -174), cPt(268, -174), cPt(294, -148), cPt(294, -70), cPt(-294, -70), cPt(-294, -148)];
  let botLabelBar = [cPt(-294, 44), cPt(294, 44), cPt(294, 84), cPt(-294, 84)];
  let leftLabelBar = [cPt(-294, -70), cPt(-212, -70), cPt(-212, 44), cPt(-294, 44)];
  let rightLabelBar = [cPt(212, -70), cPt(294, -70), cPt(294, 44), cPt(212, 44)];
  drawPolyWash(topLabelBar, PAL.paperLight, 235);
  drawPolyWash(botLabelBar, PAL.earthOchre, 225);
  drawPolyWash(leftLabelBar, PAL.cyanBright, 220);
  drawPolyWash(rightLabelBar, PAL.cyanBright, 220);

  // Chrome gradient scanlines across the label (with wavy anamorphic horizon reflection)
  for (let ly = -172; ly <= 82; ly += 2.6) {
    let xLeft = -294;
    let xRight = 294;
    if (ly < -148) {
      let cut = -148 - ly;
      xLeft = -294 + cut;
      xRight = 294 - cut;
    }

    // Determine horizontal spans (splitting around the central window if ly in [-70, 44])
    let spans = (ly > -70 && ly < 44) ? [[xLeft, -212], [212, xRight]] : [[xLeft, xRight]];

    for (let sp of spans) {
      // Subdivide each span into segments so we can modulate the warped chrome reflection along lx
      let segs = 12;
      let dx = (sp[1] - sp[0]) / segs;
      for (let s = 0; s < segs; s++) {
        let lx1 = sp[0] + s * dx;
        let lx2 = lx1 + dx;
        let lxMid = (lx1 + lx2) * 0.5;

        // Warped chrome horizon curve on the label
        let warpHorY = -42 + 22 * Math.sin(lxMid * 0.009 + 0.4) + 8 * Math.cos(lxMid * 0.021);
        let d = ly - warpHorY;

        let col, w = 1.15, bType = "marker";
        if (d < -75) {
          col = PAL.violetDeep;
        } else if (d < -38) {
          col = lerpColor(color(PAL.violetMid), color(PAL.cyanElec), (d + 75) / 37);
        } else if (d < -10) {
          col = lerpColor(color(PAL.cyanElec), color(PAL.cyanBright), (d + 38) / 28);
        } else if (d < 4) {
          col = PAL.chromeWhite;
          bType = "rotring";
          w = 0.95;
        } else if (d < 22) {
          // Classic dark chrome horizon core reflection
          col = d < 12 ? PAL.earthBlack : PAL.earthUmber;
        } else if (d < 55) {
          col = lerpColor(color(PAL.earthRust), color(PAL.earthOchre), (d - 22) / 33);
        } else if (d < 92) {
          col = lerpColor(color(PAL.earthOchre), color(PAL.paperLight), (d - 55) / 37);
        } else {
          col = lerpColor(color(PAL.paperLight), color(PAL.cyanMuted), Math.min(1, (d - 92) / 45));
        }

        let p1 = cPt(lx1, ly);
        let p2 = cPt(lx2, ly);
        brush.set(bType, col, w);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }
  }

  // Warped Grid Reflection Mapped Onto the Chrome Label
  // Spherical / barrel distortion centered at (25, -45) on the reflective foil label
  function warpLabelPt(u, v) {
    // u in [-1, 1], v in [-1, 1]
    let r2 = u * u + v * v;
    let factor = 1 + 0.38 * r2 + 0.12 * Math.sin(u * 4.5) * Math.cos(v * 3.5);
    let lx = u * 310 / factor;
    let ly = -45 + v * 155 / factor + 14 * Math.sin(u * 3.2);
    return [lx, ly];
  }

  // Draw warped longitudinal & latitudinal grid curves clipped to the chrome label
  for (let uIdx = -14; uIdx <= 14; uIdx++) {
    let u = uIdx / 14;
    let steps = 34;
    for (let s = 0; s < steps; s++) {
      let v1 = -1.1 + (s / steps) * 2.2;
      let v2 = -1.1 + ((s + 1) / steps) * 2.2;
      let a = warpLabelPt(u, v1);
      let b = warpLabelPt(u, v2);
      if (isInsideLabel(a[0], a[1]) && isInsideLabel(b[0], b[1])) {
        let p1 = cPt(a[0], a[1]);
        let p2 = cPt(b[0], b[1]);
        let gCol = a[1] < -40 ? PAL.chromeWhite : (uIdx % 2 === 0 ? PAL.cyanBright : PAL.violetDeep);
        brush.set("rotring", gCol, 0.48);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }
  }

  for (let vIdx = -9; vIdx <= 9; vIdx++) {
    let v = vIdx / 9;
    let steps = 48;
    for (let s = 0; s < steps; s++) {
      let u1 = -1.1 + (s / steps) * 2.2;
      let u2 = -1.1 + ((s + 1) / steps) * 2.2;
      let a = warpLabelPt(u1, v);
      let b = warpLabelPt(u2, v);
      if (isInsideLabel(a[0], a[1]) && isInsideLabel(b[0], b[1])) {
        let p1 = cPt(a[0], a[1]);
        let p2 = cPt(b[0], b[1]);
        let gCol = v < 0 ? PAL.cyanBright : PAL.earthUmber;
        brush.set("rotring", gCol, 0.5);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }
  }

  // Sharp chrome border around the label & inner window + type-free gauge tick marks
  let labelOutline = [cPt(-268, -174), cPt(268, -174), cPt(294, -148), cPt(294, 84), cPt(-294, 84), cPt(-294, -148)];
  for (let i = 0; i < labelOutline.length; i++) {
    let p1 = labelOutline[i];
    let p2 = labelOutline[(i + 1) % labelOutline.length];
    brush.set("rotring", PAL.earthBlack, 0.9);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  let winOutline = [cPt(-212, -70), cPt(212, -70), cPt(212, 44), cPt(-212, 44)];
  for (let i = 0; i < 4; i++) {
    let p1 = winOutline[i];
    let p2 = winOutline[(i + 1) % 4];
    brush.set("rotring", PAL.earthBlack, 1.0);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    let p1In = cPt(i === 1 || i === 2 ? 210 : -210, i < 2 ? -68 : 42);
    let p2In = cPt((i + 1) % 4 === 1 || (i + 1) % 4 === 2 ? 210 : -210, (i + 1) % 4 < 2 ? -68 : 42);
    brush.set("rotring", PAL.chromeWhite, 0.65);
    brush.line(p1In[0], p1In[1], p2In[0], p2In[1]);
  }

  // Type-free tape gauge tick scale inside the central window
  let scaleL = cPt(-65, -13), scaleR = cPt(65, -13);
  brush.set("rotring", PAL.chromeWhite, 0.55);
  brush.line(scaleL[0], scaleL[1], scaleR[0], scaleR[1]);
  for (let tx = -65; tx <= 65; tx += 13) {
    let th = (tx % 26 === 0) ? 9 : 5;
    let t1 = cPt(tx, -13 - th), t2 = cPt(tx, -13 + th);
    brush.set("rotring", PAL.chromeWhite, 0.5);
    brush.line(t1[0], t1[1], t2[0], t2[1]);
  }

  // =========================================================================
  // 4F. BOTTOM TRAPEZOID HEAD HOUSING, PRESSURE PAD & 5 SHARP SCREWS
  // =========================================================================
  let trapTopL = -208, trapTopR = 208, trapBotL = -242, trapBotR = 242;
  let trapPts = [cPt(trapTopL, 102), cPt(trapTopR, 102), cPt(trapBotR, 210), cPt(trapBotL, 210)];
  drawPolyWash(trapPts, PAL.violetDeep, 120);

  // Ridged semi-transparent plastic texture on trapezoid
  for (let ty = 108; ty <= 204; ty += 5.5) {
    let frac = (ty - 102) / (210 - 102);
    let lx1 = lerp(trapTopL, trapBotL, frac);
    let lx2 = lerp(trapTopR, trapBotR, frac);
    let p1 = cPt(lx1, ty), p2 = cPt(lx2, ty);
    brush.set("rotring", ty % 11 < 5.5 ? PAL.paperLight : PAL.violetDeep, 0.42);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 3D beveled border of the trapezoid
  brush.set("rotring", PAL.chromeWhite, 0.95);
  brush.line(trapPts[0][0], trapPts[0][1], trapPts[1][0], trapPts[1][1]);
  brush.line(trapPts[0][0], trapPts[0][1], trapPts[3][0], trapPts[3][1]);
  brush.set("rotring", PAL.cyanBright, 0.65);
  brush.line(trapPts[1][0], trapPts[1][1], trapPts[2][0], trapPts[2][1]);

  // Copper spring + felt pressure pad in bottom center window (visible through clear casing)
  let springPts = [cPt(-62, 184), cPt(62, 184), cPt(62, 194), cPt(-62, 194)];
  drawPolyWash(springPts, PAL.earthOchre, 225);
  let padPts = [cPt(-20, 176), cPt(20, 176), cPt(20, 202), cPt(-20, 202)];
  drawPolyWash(padPts, PAL.earthUmber, 235);
  brush.set("rotring", PAL.chromeWhite, 0.55);
  brush.line(springPts[0][0], springPts[0][1], springPts[1][0], springPts[1][1]);

  // 4 Capstan & Guide Pin Holes along the trapezoid
  const holes = [
    { lx: -165, ly: 165, r: 19 },
    { lx: -95, ly: 176, r: 15 },
    { lx: 95, ly: 176, r: 15 },
    { lx: 165, ly: 165, r: 19 }
  ];
  for (let h of holes) {
    // 3D depth well inside the hole
    fillCassetteCircle(h.lx + extX * 0.25, h.ly + extY * 0.25, h.r, PAL.violetDeep, 240, 24);
    drawCassetteCircle(h.lx + extX * 0.22, h.ly + extY * 0.22, h.r * 0.85, PAL.cyanMuted, 0.45, "rotring", 24);
    // Crisp top acrylic rim
    drawCassetteCircle(h.lx, h.ly, h.r, PAL.chromeWhite, 0.85, "rotring", 28);
    drawCassetteCircle(h.lx, h.ly, h.r + 3, PAL.cyanBright, 0.4, "rotring", 28);
  }

  // 5 Sharp Metallic Philips-Head Screws
  const screws = [
    [-308, -188],
    [308, -188],
    [-308, 188],
    [308, 188],
    [0, 122]
  ];
  for (let sc of screws) {
    let sx = sc[0], sy = sc[1];
    // Acrylic screw boss ring
    drawCassetteCircle(sx, sy, 15, PAL.paperLight, 0.5, "rotring", 24);
    fillCassetteCircle(sx, sy, 11, PAL.earthBlack, 230, 20);
    // Metallic screw head with chrome gradient
    fillCassetteCircle(sx, sy, 9.5, PAL.paperLight, 240, 20);
    for (let dy = -7; dy <= 7; dy += 2) {
      let hw = Math.sqrt(Math.max(0, 81 - dy * dy));
      let p1 = cPt(sx - hw, sy + dy), p2 = cPt(sx + hw, sy + dy);
      let sCol = dy < -2 ? PAL.chromeWhite : (dy < 2 ? PAL.earthBlack : PAL.cyanBright);
      brush.set("rotring", sCol, 0.55);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
    // Sharp Philips cross slot + glint
    let c1 = cPt(sx - 6.5, sy - 1.5), c2 = cPt(sx + 6.5, sy + 1.5);
    let c3 = cPt(sx - 1.5, sy + 6.5), c4 = cPt(sx + 1.5, sy - 6.5);
    brush.set("rotring", PAL.earthBlack, 1.1);
    brush.line(c1[0], c1[1], c2[0], c2[1]);
    brush.line(c3[0], c3[1], c4[0], c4[1]);
    let g1 = cPt(sx - 5.5, sy - 2.5), g2 = cPt(sx + 5.5, sy + 0.5);
    brush.set("rotring", PAL.chromeWhite, 0.5);
    brush.line(g1[0], g1[1], g2[0], g2[1]);
  }

  // 4G. Scratched Clear Casing Specular Glints & Acrylic Edge Highlights
  // Diagonal glassy reflection bands across the clear window and shell
  const glassBands = [
    [-250, -210, -330, -80, 3.2],
    [-110, -210, -290, 120, 4.0],
    [-95, -210, -275, 120, 2.2],
    [80, -70, -35, 110, 3.5],
    [220, -210, 40, 100, 2.8],
    [310, -140, 160, 210, 3.2]
  ];
  for (let gb of glassBands) {
    let p1 = cPt(gb[0], gb[1]), p2 = cPt(gb[2], gb[3]);
    brush.set("marker", PAL.chromeWhite, gb[4]);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.set("rotring", PAL.cyanBright, 0.5);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Outer clear casing razor-sharp bevel lines
  for (let i = 0; i < frontFacePts.length; i++) {
    let p1 = frontFacePts[i];
    let p2 = frontFacePts[(i + 1) % frontFacePts.length];
    brush.set("rotring", i < 3 || i === 7 ? PAL.chromeWhite : PAL.cyanBright, 1.05);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  let botEdge1 = cPt(-318 + extX, 210 + extY);
  let botEdge2 = cPt(318 + extX, 210 + extY);
  let leftEdge1 = cPt(-330 + extX, -198 + extY);
  let leftEdge2 = cPt(-330 + extX, 198 + extY);
  brush.set("rotring", PAL.cyanElec, 0.85);
  brush.line(botEdge1[0], botEdge1[1], botEdge2[0], botEdge2[1]);
  brush.line(leftEdge1[0], leftEdge1[1], leftEdge2[0], leftEdge2[1]);

  // Hyperreal micro-scratches & acrylic surface scuffs on the clear plastic shell
  for (let i = 0; i < 145; i++) {
    let sx = random(-315, 315);
    let sy = random(-195, 195);
    // Concentrate scratches on the clear window & clear outer edges (skip most of the foil label body)
    if (isInsideLabel(sx, sy) && random() < 0.78) continue;
    let sAng = random(360);
    let sLen = random(8, 52);
    let p1 = cPt(sx, sy);
    let p2 = cPt(sx + cos(sAng) * sLen, sy + sin(sAng) * sLen);
    let scCol = random() < 0.65 ? PAL.chromeWhite : (random() < 0.5 ? PAL.cyanBright : PAL.paperLight);
    brush.set(random() < 0.4 ? "rotring" : "2H", scCol, random(0.28, 0.52));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // =========================================================================
  // 5. SPILLING LOOP OF SHINY MAGNETIC TAPE + SMUDGY SPRAY HALO
  // =========================================================================
  // Catmull-Rom spline evaluator for smooth, twisting 3D tape ribbon
  function evalCatmullRom(pts, tGlobal) {
    let n = pts.length - 3;
    let scaled = constrain(tGlobal, 0, 0.999999) * n;
    let idx = Math.floor(scaled);
    let t = scaled - idx;
    let p0 = pts[idx], p1 = pts[idx + 1], p2 = pts[idx + 2], p3 = pts[idx + 3];
    let t2 = t * t, t3 = t2 * t;
    let x = 0.5 * (
      (2 * p1[0]) +
      (-p0[0] + p2[0]) * t +
      (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
      (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3
    );
    let y = 0.5 * (
      (2 * p1[1]) +
      (-p0[1] + p2[1]) * t +
      (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
      (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3
    );
    return [x, y];
  }

  // Control points: tape exits left head slot of cassette, loops wildly across foreground, re-enters right head slot
  const exitLeft = cPt(-105, 208);
  const exitLeftOut = cPt(-115, 255);
  const enterRightOut = cPt(115, 255);
  const enterRight = cPt(105, 208);

  const tapeCtrl = [
    cPt(-105, 190),
    exitLeft,
    exitLeftOut,
    [430, 690],
    [230, 740],
    [145, 895],
    [265, 1055],
    [515, 1025],
    [685, 845],
    [520, 705],
    [355, 815],
    [465, 985],
    [765, 1085],
    [1035, 995],
    [1065, 805],
    [875, 695],
    [720, 785],
    [825, 920],
    [945, 835],
    [805, 635],
    enterRightOut,
    enterRight,
    cPt(105, 190)
  ];

  // Sample the ribbon geometry
  const ribbonSteps = 780;
  const rPts = [];
  for (let i = 0; i <= ribbonSteps; i++) {
    let t = i / ribbonSteps;
    rPts.push(evalCatmullRom(tapeCtrl, t));
  }

  // 5A. Smudgy Halo around the Tape's Ribbon (Spray + Dark Violet/Earth/Cyan Glow)
  for (let i = 0; i < ribbonSteps; i += 3) {
    let p = rPts[i];
    let pNext = rPts[Math.min(ribbonSteps, i + 4)];
    // Outer violet/earth smudgy photocopy halo
    brush.set("spray", i % 6 === 0 ? PAL.violetDeep : PAL.earthBlack, random(1.8, 3.0));
    let ang = random(360);
    let rad = random(18, 48);
    brush.line(p[0] - cos(ang) * rad * 0.5, p[1] - sin(ang) * rad * 0.5, p[0] + cos(ang) * rad, p[1] + sin(ang) * rad);

    // Inner electric cyan & warm ochre halo smudge
    if (i % 6 === 0) {
      brush.set("spray", (i % 12 === 0) ? PAL.cyanElec : PAL.earthOchre, 1.5);
      brush.line(p[0] + random(-18, 18), p[1] + random(-18, 18), pNext[0] + random(-18, 18), pNext[1] + random(-18, 18));
    }
    // Soft charcoal/marker smudge core beneath the ribbon
    brush.set("charcoal", PAL.violetDeep, 2.4);
    brush.line(p[0] + 6, p[1] + 10, pNext[0] + 6, pNext[1] + 10);
  }

  // 5B. Hyperreal Shiny Magnetic Tape Ribbon (Twisting 3D Normals + Anisotropic Specular Bands)
  const baseHalfWidth = 17.5;
  let prevEdgeA = null;
  let prevEdgeB = null;

  for (let i = 0; i <= ribbonSteps; i++) {
    let t = i / ribbonSteps;
    let p = rPts[i];
    let pPrev = rPts[Math.max(0, i - 1)];
    let pNext = rPts[Math.min(ribbonSteps, i + 1)];

    let tx = pNext[0] - pPrev[0];
    let ty = pNext[1] - pPrev[1];
    let tLen = Math.hypot(tx, ty) || 1;
    tx /= tLen;
    ty /= tLen;

    let nx = -ty;
    let ny = tx;

    // Smooth continuous twist angle so the ribbon flips side-over-side 7 times
    let twist = t * Math.PI * 7.4 + 0.85 * Math.sin(t * Math.PI * 11) + 0.4 * Math.cos(t * Math.PI * 19);
    // Taper slightly right as it enters the cassette slots
    let endTaper = (t < 0.04) ? map(t, 0, 0.04, 0.45, 1) : ((t > 0.96) ? map(t, 0.96, 1, 1, 0.45) : 1);
    let hw = baseHalfWidth * endTaper;

    let cosTw = Math.cos(twist);
    let sinTw = Math.sin(twist);

    // Projected 2D ribbon width vector
    let wx = (nx * cosTw + tx * 0.24 * sinTw) * hw;
    let wy = (ny * cosTw + ty * 0.24 * sinTw) * hw;

    let edgeA = [p[0] - wx, p[1] - wy];
    let edgeB = [p[0] + wx, p[1] + wy];

    // Calculate anisotropic metallic/mylar reflection from tangent angle and twist angle
    let surfAngle = Math.atan2(ny, nx) + twist * 0.85;
    let spec1 = Math.pow(0.5 + 0.5 * Math.cos(surfAngle * 2.0 - 0.9), 4);
    let spec2 = Math.pow(0.5 + 0.5 * Math.sin(surfAngle * 3.0 + 1.4), 8);

    // Choose slick marker body color and sharp rotring reflection stripe color
    let bodyCol, highlightCol;
    if (spec2 > 0.72) {
      bodyCol = PAL.cyanBright;
      highlightCol = PAL.chromeWhite;
    } else if (spec1 > 0.78) {
      bodyCol = PAL.earthOchre;
      highlightCol = PAL.chromeWhite;
    } else if (spec1 > 0.52) {
      bodyCol = PAL.earthRust;
      highlightCol = PAL.cyanElec;
    } else if (spec1 < 0.16) {
      bodyCol = PAL.earthBlack;
      highlightCol = PAL.violetMid;
    } else {
      bodyCol = PAL.earthUmber;
      highlightCol = PAL.earthOchre;
    }

    // Draw cross-ribbon scanline
    brush.set("marker", bodyCol, 1.35);
    brush.line(edgeA[0], edgeA[1], edgeB[0], edgeB[1]);

    // Longitudinal sheen band & crisp specular reflections across the shiny ribbon
    if (spec2 > 0.55 || spec1 > 0.65 || i % 2 === 0) {
      let hFrac1 = (spec2 > 0.6) ? 0.1 : 0.25;
      let hFrac2 = (spec2 > 0.6) ? 0.9 : 0.75;
      let hx1 = lerp(edgeA[0], edgeB[0], hFrac1);
      let hy1 = lerp(edgeA[1], edgeB[1], hFrac1);
      let hx2 = lerp(edgeA[0], edgeB[0], hFrac2);
      let hy2 = lerp(edgeA[1], edgeB[1], hFrac2);
      brush.set("rotring", highlightCol, (spec2 > 0.72 || spec1 > 0.82) ? 0.9 : 0.5);
      brush.line(hx1, hy1, hx2, hy2);
    }

    // Razor-sharp ribbon edges (flashing bright white/cyan at twists and dark oxide in shadows)
    if (prevEdgeA && prevEdgeB) {
      let isPinch = Math.abs(cosTw) < 0.35;
      let edgeColA = (isPinch || spec2 > 0.55) ? PAL.chromeWhite : (cosTw > 0 ? PAL.cyanBright : PAL.earthBlack);
      let edgeColB = (isPinch || spec1 > 0.7) ? PAL.chromeWhite : (cosTw < 0 ? PAL.earthOchre : PAL.earthBlack);

      brush.set("rotring", edgeColA, isPinch ? 0.85 : 0.6);
      brush.line(prevEdgeA[0], prevEdgeA[1], edgeA[0], edgeA[1]);

      brush.set("rotring", edgeColB, isPinch ? 0.85 : 0.6);
      brush.line(prevEdgeB[0], prevEdgeB[1], edgeB[0], edgeB[1]);
    }

    prevEdgeA = edgeA;
    prevEdgeB = edgeB;
  }

  // Secondary tight crinkle loop right at the center head opening of the cassette
  const crinkleCtrl = [
    cPt(-35, 204),
    cPt(-38, 222),
    [545, 705],
    [605, 765],
    [655, 705],
    cPt(38, 222),
    cPt(35, 204)
  ];
  let prevCrA = null, prevCrB = null;
  for (let i = 0; i <= 110; i++) {
    let t = i / 110;
    let p = evalCatmullRom(crinkleCtrl, t);
    let pNext = evalCatmullRom(crinkleCtrl, Math.min(1, t + 0.01));
    let tx = pNext[0] - p[0], ty = pNext[1] - p[1];
    let tl = Math.hypot(tx, ty) || 1;
    let nx = -ty / tl, ny = tx / tl;
    let tw = t * Math.PI * 3.2;
    let hw = 13 * Math.cos(tw);
    let eA = [p[0] - nx * hw, p[1] - ny * hw];
    let eB = [p[0] + nx * hw, p[1] + ny * hw];

    brush.set("marker", Math.abs(Math.cos(tw)) < 0.35 ? PAL.cyanBright : PAL.earthUmber, 1.2);
    brush.line(eA[0], eA[1], eB[0], eB[1]);
    if (prevCrA) {
      brush.set("rotring", Math.sin(t * 18) > 0.3 ? PAL.chromeWhite : PAL.earthBlack, 0.55);
      brush.line(prevCrA[0], prevCrA[1], eA[0], eA[1]);
      brush.line(prevCrB[0], prevCrB[1], eB[0], eB[1]);
    }
    prevCrA = eA;
    prevCrB = eB;
  }

  // =========================================================================
  // 6. CRUMPLED PHOTOCOPIED FLYER TEXTURE, POCKET FOLDS & GRAINY SPRAY NOISE
  // =========================================================================
  // Helper to draw a realistic crumpled paper fold (shadow trough + cracked white toner ridge)
  function drawPaperCrease(x1, y1, x2, y2, strength = 1.0) {
    let segs = Math.max(6, Math.floor(Math.hypot(x2 - x1, y2 - y1) / 45));
    let pts = [[x1, y1]];
    for (let i = 1; i < segs; i++) {
      let t = i / segs;
      pts.push([
        lerp(x1, x2, t) + random(-9, 9) * strength,
        lerp(y1, y2, t) + random(-9, 9) * strength
      ]);
    }
    pts.push([x2, y2]);

    for (let i = 0; i < pts.length - 1; i++) {
      let a = pts[i], b = pts[i + 1];
      // Soft pocket-dirt shadow along fold trough
      brush.set("charcoal", PAL.paperDark, 1.3 * strength);
      brush.line(a[0] + 3, a[1] + 4, b[0] + 3, b[1] + 4);
      brush.set("HB", PAL.earthUmber, 0.7 * strength);
      brush.line(a[0] + 2, a[1] + 2, b[0] + 2, b[1] + 2);

      // Abraded paper fiber ridge where photocopy toner flaked off the crease
      brush.set("rotring", PAL.paperLight, 0.85 * strength);
      brush.line(a[0], a[1], b[0], b[1]);
      brush.set("2H", PAL.chromeWhite, 0.55 * strength);
      brush.line(a[0] - 1, a[1] - 1, b[0] - 1, b[1] - 1);
    }
  }

  // Primary quarter-fold creases (from being folded in a jacket pocket)
  drawPaperCrease(0, 612, 605, 592, 1.25);
  drawPaperCrease(605, 592, 1200, 624, 1.25);
  drawPaperCrease(588, 0, 605, 592, 1.15);
  drawPaperCrease(605, 592, 578, 1200, 1.15);

  // Branching diagonal pocket crumple network across the flyer
  const crumples = [
    [0, 210, 390, 410, 0.85],
    [390, 410, 605, 592, 0.75],
    [1200, 140, 810, 385, 0.9],
    [810, 385, 605, 592, 0.7],
    [0, 960, 410, 775, 0.9],
    [410, 775, 588, 880, 0.75],
    [1200, 940, 845, 790, 0.85],
    [845, 790, 578, 1200, 0.8],
    [210, 0, 390, 410, 0.65],
    [940, 0, 810, 385, 0.65],
    [140, 1200, 410, 775, 0.7],
    [0, 460, 265, 602, 0.65],
    [920, 610, 1200, 470, 0.65]
  ];
  for (let cr of crumples) {
    drawPaperCrease(cr[0], cr[1], cr[2], cr[3], cr[4]);
  }

  // Grainy photocopy noise across the canvas (Spray toner stipple + dust specks)
  for (let i = 0; i < 190; i++) {
    let gx = random(20, 1180);
    let gy = random(20, 1180);
    let gLen = random(15, 75);
    let gAng = random(360);
    let nCol = (i % 3 === 0) ? PAL.violetDeep : (i % 3 === 1 ? PAL.paperLight : PAL.earthUmber);
    brush.set("spray", nCol, random(0.9, 1.9));
    brush.line(gx, gy, gx + cos(gAng) * gLen, gy + sin(gAng) * gLen);
  }

  // Worn flyer border / cheap photocopy edge toner artifacts
  const m = 22;
  drawPolyWash([[0, 0], [1200, 0], [1200, m], [0, m]], PAL.paper, 235);
  drawPolyWash([[0, 1200 - m], [1200, 1200 - m], [1200, 1200], [0, 1200]], PAL.paper, 235);
  drawPolyWash([[0, 0], [m, 0], [m, 1200], [0, 1200]], PAL.paper, 235);
  drawPolyWash([[1200 - m, 0], [1200, 0], [1200, 1200], [1200 - m, 1200]], PAL.paper, 235);

  // Double-printed registration border line (cyan + deep violet offset)
  brush.set("rotring", PAL.cyanElec, 0.75);
  brush.rect(m + 4, m - 3, 1200 - 2 * m, 1200 - 2 * m, "corner");
  brush.set("rotring", PAL.violetDeep, 0.95);
  brush.rect(m, m, 1200 - 2 * m, 1200 - 2 * m, "corner");

  // Toner scum & corner wear marks
  for (let i = 0; i < 45; i++) {
    let edge = i % 4;
    let ex = edge === 0 ? random(m, 1200 - m) : (edge === 1 ? 1200 - m : (edge === 2 ? random(m, 1200 - m) : m));
    let ey = edge === 0 ? m : (edge === 1 ? random(m, 1200 - m) : (edge === 2 ? 1200 - m : random(m, 1200 - m)));
    brush.set("charcoal", i % 2 === 0 ? PAL.violetDeep : PAL.paperDark, random(0.8, 1.8));
    brush.line(ex + random(-12, 12), ey + random(-12, 12), ex + random(-25, 25), ey + random(-25, 25));
  }

  noLoop();
}

