// 3. FOREGROUND PARAPET WITH SOFT CHARCOAL BLOOMS & CLOTHESLINE POST
// ============================================================================

function drawParapetAndPost() {
  // Parapet geometry: slopes slightly from left (y = 946) to right (y = 978)
  let yL = 946, yR = 978;

  // Top flat stone coping plane (catches cool cerulean zenith sky light)
  let copingTop = [
    [-20, yL], [1220, yR],
    [1220, yR + 18], [-20, yL + 18]
  ];
  washPoly(copingTop, "#293e5c", 245, 0.02);
  fillPoly(copingTop, "#3c5980", 130, 0.22, 0.55, 0.35, 0.03);

  // Subtle warm tungsten reflection on the coping stone directly below the lit window (x = 390..480)
  fillPoly([
    [380, 956], [490, 959], [495, 976], [375, 973]
  ], "#9c704c", 70, 0.35, 0.45, 0.25, 0.15);

  // Vertical front lip of stone coping
  let copingLip = [
    [-20, yL + 18], [1220, yR + 18],
    [1220, yR + 44], [-20, yL + 44]
  ];
  washPoly(copingLip, "#152236", 250, 0.01);

  // Main lower parapet wall (y = 990 to 1220)
  let parapetWall = [
    [-20, yL + 42], [1220, yR + 42],
    [1220, 1220], [-20, 1220]
  ];
  washPoly(parapetWall, "#0c1320", 250, 0.01);

  // SOFT CHARCOAL BLOOMS deepening the foreground parapet
  let bloomRegions = [
    { x: -30, y: 985, w: 420, h: 240, col: "#060a12", op: 185 },
    { x: 310, y: 995, w: 460, h: 230, col: "#080d18", op: 175 },
    { x: 700, y: 1000, w: 530, h: 225, col: "#050911", op: 195 },
    { x: 60,  y: 1045, w: 550, h: 180, col: "#04070d", op: 200 },
    { x: 560, y: 1055, w: 660, h: 175, col: "#04070d", op: 205 }
  ];
  for (let b of bloomRegions) {
    let pts = [];
    let steps = 10;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      pts.push([b.x + t * b.w, b.y + (noise(t * 3.5, b.x * 0.01) - 0.5) * 34]);
    }
    pts.push([b.x + b.w, b.y + b.h]);
    pts.push([b.x, b.y + b.h]);
    fillPoly(pts, b.col, b.op, 0.48, 0.85, 0.65, 0.25);
  }

  // Dry charcoal mass and expressive charcoal_bloom strokes across the parapet
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.mass("charcoal", "#070c16", { precision: 0.25, strength: 0.65, gradient: 0.55, outline: false });
  brush.rect(-10, 1020, 1220, 190, "corner");
  brush.noMass();

  // Layered charcoal_bloom & 2B strokes for velvety soot/masonry texture
  for (let i = 0; i < 55; i++) {
    let x1 = random(-20, 1150);
    let y1 = random(985, 1195);
    let len = random(80, 260);
    let ang = random(-8, 8);
    let x2 = x1 + cos(ang) * len;
    let y2 = y1 + sin(ang) * len;
    let col = i % 4 === 0 ? "#17253b" : (i % 3 === 0 ? "#0d1626" : "#050810");
    strokeSpline([
      [x1, y1, random(0.4, 0.9)],
      [(x1 + x2) * 0.5, (y1 + y2) * 0.5 + random(-10, 10), random(0.8, 1.3)],
      [x2, y2, random(0.3, 0.7)]
    ], "charcoal_bloom", col, random(0.8, 1.6), 0.4);
  }

  // Crisp shadow line under the coping overhang & weathered mortar joints
  strokeLine(-20, yL + 44, 1220, yR + 44, "charcoal", "#03050a", 1.8);
  strokeLine(-20, yL + 18, 1220, yR + 18, "2B", "#587ba6", 0.95);
  strokeLine(-20, yL, 1220, yR, "cpencil", "#4b6b94", 0.8);

  // Stone coping slab joints
  for (let jx of [185, 435, 695, 955]) {
    let jy = map(jx, -20, 1220, yL, yR);
    strokeLine(jx, jy, jx - 14, jy + 18, "2B", "#162336", 0.85);
    strokeLine(jx - 14, jy + 18, jx - 14, jy + 44, "2B", "#080e18", 0.95);
  }

  // Charcoal spatter/grain along the coping edge
  for (let i = 0; i < 32; i++) {
    let sx = random(0, 1200);
    let sy = map(sx, 0, 1200, yL, yR) + random(-4, 65);
    strokeLine(sx, sy, sx + random(15, 55), sy + random(-6, 6), "terry_grain", "#080f1c", random(0.8, 1.5));
  }

  // ==========================================================================
  // LEFT ROOFTOP IRON CLOTHESLINE STANCHION / PIPE POST (x = 54, y = 188..952)
  // ==========================================================================
  let px = 54;
  // Iron pipe body
  washPoly([
    [px - 6, 188], [px + 6, 188],
    [px + 8, 952], [px - 8, 952]
  ], "#0e1726", 250, 0.01);

  // Diagonal iron brace at base anchored into parapet coping
  washPoly([
    [px + 6, 825], [px + 12, 825],
    [px + 68, 954], [px + 58, 954]
  ], "#101b2b", 245, 0.01);
  strokeLine(px + 11, 825, px + 67, 954, "cpencil", "#5477a1", 0.75);

  // Top T-bar crosspiece at y = 205
  washPoly([
    [px - 28, 200], [px + 26, 200],
    [px + 26, 210], [px - 28, 210]
  ], "#111c2e", 250, 0.01);
  strokeLine(px - 28, 200, px + 26, 200, "cpencil", "#7ca4cf", 0.85);

  // Cerulean sky highlight along right side of iron post & warm apricot glint lower down
  strokeLine(px + 5, 190, px + 6, 680, "cpencil", "#6d96c2", 0.9);
  strokeLine(px + 6, 680, px + 7, 835, "cpencil", "#c98b6b", 0.75);
  strokeLine(px - 6, 190, px - 7, 950, "2B", "#060b14", 0.9);
}

