  ];

  for (let f of foldCols) {
    let yStart = 290;
    let yEnd = 768 - abs(f.xBot - 335) * 0.38;
    // Across each fold column (-1 to +1), interpolate shadow trough -> lit ridge -> terminator
    for (let s = -4; s <= 4; s++) {
      let u = s / 4; // -1 to 1
      let dxTop = u * f.w * 0.38;
      let dxMid = u * f.w * 0.52;
      let dxBot = u * f.w * 0.58;

      let p1 = [f.xTop + dxTop, yStart + abs(u) * 8, 0.5];
