  for (let b = 0; b < 7; b++) {
    let by = 346 + b * 64;
    let bx = map(by, 314, 784, 335, 331);
    // Button cast shadow
    strokeLine(bx - 3, by + 3, bx + 3, by + 3, "2B", "#1e3452", 1.2);
    // Button rim
    brush.noFill();
    brush.noWash();
    brush.set("cpencil", b > 4 ? "#f5d1b8" : "#eef8ff", 0.9);
    brush.circle(bx, by, 4.2, 0.1);
    // Thread cross in center
    strokeLine(bx - 1.5, by - 1.5, bx + 1.5, by + 1.5, "rotring", "#335278", 0.55);
    strokeLine(bx + 1.5, by - 1.5, bx - 1.5, by + 1.5, "rotring", "#335278", 0.55);
  }

  // Rolled shirttail hem with double stitching & warm apricot rim glow
  let hemCurve = [
    [190, 714], [235, 754], [285, 776], [335, 784], [382, 779], [428, 762], [468, 722]
  ];
  let hemStitch = hemCurve.map(p => [p[0], p[1] - 9]);
  strokeSpline(hemCurve, "crease", "#384b6b", 1.1, 0.45);
  strokeSpline(hemCurve.map(p => [p[0], p[1] - 2]), "cpencil", "#fad0b1", 1.0, 0.45);
  strokeSpline(hemStitch, "rotring", "#496487", 0.6, 0.45);

  // Crisp sky-lit outer contour highlights on shoulders and upper sleeves
  strokeSpline([[126, 540], [136, 448], [154, 355], [180, 296], [205, 252]], "cpencil", "#eef8ff", 1.05, 0.4);
  strokeSpline([[205, 252], [238, 268], [268, 278]], "cpencil", "#f2faff", 1.1, 0.35);
  strokeSpline([[398, 282], [434, 277], [465, 272]], "cpencil", "#f2faff", 1.1, 0.35);
  strokeSpline([[465, 272], [495, 312], [520, 372], [538, 468]], "cpencil", "#e3f3ff", 0.95, 0.4);
}

function drawPinchCreases(px, py, targets, lightCol, darkCol) {
  for (let i = 0; i < targets.length; i++) {
    let tx = targets[i][0];
    let ty = targets[i][1];
    let mx = lerp(px, tx, 0.48) + (i - 3) * 3;
    let my = lerp(py, ty, 0.48);

    // Sharp shadow crease
    strokeSpline([
      [px, py + 4, 1.25],
      [mx, my, 0.85],
      [tx, ty, 0.15]
    ], "crease", darkCol, 1.05, 0.35);

    // Adjacent crisp sky-lit ridge
    strokeSpline([
      [px + 2.5, py + 4, 1.2],
      [mx + 3.5, my, 0.9],
      [tx + 4, ty, 0.15]
    ], "crease", lightCol, 1.1, 0.35);
  }
}

// ============================================================================
// 5B. THE STRIPED TOWEL (x = 582..855, y = 272..824)
// ============================================================================

// Mathematical 3D fold field for the heavy terrycloth bath towel
function towelPoint(u, v) {
  // u in [0, 1] across width, v in [0, 1] down length
  let topX = lerp(592, 838, u);
  // Top catenary sag between Pin 2 (u=0.02) and Pin 3 (u=0.98)
  let topSag = 18 * sin(u * 180);
  let topY = lerp(278, 274, u) + topSag;

  // Slight evening breeze sway & bottom flare
  let botX = lerp(576, 852, u) - 8 * sin(v * 90);
  let botY = 804 + 14 * sin(u * 180);

  let x = lerp(topX, botX, v);
  let y = lerp(topY, botY, v);

  // 6 major cylindrical vertical pipe-folds + pinch harmonics near top
  let waveAmp = lerp(4, 17, pow(v, 0.65));
  let pinchWave = (1 - v) * 6 * sin(u * 180 * 9);
  let mainWave = sin(u * 180 * 5.5 - 20);
  let secWave = 0.35 * cos(u * 180 * 11 + 35);
  let z = (mainWave + secWave) * waveAmp + pinchWave;

  // Derivative dz/du for surface normal lighting (light comes from upper-left sky)
  let dzdu = (5.5 * cos(u * 180 * 5.5 - 20) - 0.35 * 11 * sin(u * 180 * 11 + 35));

  // Perspective foreshortening: outward ridges (z > 0) shift slightly up-left, troughs (z < 0) dip down
  return {
    x: x + z * 0.25,
    y: y - z * 0.72,
    z: z,
    shade: constrain(map(dzdu + z * 0.12, -6, 6, 0, 1), 0, 1)
  };
}

function drawStripedTowel() {
  // 1. Underside shadow of the undulating bottom hem (gives 3D ribbon thickness to the cloth edge)
  let underHem = [];
  for (let i = 0; i <= 36; i++) {
    let p = towelPoint(i / 36, 1.0);
    underHem.push([p.x, p.y]);
  }
  for (let i = 36; i >= 0; i--) {
    let p = towelPoint(i / 36, 1.0);
    underHem.push([p.x + 3, p.y + 11 + max(0, -p.z * 0.45)]);
  }
  washPoly(underHem, "#122036", 245, 0.2);

  // 2. Main towel silhouette polygon
  let towelOutline = [];
  for (let i = 0; i <= 32; i++) {
    let p = towelPoint(i / 32, 0);
    towelOutline.push([p.x, p.y]);
  }
  for (let j = 1; j <= 24; j++) {
    let p = towelPoint(1, j / 24);
    towelOutline.push([p.x, p.y]);
  }
  for (let i = 31; i >= 0; i--) {
    let p = towelPoint(i / 32, 1);
    towelOutline.push([p.x, p.y]);
  }
  for (let j = 23; j >= 1; j--) {
    let p = towelPoint(0, j / 24);
    towelOutline.push([p.x, p.y]);
  }

  // Base terrycloth wash
  washPoly(towelOutline, "#6891b8", 244, 0.05);

  // Watercolor atmospheric washes on towel (cerulean sky top, subtle apricot bounce at bottom)
  let towelTopZone = [];
  for (let i = 0; i <= 16; i++) { let p = towelPoint(i / 16, 0); towelTopZone.push([p.x, p.y]); }
  for (let i = 16; i >= 0; i--) { let p = towelPoint(i / 16, 0.48); towelTopZone.push([p.x, p.y]); }
  fillPoly(towelTopZone, "#b8dcf5", 110, 0.25, 0.5, 0.3, 0.15);

  let towelBotZone = [];
  for (let i = 0; i <= 16; i++) { let p = towelPoint(i / 16, 0.72); towelBotZone.push([p.x, p.y]); }
  for (let i = 16; i >= 0; i--) { let p = towelPoint(i / 16, 1.0); towelBotZone.push([p.x, p.y]); }
  fillPoly(towelBotZone, "#d49879", 75, 0.28, 0.5, 0.3, 0.15);

  // 3. Woven Vertical Stripes & 3D Cylindrical Fold Modeling
  // Define 11 vertical stripe bands across u in [0, 1] (alternating cream-cerulean and deep indigo-slate stripes)
  let cols = 56;
  for (let c = 0; c <= cols; c++) {
    let u = c / cols;
    // Determine if u falls inside a dark woven stripe or a light terrycloth stripe
    let stripeCycle = (u * 6.5) % 1.0;
    let isDarkStripe = (stripeCycle > 0.28 && stripeCycle < 0.62) || (stripeCycle > 0.72 && stripeCycle < 0.80);

    let ptsUpper = [];
    let ptsLower = [];
    let avgShade = 0;

    for (let r = 0; r <= 14; r++) {
      let v = r / 14;
      let pt = towelPoint(u, v);
      avgShade += pt.shade;
      let press = 0.5 + 0.5 * sin(v * 180);
      if (r <= 9) ptsUpper.push([pt.x, pt.y, press]);
      if (r >= 7) ptsLower.push([pt.x, pt.y, press]);
    }
    avgShade /= 15;

    let colUp, colLow;
    if (isDarkStripe) {
      // Woven indigo-slate stripe modulated by 3D fold normal
      if (avgShade > 0.64) {
        colUp = "#436891"; colLow = "#4f6885";
      } else if (avgShade > 0.38) {
        colUp = "#284569"; colLow = "#304866";
      } else {
        colUp = "#152740"; colLow = "#182940";
      }
    } else {
      // Bleached cerulean-white terry stripe modulated by 3D fold normal
      if (avgShade > 0.66) {
        colUp = "#d4edfc"; colLow = "#e3c5b1";
      } else if (avgShade > 0.40) {
        colUp = "#84add4"; colLow = "#96a6bd";
      } else {
        colUp = "#385980"; colLow = "#3f5878";
      }
    }

    strokeSpline(ptsUpper, "drapery", colUp, 1.15, 0.45);
    strokeSpline(ptsLower, "drapery", colLow, 1.15, 0.45);

    // Crisp crease lines in deepest fold troughs
    if (avgShade < 0.22 && c % 2 === 0) {
      strokeSpline(ptsUpper.concat(ptsLower.slice(2)), "crease", "#112036", 0.9, 0.45);
    }
    // Brightest sky-lit ridges
    if (avgShade > 0.78 && !isDarkStripe) {
      strokeSpline(ptsUpper, "crease", "#eef8ff", 0.95, 0.45);
    }
  }

  // 4. Horizontal Woven Dobby Border Bands near the bottom (v = 0.84..0.92)
  // These bands warp up and down in 3D across every cylindrical fold ridge and trough!
  let borderV = [
    { v1: 0.835, v2: 0.852, light: "#355780", dark: "#13233b" },
    { v1: 0.858, v2: 0.870, light: "#e3f2fc", dark: "#47698f" },
    { v1: 0.875, v2: 0.912, light: "#29466b", dark: "#0f1d33" },
    { v1: 0.918, v2: 0.928, light: "#ebcdb7", dark: "#4a6382" }
  ];

  for (let b of borderV) {
    let segs = 28;
    for (let s = 0; s < segs; s++) {
      let u1 = s / segs;
      let u2 = (s + 1) / segs;
      let p1 = towelPoint(u1, b.v1);
      let p2 = towelPoint(u2, b.v1);
      let p3 = towelPoint(u2, b.v2);
      let p4 = towelPoint(u1, b.v2);
      let sh = (p1.shade + p2.shade) * 0.5;
      let col = sh > 0.58 ? b.light : (sh > 0.35 ? "#223b5c" : b.dark);
      washPoly([[p1.x, p1.y], [p2.x, p2.y], [p3.x, p3.y], [p4.x, p4.y]], col, 225, 0.02);
    }
    // Ribbed dobby texture along the border band
    let ribLine = [];
    for (let s = 0; s <= 32; s++) {
      let p = towelPoint(s / 32, (b.v1 + b.v2) * 0.5);
      ribLine.push([p.x, p.y, 0.6 + p.shade * 0.5]);
    }
    strokeSpline(ribLine, "cpencil", b.light, 0.75, 0.45);
  }

  // 5. Top Folded Overhang Flap over the Clothesline (v = 0 to 0.13)
  let flapPts = [];
  for (let i = 0; i <= 24; i++) {
    let p = towelPoint(i / 24, 0);
    flapPts.push([p.x, p.y - 3]);
  }
  for (let i = 24; i >= 0; i--) {
    let u = i / 24;
    let p = towelPoint(u, 0.11 + 0.035 * sin(u * 180));
    flapPts.push([p.x, p.y]);
  }
  // Cast shadow beneath the overhang flap onto the towel body
  let flapShadow = flapPts.slice(25).map(p => [p[0], p[1] + 9]);
  strokeSpline(flapShadow, "drapery", "#0f1d33", 1.5, 0.4);
  strokeSpline(flapShadow, "crease", "#091324", 1.15, 0.4);

  washPoly(flapPts, "#7fa8cf", 242, 0.08);
  // Stripes on the overhang flap
  for (let c = 0; c <= 28; c++) {
    let u = c / 28;
    let stripeCycle = (u * 6.5) % 1.0;
    let isDark = (stripeCycle > 0.28 && stripeCycle < 0.62) || (stripeCycle > 0.72 && stripeCycle < 0.80);
    let pTop = towelPoint(u, 0);
    let pBot = towelPoint(u, 0.11 + 0.035 * sin(u * 180));
    let col = isDark
      ? (pTop.shade > 0.5 ? "#385a82" : "#182c47")
      : (pTop.shade > 0.5 ? "#daf0ff" : "#678fb8");
    strokeLine(pTop.x, pTop.y - 2, pBot.x, pBot.y, "drapery", col, 1.0);
  }
  // Sky-lit top fold ridge of the towel along the clothesline
  let topRidge = [];
  for (let i = 0; i <= 24; i++) {
    let p = towelPoint(i / 24, 0);
    topRidge.push([p.x, p.y - 2, 0.9]);
  }
  strokeSpline(topRidge, "cpencil", "#eef8ff", 1.15, 0.4);

  // Clothespin pressure creases on towel at Pin 2 (595, 278) and Pin 3 (835, 274)
  drawPinchCreases(595, 278, [
    [584, 345], [596, 368], [614, 375], [634, 362], [652, 340]
  ], "#e6f5ff", "#13243b");

  drawPinchCreases(835, 274, [
    [782, 338], [802, 358], [820, 368], [836, 360], [846, 340]
  ], "#e6f5ff", "#13243b");

  // 6. Tactile Terrycloth Looped-Pile Texture & Care Tag
  for (let i = 0; i < 65; i++) {
    let u = random(0.03, 0.97);
    let v = random(0.05, 0.96);
    let p1 = towelPoint(u, v);
    let p2 = towelPoint(u, min(1, v + 0.07));
    let col = p1.shade > 0.55 ? "#d8eefc" : "#1d3352";
    strokeLine(p1.x, p1.y, p2.x, p2.y, "terry_grain", col, random(0.6, 1.1));
  }

  // Small white woven care label peeking out from lower-left selvage seam (x ~ 578, y ~ 695)
  let tagP = towelPoint(0, 0.78);
  washPoly([
    [tagP.x - 16, tagP.y + 2], [tagP.x, tagP.y],
    [tagP.x, tagP.y + 22], [tagP.x - 15, tagP.y + 25]
  ], "#c9e2f5", 235, 0.02);
  strokeLine(tagP.x - 16, tagP.y + 2, tagP.x, tagP.y, "cpencil", "#f2faff", 0.7);
  strokeLine(tagP.x - 15, tagP.y + 25, tagP.x, tagP.y + 22, "cpencil", "#e8b090", 0.65);

  // Undulating bottom hem highlight & shadow contour
  let botHemPts = [];
  for (let i = 0; i <= 36; i++) {
    let p = towelPoint(i / 36, 1.0);
    botHemPts.push([p.x, p.y, 0.8]);
  }
  strokeSpline(botHemPts, "crease", "#253e61", 1.0, 0.45);
  strokeSpline(botHemPts.map(p => [p[0], p[1] - 2.5, 0.8]), "cpencil", "#f0c3a5", 0.85, 0.45);
}

