// Hyperrealism in p5.brush:
// Soap film stretched across a bubble wand held right up to a child's eye.
// Marbled marker thin-film interference bands (magenta, brass gold, cyan, sea green)
// pooling into black film at the bottom; crisp coloured-pencil eye distorted behind;
// faint spray of window reflections; out-of-focus kitchen beige background.

const W_CX = 590;
const W_CY = 585;
const W_R_IN = 398;
const W_R_OUT = 452;

const E_CX = 605;
const E_CY = 505;
const I_CX = 608;
const I_CY = 492;
const I_R = 174;
const P_R = 64;

let vortices = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  // Custom translucent marker brushes for marbled soap-film flows (no endpoint blobs)
  brush.add("marbled_marker", {
    type: "marker",
    weight: 9,
    scatter: 0.12,
    opacity: 24,
    spacing: 0.28,
    pressure: [0.3, 1.15, 0.3],
    markerTip: false,
    noise: 0.35
  });

  brush.add("pool_marker", {
    type: "marker",
    weight: 16,
    scatter: 0.18,
    opacity: 38,
    spacing: 0.32,
    pressure: [0.4, 1.25, 0.4],
    markerTip: false,
    noise: 0.45
  });

  brush.add("ribbon_marker", {
    type: "marker",
    weight: 4.5,
    scatter: 0.06,
    opacity: 34,
    spacing: 0.22,
    pressure: [0.2, 1.0, 0.2],
    markerTip: false,
    noise: 0.25
  });

  brush.add("mist_spray", {
    type: "spray",
    weight: 14,
    scatter: 2.8,
    opacity: 22,
    spacing: 0.55,
    pressure: [0.4, 1.0, 0.4]
  });

  // Define Marangoni soap-film vortices (concentrated around edges & lower pooling zone)
  vortices = [
    { x: 380, y: 690, r: 165, str: 1.6, dir: 1 },
    { x: 790, y: 670, r: 175, str: 1.7, dir: -1 },
    { x: 580, y: 780, r: 190, str: 1.9, dir: 1 },
    { x: 325, y: 460, r: 140, str: 1.2, dir: -1 },
    { x: 845, y: 440, r: 145, str: 1.25, dir: 1 },
    { x: 470, y: 300, r: 130, str: 0.95, dir: 1 },
    { x: 710, y: 310, r: 135, str: 1.0, dir: -1 },
    { x: 505, y: 655, r: 115, str: 1.3, dir: -1 },
    { x: 695, y: 645, r: 120, str: 1.35, dir: 1 }
  ];
}

// Optical meniscus distortion of the soap film inside the wand
function distortEye(x, y) {
  let dx = x - W_CX;
  let dy = y - W_CY;
  let d = sqrt(dx * dx + dy * dy);
  if (d < W_R_IN) {
    let u = d / W_R_IN;
    // Spherical meniscus magnification + slight rim inflection
    let lensShift = sin(u * 180) * 18 - pow(u, 3) * 14;
    // Subtle fluid thickness wave at the bottom where soap pools
    let poolWave =exp(-pow((y - 760) / 140, 2)) * sin((x - W_CX) * 0.8) * 6;
    let ang = atan2(dy, dx);
    return [
      x + cos(ang) * lensShift + poolWave * 0.4,
      y + sin(ang) * lensShift + abs(poolWave) * 0.7
    ];
  }
  return [x, y];
}

// Upper eyelid margin curve (child's wide open eye)
function upperLidY(x) {
  let t = (x - E_CX) / 310;
  let base = E_CY - 122 + 128 * pow(t, 2) - 18 * pow(t, 3) + 12 * pow(t, 4);
  return base;
}

// Lower eyelid margin curve
function lowerLidY(x) {
  let t = (x - E_CX) / 310;
  let base = E_CY + 78 - 62 * pow(t, 2) - 14 * t + 10 * pow(t, 4);
  return base;
}

// Upper supratarsal eyelid crease
function upperCreaseY(x) {
  let t = (x - E_CX) / 335;
  return E_CY - 178 + 135 * pow(t, 2) - 22 * pow(t, 3);
}

// Scalar field representing soap film thickness / interference order
function filmThickness(x, y) {
  let wx = x;
  let wy = y;

  // Apply rotational displacement from Marangoni vortices
  for (let i = 0; i < vortices.length; i++) {
    let v = vortices[i];
    let dx = wx - v.x;
    let dy = wy - v.y;
    let d2 = dx * dx + dy * dy;
    let r2 = v.r * v.r;
    if (d2 < r2 * 2.8) {
      let factor = v.str * exp(-d2 / (r2 * 0.75)) * 85 * v.dir;
      let a = atan2(dy, dx) + factor;
      let dist = sqrt(d2);
      wx = v.x + cos(a) * dist;
      wy = v.y + sin(a) * dist;
    }
  }

  // Domain-warped Perlin noise for liquid marbling
  let n1 = noise(wx * 0.0032, wy * 0.0032, 1.7);
  let n2 = noise(wx * 0.0065 + n1 * 2.4, wy * 0.0065 - n1 * 2.1, 4.3);
  let n3 = noise(wx * 0.014 - n2 * 1.8, wy * 0.014 + n2 * 1.8, 8.1);

  // Radial distance from wand center (meniscus climbs along rim)
  let rx = x - W_CX;
  let ry = y - W_CY;
  let rNorm = sqrt(rx * rx + ry * ry) / W_R_IN;
  let rimSag = pow(constrain(rNorm, 0, 1), 2.6) * 0.38;

  // Vertical drainage gradient (pooling toward bottom y ~ 980)
  let vGrad = (y - (W_CY - W_R_IN)) / (2 * W_R_IN);

  return vGrad * 1.35 + (n1 - 0.5) * 0.55 + (n2 - 0.5) * 0.32 + (n3 - 0.5) * 0.14 - rimSag;
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. SOFT OUT-OF-FOCUS KITCHEN BEIGE BACKGROUND & PERIPHERAL SKIN
  background("#e8dec9");
  drawKitchenBackground();

  // 2. CHILD'S EYE & SURROUNDING ORBIT (Crisp Coloured Pencil, Distorted Inside Wand)
  drawEyeUnderpainting();
  drawOrbitalSkinAndCreases();
  drawScleraAndCaruncle();
  drawWetIrisAndPupil();
  drawEyelashes();

  // 3. SOAP FILM: BLACK POOLING ZONE & MARBLED MARKER INTERFERENCE FLOWS
  drawBlackFilmPool();
  drawMarbledMarkerInterference();

  // 4. CRISP RE-EMPHASIS OF EYE HIGHLIGHTS & LASH TIPS SEEN THROUGH FILM
  drawCrispEyeSpeculars();

  // 5. FAINT SPRAY OF WINDOW REFLECTIONS ON THE SOAP FILM
  drawFilmWindowReflections();

  // 6. PLASTIC BUBBLE WAND, WET MENISCUS TEETH & GLOSSY HANDLE
  drawBubbleWand();

  noLoop();
}

// =========================================================================
// 1. OUT-OF-FOCUS KITCHEN BEIGE BACKGROUND
// =========================================================================
function drawKitchenBackground() {
  brush.noStroke();

  // Soft warm window light patches (upper left & top)
  brush.fill("#f7f1e1", 95);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.35, 0.15);
  brush.circle(190, 180, 260, 0.25);
  brush.circle(470, 110, 210, 0.25);
  brush.circle(110, 480, 190, 0.25);

  // Mid-tone oatmeal and biscuit bokeh (kitchen tiles / cabinets out of focus)
  brush.fill("#d6c5ad", 85);
  brush.fillBleed(0.4, "out");
  brush.circle(980, 220, 280, 0.3);
  brush.circle(150, 880, 260, 0.3);
  brush.circle(1050, 960, 290, 0.3);

  // Deeper warm taupe kitchen shadows for high-contrast backdrop
  brush.fill("#a89379", 80);
  brush.fillBleed(0.45, "out");
  brush.circle(1080, 140, 220, 0.3);
  brush.circle(85, 1080, 240, 0.3);
  brush.circle(960, 1080, 250, 0.3);

  // Out-of-focus child's forehead, temple and cheek extending outside the wand on the right
  brush.fill("#e8c3ac", 105);
  brush.fillBleed(0.38, "out");
  brush.circle(860, 420, 340, 0.22);
  brush.circle(830, 740, 310, 0.22);

  brush.fill("#c99277", 85);
  brush.fillBleed(0.35, "out");
  brush.circle(980, 560, 240, 0.25);
  brush.circle(420, 860, 250, 0.25);

  brush.noFill();

  // Soft out-of-focus atmospheric grain in background
  brush.set("mist_spray", "#fcf7eb", 1.3);
  for (let i = 0; i < 24; i++) {
    let ang = random(360);
    let rad = random(480, 680);
    let x = W_CX + cos(ang) * rad;
    let y = W_CY + sin(ang) * rad;
    brush.line(x - 40, y - 20, x + 40, y + 20);
  }

  // Soft out-of-focus eyebrow arch above the wand rim (top right)
  for (let i = 0; i < 85; i++) {
    let t = i / 85;
    let bx = lerp(430, 980, t);
    let by = 185 - sin(t * 170) * 58 + (t - 0.5) * 40 + random(-14, 14);
    let d = dist(bx, by, W_CX, W_CY);
    if (d > W_R_OUT - 10) {
      brush.set("charcoal", i % 2 === 0 ? "#4a3326" : "#6e4f3d", random(0.35, 0.75));
      let hairAng = -18 + t * 48 + random(-8, 8);
      let len = random(35, 65);
      brush.line(bx, by, bx + cos(hairAng) * len, by + sin(hairAng) * len);
    }
  }
}

// =========================================================================
// 2. CHILD'S EYE (CRISP COLOURED PENCIL)
// =========================================================================
function drawEyeUnderpainting() {
  brush.noStroke();

  // Warm skin tone base inside the wand
  brush.fill("#f0cbb4", 90);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.3, 0.15);
  brush.circle(E_CX, E_CY, 370, 0.12);

  // Orbital shadow under brow & nasal bridge (left side)
  brush.fill("#b57359", 95);
  brush.fillBleed(0.28, "out");
  brush.circle(340, 430, 175, 0.2);
  brush.circle(865, 495, 150, 0.2);
  brush.circle(590, 325, 190, 0.2);

  // Sclera porcelain-ivory wash
  brush.fill("#faf6f0", 180);
  brush.fillBleed(0.08, "in");
  brush.beginShape(0.3);
  for (let x = 300; x <= 900; x += 30) {
    let p = distortEye(x, upperLidY(x));
    brush.vertex(p[0], p[1]);
  }
  for (let x = 900; x >= 300; x -= 30) {
    let p = distortEye(x, lowerLidY(x));
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);

  // Iris dark base wash for high contrast
  let ic = distortEye(I_CX, I_CY);
  brush.fill("#1c120c", 210);
  brush.fillBleed(0.04, "in");
  brush.circle(ic[0], ic[1], I_R, 0.04);

  brush.noFill();
}

function drawOrbitalSkinAndCreases() {
  // Contour-following coloured pencil strokes across upper & lower eyelids
  const skinPalette = [
    "#f7dccb", "#ecc6b0", "#dfa185", "#c77b61", "#9e503b", "#63291b"
  ];

  // Upper eyelid & supratarsal fold hatching
  for (let row = 0; row < 48; row++) {
    let v = row / 47; // 0 = lid margin, 1 = high above crease
    for (let seg = 0; seg < 14; seg++) {
      let xStart = lerp(255, 925, seg / 14) + random(-8, 8);
      let xEnd = xStart + random(45, 78);
      let pts = [];
      let steps = 6;
      for (let s = 0; s <= steps; s++) {
        let x = lerp(xStart, xEnd, s / steps);
        let yMargin = upperLidY(x);
        let yCrease = upperCreaseY(x);
        let y = lerp(yMargin - 4, yCrease - 95, v) + sin(s * 45) * 1.5;
        pts.push(distortEye(x, y));
      }

      // Determine tonal value: dark in the crease (v ~ 0.36) and near medial corner
      let creaseDist = abs(v - 0.36);
      let colIdx = 1;
      if (creaseDist < 0.05) colIdx = 5;
      else if (creaseDist < 0.11) colIdx = 4;
      else if (creaseDist < 0.20) colIdx = 3;
      else if (v < 0.18) colIdx = 0; // Plump illuminated tarsal fold
      else colIdx = 2;

      if (xStart < 370 && colIdx < 4) colIdx++; // Nasal shadow

      brush.set("cpencil", skinPalette[colIdx], random(0.35, 0.65));
      brush.spline(pts, 0.4);
    }
  }

  // Crisp dark supratarsal crease line
  for (let pass = 0; pass < 6; pass++) {
    let pts = [];
    for (let x = 275; x <= 905; x += 22) {
      let y = upperCreaseY(x) + random(-2.5, 2.5) + (pass - 2.5) * 1.8;
      pts.push(distortEye(x, y));
    }
    brush.set("cpencil", pass < 3 ? "#2b0f08" : "#5e2518", random(0.45, 0.75));
    brush.spline(pts, 0.5);
  }

  // Lower eyelid & tear trough contour hatching
  for (let row = 0; row < 42; row++) {
    let v = row / 41;
    for (let seg = 0; seg < 13; seg++) {
      let xStart = lerp(275, 910, seg / 13) + random(-8, 8);
      let xEnd = xStart + random(48, 82);
      let pts = [];
      for (let s = 0; s <= 5; s++) {
        let x = lerp(xStart, xEnd, s / 5);
        let yMargin = lowerLidY(x) + 12; // Below wet waterline
        let y = yMargin + v * 195 + pow((x - E_CX) / 320, 2) * v * 45;
        pts.push(distortEye(x, y));
      }

      let col = "#e6b39a";
      if (v < 0.08) col = "#c9746b"; // Pinkish lower lid rim
      else if (v < 0.22) col = "#f5d5c3"; // Illuminated lower lid puff (aegyo-sal)
      else if (v > 0.34 && v < 0.48) col = "#a66356"; // Subtle infraorbital crease
      else if (v >= 0.48) col = "#dfab94";

      brush.set("cpencil", col, random(0.35, 0.6));
      brush.spline(pts, 0.4);
    }
  }

  // Wet lower waterline (mucocutaneous junction)
  for (let pass = 0; pass < 5; pass++) {
    let pts = [];
    for (let x = 305; x <= 885; x += 20) {
      let y = lowerLidY(x) + pass * 2.2;
      pts.push(distortEye(x, y));
    }
    let col = pass === 0 ? "#ffffff" : (pass < 3 ? "#f5b8b8" : "#c76b6d");
    brush.set("cpencil", col, pass === 0 ? 0.55 : 0.45);
    brush.spline(pts, 0.45);
  }
}

function drawScleraAndCaruncle() {
  // Spherical shading of the sclera (porcelain white center, cool blue-violet/rose corners & upper lid shadow)
  for (let i = 0; i < 320; i++) {
    let x = random(310, 885);
    let yTop = upperLidY(x);
    let yBot = lowerLidY(x);
    if (yBot <= yTop + 6) continue;

    let v = random(0.02, 0.98);
    let y = lerp(yTop, yBot, v);

    // Skip inside iris
    if (dist(x, y, I_CX, I_CY) < I_R - 4) continue;

    let ang = atan2(y - E_CY, (x - E_CX) * 0.45);
    let len = random(16, 36);
    let p1 = distortEye(x, y);
    let p2 = distortEye(x + cos(ang) * len * 0.5, y + sin(ang) * len * 0.25);
    let p3 = distortEye(x + cos(ang) * len, y + sin(ang) * len * 0.5);

    // Pick sclera color based on position
    let col = "#fcf9f2";
    let cornerDist = abs(x - E_CX) / 290;
    if (v < 0.16) col = "#635870"; // Cast shadow of upper lid
    else if (v < 0.28) col = "#9c92a8";
    else if (cornerDist > 0.78) col = "#d4afb5"; // Vascular pink at corners
    else if (cornerDist > 0.62) col = "#dfd6e0"; // Cool blue-grey turn of eyeball
    else if (v > 0.86) col = "#e8d5d8";

    brush.set("cpencil", col, random(0.3, 0.55));
    brush.spline([p1, p2, p3], 0.35);
  }

  // Delicate episcleral capillaries at medial & lateral corners
  const veins = [
    [[345, 535], [375, 522], [405, 518], [428, 510]],
    [[375, 522], [398, 534], [420, 538]],
    [[355, 552], [390, 548], [422, 542]],
    [[865, 502], [830, 496], [798, 490], [778, 482]],
    [[830, 496], [805, 512], [785, 518]],
    [[855, 518], [822, 526], [792, 528]]
  ];
  for (let v of veins) {
    let pts = v.map(pt => distortEye(pt[0], pt[1]));
    brush.set("cpencil", "#c95b65", 0.22);
    brush.spline(pts, 0.45);
  }

  // Medial canthus & lacrimal caruncle (fleshy pink tear-duct at left corner)
  for (let i = 0; i < 45; i++) {
    let cx = random(292, 352);
    let cy = random(525, 562);
    let p1 = distortEye(cx, cy);
    let p2 = distortEye(cx + random(8, 18), cy + random(-6, 6));
    let col = i < 15 ? "#8c2b32" : (i < 32 ? "#d46368" : "#f7b2b5");
    brush.set("cpencil", col, random(0.3, 0.55));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  // Wet glint on caruncle
  for (let i = 0; i < 8; i++) {
    let p = distortEye(random(305, 338), random(536, 550));
    brush.set("cpencil", "#ffffff", 0.45);
    brush.line(p[0], p[1], p[0] + 5, p[1] - 2);
  }
}

function drawWetIrisAndPupil() {
  // Clip iris helper: only draw inside eyelid aperture
  function inAperture(x, y) {
    return y >= upperLidY(x) - 3 && y <= lowerLidY(x) + 3;
  }

  // 1. Deep Limbal Ring & Outer Ciliary Zone
  for (let i = 0; i < 420; i++) {
    let ang = random(360);
    let r1 = random(I_R - 36, I_R - 14);
    let r2 = I_R + random(-3, 2);
    let x1 = I_CX + cos(ang) * r1;
    let y1 = I_CY + sin(ang) * r1;
    let x2 = I_CX + cos(ang + random(-3, 3)) * r2;
    let y2 = I_CY + sin(ang + random(-3, 3)) * r2;
    if (!inAperture(x1, y1) && !inAperture(x2, y2)) continue;

    let p1 = distortEye(x1, constrain(y1, upperLidY(x1), lowerLidY(x1)));
    let p2 = distortEye(x2, constrain(y2, upperLidY(x2), lowerLidY(x2)));
    let col = i % 3 === 0 ? "#0d0912" : (i % 3 === 1 ? "#1f130d" : "#132629");
    brush.set("cpencil", col, random(0.35, 0.65));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 2. Radial Stroma Fibers (Rich Chestnut, Brass Gold, Honey Amber, Sea-Slate)
  const stromaColors = [
    "#29150b", "#472512", "#6e3d19", "#9c6221",
    "#c98b27", "#ebb644", "#2c4a47", "#436e66", "#f7d56e"
  ];

  for (let i = 0; i < 680; i++) {
    let ang = (i / 680) * 360 + random(-0.6, 0.6);
    let rStart = P_R + random(-2, 18);
    let rEnd = I_R - random(8, 32);

    // Create wavy radial trabeculae curving around crypts
    let waveFreq = random(2, 4);
    let waveAmp = random(-3.5, 3.5);
    let pts = [];
    let valid = true;
    for (let s = 0; s <= 4; s++) {
      let t = s / 4;
      let r = lerp(rStart, rEnd, t);
      let a = ang + sin(t * 180 * waveFreq) * waveAmp;
      let x = I_CX + cos(a) * r;
      let y = I_CY + sin(a) * r;
      if (!inAperture(x, y)) {
        y = constrain(y, upperLidY(x), lowerLidY(x));
      }
      pts.push(distortEye(x, y));
    }

    // Color distribution: darker at top (under lid shadow), glowing gold/amber in lower half
    let col;
    let isBottom = sin(ang) > -0.15;
    if (!isBottom && sin(ang) < -0.55) {
      col = random(["#140b08", "#26150d", "#1b282b"]);
    } else {
      let pick = random(1);
      if (pick < 0.25) col = "#29150b";
      else if (pick < 0.48) col = "#5c3314";
      else if (pick < 0.68) col = "#9c6221";
      else if (pick < 0.84) col = "#d99b2e";
      else if (pick < 0.93) col = "#355954";
      else col = "#f7d56e";
    }

    brush.set("cpencil", col, random(0.22, 0.45));
    brush.spline(pts, 0.4);
  }

  // 3. Iris Collarette (Jagged luminous golden/amber ring around pupil at r ~ 88..108)
  for (let i = 0; i < 220; i++) {
    let ang = (i / 220) * 360 + random(-1.5, 1.5);
    let rMid = 94 + sin(ang * 14) * 7 + cos(ang * 9) * 5;
    let r1 = rMid - random(8, 22);
    let r2 = rMid + random(8, 24);
    let x1 = I_CX + cos(ang) * r1;
    let y1 = I_CY + sin(ang) * r1;
    let x2 = I_CX + cos(ang + random(-4, 4)) * r2;
    let y2 = I_CY + sin(ang + random(-4, 4)) * r2;
    if (!inAperture(x1, y1) || !inAperture(x2, y2)) continue;

    let p1 = distortEye(x1, y1);
    let p2 = distortEye(x2, y2);
    let col = sin(ang) < -0.45 ? "#593416" : random(["#e09f2b", "#f7c948", "#ffdf7a", "#b8611a"]);
    brush.set("cpencil", col, random(0.28, 0.48));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 4. Pupillary Ruff (Dark rust-umber inner border around pupil)
  for (let i = 0; i < 140; i++) {
    let ang = (i / 140) * 360;
    let r1 = P_R - 2;
    let r2 = P_R + random(10, 22);
    let x1 = I_CX + cos(ang) * r1;
    let y1 = I_CY + sin(ang) * r1;
    let x2 = I_CX + cos(ang) * r2;
    let y2 = I_CY + sin(ang) * r2;
    if (!inAperture(x1, y1)) continue;
    let p1 = distortEye(x1, y1);
    let p2 = distortEye(x2, y2);
    brush.set("cpencil", i % 2 === 0 ? "#240d04" : "#4a1f0a", 0.35);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 5. Velvet-Black Pupil (Dense multi-angle 2B & cpencil hatching)
  let pc = distortEye(I_CX, I_CY);
  brush.noStroke();
  brush.fill("#050408", 245);
  brush.fillBleed(0.01, "in");
  brush.circle(pc[0], pc[1], P_R, 0.02);
  brush.noFill();

  for (let i = 0; i < 160; i++) {
    let a1 = random(360);
    let a2 = a1 + random(130, 230);
    let r = P_R * random(0.75, 1.02);
    let p1 = distortEye(I_CX + cos(a1) * r, I_CY + sin(a1) * r);
    let p2 = distortEye(I_CX + cos(a2) * r, I_CY + sin(a2) * r);
    brush.set("2B", "#07050a", random(0.35, 0.6));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 6. Upper Eyelid Cast Shadow Across Top of Iris & Sclera
  for (let x = 315; x <= 880; x += 4) {
    let yTop = upperLidY(x);
    let shadowDepth = 34 - pow((x - E_CX) / 280, 2) * 18;
    if (shadowDepth > 4) {
      let p1 = distortEye(x, yTop);
      let p2 = distortEye(x + random(-3, 3), yTop + shadowDepth);
      brush.set("cpencil", "#120c18", random(0.35, 0.55));
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }
}

function drawEyelashes() {
  // Upper eyelid margin dark tightline
  for (let pass = 0; pass < 5; pass++) {
    let pts = [];
    for (let x = 295; x <= 895; x += 18) {
      pts.push(distortEye(x, upperLidY(x) + (pass - 2) * 1.3));
    }
    brush.set("cpencil", "#120a07", 0.55);
    brush.spline(pts, 0.45);
  }

  // UPPER EYELASHES: Long, curved, slightly wet-clumped child's lashes
  const numUpperClusters = 46;
  for (let c = 0; c < numUpperClusters; c++) {
    let t = c / (numUpperClusters - 1); // 0 = left (medial), 1 = right (lateral)
    let rootX = lerp(318, 888, t) + random(-3, 3);
    let rootY = upperLidY(rootX) + random(-2, 2);

    // Lash length & sweep angle across the eye
    let len = (72 + sin(t * 180) * 58) * random(0.88, 1.12);
    if (t < 0.12) len *= 0.65;
    let baseAng = lerp(-152, -22, t); // Sweeps left on left, straight up in center, right on right

    // Tip target where wet hairs in a cluster converge slightly
    let tipX = rootX + cos(baseAng) * len;
    let tipY = rootY + sin(baseAng) * len - sin(t * 180) * 18;

    // Subtle cast shadow of each lash on the sclera/iris below
    if (t > 0.15 && t < 0.88) {
      let sh1 = distortEye(rootX, rootY + 3);
      let sh2 = distortEye(rootX + cos(baseAng + 18) * (len * 0.32), rootY + 24);
      brush.set("cpencil", "#211829", 0.25);
      brush.line(sh1[0], sh1[1], sh2[0], sh2[1]);
    }

    // 3 to 5 individual hairs per cluster
    let hairs = floor(random(3, 6));
    for (let h = 0; h < hairs; h++) {
      let hOffset = (h - (hairs - 1) / 2) * random(2.8, 4.5);
      let rx = rootX + hOffset;
      let ry = rootY + abs(hOffset) * 0.3;

      // Control points for natural downward-then-upward curl of eyelashes
      let mid1X = lerp(rx, tipX, 0.32) + hOffset * 0.6;
      let mid1Y = lerp(ry, tipY, 0.22) + 14; // dips slightly before curling up
      let mid2X = lerp(rx, tipX, 0.68) + hOffset * 0.25;
      let mid2Y = lerp(ry, tipY, 0.65) + 5;
      let tx = tipX + random(-2.5, 2.5);
      let ty = tipY + random(-2.5, 2.5);

      let pts = [
        distortEye(rx, ry),
        distortEye(mid1X, mid1Y),
        distortEye(mid2X, mid2Y),
        distortEye(tx, ty)
      ];

      let col = h === 0 ? "#0a0605" : (h === 1 ? "#1c110d" : "#2e1c14");
      brush.set("cpencil", col, random(0.32, 0.58));
      brush.spline(pts, 0.5);
    }
  }

  // LOWER EYELASHES: Shorter, delicate downward-sweeping clusters
  const numLowerClusters = 34;
  for (let c = 0; c < numLowerClusters; c++) {
    let t = c / (numLowerClusters - 1);
    let rootX = lerp(335, 875, t) + random(-3, 3);
    let rootY = lowerLidY(rootX) + 9 + random(-1.5, 1.5);

    let len = (32 + sin(t * 180) * 34) * random(0.85, 1.15);
    if (t < 0.12 || t > 0.9) len *= 0.6;
    let baseAng = lerp(138, 42, t);

    let tipX = rootX + cos(baseAng) * len;
    let tipY = rootY + sin(baseAng) * len;

    // Faint shadow on lower lid skin
    let s1 = distortEye(rootX, rootY + 2);
    let s2 = distortEye(tipX + 4, tipY + 6);
    brush.set("cpencil", "#9e6356", 0.2);
    brush.line(s1[0], s1[1], s2[0], s2[1]);

    let hairs = floor(random(2, 4));
    for (let h = 0; h < hairs; h++) {
      let hOff = (h - 1) * 3.2;
      let rx = rootX + hOff;
      let ry = rootY;
      let mx = lerp(rx, tipX, 0.5) + hOff * 0.4;
      let my = lerp(ry, tipY, 0.45) - 5;
      let pts = [
        distortEye(rx, ry),
        distortEye(mx, my),
        distortEye(tipX + random(-2, 2), tipY + random(-2, 2))
      ];
      brush.set("cpencil", h === 0 ? "#170e0b" : "#38231b", random(0.24, 0.42));
      brush.spline(pts, 0.45);
    }
  }
}

// =========================================================================
// 3. SOAP FILM: BLACK POOLING ZONE & MARBLED MARKER INTERFERENCE FLOWS
// =========================================================================
function drawBlackFilmPool() {
  // At the bottom of the wand, the soap film thins/pools into a high-contrast black zone
  // with upward-curling Marangoni plumes along the lower crescent.
  function blackBoundaryY(x) {
    let dx = (x - W_CX) / W_R_IN;
    let rimClimb = pow(constrain(abs(dx), 0, 1), 2.2) * 195;
    let plume1 = exp(-pow((x - 420) / 52, 2)) * 75;
    let plume2 = exp(-pow((x - 755) / 58, 2)) * 82;
    let plume3 = exp(-pow((x - 585) / 45, 2)) * 42;
    let ripple = sin(x * 1.4) * 12 + cos(x * 2.3) * 8;
    return 825 - rimClimb - plume1 - plume2 - plume3 + ripple;
  }

  // Deep obsidian-black wash at the bottom crescent inside the wand
  brush.noStroke();
  brush.fill("#07060c", 230);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.25, 0.2);
  brush.beginShape(0.35);
  for (let a = 18; a <= 162; a += 4) {
    let x = W_CX + cos(a) * (W_R_IN - 2);
    let y = blackBoundaryY(x);
    let maxY = W_CY + sin(a) * (W_R_IN - 2);
    brush.vertex(x, min(y, maxY));
  }
  for (let a = 162; a >= 18; a -= 4) {
    let x = W_CX + cos(a) * (W_R_IN - 2);
    let y = W_CY + sin(a) * (W_R_IN - 2);
    brush.vertex(x, y);
  }
  brush.endShape(true);
  brush.noFill();

  // Dense black and midnight-indigo marker swirls pooling in the bottom crescent
  for (let i = 0; i < 145; i++) {
    let aStart = random(20, 160);
    let r = random(W_R_IN - 165, W_R_IN - 6);
    let x = W_CX + cos(aStart) * r;
    let y = W_CY + sin(aStart) * r;
    if (y < blackBoundaryY(x) - 18) continue;

    let pts = [];
    let cx = x;
    let cy = y;
    for (let s = 0; s < 7; s++) {
      pts.push([cx, cy]);
      let tang = atan2(cy - W_CY, cx - W_CX) + 90 + sin(s * 50 + i) * 22;
      cx += cos(tang) * 24;
      cy += sin(tang) * 24;
      if (dist(cx, cy, W_CX, W_CY) > W_R_IN - 4) break;
    }
    if (pts.length >= 3) {
      let col = i % 3 === 0 ? "#050408" : (i % 3 === 1 ? "#110a1c" : "#071a21");
      brush.set("pool_marker", col, random(0.7, 1.35));
      brush.spline(pts, 0.5);
    }
  }
}

function drawMarbledMarkerInterference() {
  // Thin-film interference palette: Magenta, Brass Gold, Cyan, Sea Green
  const interferenceBands = [
    { col: "#f2c12e", name: "brass_gold" },
    { col: "#e61973", name: "magenta" },
    { col: "#00b8e6", name: "cyan" },
    { col: "#17b890", name: "sea_green" },
    { col: "#ff5ca8", name: "bright_magenta" },
    { col: "#d49b1a", name: "deep_brass" },
    { col: "#4ce6ff", name: "ice_cyan" },
    { col: "#42e3b8", name: "bright_seagreen" },
    { col: "#9e0b52", name: "deep_magenta" }
  ];

  // Trace fluid streamlines along level-sets of filmThickness(x, y)
  // We seed denser streamlines toward the bottom pooling zone and swirling margins,
  // and sparser, delicate ribbons across the eye so the crisp pencil eye shines through!
  const numStreamlines = 540;

  for (let i = 0; i < numStreamlines; i++) {
    // Bias seed points toward the lower half and outer ring, with graceful bands crossing the eye
    let ang = random(360);
    let u = random(1);
    let r = W_R_IN * (0.15 + 0.83 * pow(u, 0.68));
    let sx = W_CX + cos(ang) * r;
    let sy = W_CY + sin(ang) * r;

    // Keep central iris/pupil window mostly clear (allow only ~18% of paths to cross right over pupil)
    let eyeDist = dist(sx, sy, I_CX, I_CY);
    if (eyeDist < I_R * 0.82 && random(1) > 0.18) continue;

    let pts = [];
    let cx = sx;
    let cy = sy;
    let steps = floor(random(10, 22));
    let stepLen = random(14, 22);
    let dirSign = random(1) < 0.5 ? 1 : -1;

    for (let s = 0; s < steps; s++) {
      if (dist(cx, cy, W_CX, W_CY) > W_R_IN - 6) break;

      // Also avoid lingering directly over the black pupil center
      if (dist(cx, cy, I_CX, I_CY) < P_R * 0.75 && s > 2) break;

      pts.push([cx, cy]);

      // Compute numerical gradient of filmThickness to follow iso-thickness contour + downward drift
      let eps = 4.0;
      let dfdx = (filmThickness(cx + eps, cy) - filmThickness(cx - eps, cy)) / (2 * eps);
      let dfdy = (filmThickness(cx, cy + eps) - filmThickness(cx, cy - eps)) / (2 * eps);

      // Tangent to iso-contour
      let tx = -dfdy * dirSign;
      let ty = dfdx * dirSign;
      let mag = sqrt(tx * tx + ty * ty) + 0.00001;
      tx /= mag;
      ty /= mag;

      // Add subtle downward drainage & boundary tangency near the wand rim
      let rDist = dist(cx, cy, W_CX, W_CY);
      if (rDist > W_R_IN - 65) {
        let rimAng = atan2(cy - W_CY, cx - W_CX) + 90 * dirSign;
        tx = lerp(tx, cos(rimAng), 0.55);
        ty = lerp(ty, sin(rimAng), 0.55);
      }

      cx += tx * stepLen;
      cy += ty * stepLen + 1.4; // slight downward drift
    }

    if (pts.length < 4) continue;

    // Sample film thickness at the midpoint of the streamline to pick the interference color band
    let midPt = pts[floor(pts.length / 2)];
    let thick = filmThickness(midPt[0], midPt[1]);

    // Map thickness phase to cyclic Newton interference bands
    let phase = ((thick * 7.5) % 1.0 + 1.0) % 1.0;
    let bandIdx = floor(phase * interferenceBands.length);
    let col = interferenceBands[bandIdx].col;

    // Near the bottom black film boundary (y ~ 720..840), intensify brass gold, magenta & cyan fringes!
    let inPoolZone = midPt[1] > 665;
    let overEye = dist(midPt[0], midPt[1], I_CX, I_CY) < I_R * 1.15;

    if (overEye) {
      brush.set("ribbon_marker", col, random(0.45, 0.85));
    } else if (inPoolZone) {
      brush.set("pool_marker", col, random(0.65, 1.25));
    } else {
      brush.set("marbled_marker", col, random(0.55, 1.15));
    }

    brush.spline(pts, 0.55);
  }

  // Add tight vortex eye rings (concentric marbled marker loops inside the main soap eddies)
  const vortexLoops = [
    { x: 380, y: 690, maxR: 72 },
    { x: 790, y: 670, maxR: 78 },
    { x: 505, y: 655, maxR: 52 },
    { x: 695, y: 645, maxR: 55 },
    { x: 325, y: 460, maxR: 58 },
    { x: 845, y: 440, maxR: 60 }
  ];
  const ringCols = ["#e61973", "#f2c12e", "#00b8e6", "#17b890", "#ff5ca8", "#07050a"];

  for (let v of vortexLoops) {
    for (let ring = 0; ring < 9; ring++) {
      let rad = map(ring, 0, 8, 10, v.maxR);
      let pts = [];
      let aStart = random(360);
      let aSpan = random(200, 310);
      for (let s = 0; s <= 12; s++) {
        let a = aStart + (s / 12) * aSpan;
        let rWobble = rad + sin(a * 3 + ring * 40) * (rad * 0.16);
        let px = v.x + cos(a) * (rWobble * 1.15);
        let py = v.y + sin(a) * (rWobble * 0.88);
        if (dist(px, py, W_CX, W_CY) < W_R_IN - 6) {
          pts.push([px, py]);
        }
      }
      if (pts.length >= 4) {
        let col = ringCols[ring % ringCols.length];
        brush.set("ribbon_marker", col, random(0.5, 0.95));
        brush.spline(pts, 0.55);
      }
    }
  }
}

// =========================================================================
// 4. CRISP RE-EMPHASIS OF EYE SPECULARS & CHROMATIC LASH TIPS
// =========================================================================
function drawCrispEyeSpeculars() {
  // Razor-sharp corneal window reflection on the wet iris/pupil (upper-left of pupil)
  // A 4-pane window warped onto the steep dome of the cornea
  const panes = [
    { x1: 528, y1: 432, x2: 562, y2: 426, x3: 565, y3: 458, x4: 532, y4: 465 },
    { x1: 569, y1: 425, x2: 602, y2: 424, x3: 602, y3: 455, x4: 571, y4: 457 },
    { x1: 534, y1: 472, x2: 566, y2: 465, x3: 569, y3: 492, x4: 539, y4: 498 },
    { x1: 573, y1: 464, x2: 602, y2: 462, x3: 603, y3: 488, x4: 575, y4: 491 }
  ];

  for (let p of panes) {
    for (let row = 0; row <= 9; row++) {
      let v = row / 9;
      let lx = lerp(p.x1, p.x4, v);
      let ly = lerp(p.y1, p.y4, v);
      let rx = lerp(p.x2, p.x3, v);
      let ry = lerp(p.y2, p.y3, v);
      let pStart = distortEye(lx, ly);
      let pEnd = distortEye(rx, ry);
      brush.set("cpencil", row % 2 === 0 ? "#ffffff" : "#e3f8ff", 0.55);
      brush.line(pStart[0], pStart[1], pEnd[0], pEnd[1]);
    }
  }

  // Secondary wet glint on lower-right iris & tear meniscus along lower lid
  for (let i = 0; i < 16; i++) {
    let x = random(645, 682);
    let y = random(538, 556);
    let p1 = distortEye(x, y);
    let p2 = distortEye(x + random(8, 16), y - random(3, 8));
    brush.set("cpencil", "#ffffff", 0.5);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Wet tear-meniscus sparkle line where lower lid meets the eyeball
  for (let x = 355; x <= 845; x += 14) {
    if (random(1) < 0.72) {
      let y = lowerLidY(x) - 1;
      let p1 = distortEye(x, y);
      let p2 = distortEye(x + random(8, 15), lowerLidY(x + 10) - 1);
      brush.set("cpencil", "#ffffff", random(0.38, 0.6));
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // Re-sharpen selected foreground eyelash tips & add thin-film chromatic glints on lashes
  const glintCols = ["#ff4da6", "#4ce6ff", "#ffdf66", "#120a07"];
  for (let i = 0; i < 28; i++) {
    let t = map(i, 0, 27, 0.14, 0.88);
    let rootX = lerp(318, 888, t);
    let rootY = upperLidY(rootX);
    let len = 76 + sin(t * 180) * 56;
    let baseAng = lerp(-152, -22, t);
    let tipX = rootX + cos(baseAng) * len;
    let tipY = rootY + sin(baseAng) * len - sin(t * 180) * 18;

    let pts = [
      distortEye(rootX, rootY),
      distortEye(lerp(rootX, tipX, 0.45), lerp(rootY, tipY, 0.35) + 11),
      distortEye(tipX, tipY)
    ];
    brush.set("cpencil", "#0d0705", 0.45);
    brush.spline(pts, 0.5);

    // Chromatic diffraction glint along the side of the lash
    if (i % 2 === 0) {
      let gPts = [
        distortEye(lerp(rootX, tipX, 0.35) + 2, lerp(rootY, tipY, 0.28) + 9),
        distortEye(tipX + 2, tipY)
      ];
      brush.set("cpencil", glintCols[i % 3], 0.28);
      brush.line(gPts[0][0], gPts[0][1], gPts[1][0], gPts[1][1]);
    }
  }
}

// =========================================================================
// 5. FAINT SPRAY OF WINDOW REFLECTIONS ON THE SOAP FILM
// =========================================================================
function drawFilmWindowReflections() {
  // Large, curved four-pane window reflection sprayed softly across the soap film surface
  // Upper-left reflection patch (curved by the spherical bulge of the soap film)
  function windowQuadPoint(u, v) {
    // u, v in [0, 1] mapped to upper-left quadrant of the soap bubble film
    let a = lerp(-165, -98, u);
    let r = lerp(195, 355, v);
    let bow = sin(u * 180) * sin(v * 180) * 24;
    return [
      W_CX + cos(a) * (r + bow),
      W_CY + sin(a) * (r + bow)
    ];
  }

  for (let i = 0; i < 290; i++) {
    let u = random(0, 1);
    let v = random(0, 1);
    // Leave a dark crossbar gap (window muntins) at u ~ 0.48..0.55 and v ~ 0.46..0.54
    if (abs(u - 0.51) < 0.045 || abs(v - 0.50) < 0.045) continue;

    let p1 = windowQuadPoint(u, v);
    let p2 = windowQuadPoint(constrain(u + 0.08, 0, 1), constrain(v + random(-0.02, 0.02), 0, 1));

    let col = random(1) < 0.65 ? "#ffffff" : (random(1) < 0.5 ? "#e0f7ff" : "#fff7e0");
    brush.set("mist_spray", col, random(0.65, 1.25));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Secondary faint inverted window reflection arc in lower-right of the film
  for (let i = 0; i < 130; i++) {
    let u = random(0, 1);
    let v = random(0, 1);
    if (abs(u - 0.5) < 0.055 || abs(v - 0.5) < 0.055) continue;

    let a = lerp(12, 68, u);
    let r = lerp(240, 358, v);
    let p1 = [W_CX + cos(a) * r, W_CY + sin(a) * r];
    let p2 = [W_CX + cos(a + 4) * r, W_CY + sin(a + 4) * r];

    brush.set("mist_spray", i % 2 === 0 ? "#ffffff" : "#d9f5ff", random(0.5, 0.95));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

// =========================================================================
// 6. PLASTIC BUBBLE WAND, WET MENISCUS TEETH & GLOSSY HANDLE
// =========================================================================
function drawBubbleWand() {
  // 1. Wand Handle descending from bottom-left of ring (around 118 degrees)
  const hAngle = 116;
  const hx0 = W_CX + cos(hAngle) * (W_R_OUT - 8);
  const hy0 = W_CY + sin(hAngle) * (W_R_OUT - 8);
  const hx1 = hx0 + cos(hAngle) * 320;
  const hy1 = hy0 + sin(hAngle) * 320;
  const perpX = cos(hAngle - 90);
  const perpY = sin(hAngle - 90);

  // Cast shadow of wand handle & ring onto the out-of-focus background
  for (let i = 0; i < 45; i++) {
    let a = random(-35, 145);
    let r = W_R_OUT + random(8, 28);
    let sx = W_CX + 18 + cos(a) * r;
    let sy = W_CY + 24 + sin(a) * r;
    brush.set("charcoal", "#7a6450", random(0.45, 0.85));
    brush.line(sx, sy, sx + cos(a + 90) * 35, sy + sin(a + 90) * 35);
  }

  // Handle plastic body (translucent coral-ruby red with dark refraction core & bright speculars)
  for (let w = -34; w <= 34; w += 2.5) {
    let col = "#d92b21";
    if (w < -24 || w > 24) col = "#4a0805"; // Dark moulded edge ribs
    else if (w > -8 && w < 4) col = "#ff6e4a"; // Translucent glowing plastic core
    else if (w >= -18 && w <= -12) col = "#ffffff"; // Specular ridge

    brush.set("pool_marker", col, 0.55);
    brush.line(hx0 + perpX * w, hy0 + perpY * w, hx1 + perpX * (w * 1.15), hy1 + perpY * (w * 1.15));
  }

  // Moulded horizontal grip notches on the wand handle
  for (let d = 35; d < 260; d += 26) {
    let cx = hx0 + cos(hAngle) * d;
    let cy = hy0 + sin(hAngle) * d;
    brush.set("cpencil", "#380503", 0.55);
    brush.line(cx - perpX * 26, cy - perpY * 26, cx + perpX * 26, cy + perpY * 26);
    brush.set("cpencil", "#ff9e85", 0.45);
    brush.line(cx - perpX * 24 + 2, cy - perpY * 24 + 2, cx + perpX * 24 + 2, cy + perpY * 24 + 2);
  }

  // 2. Circular Plastic Wand Ring (Translucent Coral-Ruby with High-Contrast Rim Refraction)
  const ringBands = [
    { rOff: 0.04, col: "#360503", brushName: "cpencil", w: 0.65 },
    { rOff: 0.14, col: "#8f1610", brushName: "marbled_marker", w: 0.65 },
    { rOff: 0.28, col: "#d92b21", brushName: "pool_marker", w: 0.85 },
    { rOff: 0.46, col: "#ff5c3b", brushName: "pool_marker", w: 0.90 },
    { rOff: 0.62, col: "#ff8559", brushName: "marbled_marker", w: 0.70 },
    { rOff: 0.78, col: "#b51c14", brushName: "marbled_marker", w: 0.75 },
    { rOff: 0.92, col: "#4a0906", brushName: "ribbon_marker", w: 0.65 },
    { rOff: 0.98, col: "#240302", brushName: "cpencil", w: 0.60 }
  ];

  for (let b of ringBands) {
    let rad = lerp(W_R_IN, W_R_OUT, b.rOff);
    for (let seg = 0; seg < 12; seg++) {
      let aStart = seg * 30;
      let aEnd = (seg + 1) * 30 + 2;
      let pts = [];
      for (let a = aStart; a <= aEnd; a += 5) {
        pts.push([W_CX + cos(a) * rad, W_CY + sin(a) * rad]);
      }
      brush.set(b.brushName, b.col, b.w);
      brush.spline(pts, 0.5);
    }
  }

  // Crisp glossy white plastic specular arcs along the wand bevel
  let specArcs = [
    { a1: -165, a2: -55, rFrac: 0.36 },
    { a1: -40, a2: 25, rFrac: 0.38 },
    { a1: 35, a2: 102, rFrac: 0.68 },
    { a1: 132, a2: 185, rFrac: 0.42 }
  ];
  for (let sa of specArcs) {
    let rad = lerp(W_R_IN, W_R_OUT, sa.rFrac);
    let pts = [];
    for (let a = sa.a1; a <= sa.a2; a += 4) {
      pts.push([W_CX + cos(a) * rad, W_CY + sin(a) * rad]);
    }
    brush.set("cpencil", "#ffffff", 0.7);
    brush.spline(pts, 0.5);
    brush.set("cpencil", "#ffd6cc", 0.45);
    brush.spline(pts.map(p => [p[0] + 2, p[1] + 2]), 0.5);
  }

  // 3. Moulded Inner Flutes / Ridges (Classic bubble wand teeth that hold liquid soap)
  // & Wet Iridescent Soap Meniscus Ring bridging the inner rim
  const numTeeth = 84;
  for (let i = 0; i < numTeeth; i++) {
    let a = (i / numTeeth) * 360;
    let rOuter = W_R_IN + 5;
    let rInner = W_R_IN - 9;
    let x1 = W_CX + cos(a) * rOuter;
    let y1 = W_CY + sin(a) * rOuter;
    let x2 = W_CX + cos(a) * rInner;
    let y2 = W_CY + sin(a) * rInner;

    // Dark plastic shadow side of tooth
    brush.set("cpencil", "#3b0604", 0.5);
    brush.line(x1, y1, x2, y2);

    // Bright wet highlight on tooth tip
    let x3 = W_CX + cos(a + 0.8) * (rInner + 2);
    let y3 = W_CY + sin(a + 0.8) * (rInner + 2);
    brush.set("cpencil", i % 2 === 0 ? "#ffffff" : "#ff9b85", 0.4);
    brush.line(x1, y1, x3, y3);
  }

  // Wet soap meniscus ring clinging to the inner teeth (Plateau border)
  const meniscusColors = ["#ffffff", "#4ce6ff", "#ff4da6", "#ffdf66", "#42e3b8"];
  for (let i = 0; i < 60; i++) {
    let a1 = i * 6;
    let a2 = a1 + 7;
    let rMeniscus = W_R_IN - 7 + sin(a1 * 6) * 2.5;
    let p1 = [W_CX + cos(a1) * rMeniscus, W_CY + sin(a1) * rMeniscus];
    let p2 = [W_CX + cos((a1 + a2) * 0.5) * (rMeniscus - 2), W_CY + sin((a1 + a2) * 0.5) * (rMeniscus - 2)];
    let p3 = [W_CX + cos(a2) * rMeniscus, W_CY + sin(a2) * rMeniscus];

    let col = meniscusColors[i % meniscusColors.length];
    brush.set("cpencil", col, i % 5 === 0 ? 0.65 : 0.45);
    brush.spline([p1, p2, p3], 0.45);
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(88314);
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm archival cotton paper base for luminous pearloid highlights
  background("#f3eee3");

  // -------------------------------------------------------------------------
  // 3D-TO-2D TILTED MACRO PROJECTION
  // u: across accordion (-850..0 bellows & frame, 0..465 keys, 465..750 rail)
  // v: along keyboard axis (-750 top-right to +850 bottom-left)
  // z: height above keybed (0 keybed, 22 white keys, 50 black keys, 38..58 frame)
  // -------------------------------------------------------------------------
  const tilt = 25.5;
  const cosT = cos(tilt);
  const sinT = sin(tilt);
  const cx = 515;
  const cy = 595;

  function proj(u, v, z = 0) {
    let sc = 1.09 * (1 + 0.00014 * v + 0.00006 * u);
    let x0 = u * cosT - v * sinT;
    let y0 = u * sinT + v * cosT;
    let x = cx + (x0 - z * 0.39) * sc;
    let y = cy + (y0 - z * 0.43) * sc;
    return [x, y];
  }

  // Helper: Draw a washed/filled 3D polygon
  function fillPoly3D(pts3D, col, alpha = 255, useBleed = false, bleedAmt = 0.05) {
    brush.noStroke();
    brush.noHatch();
    if (useBleed) {
      brush.noWash();
      brush.fill(col, alpha);
      brush.fillBleed(bleedAmt, "out");
      brush.fillTexture(0.35, 0.25);
    } else {
      brush.noFill();
      brush.wash(col, alpha);
    }
    brush.beginShape(0);
    for (let i = 0; i < pts3D.length; i++) {
      let [x, y] = proj(pts3D[i][0], pts3D[i][1], pts3D[i][2] || 0);
      brush.vertex(x, y);
    }
    brush.endShape(true);
    brush.noFill();
    brush.noWash();
  }

  // Helper: Draw a 3D line
  function line3D(p1, p2, bName, col, w) {
    let [x1, y1] = proj(p1[0], p1[1], p1[2] || 0);
    let [x2, y2] = proj(p2[0], p2[1], p2[2] || 0);
    brush.set(bName, col, w);
    brush.line(x1, y1, x2, y2);
  }

  // Helper: Draw a 3D spline with optional pressure array [u, v, z, pressure]
  function spline3D(pts3D, curv, bName, col, w) {
    if (pts3D.length < 2) return;
    let pts2D = [];
    for (let i = 0; i < pts3D.length; i++) {
      let [x, y] = proj(pts3D[i][0], pts3D[i][1], pts3D[i][2] || 0);
      let pr = pts3D[i][3] !== undefined ? pts3D[i][3] : 1.0;
      pts2D.push([x, y, pr]);
    }
    brush.set(bName, col, w);
    brush.spline(pts2D, curv);
  }

  // Helper: Interpolate directional hatching across a 3D quad [A, B, C, D]
  function hatchQuad3D(pA, pB, pC, pD, steps, bName, col, w, jitter = 0) {
    brush.set(bName, col, w);
    for (let i = 0; i <= steps; i++) {
      let t = i / max(1, steps);
      let u1 = lerp(pA[0], pD[0], t) + (jitter ? random(-jitter, jitter) : 0);
      let v1 = lerp(pA[1], pD[1], t) + (jitter ? random(-jitter, jitter) : 0);
      let z1 = lerp(pA[2] || 0, pD[2] || 0, t);
      let u2 = lerp(pB[0], pC[0], t) + (jitter ? random(-jitter, jitter) : 0);
      let v2 = lerp(pB[1], pC[1], t) + (jitter ? random(-jitter, jitter) : 0);
      let z2 = lerp(pB[2] || 0, pC[2] || 0, t);
      let [x1, y1] = proj(u1, v1, z1);
      let [x2, y2] = proj(u2, v2, z2);
      brush.line(x1, y1, x2, y2);
    }
  }

  // =========================================================================
  // 1. BELLOWS (FIRST 5 FOLDS, V-GUSSETS & WORN BLACK BELLOWS CORNERS)
  // u in [-860, -135], v in [-820, 880]
  // =========================================================================
  const numFolds = 5;
  const foldSpan = 138;
  const bellowsStartU = -135;

  // Deep studio shadow backdrop under bellows & keyboard
  fillPoly3D(
    [[-900, -900, -60], [50, -900, -60], [50, 950, -60], [-900, 950, -60]],
    "#101217", 245, false
  );

  for (let f = numFolds - 1; f >= 0; f--) {
    let uRight = bellowsStartU - f * foldSpan;       // Valley (inner crease)
    let uPeak  = uRight - foldSpan * 0.52;           // Peak (outer ridge)
    let uLeft  = uRight - foldSpan;                  // Next valley
    let zVal   = -52;
    let zPeak  = 34 - f * 2.5;

    // Corner position along v where the front pleat meets the top gusset fold
    let vCorner = -165 + f * 48;
    let vTop = -850;
    let vBot = 920;

    // Valley gusset indent at the corner
    let uGussetIn = uPeak + 46;
    let zGussetIn = -18;

    // --- A. TOP END-FACE OF BELLOWS (above vCorner: vTop .. vCorner) ---
    // Left-sloping top pleat facet (from uLeft valley up to uPeak ridge)
    fillPoly3D(
      [
        [uLeft, vTop, zVal],
        [uPeak, vTop, zPeak],
        [uPeak, vCorner - 36, zPeak],
        [uGussetIn, vCorner, zGussetIn],
        [uLeft, vCorner, zVal]
      ],
      "#232730", 235, false
    );
    hatchQuad3D(
      [uLeft, vTop, zVal], [uPeak, vTop, zPeak],
      [uPeak, vCorner - 36, zPeak], [uLeft, vCorner, zVal],
      34, "2B", "#14171d", 0.55, 1.5
    );
    // Subtle raking light across the upper gusset slope
    hatchQuad3D(
      [uLeft + 15, vTop, zVal + 12], [uPeak, vTop, zPeak],
      [uPeak, vCorner - 36, zPeak], [uLeft + 15, vCorner, zVal + 12],
      22, "cpencil", "#4b5260", 0.42, 1.0
    );

    // Right-sloping top pleat facet (plunging into deep shadow toward uRight)
    fillPoly3D(
      [
        [uPeak, vTop, zPeak],
        [uRight, vTop, zVal],
        [uRight, vCorner, zVal],
        [uGussetIn, vCorner, zGussetIn],
        [uPeak, vCorner - 36, zPeak]
      ],
      "#0d0f14", 245, false
    );
    hatchQuad3D(
      [uPeak, vTop, zPeak], [uRight, vTop, zVal],
      [uRight, vCorner, zVal], [uPeak, vCorner - 36, zPeak],
      38, "charcoal", "#07080b", 0.65, 1.2
    );

    // --- B. V-GUSSET DIAMOND FOLD AT vCorner ---
    // Upper gusset triangle (catches oblique raking light)
    fillPoly3D(
      [
        [uPeak, vCorner - 36, zPeak],
        [uGussetIn, vCorner, zGussetIn],
        [uPeak, vCorner + 38, zPeak]
      ],
      "#1b1e26", 240, false
    );
    hatchQuad3D(
      [uPeak, vCorner - 36, zPeak], [uGussetIn, vCorner, zGussetIn],
      [uGussetIn, vCorner, zGussetIn], [uPeak, vCorner + 38, zPeak],
      18, "2B", "#0c0e13", 0.45, 0.8
    );

    // --- C. MAIN FRONT PLEATS (below vCorner: vCorner .. vBot) ---
    // 1. Left-facing slope of pleat (uLeft valley -> uPeak ridge): Lit by lateral light
    let litCol = f === 0 ? "#2f3542" : f === 1 ? "#282d38" : "#212630";
    fillPoly3D(
      [
        [uLeft, vCorner, zVal],
        [uPeak, vCorner + 38, zPeak],
        [uPeak, vBot, zPeak],
        [uLeft, vBot, zVal]
      ],
      litCol, 235, false
    );

    // Woven black cloth cross-hatching on lit bellows facet
    hatchQuad3D(
      [uLeft, vCorner, zVal], [uPeak, vCorner + 38, zPeak],
      [uPeak, vBot, zPeak], [uLeft, vBot, zVal],
      68, "2B", "#181b22", 0.5, 1.5
    );
    // Raking light sheen near the peak ridge
    hatchQuad3D(
      [lerp(uLeft, uPeak, 0.45), vCorner + 20, lerp(zVal, zPeak, 0.45)],
      [uPeak, vCorner + 38, zPeak],
      [uPeak, vBot, zPeak],
      [lerp(uLeft, uPeak, 0.45), vBot, lerp(zVal, zPeak, 0.45)],
      45, "HB", "#586070", 0.4, 1.2
    );
    // Fine linen weave diagonal grain
    for (let vLine = vCorner + 20; vLine < vBot; vLine += 26) {
      line3D(
        [uLeft + 8, vLine - 18, zVal + 6],
        [uPeak - 4, vLine + 24, zPeak - 3],
        "2H", "#464d5c", 0.32
      );
      if (random() < 0.55) {
        line3D(
          [lerp(uLeft, uPeak, 0.6), vLine, lerp(zVal, zPeak, 0.6)],
          [uPeak - 2, vLine + 14, zPeak - 1],
          "cpencil", "#7b8496", 0.28
        );
      }
    }

    // 2. Right-facing slope of pleat (uPeak ridge -> uRight valley): Deep velvet shadow
    fillPoly3D(
      [
        [uPeak, vCorner + 38, zPeak],
        [uGussetIn, vCorner, zGussetIn],
        [uRight, vCorner, zVal],
        [uRight, vBot, zVal],
        [uPeak, vBot, zPeak]
      ],
      "#0e1015", 248, false
    );
    hatchQuad3D(
      [uPeak, vCorner + 38, zPeak], [uRight, vCorner, zVal],
      [uRight, vBot, zVal], [uPeak, vBot, zPeak],
      72, "charcoal", "#07080c", 0.7, 1.4
    );
    // Faint reflected light deep inside the valley crease from adjacent lit ridge
    for (let vLine = vCorner + 30; vLine < vBot; vLine += 35) {
      line3D(
        [lerp(uPeak, uRight, 0.25), vLine, lerp(zPeak, zVal, 0.25)],
        [lerp(uPeak, uRight, 0.75), vLine + 12, lerp(zPeak, zVal, 0.75)],
        "2H", "#282d38", 0.3
      );
    }

    // Deep valley crease line at uRight
    line3D([uRight, vTop, zVal], [uRight, vBot, zVal], "charcoal", "#050608", 0.9);

    // --- D. WORN BLACK CLOTH TAPE ALONG PLEAT RIDGE ---
    let tapeW = 13;
    // Left tape lip
    fillPoly3D(
      [
        [uPeak - tapeW, vCorner + 38, zPeak - 6],
        [uPeak, vCorner + 38, zPeak],
        [uPeak, vBot, zPeak],
        [uPeak - tapeW, vBot, zPeak - 6]
      ],
      "#3a414f", 220, false
    );
    // Scuffed graphite highlights along the worn black cloth tape ridge
    for (let vS = vCorner + 44; vS < vBot; vS += 9) {
      let scuff = noise(f * 10, vS * 0.03);
      let col = scuff > 0.58 ? "#b8c2d1" : scuff > 0.4 ? "#788294" : "#49505e";
      let w = scuff > 0.58 ? 0.52 : 0.35;
      line3D(
        [uPeak - tapeW * random(0.3, 0.9), vS, zPeak - 3],
        [uPeak + random(-2, 3), vS + random(-2, 4), zPeak + 0.5],
        "HB", col, w
      );
      // Tiny frayed thread marks on worn ridge
      if (scuff > 0.64) {
        line3D(
          [uPeak - 3, vS, zPeak],
          [uPeak + 2, vS + 5, zPeak],
          "2H", "#e3e8f0", 0.28
        );
      }
    }

    // --- E. WORN BLACK / CHROME STAMPED BELLOWS CORNER PROTECTOR ---
    // Rendered in dense graphite with worn black lacquer and exposed steel highlights
    let cLen = 44;
    let cWidth = 24;
    let pTip = [uPeak + 5, vCorner + 2, zPeak + 3];
    let pTopL = [uPeak - cWidth, vCorner - cLen, zPeak - 9];
    let pTopR = [uPeak + cWidth * 0.75, vCorner - cLen * 0.75, zPeak - 11];
    let pBotL = [uPeak - cWidth, vCorner + cLen + 14, zPeak - 9];
    let pBotR = [uPeak + cWidth * 0.75, vCorner + cLen + 8, zPeak - 11];
    let pMidRidge = [uPeak, vCorner + 4, zPeak + 4.5];

    // Dark oxidized metal base of the corner cap
    fillPoly3D([pTopL, pMidRidge, pBotL], "#222730", 245, false);
    fillPoly3D([pMidRidge, pTopR, pTip, pBotR], "#11141a", 250, false);

    // Dense graphite modelling across the stamped metal corner
    hatchQuad3D(pTopL, pMidRidge, pMidRidge, pBotL, 24, "2B", "#151820", 0.45, 0.5);
    hatchQuad3D(pMidRidge, pTopR, pBotR, pMidRidge, 24, "charcoal", "#090b0f", 0.55, 0.5);

    // Crimped perimeter lip & rivets
    spline3D([pTopL, [uPeak - cWidth * 0.85, vCorner + 4, zPeak - 6], pBotL], 0.4, "2B", "#0a0c10", 0.75);
    spline3D([pTopL, [uPeak - cWidth * 0.8, vCorner + 4, zPeak - 5.5], pBotL], 0.4, "2H", "#8d96a6", 0.35);

    // Embossed reinforcement ribs on the metal corner cap (catching lateral raking light)
    for (let rib = -1; rib <= 1; rib++) {
      let rv = vCorner + 4 + rib * 13;
      let ribPts = [
        [uPeak - cWidth * 0.75, rv - 3, zPeak - 6],
        [uPeak - 4, rv, zPeak + 4],
        [uPeak + 4, rv + 1, zPeak + 3.5],
        [uPeak + cWidth * 0.55, rv - 2, zPeak - 7]
      ];
      // Dark shadow beneath rib
      spline3D(
        ribPts.map(p => [p[0], p[1] + 2.2, p[2] - 0.5]),
        0.5, "2B", "#080a0e", 0.65
      );
      // Worn silver-graphite highlight on top of rib
      spline3D(ribPts, 0.5, "HB", "#c4cddb", 0.5);
      // Specular raw steel glint where black lacquer wore off the knuckle
      line3D(
        [uPeak - 7, rv - 0.5, zPeak + 3.5],
        [uPeak + 3, rv + 0.5, zPeak + 4.2],
        "cpencil", "#ffffff", 0.55
      );
    }

    // Scratches and burnished graphite wear on the corner knuckle
    for (let s = 0; s < 16; s++) {
      let sv = vCorner + random(-24, 34);
      let su = uPeak + random(-14, 6);
      let col = random() < 0.4 ? "#f5f8fc" : "#95a0b2";
      line3D(
        [su, sv, zPeak + 2],
        [su + random(-5, 5), sv + random(4, 12), zPeak + 2],
        "2H", col, random(0.25, 0.45)
      );
    }
  }

  // =========================================================================
  // 2. KEYBED UNDER-SHADOW & FRONT KEYBOARD RAIL (BOTTOM-RIGHT CORNER)
  // =========================================================================
  // Deep shadow recess directly beneath all white keys (u in [0, 485], z = 0)
  fillPoly3D(
    [[0, -850, 0], [490, -850, 0], [490, 920, 0], [0, 920, 0]],
    "#0a0c10", 252, false
  );

  // Molded black celluloid front rail beyond the key tips (u in [472, 760], z = -12..10)
  fillPoly3D(
    [[472, -850, 8], [535, -850, 10], [535, 920, 10], [472, 920, 8]],
    "#1e222b", 245, false
  );
  fillPoly3D(
    [[535, -850, 10], [780, -850, -25], [780, 920, -25], [535, 920, 10]],
    "#0e1015", 250, false
  );
  hatchQuad3D(
    [472, -750, 8], [535, -750, 10], [535, 850, 10], [472, 850, 8],
    60, "2B", "#12151c", 0.5, 1.0
  );
  // Raking highlight along the moulded keyboard rail lip at u = 476
  for (let vR = -700; vR < 800; vR += 35) {
    line3D([475, vR, 9.5], [475, vR + 28, 9.5], "HB", "#697282", 0.42);
    line3D([532, vR, 10.5], [532, vR + 25, 10.5], "2H", "#8d96a6", 0.35);
  }

  // =========================================================================
  // 3. PEARLOID WHITE KEYS
  // Drawn back-to-front (k = -7 to +10) for true 3D occlusion
  // =========================================================================
  const keyPitch = 86;
  const keyGap = 4.6;
  const keyW = keyPitch - keyGap;
  const uKeyStart = 0;
  const uKeyEnd = 462;
  const uTipStart = 434;

  // Musical pattern: which inter-key boundaries have a Black Key (2 - 3 - 2 - 3 pattern)
  function hasBlackKeyAfter(k) {
    let mod = ((k % 7) + 7) % 7;
    // C D E F G A B -> sharps after C(0), D(1), F(3), G(4), A(5)
    return mod === 0 || mod === 1 || mod === 3 || mod === 4 || mod === 5;
  }

  // Which keys have tiny celluloid chips or fingerprint smudges
  const chippedKeys = new Set([-2, 1, 3, 5, 7]);
  const smudgedKeys = new Set([0, 2, 3, 5, 6]);

  for (let k = -7; k <= 10; k++) {
    let v1 = k * keyPitch;
    let v2 = v1 + keyW;

    // Slight mechanical variation in key rest height sells the vintage realism
    let zTop = 22.0 + sin(k * 73) * 0.9 - (k === 2 || k === 5 ? 1.6 : 0);
    let zLaminateBot = zTop - 7.5;
    let zWoodBot = 0;

    // --- A. 3D WOOD LEVER & PEARLOID SIDE WALL (+v face at v = v2) ---
    // Dark wood/felt under-wall (z = 0 .. zLaminateBot)
    fillPoly3D(
      [
        [uKeyStart, v2, zWoodBot],
        [uTipStart, v2, zWoodBot],
        [uTipStart, v2, zLaminateBot],
        [uKeyStart, v2, zLaminateBot]
      ],
      "#181514", 248, false
    );
    // Pearloid celluloid side wall (z = zLaminateBot .. zTop) in core shadow
    fillPoly3D(
      [
        [uKeyStart, v2, zLaminateBot],
        [uTipStart, v2, zLaminateBot],
        [uTipStart + 18, v2 - 4, zTop - 1],
        [uKeyStart, v2, zTop]
      ],
      "#6f7684", 240, false
    );
    hatchQuad3D(
      [uKeyStart, v2, zLaminateBot], [uTipStart, v2, zLaminateBot],
      [uTipStart, v2, zTop], [uKeyStart, v2, zTop],
      12, "HB", "#4b515e", 0.36, 0.3
    );
    // Subtle warm bounce-light reflected near bottom of pearloid side wall
    line3D(
      [uKeyStart + 25, v2, zLaminateBot + 1.8],
      [uTipStart - 10, v2, zLaminateBot + 1.8],
      "cpencil", "#b8b4be", 0.35
    );

    // --- B. ROUNDED WATERFALL FRONT NOSE OF KEY (u = uTipStart .. uKeyEnd) ---
    let noseSteps = 8;
    let noseTopPts = [];
    let noseBotPts = [];
    for (let s = 0; s <= noseSteps; s++) {
      let t = s / noseSteps;
      // Rounded corner in (u, v) and waterfall droop in z
      let uN = lerp(uTipStart, uKeyEnd, sin(t * 90));
      let vN1 = v1 + (1 - cos(t * 90)) * 7;
      let vN2 = v2 - (1 - cos(t * 90)) * 7;
      let zN = zTop - (1 - cos(t * 90)) * 4.5;
      noseTopPts.push([uN, vN1, zN]);
      noseBotPts.unshift([uN, vN2, zN]);
    }
    // Front vertical waterfall face at uKeyEnd (z = 2 .. zTop - 4.5)
    fillPoly3D(
      [
        [uKeyEnd, v1 + 7, 3],
        [uKeyEnd, v2 - 7, 3],
        [uKeyEnd, v2 - 7, zTop - 4.5],
        [uKeyEnd, v1 + 7, zTop - 4.5]
      ],
      "#8b919e", 235, false
    );
    // Side corner wrap of the nose
    fillPoly3D(
      [
        [uTipStart, v2, zLaminateBot],
        [uKeyEnd, v2 - 7, 4],
        [uKeyEnd, v2 - 7, zTop - 4.5],
        [uTipStart, v2, zTop]
      ],
      "#5c6270", 240, false
    );
    hatchQuad3D(
      [uKeyEnd, v1 + 7, 4], [uKeyEnd, v2 - 7, 4],
      [uKeyEnd, v2 - 7, zTop - 4.5], [uKeyEnd, v1 + 7, zTop - 4.5],
      10, "HB", "#626875", 0.35, 0.2
    );

    // --- C. TOP SURFACE OF WHITE KEY: BASE WASH ---
    let keyOutline = [
      [uKeyStart, v1, zTop],
      ...noseTopPts,
      ...noseBotPts,
      [uKeyStart, v2, zTop]
    ];
    // Warm cream base wash
    fillPoly3D(keyOutline, "#f6f0e4", 240, false);

    // Subtle lateral light gradient across the key width (cooler pearl toward +v edge)
    fillPoly3D(
      [
        [uKeyStart, lerp(v1, v2, 0.58), zTop],
        [uKeyEnd - 4, lerp(v1, v2, 0.58), zTop - 2],
        [uKeyEnd - 6, v2 - 6, zTop - 3],
        [uKeyStart, v2, zTop]
      ],
      "#dfe3ea", 130, true, 0.04
    );

    // --- D. MOTHER-OF-PEARL (PEARLOID) SWIRL & DIRECTIONAL NACRE HATCHING ---
    // Each key has its own cut of swirled pearloid celluloid sheet
    let seedOff = k * 37.4 + 100;

    // 1. Soft underlying nacre color clouds (pale pink, celadon, lavender, cream)
    let numLobes = 11;
    let lobeStep = (uKeyEnd - 14 - uKeyStart) / numLobes;
    for (let l = 0; l < numLobes; l++) {
      let uL1 = uKeyStart + l * lobeStep;
      let uL2 = uL1 + lobeStep * 1.15;
      let nVal = noise(seedOff + l * 0.45, k * 1.7);
      let nVal2 = noise(seedOff + l * 0.45 + 9.2, k * 1.7 + 3.1);

      // Select nacre tint: pale pink, celadon, lavender, or champagne cream
      let lobeColA, lobeColB;
      if (nVal < 0.28) {
        lobeColA = "#f2d3dc"; // pale rose pink
        lobeColB = "#cfe2db"; // celadon
      } else if (nVal < 0.54) {
        lobeColA = "#cce0d8"; // celadon green-grey
        lobeColB = "#dad2eb"; // soft lavender
      } else if (nVal < 0.78) {
        lobeColA = "#d8d0ea"; // pale lavender
        lobeColB = "#f4d7df"; // blush pink
      } else {
        lobeColA = "#f7eedb"; // warm champagne cream
        lobeColB = "#d2deea"; // cool silver-pearl
      }

      let vMidWave1 = lerp(v1 + 6, v2 - 6, constrain(0.25 + 0.55 * sin(l * 52 + k * 40), 0.15, 0.85));
      let vMidWave2 = lerp(v1 + 6, v2 - 6, constrain(0.25 + 0.55 * sin((l + 1) * 52 + k * 40), 0.15, 0.85));

      // Upper nacre ribbon lobe
      fillPoly3D(
        [
          [uL1, v1 + 3, zTop],
          [uL2, v1 + 3, zTop],
          [uL2, vMidWave2, zTop],
          [uL1, vMidWave1, zTop]
        ],
        lobeColA, 105, true, 0.05
      );
      // Lower nacre ribbon lobe
      fillPoly3D(
        [
          [uL1, vMidWave1, zTop],
          [uL2, vMidWave2, zTop],
          [uL2, v2 - 4, zTop],
          [uL1, v2 - 4, zTop]
        ],
        lobeColB, 110, true, 0.05
      );

      // Chatoyant silver-pearl pocket in the curl of the swirl
      if (nVal2 > 0.46) {
        let uC = (uL1 + uL2) * 0.5;
        let vC = vMidWave1;
        fillPoly3D(
          [
            [uC - 16, vC - 10, zTop],
            [uC + 14, vC - 6, zTop],
            [uC + 18, vC + 11, zTop],
            [uC - 12, vC + 8, zTop]
          ],
          "#bbc3d1", 90, true, 0.04
        );
      }
    }

    // 2. Directional Colored-Pencil Hatching following the Flaming Grain of the Nacre
    // Flaming grain angle waves organically along u and v
    let nacreStreams = 78;
    for (let s = 0; s < nacreStreams; s++) {
      let u0 = random(uKeyStart + 6, uKeyEnd - 16);
      let v0 = random(v1 + 4, v2 - 5);

      // Evaluate local nacre wave phase to pick burnished colored pencil shade
      let wave = sin((u0 * 0.048) * 57.3 + k * 45 + 2.2 * sin(v0 * 0.07 * 57.3));
      let cellNoise = noise(u0 * 0.018 + seedOff, v0 * 0.028);

      let pCol, bType, pWeight;
      if (wave > 0.55) {
        // Burnished white / warm cream specular nacre crest
        pCol = cellNoise > 0.5 ? "#ffffff" : "#fcf6e8";
        bType = "cpencil";
        pWeight = 0.52;
      } else if (wave > 0.12) {
        // Pale blush pink nacre band
        pCol = cellNoise > 0.52 ? "#ebbecb" : "#f5d8e0";
        bType = "cpencil";
        pWeight = 0.44;
      } else if (wave > -0.32) {
        // Celadon green-grey nacre band
        pCol = cellNoise > 0.5 ? "#b6d1c7" : "#cfe4dc";
        bType = "cpencil";
        pWeight = 0.44;
      } else if (wave > -0.72) {
        // Soft lavender nacre band
        pCol = cellNoise > 0.5 ? "#c2b6dc" : "#dad2ec";
        bType = "cpencil";
        pWeight = 0.44;
      } else {
        // Chatoyant silver-graphite fold boundary between nacre lobes
        pCol = cellNoise > 0.5 ? "#8790a0" : "#a5aebe";
        bType = "2H";
        pWeight = 0.34;
      }

      // Trace a 4-point curved streamline along the flaming grain field
      let curvePts = [];
      let curU = u0;
      let curV = v0;
      let stepLen = random(9, 15);
      for (let step = 0; step < 4; step++) {
        // Local flaming grain orientation (swirling ribbons across the key)
        let grainAng =
          58 * sin((curU * 0.035 + k * 0.8) * 57.3) +
          36 * cos((curV * 0.055 - k * 0.5) * 57.3) +
          25 * (noise(curU * 0.02 + seedOff, curV * 0.02) - 0.5);

        let curZ = curU > uTipStart
          ? zTop - pow((curU - uTipStart) / (uKeyEnd - uTipStart), 1.6) * 4.2
          : zTop;
        let pr = step === 0 || step === 3 ? 0.55 : 1.15;
        curvePts.push([curU, curV, curZ, pr]);

        curU += cos(grainAng) * stepLen;
        curV += sin(grainAng) * stepLen * 0.72;
        curU = constrain(curU, uKeyStart + 3, uKeyEnd - 5);
        curV = constrain(curV, v1 + 3.5, v2 - 3.5);
      }
      spline3D(curvePts, 0.55, bType, pCol, pWeight);
    }

    // 3. Crisp Silver-Graphite Chatoyant Veins & Burnished Shimmer Accents
    for (let vIdx = 0; vIdx < 14; vIdx++) {
      let uVein = uKeyStart + 22 + vIdx * 31 + random(-8, 8);
      if (uVein > uKeyEnd - 18) continue;
      let vA = v1 + random(5, 22);
      let vM1 = lerp(v1, v2, random(0.3, 0.5));
      let vM2 = lerp(v1, v2, random(0.55, 0.78));
      let vB = v2 - random(5, 20);
      let uShift1 = random(-18, 18);
      let uShift2 = random(-18, 18);

      // Dark chatoyant vein line where nacre crystal orientation flips
      spline3D(
        [
          [uVein, vA, zTop, 0.4],
          [uVein + uShift1, vM1, zTop, 1.0],
          [uVein + uShift2, vM2, zTop, 0.9],
          [uVein + uShift1 * 0.5, vB, zTop, 0.3]
        ],
        0.65, "2H", "#8e96a6", 0.3
      );
      // Immediate adjacent burnished white pearl flash
      spline3D(
        [
          [uVein + 3.5, vA + 2, zTop, 0.5],
          [uVein + uShift1 + 4, vM1, zTop, 1.2],
          [uVein + uShift2 + 4, vM2, zTop, 1.1],
          [uVein + uShift1 * 0.5 + 3.5, vB - 2, zTop, 0.4]
        ],
        0.65, "cpencil", "#ffffff", 0.55
      );
    }

    // --- E. RAKING LATERAL LIGHT ACROSS KEY EDGES ---
    // 1. Brilliant raking highlight along the upper (-v) bevel of the key
    spline3D(
      [
        [uKeyStart + 4, v1 + 1.2, zTop + 0.3, 0.7],
        [uTipStart * 0.5, v1 + 1.2, zTop + 0.3, 1.2],
        [uTipStart, v1 + 1.5, zTop + 0.3, 1.3],
        [uKeyEnd - 3, v1 + 7.5, zTop - 3.5, 0.8]
      ],
      0.35, "cpencil", "#ffffff", 0.78
    );
    line3D(
      [uKeyStart + 8, v1 + 3.0, zTop],
      [uTipStart, v1 + 3.0, zTop],
      "cpencil", "#fdf9f0", 0.52
    );

    // 2. Curved waterfall highlight across the rounded front nose
    spline3D(
      [
        [uTipStart + 10, v1 + 4, zTop - 0.8, 0.9],
        [uTipStart + 16, (v1 + v2) * 0.5, zTop - 1.1, 1.3],
        [uTipStart + 10, v2 - 5, zTop - 1.2, 0.6]
      ],
      0.5, "cpencil", "#ffffff", 0.68
    );

    // 3. Lower (+v) bevel core shadow turning down into the key gap
    line3D(
      [uKeyStart + 4, v2 - 1.5, zTop - 0.3],
      [uTipStart + 6, v2 - 2.2, zTop - 0.6],
      "HB", "#7b8391", 0.45
    );
    line3D(
      [uKeyStart + 4, v2, zTop - 0.8],
      [uTipStart + 4, v2 - 1, zTop - 1.0],
      "2B", "#313640", 0.42
    );

    // --- F. TINY CHIPS IN THE CELLULOID ---
    if (chippedKeys.has(k)) {
      // Chip 1: Along the front nose or upper/lower bevel edge
      let isFrontChip = (k % 2 !== 0);
      let uChip = isFrontChip ? uTipStart + 12 : random(275, 405);
      let vChip = isFrontChip ? lerp(v1 + 14, v2 - 14, 0.35 + 0.2 * (k % 3)) : (k > 2 ? v1 + 2.5 : v2 - 3.5);
      let zChip = isFrontChip ? zTop - 1.2 : zTop;
      let cw = random(7, 13);
      let ch = random(5, 9);

      // Exposed dark porous wood/core inside the broken celluloid notch
      fillPoly3D(
        [
          [uChip - cw * 0.5, vChip - ch * 0.4, zChip - 1.5],
          [uChip + cw * 0.6, vChip - ch * 0.2, zChip - 1.5],
          [uChip + cw * 0.3, vChip + ch * 0.6, zChip - 1.5],
          [uChip - cw * 0.4, vChip + ch * 0.4, zChip - 1.5]
        ],
        "#2a231e", 245, false
      );
      // Micro-shadow at upper rim of chip
      line3D(
        [uChip - cw * 0.5, vChip - ch * 0.4, zChip - 0.5],
        [uChip + cw * 0.6, vChip - ch * 0.2, zChip - 0.5],
        "2B", "#0d0b0a", 0.42
      );
      // Bright fractured celluloid thickness catch-light on lower rim of chip
      spline3D(
        [
          [uChip - cw * 0.4, vChip + ch * 0.4, zChip, 0.7],
          [uChip + cw * 0.3, vChip + ch * 0.6, zChip, 1.2],
          [uChip + cw * 0.6, vChip - ch * 0.2, zChip, 0.6]
        ],
        0.3, "cpencil", "#ffffff", 0.5
      );
    }

    // --- G. FINGERPRINT SMUDGES & MICRO SURFACE WEAR ON KEYS ---
    if (smudgedKeys.has(k)) {
      let uSmudge = random(315, 395);
      let vSmudge = (v1 + v2) * 0.5 + random(-8, 8);
      let tiltSmudge = random(-22, 18);

      // Subtle warm oily halo that slightly mutes the nacre contrast
      let haloPts = [];
      for (let a = 0; a < 360; a += 45) {
        let du = cos(a) * 28;
        let dv = sin(a) * 19;
        haloPts.push([uSmudge + du, vSmudge + dv, zTop]);
      }
      fillPoly3D(haloPts, "#e3dccb", 65, true, 0.06);

      // Concentric fingerprint whorl ridges in ultra-fine 2H graphite & cream pencil
      for (let r = 3.5; r <= 24; r += 2.4) {
        let aStart = random(-150, -40);
        let aEnd = aStart + random(110, 210);
        let ridgePts = [];
        for (let a = aStart; a <= aEnd; a += 28) {
          let radU = r * 1.35;
          let radV = r * 0.92;
          let du0 = cos(a) * radU;
          let dv0 = sin(a) * radV;
          let du = du0 * cos(tiltSmudge) - dv0 * sin(tiltSmudge);
          let dv = du0 * sin(tiltSmudge) + dv0 * cos(tiltSmudge);
          ridgePts.push([
            constrain(uSmudge + du, uKeyStart + 10, uTipStart + 8),
            constrain(vSmudge + dv, v1 + 5, v2 - 5),
            zTop,
            0.75
          ]);
        }
        let ridgeCol = r % 4.8 < 2.4 ? "#9ca3b0" : "#f7f1e3";
        spline3D(ridgePts, 0.5, "2H", ridgeCol, 0.24);
      }
    }
  }

  // =========================================================================
  // 4. RAKING CAST SHADOWS FROM BLACK KEYS & TREBLE CASING ONTO WHITE KEYS
  // =========================================================================
  const uBlackEnd = 256;
  const uBlackSlopeStart = 212;
  const blackW = 45;

  // A. Long shadow cast by the treble casing overhang (u = 0..24) across all keys
  fillPoly3D(
    [[0, -820, 22.5], [26, -820, 22.5], [26, 900, 22.5], [0, 900, 22.5]],
    "#1b2029", 165, true, 0.05
  );
  hatchQuad3D(
    [0, -750, 22.5], [22, -750, 22.5], [22, 850, 22.5], [0, 850, 22.5],
    95, "2B", "#11141b", 0.42, 0.8
  );

  // B. Raking diagonal cast shadows of each Black Key onto the White Keys below
  for (let k = -7; k <= 9; k++) {
    if (!hasBlackKeyAfter(k)) continue;

    let vBoundary = (k + 1) * keyPitch - keyGap * 0.5;
    let mod = ((k % 7) + 7) % 7;
    let vShift = mod === 0 || mod === 3 ? -3.5 : mod === 1 || mod === 5 ? 3.5 : 0;
    let vB1 = vBoundary - blackW * 0.5 + vShift;
    let vB2 = vBoundary + blackW * 0.5 + vShift;

    // Raking light from upper-left (-v, -u) casts shadow toward (+v, +u)
    let duShadow = 32;
    let dvShadow = 42;
    let zShadow = 22.2;

    let shadowPoly = [
      [0, vB2, zShadow],
      [uBlackSlopeStart, vB2, zShadow],
      [uBlackEnd + duShadow * 0.65, vB2 + dvShadow * 0.72, zShadow],
      [uBlackSlopeStart + duShadow, vB2 + dvShadow, zShadow],
      [0, vB2 + dvShadow, zShadow]
    ];

    // Cool translucent slate-violet shadow wash (preserving nacre texture underneath)
    fillPoly3D(shadowPoly, "#2b313f", 145, true, 0.05);

    // Directional graphite hatching inside the cast shadow
    hatchQuad3D(
      [4, vB2 + 1, zShadow],
      [uBlackSlopeStart + 10, vB2 + 4, zShadow],
      [uBlackSlopeStart + duShadow - 4, vB2 + dvShadow - 2, zShadow],
      [4, vB2 + dvShadow - 2, zShadow],
      32, "HB", "#1e232e", 0.36, 0.6
    );
    // Crisp dark umbra core right against the base of the black key
    hatchQuad3D(
      [2, vB2, zShadow],
      [uBlackEnd - 8, vB2, zShadow],
      [uBlackEnd + 4, vB2 + 11, zShadow],
      [2, vB2 + 11, zShadow],
      14, "2B", "#0f1218", 0.42, 0.3
    );
  }

  // =========================================================================
  // 5. BLACK KEYS (SHARPS/FLATS) IN DENSE GRAPHITE
  // Drawn back-to-front (k = -7 to +9), elevated at z = 22 .. 50
  // =========================================================================
  for (let k = -7; k <= 9; k++) {
    if (!hasBlackKeyAfter(k)) continue;

    let vBoundary = (k + 1) * keyPitch - keyGap * 0.5;
    let mod = ((k % 7) + 7) % 7;
    let vShift = mod === 0 || mod === 3 ? -3.5 : mod === 1 || mod === 5 ? 3.5 : 0;
    let vB1 = vBoundary - blackW * 0.5 + vShift;
    let vB2 = vBoundary + blackW * 0.5 + vShift;

    let zBase = 22.0;
    let zCrown = 50.0;
    let taper = 5.0; // Top of black key is slightly narrower than its base

    // --- A. +V SIDE WALL OF BLACK KEY (glossy ebony reflecting adjacent pearloid) ---
    let sideWall = [
      [0, vB2, zBase],
      [uBlackEnd, vB2 - 2, zBase],
      [uBlackEnd - 8, vB2 - taper, zBase + 10],
      [uBlackSlopeStart, vB2 - taper, zCrown],
      [0, vB2 - taper, zCrown]
    ];
    fillPoly3D(sideWall, "#101319", 252, false);

    // Dense graphite hatching on side wall
    hatchQuad3D(
      [0, vB2, zBase], [uBlackSlopeStart, vB2, zBase],
      [uBlackSlopeStart, vB2 - taper, zCrown], [0, vB2 - taper, zCrown],
      22, "charcoal", "#07090d", 0.55, 0.5
    );

    // Reflected pearloid bounce-light band along the middle-lower glossy side wall
    fillPoly3D(
      [
        [12, vB2 - 1.5, zBase + 5],
        [uBlackSlopeStart + 10, vB2 - 2, zBase + 5],
        [uBlackSlopeStart + 4, vB2 - 3.2, zBase + 15],
        [12, vB2 - 3.0, zBase + 15]
      ],
      "#6e6b78", 130, true, 0.04
    );
    for (let bLine = 0; bLine < 7; bLine++) {
      let zB = zBase + 6 + bLine * 1.4;
      let colB = bLine % 2 === 0 ? "#8d8998" : "#788886"; // faint pink & celadon bounce
      line3D(
        [14, vB2 - 2, zB],
        [uBlackSlopeStart + 8 - bLine * 2, vB2 - 2.5, zB],
        "cpencil", colB, 0.34
      );
    }
    // Jet-black base crease where black key meets the white key slot
    line3D([0, vB2, zBase], [uBlackEnd, vB2 - 2, zBase], "2B", "#040507", 0.65);

    // --- B. SLOPED & ROUNDED FRONT NOSE OF BLACK KEY (u = uBlackSlopeStart .. uBlackEnd) ---
    let frontNose = [
      [uBlackSlopeStart, vB1 + taper, zCrown],
      [uBlackEnd - 6, vB1 + taper + 3, zBase + 11],
      [uBlackEnd, (vB1 + vB2) * 0.5, zBase + 2],
      [uBlackEnd - 2, vB2 - 2, zBase],
      [uBlackEnd - 8, vB2 - taper, zBase + 10],
      [uBlackSlopeStart, vB2 - taper, zCrown]
    ];
    fillPoly3D(frontNose, "#1c2029", 248, false);
    hatchQuad3D(
      [uBlackSlopeStart, vB1 + taper, zCrown],
      [uBlackSlopeStart, vB2 - taper, zCrown],
      [uBlackEnd - 4, vB2 - 4, zBase + 4],
      [uBlackEnd - 4, vB1 + 4, zBase + 4],
      18, "2B", "#101319", 0.45, 0.4
    );

    // --- C. CROWNED TOP SURFACE OF BLACK KEY (z = zCrown) ---
    let topFace = [
      [0, vB1 + taper, zCrown],
      [uBlackSlopeStart, vB1 + taper, zCrown],
      [uBlackSlopeStart + 10, (vB1 + vB2) * 0.5, zCrown - 2],
      [uBlackSlopeStart, vB2 - taper, zCrown],
      [0, vB2 - taper, zCrown]
    ];
    fillPoly3D(topFace, "#242934", 248, false);

    // Lengthwise dense graphite burnishing on black key crown
    hatchQuad3D(
      [0, vB1 + taper + 2, zCrown],
      [uBlackSlopeStart, vB1 + taper + 2, zCrown],
      [uBlackSlopeStart, vB2 - taper - 2, zCrown],
      [0, vB2 - taper - 2, zCrown],
      24, "2B", "#151921", 0.46, 0.5
    );
    // Soft satin sheen along the upper-center of the crowned top
    for (let s = 0; s < 10; s++) {
      let vS = lerp(vB1 + taper + 2, (vB1 + vB2) * 0.52, s / 9);
      line3D(
        [8, vS, zCrown + 0.5],
        [uBlackSlopeStart - 4, vS, zCrown + 0.5],
        "HB", s < 4 ? "#6d7687" : "#444b59", 0.36
      );
    }

    // --- D. RAZOR-SHARP RAKING SPECULAR HIGHLIGHT ON UPPER (-V) BEVEL & NOSE ---
    spline3D(
      [
        [4, vB1 + taper + 0.8, zCrown + 0.4, 0.7],
        [uBlackSlopeStart * 0.55, vB1 + taper + 0.8, zCrown + 0.5, 1.2],
        [uBlackSlopeStart, vB1 + taper + 1.2, zCrown + 0.4, 1.3],
        [uBlackEnd - 8, vB1 + taper + 5, zBase + 11, 1.0],
        [uBlackEnd - 2, (vB1 + vB2) * 0.5, zBase + 4, 0.5]
      ],
      0.4, "cpencil", "#ffffff", 0.65
    );
    // Secondary silver-blue edge sheen beside the main specular highlight
    spline3D(
      [
        [8, vB1 + taper + 2.8, zCrown, 0.6],
        [uBlackSlopeStart, vB1 + taper + 3.0, zCrown, 1.0],
        [uBlackEnd - 10, (vB1 + vB2) * 0.46, zBase + 12, 0.7]
      ],
      0.4, "2H", "#b8c4d6", 0.4
    );

    // --- E. FINGERPRINT SMUDGE & FINE CELLULOID SCRATCHES ON CENTRAL BLACK KEYS ---
    if (k >= 0 && k <= 5) {
      let uSm = random(135, 195);
      let vSm = (vB1 + vB2) * 0.5;
      for (let r = 3; r <= 12; r += 2.6) {
        spline3D(
          [
            [uSm - r * 1.4, vSm - r * 0.5, zCrown + 0.5, 0.5],
            [uSm, vSm - r * 0.8, zCrown + 0.5, 0.9],
            [uSm + r * 1.4, vSm - r * 0.3, zCrown + 0.5, 0.6],
            [uSm + r * 0.9, vSm + r * 0.6, zCrown + 0.5, 0.4]
          ],
          0.55, "2H", "#7c8596", 0.24
        );
      }
    }
  }

  // =========================================================================
  // 6. TREBLE CASING, CELLULOID HOUSING, GRILLE SLOTS & CHROME GRILLE BOLTS
  // u in [-138, 6], v in [-820, 880], z = 22 .. 56
  // =========================================================================
  const uFrameLeft = -138;
  const uFrameRight = 6;
  const zFrameTop = 41;

  // --- A. STEPPED BLACK CELLULOID KEYBOARD LIP (u = -12 .. 6, z = 22 .. 41) ---
  fillPoly3D(
    [
      [-10, -820, zFrameTop],
      [6, -820, 24],
      [6, 890, 24],
      [-10, 890, zFrameTop]
    ],
    "#0f1218", 252, false
  );
  hatchQuad3D(
    [-10, -760, zFrameTop], [6, -760, 24],
    [6, 840, 24], [-10, 840, zFrameTop],
    95, "charcoal", "#07090d", 0.55, 0.6
  );

  // --- B. MAIN BLACK CELLULOID TREBLE CASING DECK (u = -138 .. -10, z = 41) ---
  fillPoly3D(
    [
      [uFrameLeft, -820, zFrameTop - 3],
      [-10, -820, zFrameTop],
      [-10, 890, zFrameTop],
      [uFrameLeft, 890, zFrameTop - 3]
    ],
    "#181c24", 250, false
  );

  // Dense directional graphite toning across the black celluloid casing
  hatchQuad3D(
    [uFrameLeft, -760, zFrameTop - 3], [-10, -760, zFrameTop],
    [-10, 840, zFrameTop], [uFrameLeft, 840, zFrameTop - 3],
    140, "2B", "#10131a", 0.52, 1.0
  );

  // Broad soft lateral specular sheen along the rounded celluloid ridge (u = -22 .. -8)
  for (let s = 0; s < 9; s++) {
    let uS = lerp(-24, -9, s / 8);
    let col = s === 5 || s === 6 ? "#c6d0df" : s > 3 ? "#7b8596" : "#404754";
    let w = s === 5 || s === 6 ? 0.52 : 0.38;
    line3D([uS, -760, zFrameTop + 0.5], [uS, 840, zFrameTop + 0.5], "HB", col, w);
  }
  // Secondary highlight along the bellows-side bezel (u = -134)
  line3D([uFrameLeft + 4, -760, zFrameTop - 2], [uFrameLeft + 4, 840, zFrameTop - 2], "HB", "#6b7485", 0.45);
  line3D([uFrameLeft, -760, zFrameTop - 4], [uFrameLeft, 840, zFrameTop - 4], "charcoal", "#06070a", 0.85);

  // --- C. DECORATIVE ART-DECO GRILLE FRETWORK SLOTS (u in [-118, -56]) ---
  for (let g = -6; g <= 7; g++) {
    let vG1 = g * 104 - 34;
    let vG2 = vG1 + 66;
    let uG1 = -116;
    let uG2 = -58;

    // Stepped slot cutout revealing deep black grille cloth underneath
    let slotPoly = [
      [uG1, vG1 + 8, zFrameTop - 1],
      [uG2, vG1, zFrameTop - 1],
      [uG2, vG2 - 8, zFrameTop - 1],
      [uG1, vG2, zFrameTop - 1]
    ];
    fillPoly3D(slotPoly, "#07080c", 252, false);

    // Woven metal mesh texture deep inside the grille slot
    for (let m = vG1 + 8; m < vG2 - 6; m += 9) {
      line3D([uG1 + 6, m, zFrameTop - 4], [uG2 - 6, m - 5, zFrameTop - 4], "2H", "#2a303c", 0.28);
      line3D([uG1 + 8, m - 4, zFrameTop - 4], [uG2 - 8, m + 5, zFrameTop - 4], "2H", "#1f242e", 0.28);
    }

    // Lit lower-right celluloid inner thickness rim of the cutout
    line3D([uG1, vG2, zFrameTop], [uG2, vG2 - 8, zFrameTop], "cpencil", "#b4bfd0", 0.44);
    line3D([uG2, vG1, zFrameTop], [uG2, vG2 - 8, zFrameTop], "HB", "#788294", 0.38);
    // Dark shadow rim on upper edge of cutout
    line3D([uG1, vG1 + 8, zFrameTop], [uG2, vG1, zFrameTop], "2B", "#040507", 0.55);
  }

  // --- D. TINY CELLULOID CHIPS & FINGERPRINT SMUDGES ON THE BLACK CASING ---
  const casingChips = [-285, -35, 215, 485];
  for (let vc of casingChips) {
    // Small jagged chip along the right casing edge (u ~ -10) exposing pale wood/core
    fillPoly3D(
      [
        [-15, vc - 6, zFrameTop - 1],
        [-8, vc - 4, zFrameTop - 2],
        [-8, vc + 7, zFrameTop - 2],
        [-16, vc + 4, zFrameTop - 1]
      ],
      "#6e6256", 240, false
    );
    line3D([-15, vc - 6, zFrameTop], [-8, vc - 4, zFrameTop - 1], "2B", "#050608", 0.45);
    line3D([-16, vc + 4, zFrameTop], [-8, vc + 7, zFrameTop - 1], "cpencil", "#ffffff", 0.48);
  }

  // --- E. HYPERREALIST CHROME GRILLE BOLTS (KNURLED THUMBSCREWS) ---
  const boltPositions = [-410, -110, 190, 490];
  for (let bIdx = 0; bIdx < boltPositions.length; bIdx++) {
    let uB = -33;
    let vB = boltPositions[bIdx];
    let rWasher = 25;
    let rCollar = 20;
    let rDome = 17.5;
    let zBaseB = zFrameTop;

    // 1. Oily fingerprint smudge halo on the black celluloid around the bolt
    for (let r = rWasher + 4; r <= rWasher + 20; r += 3.2) {
      let smPts = [];
      for (let a = -60; a <= 150; a += 30) {
        smPts.push([uB + cos(a) * r * 0.9, vB + sin(a) * r * 1.15, zBaseB + 0.2, 0.6]);
      }
      spline3D(smPts, 0.5, "2H", r % 6 < 3 ? "#4c5464" : "#252a35", 0.26);
    }

    // 2. Cast shadow of the bolt onto the celluloid deck (shifted toward +u, +v)
    let shPts = [];
    for (let a = 0; a < 360; a += 20) {
      shPts.push([uB + 7 + cos(a) * (rWasher + 2), vB + 11 + sin(a) * (rWasher + 3), zBaseB + 0.3]);
    }
    fillPoly3D(shPts, "#050609", 235, false);

    // 3. Recessed Chrome Washer Seat (z = zBaseB + 1.5)
    let washerPts = [];
    for (let a = 0; a < 360; a += 18) {
      washerPts.push([uB + cos(a) * rWasher, vB + sin(a) * rWasher, zBaseB + 1.5]);
    }
    fillPoly3D(washerPts, "#495160", 248, false);
    // High-contrast chrome reflection sectors on washer rim
    for (let a = 0; a < 360; a += 8) {
      let cW = (a > 190 && a < 310) ? "#ffffff" : (a > 20 && a < 130) ? "#11141c" : "#8b95a6";
      line3D(
        [uB + cos(a) * (rCollar + 1), vB + sin(a) * (rCollar + 1), zBaseB + 1.8],
        [uB + cos(a) * rWasher, vB + sin(a) * rWasher, zBaseB + 1.5],
        "2H", cW, 0.36
      );
    }

    // 4. Knurled Cylindrical Collar (z = zBaseB + 2 .. zBaseB + 9)
    let zColTop = zBaseB + 9.5;
    for (let a = 0; a < 360; a += 10) {
      let uK1 = uB + cos(a) * rCollar;
      let vK1 = vB + sin(a) * rCollar;
      let uK2 = uB + cos(a + 8) * rCollar;
      let vK2 = vB + sin(a + 8) * rCollar;

      // Alternating high-contrast knurl grooves
      let knurlLight = sin(a * 2.5) + cos(a - 235);
      let kCol = knurlLight > 0.75 ? "#ffffff" : knurlLight > 0.0 ? "#9aa4b5" : knurlLight > -0.7 ? "#39404d" : "#0b0d12";
      fillPoly3D(
        [
          [uK1, vK1, zBaseB + 2],
          [uK2, vK2, zBaseB + 2],
          [uK2, vK2, zColTop],
          [uK1, vK1, zColTop]
        ],
        kCol, 248, false
      );
      line3D([uK1, vK1, zBaseB + 2], [uK1, vK1, zColTop], "2B", "#0d1016", 0.35);
      if (knurlLight > 0.4) {
        line3D(
          [(uK1 + uK2) * 0.5, (vK1 + vK2) * 0.5, zBaseB + 2.5],
          [(uK1 + uK2) * 0.5, (vK1 + vK2) * 0.5, zColTop - 0.5],
          "cpencil", "#ffffff", 0.38
        );
      }
    }

    // 5. Mirror-Chrome Domed Head (z = zColTop .. zBaseB + 15.5)
    let zDomeApex = zBaseB + 15.5;
    let domeOutline = [];
    for (let a = 0; a < 360; a += 15) {
      domeOutline.push([uB + cos(a) * rDome, vB + sin(a) * rDome, zColTop + 0.5]);
    }
    fillPoly3D(domeOutline, "#cdd5e3", 250, false);

    // Dark warped horizon reflection across the lower-right hemisphere of the chrome dome
    fillPoly3D(
      [
        [uB - rDome * 0.85, vB + rDome * 0.1, zColTop + 2],
        [uB, vB - rDome * 0.15, zDomeApex],
        [uB + rDome * 0.92, vB - rDome * 0.2, zColTop + 2],
        [uB + rDome * 0.85, vB + rDome * 0.55, zColTop + 1.5],
        [uB, vB + rDome * 0.85, zColTop + 1.5],
        [uB - rDome * 0.65, vB + rDome * 0.6, zColTop + 1.5]
      ],
      "#0d1017", 245, false
    );

    // Secondary reflection of the pearloid keys (pale pink & celadon band) in lower rim of dome
    for (let a = 15; a <= 145; a += 12) {
      let cRef = a < 75 ? "#ebccd5" : "#c5ded6";
      line3D(
        [uB + cos(a) * (rDome * 0.58), vB + sin(a) * (rDome * 0.58), zColTop + 3],
        [uB + cos(a + 12) * (rDome * 0.78), vB + sin(a + 12) * (rDome * 0.78), zColTop + 2],
        "cpencil", cRef, 0.45
      );
    }

    // Concentric lathe-turned graphite rings on the dome
    for (let ringR = 4; ringR <= rDome; ringR += 2.8) {
      let ringZ = lerp(zDomeApex, zColTop + 0.5, pow(ringR / rDome, 1.4));
      let ringPts = [];
      for (let a = 0; a <= 360; a += 30) {
        ringPts.push([uB + cos(a) * ringR, vB + sin(a) * ringR, ringZ, 0.7]);
      }
      let ringCol = ringR < 9 ? "#eef3fa" : "#5a6373";
      spline3D(ringPts, 0.5, "2H", ringCol, 0.28);
    }

    // Blinding white studio light reflection on upper-left quadrant of chrome dome
    fillPoly3D(
      [
        [uB - rDome * 0.75, vB - rDome * 0.2, zColTop + 2.5],
        [uB - rDome * 0.2, vB - rDome * 0.8, zColTop + 2.5],
        [uB + rDome * 0.15, vB - rDome * 0.35, zDomeApex - 1],
        [uB - rDome * 0.25, vB + rDome * 0.05, zDomeApex]
      ],
      "#ffffff", 250, false
    );
    for (let h = 0; h < 8; h++) {
      let ang = 200 + h * 11;
      line3D(
        [uB + cos(ang) * 3, vB + sin(ang) * 3, zDomeApex],
        [uB + cos(ang) * (rDome - 1.5), vB + sin(ang) * (rDome - 1.5), zColTop + 1.5],
        "cpencil", "#ffffff", 0.58
      );
    }

    // 6. Machined Screwdriver Slot across the Chrome Dome
    let slotAng = 32 + bIdx * 23;
    let dxS = cos(slotAng) * (rDome - 1.5);
    let dyS = sin(slotAng) * (rDome - 1.5);
    let nxS = -sin(slotAng) * 2.4;
    let nyS = cos(slotAng) * 2.4;

    fillPoly3D(
      [
        [uB - dxS - nxS, vB - dyS - nyS, zColTop + 3],
        [uB + dxS - nxS, vB + dyS - nyS, zColTop + 3],
        [uB + dxS + nxS, vB + dyS + nyS, zColTop + 3],
        [uB - dxS + nxS, vB - dyS + nyS, zColTop + 3]
      ],
      "#080a0f", 252, false
    );
    // Razor-sharp specular catch-light along the lower-right lip of the machined slot
    line3D(
      [uB - dxS + nxS, vB - dyS + nyS, zColTop + 3.5],
      [uB + dxS + nxS, vB + dyS + nyS, zColTop + 3.5],
      "cpencil", "#ffffff", 0.62
    );
  }

  // =========================================================================
  // 7. FINAL HYPERREALIST GRAPHITE GRAIN & MICRO-DUST POLISH
  // =========================================================================
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  // Subtle graphite dust & paper tooth across the dark bellows and casing shadows
  for (let i = 0; i < 180; i++) {
    let uG = random(-750, 450);
    let vG = random(-700, 800);
    let zG = uG < 0 ? 35 : 22;
    let [x, y] = proj(uG, vG, zG);
    if (x < 0 || x > width || y < 0 || y > height) continue;

    if (uG < -20) {
      // Micro-graphite stipple and hairline scratches on bellows & casing
      brush.set("2H", random() < 0.35 ? "#697282" : "#141820", 0.24);
      let ang = random(360);
      let len = random(4, 14);
      brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
    } else {
      // Faint playing micro-scratches on the glossy pearloid celluloid keys
      brush.set("cpencil", random() < 0.5 ? "#ffffff" : "#b8c0ce", 0.22);
      let len = random(6, 18);
      brush.line(x, y, x + cos(25) * len, y + sin(25) * len);
    }
  }

  noLoop();
}

// Hyperreal Worm's-Eye Megastructure of Stacked Microwaves
// Technical pen ("rotring"), cool grey marker layers, and warm amber colored pencil vignettes

let camPos, lookAt, camRight, camUp, camFwd;
let focalLength = 980;
let screenCX = 575;
let screenCY = 650;

// Palette
const PAL = {
  paper: "#f4ecdc",
  paperWarm: "#efe2c8",
  inkDark: "#1a1715",
  inkMid: "#332e2a",
  inkFaint: "#6e675f",
  draftLine: "#9e9588",
  draftBlue: "#8a98a4",

  // Cool grey marker scale (brushed steel)
  steel1: "#e6eaee",
  steel2: "#cdd4dc",
  steel3: "#b2bcc6",
  steel4: "#94a0ac",
  steel5: "#778390",
  steel6: "#5b6672",
  steel7: "#414a54",
  steel8: "#2a313a",
  steel9: "#181d23",

  // Warm bounce & ambient tones on steel
  warmSteel1: "#f5e6cf",
  warmSteel2: "#dfc39d",
  warmSteel3: "#c79a6b",
  warmSteel4: "#9e7248",

  // Incandescent amber pencil & glow palette
  glowWhite: "#fffbe6",
  glowPale: "#ffeaa0",
  glowGold: "#ffca52",
  glowAmber: "#f59b23",
  glowOrange: "#df6e12",
  glowRust: "#b5460c",
  glowUmber: "#782808",
  glowDeep: "#3d1204",

  // Dead unit cold tones
  deadGlass1: "#14181e",
  deadGlass2: "#222932",
  deadGlass3: "#353f4c",
  deadHighlight: "#7c8b99",

  // LEDs
  ledAmber: "#ff9e22",
  ledBright: "#ffe699",
  ledGreen: "#5cd67a"
};

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4271);
  noiseSeed(4271);
  setupCamera();
}

function setupCamera() {
  // Worm's-eye camera looking steeply upward at the megastructure wall
  camPos = { x: -1.42, y: -2.25, z: 8.85 };
  lookAt = { x: 0.18, y: 4.55, z: 0.80 };

  let fx = lookAt.x - camPos.x;
  let fy = lookAt.y - camPos.y;
  let fz = lookAt.z - camPos.z;
  let fl = Math.hypot(fx, fy, fz);
  camFwd = { x: fx / fl, y: fy / fl, z: fz / fl };

  // World up = (0, 1, 0)
  // Right = normalize(cross(Fwd, Up))
  let rx = -camFwd.z;
  let ry = 0;
  let rz = camFwd.x;
  let rl = Math.hypot(rx, ry, rz);
  camRight = { x: rx / rl, y: ry / rl, z: rz / rl };

  // Up = cross(Right, Fwd)
  camUp = {
    x: camRight.y * camFwd.z - camRight.z * camFwd.y,
    y: camRight.z * camFwd.x - camRight.x * camFwd.z,
    z: camRight.x * camFwd.y - camRight.y * camFwd.x
  };
}

// Project 3D world coordinate to 2D canvas coordinate
function proj(x, y, z) {
  let vx = x - camPos.x;
  let vy = y - camPos.y;
  let vz = z - camPos.z;

  let cx = vx * camRight.x + vy * camRight.y + vz * camRight.z;
  let cy = vx * camUp.x + vy * camUp.y + vz * camUp.z;
  let cz = vx * camFwd.x + vy * camFwd.y + vz * camFwd.z;

  if (cz < 0.2) cz = 0.2;
  return {
    x: screenCX + (cx / cz) * focalLength,
    y: screenCY - (cy / cz) * focalLength,
    z: cz
  };
}

function projPt(p) {
  return proj(p.x, p.y, p.z);
}

// Interpolate in 2D
function lerpPt(a, b, t) {
  return { x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t };
}

// Interpolate in 3D
function lerp3(a, b, t) {
  return {
    x: a.x + (b.x - a.x) * t,
    y: a.y + (b.y - a.y) * t,
    z: a.z + (b.z - a.z) * t
  };
}

// Bilinear interpolation on a 2D quad [TL, TR, BR, BL]
// u in [0,1] left-to-right, v in [0,1] bottom-to-top
function quadUV(q, u, v) {
  // q[0]=TL, q[1]=TR, q[2]=BR, q[3]=BL
  let bot = lerpPt(q[3], q[2], u);
  let top = lerpPt(q[0], q[1], u);
  return lerpPt(bot, top, v);
}

// ---------------------------------------------------------------------------
// Geometry Clipping Helpers (clips 2D lines & polygons to a convex 2D quad)
// ---------------------------------------------------------------------------
function quadCentroid(quad) {
  let sx = 0, sy = 0;
  for (let i = 0; i < quad.length; i++) {
    sx += quad[i].x;
    sy += quad[i].y;
  }
  return { x: sx / quad.length, y: sy / quad.length };
}

function clipPolyToQuad(poly, quad) {
  if (!poly || poly.length < 3) return [];
  let c = quadCentroid(quad);
  let out = poly.slice();

  for (let i = 0; i < quad.length; i++) {
    let A = quad[i];
    let B = quad[(i + 1) % quad.length];
    let ex = B.x - A.x;
    let ey = B.y - A.y;
    let refSign = ex * (c.y - A.y) - ey * (c.x - A.x) >= 0 ? 1 : -1;

    let inp = out;
    out = [];
    if (inp.length === 0) break;

    for (let j = 0; j < inp.length; j++) {
      let P = inp[j];
      let Q = inp[(j + 1) % inp.length];
      let pVal = (ex * (P.y - A.y) - ey * (P.x - A.x)) * refSign;
      let qVal = (ex * (Q.y - A.y) - ey * (Q.x - A.x)) * refSign;

      if (pVal >= -1e-5) {
        out.push(P);
        if (qVal < -1e-5) {
          let t = pVal / (pVal - qVal);
          out.push(lerpPt(P, Q, t));
        }
      } else if (qVal >= -1e-5) {
        let t = pVal / (pVal - qVal);
        out.push(lerpPt(P, Q, t));
      }
    }
  }
  return out;
}

function clipSegToQuad(p1, p2, quad) {
  let c = quadCentroid(quad);
  let a = { x: p1.x, y: p1.y };
  let b = { x: p2.x, y: p2.y };

  for (let i = 0; i < quad.length; i++) {
    let A = quad[i];
    let B = quad[(i + 1) % quad.length];
    let ex = B.x - A.x;
    let ey = B.y - A.y;
    let refSign = ex * (c.y - A.y) - ey * (c.x - A.x) >= 0 ? 1 : -1;

    let va = (ex * (a.y - A.y) - ey * (a.x - A.x)) * refSign;
    let vb = (ex * (b.y - A.y) - ey * (b.x - A.x)) * refSign;

    if (va < 0 && vb < 0) return null;
    if (va < 0 || vb < 0) {
      let t = va / (va - vb);
      let m = lerpPt(a, b, t);
      if (va < 0) a = m;
      else b = m;
    }
  }
  return [a, b];
}

// ---------------------------------------------------------------------------
// Safe p5.brush Drawing Wrappers (Guarantees brush.set before strokes)
// ---------------------------------------------------------------------------
function drawLine2D(p1, p2, bName, col, weight, overrun = 0) {
  if (!p1 || !p2) return;
  let dx = p2.x - p1.x;
  let dy = p2.y - p1.y;
  let d = Math.hypot(dx, dy);
  if (d < 0.5) return;
  let x1 = p1.x, y1 = p1.y, x2 = p2.x, y2 = p2.y;
  if (overrun !== 0) {
    let ux = (dx / d) * overrun;
    let uy = (dy / d) * overrun;
    x1 -= ux; y1 -= uy;
    x2 += ux; y2 += uy;
  }
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, weight);
  brush.line(x1, y1, x2, y2);
}

function drawLineClipped(p1, p2, quad, bName, col, weight) {
  let seg = clipSegToQuad(p1, p2, quad);
  if (seg) drawLine2D(seg[0], seg[1], bName, col, weight, 0);
}

function washPoly(pts, col, opacity) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, opacity);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i].x, pts[i].y);
  }
  brush.endShape(true);
  brush.noWash();
}

function washPolyClipped(pts, quad, col, opacity) {
  let cPts = clipPolyToQuad(pts, quad);
  if (cPts.length >= 3) washPoly(cPts, col, opacity);
}

function watercolorPoly(pts, col, opacity, bleed = 0.12, tex = 0.35) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, 0.25);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i].x, pts[i].y);
  }
  brush.endShape(true);
  brush.noFill();
}

function hatchPoly(pts, bName, col, weight, dist, angleDeg, opts = { rand: 0.03 }) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.hatchStyle(bName, col, weight);
  brush.hatch(dist, angleDeg, opts);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i].x, pts[i].y);
  }
  brush.endShape(true);
  brush.noHatch();
}

function strokePoly(pts, closeShape, bName, col, weight, overrun = 0) {
  if (!pts || pts.length < 2) return;
  let n = closeShape ? pts.length : pts.length - 1;
  for (let i = 0; i < n; i++) {
    drawLine2D(pts[i], pts[(i + 1) % pts.length], bName, col, weight, overrun);
  }
}

function drawSpline2D(pts, bName, col, weight, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  if (pts.length === 2) {
    drawLine2D(pts[0], pts[1], bName, col, weight, 0);
    return;
  }
  let arr = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (p.p !== undefined) arr.push([p.x, p.y, p.p]);
    else arr.push([p.x, p.y]);
  }
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, weight);
  brush.spline(arr, curvature);
}

function drawSplineClipped(pts, quad, bName, col, weight, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  // Filter/clip spline segments into contiguous runs inside quad
  let run = [];
  for (let i = 0; i < pts.length - 1; i++) {
    let seg = clipSegToQuad(pts[i], pts[i + 1], quad);
    if (seg) {
      if (run.length === 0) run.push(seg[0]);
      run.push(seg[1]);
    } else {
      if (run.length >= 2) drawSpline2D(run, bName, col, weight, curvature);
      run = [];
    }
  }
  if (run.length >= 2) drawSpline2D(run, bName, col, weight, curvature);
}

// Generate projected 2D polygon of a horizontal 3D ellipse (lying in XZ plane at height y)
function ellipse3D_XZ(cx, y, cz, rx, rz, steps = 28, rotDeg = 0) {
  let pts = [];
  let rad = (rotDeg * Math.PI) / 180;
  let cr = Math.cos(rad);
  let sr = Math.sin(rad);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * Math.PI * 2;
    let lx = Math.cos(a) * rx;
    let lz = Math.sin(a) * rz;
    let wx = cx + lx * cr - lz * sr;
    let wz = cz + lx * sr + lz * cr;
    pts.push(proj(wx, y, wz));
  }
  return pts;
}

// Fill a 2D quad with realistic layered industrial marker strokes
function markerBandQuad(q, dir, col, weight, count, u0 = 0, u1 = 1, v0 = 0, v1 = 1) {
  for (let i = 0; i < count; i++) {
    let t = count === 1 ? 0.5 : i / (count - 1);
    let p1, p2;
    if (dir === "h") {
      let v = v0 + (v1 - v0) * t;
      p1 = quadUV(q, u0, v);
      p2 = quadUV(q, u1, v);
    } else if (dir === "v") {
      let u = u0 + (u1 - u0) * t;
      p1 = quadUV(q, u, v0);
      p2 = quadUV(q, u, v1);
    } else {
      // diagonal specular streak
      let s = (i / count) * 0.7;
      p1 = quadUV(q, Math.max(0, s), Math.min(1, v0 + s * 0.4));
      p2 = quadUV(q, Math.min(1, s + 0.45), Math.min(1, v1));
    }
    drawLine2D(p1, p2, "marker", col, weight, 0);
  }
}

// ---------------------------------------------------------------------------
// Main Draw Loop
// ---------------------------------------------------------------------------
function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // 1. Warm paper ground & atmospheric hum
  drawBackgroundAndAtmosphere();

  // 2. Megastructure core columns, service channels & drafting construction lines
  drawMegastructureCore();

  // 3. Build and sort all microwave capsule modules in 3D
  let capsules = buildCapsuleList();

  // Sort back-to-front from camera position (Painter's Algorithm)
  capsules.sort((a, b) => b.camDistSq - a.camDistSq);

  // 4. Render each microwave capsule (housing, soffit, controls, window vignette)
  for (let i = 0; i < capsules.length; i++) {
    drawMicrowaveCapsule(capsules[i]);
  }

  // 5. Final atmospheric hum, drafting annotations, and foreground framing
  drawForegroundPolish();

  noLoop();
}

// ---------------------------------------------------------------------------
